INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7136cca2-b2d9-4522-9ef5-ce8cc0d55cc7', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Công nghệ và đổi mới công nghệ: doanh nghiệp thực sự cần hiểu gì? như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d15dfe62-6579-4a7b-af5c-8464db45ada1', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2aae2623-b5ae-4c22-9351-d3a66190e6c9', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('369f6565-5133-4ec0-96bf-9cdd0c0ca9df', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('76a86d4b-c394-408d-a686-1deff49454dd', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 5, 'Chi phí thử nghiệm PoC thường chiếm bao nhiêu?', 'Thông thường khoảng 5-15% tổng chi phí dự án, giúp phòng ngừa 80% rủi ro thất bại.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('26a15e53-f9e4-4492-8ec1-004f63a3a81d', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('46fb3914-2abc-486f-b7c4-b588cd07a504', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c909ba19-11a0-43c4-ac65-569e81b199ec', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('66df161e-5cb0-453e-8e20-1e86c7eb4f1a', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 1, 'Vì sao không bắt đầu từ mua công nghệ?', 'Tên công nghệ không chỉ ra kết quả cần cải thiện. Hãy định nghĩa mục tiêu, KPI và trở ngại trước khi so sánh phương án.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b5bd207c-3af4-48da-b1c6-2fe486cc6dc7', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 2, 'Mục tiêu kinh doanh và KPI khác nhau thế nào?', 'Mục tiêu nêu kết quả doanh nghiệp mong muốn; KPI xác định cách đo cụ thể, kỳ đo và nguồn dữ liệu.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ff043dd0-e01f-42b1-b2c1-8752c62b37d6', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 3, 'Chưa có dữ liệu đường cơ sở thì làm gì?', 'Nêu cách tính, người phụ trách và khoảng thời gian cần thu thập. Không tự gán số liệu.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('84f10839-bb1c-4f1b-84ba-82a56ebeb001', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 4, 'Điểm nghẽn có đồng nghĩa nguyên nhân không?', 'Không. Điểm có công việc dồn lại cần kiểm tra cả đầu vào và các bước trước; nguyên nhân cần bằng chứng.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('e049182f-10a0-45a7-935b-bd467f02e2d2', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 5, 'Có cần triển khai công nghệ cho mọi vấn đề?', 'Không. Cải tiến quy trình, phân vai và truyền đạt có thể là phương án cần thử trước.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('dd06ac99-35f1-4c6a-b86a-5a4ee681d32f', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 6, 'Nên ưu tiên phương án tác động cao nhất?', 'Chưa đủ. Cần xem điều kiện bắt buộc, khả thi, rủi ro và độ tin cậy bằng chứng.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b470a2b5-a2c4-4f1d-a1b3-d751650d8270', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 7, 'Làm gì khi hai bộ phận dùng dữ liệu khác nhau?', 'Thống nhất định nghĩa KPI, thời điểm ghi nhận, nguồn dữ liệu và người xác nhận trước khi so sánh.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6932ddb3-71e6-4d64-bcdb-dfde126d6a93', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 8, 'Thử nghiệm tốt cần điều gì?', 'Có giả thuyết, phạm vi, KPI trước-sau, theo dõi yếu tố gây nhiễu, người xác nhận và tiêu chí tiếp tục hoặc dừng.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b9709687-2d0a-4752-a729-c3ef1640146b', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 1, 'Điểm nghẽn có phải luôn là máy chạy chậm nhất?', 'Không. Dòng công việc có thể bị giới hạn do phê duyệt, thiếu nguyên liệu, sản phẩm làm lại hoặc xử lý phản hồi khách. Cần xác định loại điểm nghẽn và kỳ khảo sát.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0e5d2ebd-de5c-4e05-89f2-2e582087e978', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 2, 'Hàng dồn ở một bước có đủ để kết luận bước đó gây nghẽn?', 'Chưa. Hàng dồn là dấu hiệu. Cần đo tốc độ đến, năng lực xử lý, thời gian chờ, luồng làm lại và thay đổi yêu cầu.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1e5fa8ab-784d-4798-b83d-d861b3f7599e', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 3, 'Tại sao phải so sánh công suất bằng cùng đơn vị?', 'Để tránh so sánh sản lượng giờ, ca hoặc đơn vị sản phẩm khác nhau. Phải quy đổi cùng kỳ, đơn vị và điều kiện trước khi lấy công đoạn nhỏ nhất.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('814f20f8-1aba-4f71-9381-2989ba32e007', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 4, 'Công suất thiết kế và đầu ra thực tế khác nhau vì sao?', 'Đầu ra thực tế còn chịu dừng máy, đổi mẫu, thiếu đầu vào, lỗi và làm lại. Không dùng con số công suất lý thuyết như cam kết hiệu quả.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('cfa2e181-8fdb-46f2-acef-84901eac0b22', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 5, 'Khi nào chất lượng trở thành điểm nghẽn?', 'Khi lỗi hoặc việc làm lại tiêu tốn nguồn lực, làm giảm sản lượng đạt hoặc kéo dài thời gian đáp ứng. Cần kiểm tra số liệu QC và vị trí phát sinh.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('481ea157-f0a0-4416-9da6-587447738423', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 6, 'Điểm nghẽn thị trường có đồng nghĩa doanh số giảm không?', 'Không. Cần kiểm tra quy trình phản hồi khách, chốt yêu cầu, giải quyết khiếu nại và các yếu tố khác như giá, cạnh tranh, mùa vụ trước khi kết luận.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('98bb4600-6bf9-48ca-a9dd-30a00edf6c46', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 7, 'Nên làm gì nếu thiếu dữ liệu nhiều ca?', 'Ghi rõ khoảng trống, thống nhất cách ghi và người xác nhận, thu thập kỳ quan sát phù hợp. Không điền số giả định vào bảng kết quả thực tế.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('67c07076-7ea4-4241-ad2b-af1c3f98905b', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 8, 'Có thể quyết định mua máy khi tìm thấy năng lực thấp nhất?', 'Chưa đủ. Phải xác nhận nhu cầu, công suất thực, ảnh hưởng tới KPI, khả năng cân bằng quy trình và phương án ít tốn kém trước khi lựa chọn đầu tư.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('250582f1-3255-4921-a541-5c7bda181ca2', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 1, 'Nguyên nhân gốc có phải luôn là một yếu tố duy nhất?', 'Không. Lỗi có thể do nhiều điều kiện cùng xuất hiện hoặc tương tác. Cần tách từng giả thuyết, cơ chế và phép đo thay vì ép một câu trả lời.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('39b69960-a60f-4157-857f-057b8dcd11ce', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 2, '5 Why có bắt buộc hỏi đúng năm lần không?', 'Không. Số lần hỏi phụ thuộc mức giải thích và khả năng kiểm chứng. Dừng khi đã xác định cơ chế hoặc điều kiện có thể kiểm tra, không phải vì đủ năm câu hỏi.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1eb4d42f-c77c-4117-9228-8f3580d82fe7', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 3, 'Sơ đồ xương cá có chứng minh được nguyên nhân không?', 'Không. Sơ đồ là công cụ tổ chức giả thuyết theo các nhóm yếu tố. Muốn xác nhận cần đối chiếu dữ kiện, đo lường và kiểm tra trong điều kiện phù hợp.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d8836e7b-4e5a-4738-9144-e3e9aeaa09b2', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 4, 'Khi hai yếu tố cùng đổi một lúc, kết luận thế nào?', 'Chỉ ghi nhận mối liên hệ ban đầu. Thiết kế thử giữ ổn định hoặc đo các yếu tố khác, ghi cách chọn mẫu và so sánh điều kiện tương đương.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('190ca2c4-e1bf-4dcc-84f7-026628f6e8bf', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 5, 'Có thể sử dụng số lỗi mà không biết mẫu số không?', 'Chỉ dùng số lỗi để mô tả số lượng tuyệt đối. Không so tỷ lệ giữa ca, lô hoặc máy khi thiếu mẫu số, kỳ đo và phương pháp lấy mẫu tương đương.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ca05c3b6-83fb-41ed-9f35-b81b3abba826', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 6, 'Nếu công nhân nói nguyên nhân là do máy, có thể ghi luôn không?', 'Ghi như một giả thuyết và hỏi thời điểm xảy ra, hiện tượng máy, log bảo trì, phép đo. Lời kể là nguồn định hướng điều tra, không thay thế chứng cứ kỹ thuật.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('72f674eb-0419-49c9-bdb2-e1db3896048f', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 7, 'Khi nào mới cân nhắc mua máy hàn mới?', 'Khi xác nhận thiết bị hiện tại không thể đạt yêu cầu trong điều kiện vận hành phù hợp và đã so sánh bảo trì, hiệu chuẩn, quy trình, vật liệu, chi phí và rủi ro.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f4678336-91b5-4ea6-bf73-0579aa86e01c', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 8, 'Không đủ dữ liệu nhưng cần xử lý ngay vì an toàn thì sao?', 'Thực hiện biện pháp kiểm soát rủi ro và xử lý sản phẩm theo quy trình an toàn của doanh nghiệp. Việc xử lý tức thời không đồng nghĩa đã xác nhận nguyên nhân gốc; vẫn phải điều tra sau đó.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('234142ab-0f2e-4b9e-aea4-ecf02c88e2d8', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 1, 'Máy đã cũ thì có cần thay ngay không?', 'Không thể kết luận từ tuổi máy. Cần đo tình trạng, năng lực, độ tin cậy, hồ sơ bảo trì, chi phí, an toàn và so sánh phương án.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1ee392f2-5fe6-4253-a53f-1f480f59c059', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 2, 'Máy móc và thiết bị khác nhau ở đâu?', 'Trong phiếu này, máy móc là tài sản tạo sản phẩm chính; thiết bị gồm cảm biến, đo kiểm và phụ trợ. Đó là phân nhóm khảo sát, có thể giao thoa.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8cc43f0e-e0b3-4976-8a4b-c7894e5ecc4c', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 3, 'Nếu không tìm được log vận hành thì ghi thế nào?', 'Ghi "chưa thu thập/không có hồ sơ để đối chiếu" cùng người phụ trách và kế hoạch thu. Không suy ra máy hỏng hoặc luôn ổn định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('87e111d3-9d0c-43d7-b74b-bde0f23c27bd', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 4, 'Tỷ lệ thời gian chạy 90% có phải OEE không?', 'Không. Chỉ số này dùng thời gian thực chạy chia thời gian dự kiến chạy. OEE cần dữ liệu phù hợp về sẵn sàng, hiệu suất tốc độ và chất lượng.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c03d5a05-9d49-40c1-805e-666eba0db116', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 5, 'Tỷ lệ lỗi giữa hai bài minh họa khác nhau có chứng minh đã cải thiện không?', 'Không. Chúng thuộc kỳ khảo sát giả định khác nhau. Muốn so phải có cùng định nghĩa, dữ liệu so sánh phù hợp và kiểm tra biến động.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a4f48bc4-b3bd-4fe9-bb42-1e7d15259946', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 6, 'Đã có phần mềm quản lý thì còn cần khảo sát gì?', 'Cần xem nơi nhập lại, liên kết mã, quyền truy cập, cập nhật, đối chiếu thực tế, độ tin cậy và khả năng truy vết giữa các bước.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a4dfecb2-878d-4144-9d07-54d35db74e65', 'fd3de369-9eb3-5db4-8ea7-7ad82868415e', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('40fb36cc-cfba-474a-8e61-338cffa9d73e', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 7, 'Khi SOP khác cách làm thực tế thì quy lỗi cho ai?', 'Trước hết ghi lại khác biệt, phiên bản SOP, điều kiện thực tế, bước ngoại lệ và phỏng vấn người thực hiện. Chưa đủ bằng chứng để quy trách nhiệm.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6200d738-f446-4d28-8e5c-98b0c6cf8bc7', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', 8, 'Khi nào đề xuất phần mềm hoặc máy mới?', 'Sau khi yêu cầu vận hành được mô tả rõ, khoảng trống đã được kiểm chứng và so sánh nâng cấp, bảo trì, chuẩn hóa quy trình, chi phí và rủi ro an toàn.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1a6044c8-2c4a-45c5-b8ea-f2f40a687f4d', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 1, 'Có đủ vốn đầu tư nghĩa là đã sẵn sàng chưa?', 'Chưa. Còn phải kiểm chứng nhân lực, quy trình, dữ liệu, hạ tầng, quản trị và điều kiện bắt buộc như an toàn.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('771b70e7-25c8-4ff2-b21c-1780e5980dd3', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 2, 'Năng lực hấp thụ có giống TRL không?', 'Không. TRL phản ánh mức sẵn sàng của giải pháp; năng lực hấp thụ phản ánh khả năng tổ chức tiếp nhận và vận dụng trong bối cảnh doanh nghiệp.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f69fcbde-fbb3-493c-8a9c-49d82d2b0cb4', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 3, 'Đã đào tạo một nhân viên thì có thể chấm nhân lực 2/2 không?', 'Chưa chắc. Cần tiêu chí cụ thể, kết quả thực hành, người dự phòng và khả năng duy trì khi đổi ca hoặc thay nhân sự.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ee4746d0-fac2-4ca0-8505-1569ac439136', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 4, 'Không có hồ sơ đào tạo có phải năng lực bằng 0?', 'Không mặc định. Ghi thiếu bằng chứng, tổ chức đánh giá thực hành và chỉ chấm theo phạm vi, tiêu chí đã định.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('348151a4-919e-452d-911a-fe0169d0e078', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 5, 'Tổng 5/10 nghĩa là 50% khả năng dự án thành công?', 'Không. Đây là tổng điểm trên thang thực hành của bài học, không phải xác suất thành công hoặc tiêu chuẩn công nhận.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('88d38c03-3304-416b-9b66-192d1b36fa43', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 6, 'Có thể bù điều kiện an toàn bằng điểm cao ở dữ liệu không?', 'Không. Những điều kiện bắt buộc phải được xem riêng và đáp ứng trước hoạt động thử nghiệm có liên quan.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5c34ba9d-e5d9-425d-bf74-640c2070ad24', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 7, 'Khi nào nên chạy thử công nghệ?', 'Khi đã xác định mục tiêu, phạm vi, tiêu chí đo, trách nhiệm, điều kiện an toàn, dữ liệu nền và người phê duyệt. Không tự gây sự cố trên dây chuyền.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a5ebad6a-c084-4f47-8ec7-c89d60bb696b', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 8, 'Sau bàn giao nên duy trì năng lực bằng cách nào?', 'Cập nhật SOP, kiểm tra thao tác định kỳ theo rủi ro, giữ người dự phòng, truy vết dữ liệu, kế hoạch bảo trì và cơ chế hỗ trợ nhà cung cấp.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1ed948d8-6845-4802-b60d-3f516dd84371', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 1, 'Bản mô tả nhu cầu này khác gì so với hồ sơ mời thầu?', 'Bản mô tả nhu cầu là tài liệu ban đầu, giúp doanh nghiệp làm rõ vấn đề cần giải quyết và trao đổi với bộ phận kỹ thuật, chuyên gia tư vấn hoặc nhà cung cấp. Trong khi đó, hồ sơ mời thầu và thiết kế kỹ thuật chi tiết là những bước tiếp theo, có yêu cầu riêng về pháp lý và chuyên môn kỹ thuật.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('523583ce-d963-4989-9720-8ae1bd4651e4', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 2, 'Chưa có số liệu cụ thể thì có thể lập bản mô tả nhu cầu không?', 'Có. Ghi rõ số liệu đang thiếu, nguồn dự kiến thu thập và người phụ trách xác minh. Không tự đặt tỷ lệ tiết kiệm hoặc chất lượng như dữ kiện đã có.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('59ac22b2-9655-4beb-9620-0a2c2502a926', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 3, 'Doanh nghiệp quy mô nhỏ, không có bộ phận kỹ thuật thì có cần lập bản mô tả nhu cầu không?', 'Có. Bản mô tả giúp doanh nghiệp diễn đạt rõ nhu cầu khi làm việc với chuyên gia tư vấn hoặc nhà cung cấp, đồng thời tạo cơ sở để so sánh các phương án trên cùng một hệ thống tiêu chí. Doanh nghiệp không nhất thiết phải có bộ phận kỹ thuật riêng mới có thể thực hiện bước này.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('caf395f2-62bb-478c-a7de-93be8ccb323c', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 4, 'Một trang có đủ để mô tả nhu cầu không?', 'Với mục đích trao đổi ban đầu, một trang thường là đủ nếu nội dung được trình bày rõ ràng và tập trung. Nếu vấn đề liên quan đến nhiều quy trình hoặc quá phức tạp, nên chia thành các bản mô tả riêng cho từng quy trình nhỏ, thay vì cố gắng đưa tất cả vào một tài liệu dài nhưng thiếu trọng tâm.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('4746de3e-6926-43aa-babf-eaf1fe87cd95', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 5, 'Có nên ghi tên sản phẩm hoặc giải pháp đã thấy ở doanh nghiệp khác vào bản mô tả không?', 'Không nên lấy tên một hãng hoặc sản phẩm cụ thể làm cơ sở xác định nhu cầu. Thay vào đó, hãy mô tả công việc cần được hỗ trợ và kết quả mong muốn. Cách làm này giúp các nhà cung cấp có thể đề xuất những phương án khác nhau trên cùng một yêu cầu, tránh giới hạn lựa chọn ngay từ đầu.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0ed52d91-e45b-4b1d-9ccb-7005fe82a7fb', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 6, 'Người trực tiếp sử dụng không muốn thay đổi cách làm hiện tại thì nên xử lý thế nào?', 'Hãy hỏi về thao tác khó, thời gian phát sinh và rủi ro mà người dùng lo ngại. Mời họ thử quy trình hoặc bản mẫu, ghi lại phản hồi và điều chỉnh yêu cầu nếu có căn cứ; không mặc định người dùng chống đối hay chưa được đào tạo.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5ddcaf18-61ff-4269-b783-f06fbb2a7e4c', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 7, 'Khi nào nên sử dụng các nhãn B, N và ?', 'B - Bắt buộc: Chức năng không thể thiếu nếu muốn công việc đạt mục tiêu. 
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6dffc864-d1d5-4b75-85a3-7f5642c2f4ff', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 8, 'Ngưỡng cụ thể cho các yêu cầu như “nhanh” hoặc “dễ dùng” là bao nhiêu?', 'Không có một ngưỡng chung phù hợp với mọi doanh nghiệp. Cần thiết kế tác vụ thử nghiệm với người dùng thực tế, ghi nhận kết quả đo lường, sau đó trao đổi và thống nhất mức chấp nhận. Như vậy, các yêu cầu định tính mới có thể chuyển thành tiêu chí đánh giá cụ thể.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('cb881a83-2245-43f5-9942-86378a09fb0e', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 1, 'Đường cơ sở khác mục tiêu như thế nào?', 'Đường cơ sở mô tả giá trị đo trước can thiệp; mục tiêu là mức muốn đạt trong tương lai. Không coi mục tiêu là kết quả đã có.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('788ac3e5-911e-4d69-a008-e9261189afbb', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 2, 'Tại sao phải ghi mẫu số cho tỷ lệ lỗi?', 'Vì số lượng kiểm/sản xuất có thể thay đổi. Tỷ lệ giúp so cùng quy tắc; vẫn cần ghi số gốc và điều kiện đo.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('62f8101e-7f55-4bc5-b4ae-e6d9a3f26946', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 3, 'Một tuần dữ liệu có đủ để làm baseline không?', 'Không có số tuần chung. Cần xem tính biến động, chu kỳ sản xuất, mùa vụ và độ đầy đủ. Một tuần có thể thiếu tính đại diện.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d8f19789-8fc4-46ac-b075-5fabac05cb4c', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 4, 'Khi mỗi tuần kiểm số túi khác nhau thì tính ra sao?', 'Cộng tổng số túi lỗi và tổng số túi kiểm, rồi chia; không tự lấy trung bình đơn giản các tỷ lệ tuần.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('fae9983e-8e34-4167-bc6f-04f0271773bb', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 5, 'Có nên bỏ tuần lỗi cao để số nền đẹp hơn?', 'Không. Chỉ loại khi có lý do về dữ liệu hoặc không cùng phạm vi theo quy tắc được thống nhất và lưu bằng chứng.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6282c30c-1d01-4d73-915e-272f7693dd78', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 6, 'Tỷ lệ từ 3% xuống 2% là giảm bao nhiêu?', 'Giảm 1 điểm phần trăm; mức giảm tương đối so với nền là khoảng 33,3%. Hai con số mang ý nghĩa khác nhau.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('bafa76b4-447e-4c5c-8bb1-15c1aeb261d8', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 7, 'KPI chính giảm nhưng thời gian dừng máy tăng thì sao?', 'Đánh giá thêm KPI hỗ trợ, năng lực giao hàng và an toàn. Một cải thiện riêng lẻ có thể kèm đánh đổi không chấp nhận được.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0644ffc3-64f0-48d2-a32f-e3a2c675e95c', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 8, 'Sau thử có thể kết luận công nghệ là nguyên nhân giảm lỗi không?', 'Chưa đủ chỉ từ số trước - sau. Cần kiểm điều kiện tương đương, thay đổi đồng thời, mức biến động và thiết kế kiểm chứng phù hợp.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('783dd759-0a04-4e5d-929d-5c3bf6a81f95', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 1, 'Có thể chấm điểm khi chưa xác định KPI nền không?', 'Nên ghi thiếu bằng chứng và kế hoạch thu thập. Có thể chấm sơ bộ để thảo luận, nhưng không trình bày như kết luận đã xác minh.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('fba7ea02-40d2-462e-b9de-19753a99ebdf', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 2, 'Vì sao phải chấm nhu cầu trước khi so nhà cung cấp?', 'Vì mục tiêu là ưu tiên vấn đề kinh doanh cần giải, không ưu tiên công nghệ chỉ do hiện đại, nhiều tính năng hay có báo giá.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c0af8ed0-1337-4cf1-b8e9-e4e651caecd6', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 3, 'Trọng số 60/40 có phải quy chuẩn không?', 'Không. Đây là ví dụ học tập. Doanh nghiệp chọn trọng số theo mục tiêu chiến lược, ghi người phê duyệt và kiểm thử thay đổi trọng số.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('799ab558-9282-4988-8f2f-26ec5d93e0da', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 4, 'Điểm 4,6/5 có nghĩa khả năng thành công 92% không?', 'Không. Đây là điểm tổng hợp có trọng số trên thang quy ước, không phải xác suất, tỷ lệ hoàn vốn hoặc lợi ích đã kiểm chứng.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8851f560-5182-4b5e-b415-2f3e84978780', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 5, 'Nếu hai nhu cầu bằng điểm thì phải làm sao?', 'Giữ cùng hạng sơ bộ, xem chứng cứ, rủi ro, quan hệ phụ thuộc, mức độ khẩn cấp, khả năng thử và thử độ nhạy; không bẻ thang để ép thứ hạng.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9b340f8b-ecfb-45de-a9bc-7c212ce99452', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 6, 'Nếu tác động cao nhưng thiếu dữ liệu hoặc nhân lực?', 'Xếp vào nhóm ưu tiên chuẩn bị: thu dữ liệu, đào tạo, chuẩn hóa quy trình, xác minh điều kiện rồi chấm lại hoặc thiết kế thử.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2b9365ad-37cd-43db-bf7e-c37c2986e673', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 7, 'Tại sao điểm cao vẫn có thể chưa được triển khai?', 'Điều kiện an toàn, tuân thủ, quyền dữ liệu hoặc các yêu cầu kỹ thuật bắt buộc có thể chưa đạt. Điểm cao không bù được cổng bắt buộc.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('34a0b060-3076-485c-a167-1eef3d3d32d5', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 8, 'Bao lâu phải đánh giá lại danh mục ưu tiên?', 'Không có chu kỳ chung. Nên xác định mốc theo thay đổi chiến lược, nguồn lực, bằng chứng mới và tiến độ chuẩn bị/thử nghiệm; ghi người chịu trách nhiệm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('71e82476-516e-4398-95de-875c3fdfc9a4', '3a6158cd-409e-53b6-b657-95bfc28329ba', 1, 'Chưa biết nguyên nhân gốc có thể gửi phiếu kết nối không?', 'Có thể gửi để xin tư vấn xác minh nguyên nhân nếu nói rõ đây là giả thuyết và ghi dữ liệu còn thiếu. Không được trình bày giả thuyết như kết luận.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('15d5c5ff-3764-4702-8546-e9b811a5ea35', '3a6158cd-409e-53b6-b657-95bfc28329ba', 2, 'Tỷ lệ 240/8.000 có chứng minh nhà máy lỗi 3% mọi sản phẩm không?', 'Không. 3% là tỷ lệ trên mẫu đã kiểm. Muốn suy rộng cần biết khung mẫu, phương pháp lấy mẫu và mức đại diện.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a7832559-c9fa-4523-8f00-ba2c07f39a8e', '3a6158cd-409e-53b6-b657-95bfc28329ba', 3, 'Có bắt buộc ghi tên máy, phần mềm hoặc hãng đề xuất không?', 'Không. Nên mô tả bài toán theo kết quả. Chỉ ghi công nghệ cụ thể khi có ràng buộc kỹ thuật được xác minh hoặc là phương án cần so sánh.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9206ae74-fec6-4879-a8dd-d4e961212690', '3a6158cd-409e-53b6-b657-95bfc28329ba', 4, 'Mục tiêu <=2% là cam kết chung cho mọi doanh nghiệp?', 'Không. Đây là số minh họa. Mục tiêu thực tế cần dựa trên dữ liệu nền, điều kiện kỹ thuật, mức chấp nhận rủi ro và phê duyệt nội bộ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9d073dce-9858-4fb7-8eeb-e146a476a999', '3a6158cd-409e-53b6-b657-95bfc28329ba', 5, 'Ký hiệu B, N và ? có ý nghĩa gì?', 'B là bắt buộc đã được thống nhất; N là nên có; ? là chưa đủ thông tin để phân loại. Mỗi ? cần người xác minh và thời điểm xử lý.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6483ddef-9d09-4e50-b69f-fbddb53ba8ea', '3a6158cd-409e-53b6-b657-95bfc28329ba', 6, 'Phiếu một trang có đủ để nhà cung cấp báo giá chính xác không?', 'Phiếu thường chỉ đủ cho trao đổi hoặc khảo sát sơ bộ. Báo giá và quyết định đầu tư có thể cần khảo sát kỹ thuật, phạm vi, dữ liệu, điều kiện và thỏa thuận chi tiết.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3d32663b-4b2d-45d8-8c73-3295afc1eba7', '3a6158cd-409e-53b6-b657-95bfc28329ba', 7, 'Có thể chuyển nguyên dữ liệu khách hàng cho chuyên gia không?', 'Chỉ chia sẻ thông tin trong phạm vi đã được phép và theo điều kiện sử dụng thích hợp. Cần xác định thông tin nhạy cảm trước khi gửi.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('88f7a61e-38c2-46f0-b3b3-1eeed57d9c40', '3a6158cd-409e-53b6-b657-95bfc28329ba', 8, 'Lỗi giảm sau thử có chứng minh giải pháp hữu hiệu?', 'Chưa chắc. Phải kiểm điều kiện so sánh, cỡ mẫu, thay đổi vật liệu/ca, an toàn và khả năng duy trì. Ghi nhận cải thiện khác chứng minh quan hệ nhân quả.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0dfd1854-300a-48e7-ae22-95e68458cc55', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Hệ sinh thái cung – cầu công nghệ: doanh nghiệp có thể tìm công nghệ ở đâu? như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8139d414-8d07-4df0-8102-763c5eb4ac0b', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('02bb2b62-58c0-443b-a5cb-1db2eefb5f98', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('e66095ac-2fd7-40cb-b1db-df746ccf5dde', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d4912b5c-ac3b-4a1d-a449-667167f031ce', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 5, 'Chi phí thử nghiệm PoC thường chiếm bao nhiêu?', 'Thông thường khoảng 5-15% tổng chi phí dự án, giúp phòng ngừa 80% rủi ro thất bại.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9177a574-5173-47b8-8418-38dccc55b726', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('40ceedec-63d2-4b9f-a52f-40a68439dc45', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('838e9f25-de2c-4604-9608-70593fc670cf', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('de156f5f-1d0b-4f6d-aee5-564923f6a871', '3115a810-8fd8-5c58-b491-e8cd3f554dd0', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Các con đường tiếp cận công nghệ: mua, thuê, licensing, chuyển giao và hợp tác R&D như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
