INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3a20b596-c421-47fb-81a0-189b04c117c4', '1c72af3d-190b-5477-a4fe-559cb0698ecf', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
