INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('32b3f666-9740-4396-b9a6-ecfb3de9690b', 'b077eeb8-a125-5b14-b57e-adb919073e53', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Khai thác cơ sở dữ liệu công nghệ, sáng chế và nguồn thông tin công khai như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
