INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('627aad01-3db5-4b06-b25c-b3c3a2fbfa84', 'b077eeb8-a125-5b14-b57e-adb919073e53', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b914e1c9-48ac-45d2-8ffa-4a9273b0d10f', 'b077eeb8-a125-5b14-b57e-adb919073e53', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1c55f4f5-3329-42fb-b6de-2d8a54f94d57', 'b077eeb8-a125-5b14-b57e-adb919073e53', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('bedf86ed-9961-45ce-8c99-44caec1647ad', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 1, 'Có thể coi tốc độ tối đa trong catalogue là năng suất thực tế không?', 'Không. Phải hỏi cách đo, loại sản phẩm, băng tải, dừng máy và thử ở điều kiện dây chuyền.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('fc215d90-c028-4c91-bceb-7443576d0ec9', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 2, 'Con số “99% chính xác” có đủ để nghiệm thu không?', 'Không. Cần xác định chỉ số, mẫu số, loại lỗi, người gán nhãn và điều kiện thử. Tách phát hiện lỗi, bỏ lọt và loại nhầm.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('64c52013-0667-4f90-b335-bde555c16d38', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 3, 'Một camera có Ethernet có chắc tích hợp được phần mềm cũ?', 'Không. Cần kiểm giao thức, định dạng dữ liệu, tín hiệu, độ trễ, quyền truy cập và thử kết nối.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('def452c1-99d9-452a-84a3-31958550b367', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 4, 'Không có bản vẽ, thông số điện thì nên chấm không đạt?', 'Chưa thể kết luận không đạt chỉ vì thiếu tài liệu. Ghi chưa xác minh, yêu cầu hồ sơ và khảo sát thực địa.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('af25bf54-2faf-4386-8c37-fd204f0e7fbc', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 5, 'Bộ thử có 100 gói lỗi trong 500 gói có nghĩa dây chuyền lỗi 20%?', 'Không. Đây là mẫu giả định có chủ đích để thử phát hiện lỗi; không đại diện tỷ lệ lỗi sản xuất.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('147d7d2b-40b3-4ac6-b32a-542b2cdc1d6f', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 6, 'Tỷ lệ phát hiện 96% và loại nhầm 3% có đạt ngưỡng ví dụ không?', 'Không. Ngưỡng ví dụ là phát hiện ít nhất 98% và loại nhầm không quá 1%. Cần điều chỉnh và thử lại có kiểm soát.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9715a6a5-bd38-4568-89d4-490080f28226', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 7, 'Ngoài thông số kỹ thuật cần đọc phần nào?', 'Xem lắp đặt, an toàn, tích hợp, vận hành, bảo trì, giấy phép, bảo hành, chi phí và điều kiện hỗ trợ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3691cf97-1052-4f09-9da0-41b7a51d155f', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 8, 'Nếu nhà cung cấp chưa cung cấp biên bản thử thì có cần dừng mọi trao đổi?', 'Có thể tiếp tục trao đổi sơ bộ để yêu cầu bằng chứng. Không phê duyệt nghiệm thu hay mua thiết bị dựa riêng trên tuyên bố chưa được kiểm chứng.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f011323d-822a-40b2-99a9-619496ffdfc6', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung TRL 1–9: đánh giá mức độ sẵn sàng công nghệ như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('76b42fcf-94b2-4b77-8410-f56fe4571158', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c97bc899-b1cf-4157-8649-314eddb6ace1', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5b50145f-208f-448e-aa44-d064a642070f', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('79854417-583d-4f15-a3c0-6cb6f1ffb9f9', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 5, 'Chi phí thử nghiệm PoC thường chiếm bao nhiêu?', 'Thông thường khoảng 5-15% tổng chi phí dự án, giúp phòng ngừa 80% rủi ro thất bại.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2fdf58d6-8aca-4b83-b612-ae35374a07c0', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('03d03d58-8cff-412f-9366-370675316601', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c75393ae-943f-4ae4-993f-229a3713c828', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('69055d01-90fb-455b-9512-629ef2bd304f', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 1, 'Hồ sơ có chữ ký nhà cung cấp đã đủ để tin kết quả chưa?', 'Chữ ký giúp xác định trách nhiệm nhưng không thay cách lấy mẫu, định nghĩa chỉ số, dữ liệu gốc và khả năng thử lại.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b994c47b-a07d-4ac1-ad42-9a210aa54f1d', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 2, 'Một video demo rõ nét có phải bằng chứng hiệu năng không?', 'Video chứng minh một thao tác đã được trình diễn; nếu không có cách chọn mẫu, số lượng, điều kiện và log thì chưa đủ để đánh giá hiệu năng.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8c0b25a8-a323-4d77-a645-cac029f9b74e', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 3, 'Vì sao phải biết ai gán nhãn đúng hoặc sai cho mẫu?', 'Chỉ số dùng nhãn chuẩn làm cơ sở so sánh. Nếu nhãn chuẩn sai hoặc không nhất quán thì tỷ lệ tính ra có thể gây hiểu nhầm.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('4b9c4d50-9a77-40ce-9566-763a1fdb305b', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 4, 'Bộ mẫu có 20% gói lỗi, có thể coi nhà máy lỗi 20% không?', 'Không. Bộ thử có thể được chọn có chủ đích để đo khả năng phát hiện; không suy được tỷ lệ lỗi dây chuyền.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('266266b4-5dfb-49a9-a8a6-17a751d63a83', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 5, 'Tỷ lệ đúng chung 96,8% có đủ để đánh giá camera không?', 'Không. Cần tách tỷ lệ phát hiện lỗi và loại nhầm; mức đúng chung chịu ảnh hưởng của cơ cấu mẫu.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('61846c59-ca61-46f1-9d77-1778c961d72f', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 6, 'Không có dữ liệu gốc thì ghi không đạt hay chưa xác minh?', 'Thông thường ghi chưa xác minh về tính đáng tin của báo cáo, nêu cụ thể chứng cứ cần bổ sung; không tự quy kết công nghệ sai.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('794cbd90-c156-4755-9608-0d6c7eb5ea9f', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 7, 'Thế nào là phép thử độc lập phù hợp?', 'Mẫu đánh giá mới và phù hợp phạm vi, quy trình khóa trước, nhãn chuẩn có kiểm soát, log đầy đủ và người xác nhận có khả năng đối chiếu kết quả.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3e297265-f7d5-4890-8bdb-1620ccb26a18', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 8, 'Kết quả dưới ngưỡng có cần dừng trao đổi nhà cung cấp?', 'Chưa nên nghiệm thu theo phép thử đó. Có thể yêu cầu phân tích sai lệch, hiệu chỉnh và thử lại với điều kiện rõ; cũng cần kiểm lại chất lượng chứng cứ.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('22fb0b86-040c-467e-8567-7b672fca3c40', '355ab944-8895-5f38-b87f-89e187038e44', 1, 'Mua camera có đồng nghĩa mua quyền sở hữu phần mềm không?', 'Không thể suy như vậy. Cần đọc nội dung chuyển giao và giấy phép để biết quyền đã được cấp đối với phần mềm, bản cài, bản sao và các hành vi khác.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c4bd6ba0-823e-491b-92b2-215c8c8c9574', '355ab944-8895-5f38-b87f-89e187038e44', 2, 'Thấy số đơn sáng chế trên brochure có đủ bảo đảm không?', 'Chưa. Cần tra tình trạng đơn hoặc văn bằng, chủ thể, phạm vi, lãnh thổ và thời điểm; nếu rủi ro lớn cần thẩm định pháp lý.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2720a3c8-2915-4a5a-8321-73e4077daa43', '355ab944-8895-5f38-b87f-89e187038e44', 3, 'Không tra thấy sáng chế thì có thể yên tâm đưa công nghệ vào sản xuất?', 'Không. Kết quả tìm kiếm tùy phạm vi từ khóa, phân loại, nơi tra và tình trạng dữ liệu; không thay đánh giá tự do khai thác.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('27ad48ff-1ff3-466b-b770-be658b67a1b5', '355ab944-8895-5f38-b87f-89e187038e44', 4, 'Nhà cung cấp giao mã nguồn có nghĩa được sửa và bán lại phần mềm?', 'Không tự động. Việc nhận tệp mã nguồn và quyền sửa, phân phối, cấp phép lại là các vấn đề khác nhau cần văn bản điều chỉnh.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('05da338e-df2d-494a-a6bf-9fff9a9755e5', '355ab944-8895-5f38-b87f-89e187038e44', 5, 'Phần mềm nguồn mở có thể dùng không cần kiểm giấy phép?', 'Không. Cần xem từng giấy phép, phiên bản, cách dùng và nghĩa vụ thông báo, phân phối hoặc cung cấp nguồn nếu phát sinh.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3e7a1314-ce5a-443f-8112-bb68e74a3dbd', '355ab944-8895-5f38-b87f-89e187038e44', 6, 'Ảnh lỗi do doanh nghiệp gửi có thể bị dùng lại để huấn luyện không?', 'Không nên mặc định. Hợp đồng cần nêu mục đích, phạm vi dùng lại, người truy cập, lưu giữ, bàn giao hoặc xóa và các quy định dữ liệu áp dụng.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('963443ab-21ff-4f8e-b6bf-643274903c1c', '355ab944-8895-5f38-b87f-89e187038e44', 7, 'Bảng tự chấm đủ 14 điểm có chứng minh công nghệ không vi phạm quyền?', 'Không. Điểm chỉ đánh giá mức đầy đủ của phiếu rà soát học tập; kết luận pháp lý đòi hỏi kiểm chứng quyền, phạm vi, hành vi và pháp luật áp dụng.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2592b14c-b16e-4c31-bd26-3d02441a7ef7', '355ab944-8895-5f38-b87f-89e187038e44', 8, 'Quy định nào cần cập nhật khi triển khai năm 2026?', 'Cần rà Luật Sở hữu trí tuệ và Luật Chuyển giao công nghệ theo các sửa đổi có hiệu lực từ 01/04/2026, cùng quy định liên quan và tình trạng quyền cụ thể; nên nhờ người có chuyên môn xem xét.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5c528a41-10e0-4014-9fea-68e1a1930a18', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 1, 'Danh sách ngắn khác gì danh sách nhà cung cấp?', 'Danh sách ngắn của bài này là các kiến trúc/giải pháp đáp ứng nhu cầu để kiểm chứng tiếp. Một kiến trúc có thể do nhiều bên cung cấp; cần phân biệt phương án và đơn vị bán.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8e6ddbbe-31f2-4187-aabb-618e1d67f265', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 2, 'Tại sao thường chọn 3-5 phương án?', 'Đây là khoảng quản lý công việc trong đề bài, giúp tập trung nguồn lực kiểm chứng. Không phải ngưỡng pháp lý hay đảm bảo rằng mọi dự án đều tìm được đủ số.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9a79a70c-6f84-4ef6-8895-abc176b25d2a', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 3, 'Có thể giữ một phương án chưa đủ tài liệu trong shortlist không?', 'Có thể giữ có điều kiện hoặc chờ xác minh nếu chưa có bằng chứng nó không đáp ứng chức năng bắt buộc. Phải nêu tài liệu thiếu, phép thử và thời hạn; không ghi đã đạt.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9c8fe9f7-3eba-43db-919f-d771e37e04b8', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 4, 'Một phương án giá rẻ nhưng không kiểm được mã lô có nên giữ?', 'Không nên giữ cho bài toán bắt buộc kiểm mã lô, dù giá thấp. Nó có thể được xem xét cho bài toán khác nếu phù hợp.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('80df5f7b-9194-40a2-9f6c-319105257441', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 5, 'Ba đại lý bán cùng một công nghệ có được tính là ba phương án?', 'Không nên đếm như ba kiến trúc độc lập. Có thể ghi ba lựa chọn thương mại dưới cùng một cơ chế và so sánh nhà cung cấp ở bước phù hợp.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2160c75b-ebb2-4476-b876-505aa3dd5db9', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 6, 'Data Matrix và mã lô in dạng chữ có giống nhau không?', 'Không. Đầu đọc mã 2D cần mã máy đọc phù hợp; chuỗi chữ thường có thể đòi camera/OCR hoặc thay đổi cách in. Cần khảo sát sản phẩm thật.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9c713a6a-169f-4d4c-b158-844599d723bd', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 7, 'Có thể chỉ dựa vào brochure để chọn giải pháp tốt nhất không?', 'Không. Brochure cho biết tuyên bố và điều kiện công bố; cần kiểm chứng tại bối cảnh sử dụng, nhất là độ chính xác, nhịp dây chuyền và khả năng tích hợp.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('038e8011-d9ea-408f-867d-01d0f890906d', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 8, 'Nếu sau thử nghiệm chỉ còn hai giải pháp đáp ứng thì có cần thêm phương án cho đủ ba?', 'Ghi nhận trung thực hai giải pháp đáp ứng, tìm nguồn bổ sung nếu cần cạnh tranh so sánh. Không được nới chức năng bắt buộc chỉ để đạt con số 3-5.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1bb24863-a566-47ae-abbc-41bf96e98151', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Thực hành khai thác nền tảng: tìm – lọc – lưu – so sánh – kết nối như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('33239f2a-6cdc-4a13-a84f-e96922b9ea37', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b7b613da-276e-425c-a1b1-c26b30916af0', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7e38e317-0005-4714-8829-846c3e2a76b1', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('db43847d-3968-4dbf-b7c2-1166df3f4a52', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 5, 'Chi phí thử nghiệm PoC thường chiếm bao nhiêu?', 'Thông thường khoảng 5-15% tổng chi phí dự án, giúp phòng ngừa 80% rủi ro thất bại.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('09c706b4-09eb-4e66-b8e5-10443c42927d', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('58f1c13e-822d-4d9d-a906-2498b75086d7', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d7658a0d-b04e-420c-a67e-00056ca11048', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c66cc4cf-cf82-4aa5-b38c-d60c74052129', '60488501-198f-51f9-b9a3-e9d658985077', 1, 'Công nghệ hiện đại hơn có luôn tốt hơn không?', 'Không. Độ phù hợp phụ thuộc bài toán, môi trường triển khai, nhân sự, chi phí và bằng chứng thử nghiệm. Công nghệ mới có thể phù hợp khi các điều kiện đó thay đổi.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('31cac755-af39-42fa-9cc2-96fe21ac7b3a', '60488501-198f-51f9-b9a3-e9d658985077', 2, 'Nếu phương án rất rẻ nhưng dưới nhịp tối thiểu thì sao?', 'Nếu nhịp là điều kiện bắt buộc đã xác minh, phương án không phù hợp cho công đoạn kiểm toàn bộ sản phẩm. Có thể xem mục đích khác nhưng không bù bằng điểm giá.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2051ba40-d48a-4b03-aca8-d159dd17c3fc', '60488501-198f-51f9-b9a3-e9d658985077', 3, 'Tốc độ máy trên brochure có dùng để so sánh được không?', 'Dùng để lập câu hỏi sơ bộ. Không coi là công suất thực tế trước khi thử trên kiểu túi, mã lô, ánh sáng và quy trình hiện hữu.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('040da6fa-c3d7-480c-b03d-74b9d16c824d', '60488501-198f-51f9-b9a3-e9d658985077', 4, 'Số 720 triệu của B có phải TCO đầy đủ?', 'Không. Đây là vốn đầu tư cộng vận hành trong ba năm, theo số giả định. TCO thực tế còn cần chi phí tích hợp, dừng máy, đào tạo, nâng cấp và các khoản thích hợp khác.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d2160995-90e7-423a-99d0-13601bfb11ee', '60488501-198f-51f9-b9a3-e9d658985077', 5, 'Tại sao vẫn giữ hệ thống C để thử dù điểm thấp hơn B?', 'Điểm phụ thuộc giả định và trọng số. C có thể phù hợp khi quy mô tăng hoặc tích hợp được cải thiện. Phải kiểm thử và thẩm định theo bối cảnh mới.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('48a89ba9-5e9c-4f36-bb5a-884149adb22a', 'fd3de369-9eb3-5db4-8ea7-7ad82868415e', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d900c37a-e615-4639-adda-52b4f7b4417b', '60488501-198f-51f9-b9a3-e9d658985077', 6, 'Điểm ma trận cao có đủ để quyết định đầu tư?', 'Không. Điều kiện bắt buộc, bằng chứng thử nghiệm, an toàn, nguồn lực và phê duyệt đầu tư vẫn phải được đáp ứng.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('eae66c0e-0de0-430c-9889-bcaa6cc25a54', '60488501-198f-51f9-b9a3-e9d658985077', 7, 'Phải làm gì khi không có dữ liệu về năng lực đội ngũ?', 'Đánh dấu chưa xác minh, đánh giá kỹ năng, kế hoạch đào tạo, trách nhiệm bảo trì và rủi ro phụ thuộc nhà cung cấp trước khi kết luận.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7c468583-74a3-4d26-a886-383c6d29637f', '60488501-198f-51f9-b9a3-e9d658985077', 8, 'Bài thực hành dùng các số liệu A/B/C làm báo giá được không?', 'Không. Các mức giá, chi phí, công suất và điểm số đều là giả định phục vụ đào tạo; doanh nghiệp phải thu hồ sơ, báo giá và kết quả đo thực tế.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5c3c33e1-aaad-4478-afc5-c7aa21f06c5c', '05cd1d76-9728-5680-8053-975784ac47d1', 1, 'Bộ tiêu chí của mọi doanh nghiệp có giống nhau không?', 'Không. Cần chọn theo nhiệm vụ, điều kiện bắt buộc, quy mô, dữ liệu và nguồn lực của doanh nghiệp. Ví dụ An Bình chỉ là minh họa.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0b958601-de66-433c-8894-13056bbe3cbb', '05cd1d76-9728-5680-8053-975784ac47d1', 2, 'Vì sao phải tách điều kiện bắt buộc ra khỏi ma trận?', 'Vì điểm cao ở giá hoặc dịch vụ không làm một hệ thống có được chức năng bắt buộc hay năng lực đã xác nhận mà nó không có.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('bf573752-1a54-45ff-9f6e-12c767b96dbe', '05cd1d76-9728-5680-8053-975784ac47d1', 3, 'Nếu không có dữ liệu để cho điểm thì nên ghi thế nào?', 'Ghi chờ xác minh, yêu cầu dữ liệu hay thử nghiệm và người chịu trách nhiệm. Không tự đặt điểm giữa hoặc điểm cao để lấp khoảng trống.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f7eb7d70-fd89-4050-a5b1-5da080987b73', '05cd1d76-9728-5680-8053-975784ac47d1', 4, 'Điểm một và năm cần phân biệt như thế nào?', 'Phải có mô tả quan sát được theo cùng điều kiện. Điểm năm cần bằng chứng mạnh hơn điểm ba; không căn cứ vào ngôn ngữ quảng cáo.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5bccf37e-d0b0-462a-8f59-0180bbc1725a', '05cd1d76-9728-5680-8053-975784ac47d1', 5, 'Chọn trọng số bằng cách nào?', 'Xuất phát từ ưu tiên kinh doanh, tiêu chí chốt trước và thảo luận giữa các bộ phận. Ghi lý do, tổng bằng 100%, thử độ nhạy.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('93278bba-a089-4b79-a5cb-07bf4225a56b', '05cd1d76-9728-5680-8053-975784ac47d1', 6, 'Một phương án điểm 4,00 có chắc tốt hơn phương án 3,85?', 'Không chắc. Khoảng cách phụ thuộc giả định, trọng số và độ tin cậy của điểm. Cần thử độ nhạy và xác minh điều kiện bắt buộc.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('89f12e77-441e-4084-8a8b-07dcd175893f', '05cd1d76-9728-5680-8053-975784ac47d1', 7, 'Nếu thay trọng số thì có phải sửa lại mọi điểm?', 'Không nhất thiết. Điểm phản ánh đánh giá từng tiêu chí, trọng số phản ánh mức ưu tiên. Chỉ sửa điểm khi có bằng chứng hoặc cách đánh giá mới.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d13fa149-c950-4e1a-8b0a-d4860c0a3a76', '05cd1d76-9728-5680-8053-975784ac47d1', 8, 'Có thể dùng ma trận để phê duyệt mua máy ngay không?', 'Không. Ma trận là một phần hồ sơ. Trước đầu tư cần bằng chứng thử, an toàn, chi phí, điều kiện hợp đồng, bảo trì và thẩm quyền phê duyệt.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('cfc4d345-08af-4234-9989-99e2d2c6f517', '3bee64ab-aa58-568d-9644-4fcc98021485', 1, 'Giá mua máy có phải là toàn bộ CAPEX?', 'Không. Cần tính thêm phần tích hợp, lắp đặt, đào tạo và các khoản chi thực tế để đưa hệ thống vào sử dụng. Một khoản đã nằm trong hợp đồng không cộng lần thứ hai.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('4c31554a-c6d4-461a-bcf1-6df8a37e7a00', '3bee64ab-aa58-568d-9644-4fcc98021485', 2, 'Phí thuê phần mềm trả theo năm đưa vào đâu?', 'Trong mô hình này là OPEX hằng năm. Nếu hợp đồng trả trước nhiều năm, phải điều chỉnh theo thời điểm dòng tiền và nêu rõ phạm vi.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('95ae1897-5d53-4dd6-bffd-9fd79de9a1d0', '3bee64ab-aa58-568d-9644-4fcc98021485', 3, 'Vì sao phải chọn cùng kỳ khi so TCO?', 'Nếu một bên tính ba năm và bên kia năm năm, kết quả không so trực tiếp được. Phải dùng cùng thời hạn, giả định sản lượng và phạm vi chi phí.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9771e6bc-0284-4ebc-84b9-f625b63604b2', '3bee64ab-aa58-568d-9644-4fcc98021485', 4, 'TCO 780 triệu có nghĩa doanh nghiệp lỗ 780 triệu?', 'Không. TCO là tổng chi phí theo phạm vi mô hình; chưa phản ánh tiền tiết kiệm hoặc doanh thu tăng thêm. Không gọi TCO là lỗ hay lợi nhuận.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b2fd58c2-cc1d-4636-aed5-87a534e3cd6c', '3bee64ab-aa58-568d-9644-4fcc98021485', 5, 'Có nên trừ giá trị bán lại máy khỏi TCO?', 'Chỉ khi có căn cứ về giá trị thu hồi sau kỳ xét. Nếu chưa có, ghi là chưa xác minh hoặc đặt bằng không trong phép tính thận trọng.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('06fa6e29-7987-4d72-abef-bbf65bb8dc55', '3bee64ab-aa58-568d-9644-4fcc98021485', 6, 'Hoàn vốn có phải lấy 480 chia 300?', 'Không. Trong ví dụ, 300 triệu là tiết kiệm gộp. Trừ OPEX 100 triệu/năm, dòng tiền thuần tăng thêm 200 triệu/năm; hoàn vốn đơn giản = 480/200 = 2,4 năm.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('19e103f0-2300-4f38-a678-c81540e39f07', '3bee64ab-aa58-568d-9644-4fcc98021485', 7, 'Nếu dự án không giảm khoản chi tiền mặt thì sao?', 'Đó có thể là lợi ích năng lực hoặc chất lượng. Cần mô tả riêng, không tự quy thành dòng tiền để làm ngắn thời gian hoàn vốn. Có thể phải dùng phương pháp đánh giá khác.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a1ed615a-991b-4c46-8938-eaef4047959d', '3bee64ab-aa58-568d-9644-4fcc98021485', 8, 'Hoàn vốn 2,4 năm đã đủ để phê duyệt đầu tư?', 'Chưa. Phải xác minh tiền tiết kiệm, chi phí, rủi ro và dòng tiền theo từng năm. Hoàn vốn đơn giản không tính giá trị thời gian của tiền; cân nhắc NPV/IRR khi thẩm định sâu.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c144b745-e008-408e-baa8-e0287a0c4e8b', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 1, 'Vì sao không so riêng tổng số kWh của hai tháng?', 'Sản lượng, số ca và loại sản phẩm có thể khác. Cần xem cả kWh trên sản phẩm đạt trong cùng phạm vi và kỳ đo đại diện.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('998ef89f-1949-4f98-9ba7-5d589af69473', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 2, 'Vì sao dùng túi đạt thay vì túi đầu vào?', 'Đơn vị chức năng của ví dụ là sản phẩm đáp ứng yêu cầu. Chia cho túi đạt giúp phản ánh cả phần sản xuất không đạt; phải mô tả cách đếm thống nhất.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ce73cc8e-a40a-4e73-b03f-71814de3c266', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 3, 'Điện ít hơn có đủ để gọi công nghệ xanh không?', 'Không. Phải xem chất lượng, rác, an toàn, tiếng ồn, nguồn nguyên liệu và phạm vi vòng đời khi có dữ liệu.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('189a69cb-7252-4e93-a008-905e50e091cd', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 4, 'Hệ số 0,60 kg CO₂e/kWh có được dùng báo cáo chính thức?', 'Không. Đây chỉ là hệ số tự đặt cho bài tập. Báo cáo thực tế phải xác định nguồn, năm, địa bàn, ranh giới và phương pháp tính phù hợp.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('692ab0d0-105e-4a96-88ae-1f7516df85f4', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 5, 'Rác 35 kg có thấp hơn rác 50 kg nếu sản lượng khác nhau?', 'Chưa chắc trên sản phẩm đạt. Hãy tính kg rác/1.000 sản phẩm đạt và kiểm tra loại rác, kỳ đo, điều kiện quy trình tương đương.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5bdcd3bd-d6bf-4b2b-9fe5-20354cae97de', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 6, 'Có thể cộng kg rác với kg CO₂e để tính chỉ số xanh?', 'Không thể cộng trực tiếp hai đại lượng. Nếu xây điểm đa tiêu chí, phải định nghĩa cách chuẩn hóa, trọng số, điều kiện loại trừ và nguồn dữ liệu riêng.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f47f885f-d4b2-4793-af31-e7d28872f97b', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 7, 'CO₂e từ điện đã là dấu chân carbon của cả thiết bị chưa?', 'Chưa. Phép tính trong phiếu không có sản xuất thiết bị, vận tải, vật liệu, xử lý rác hay điện ngoài phạm vi. Đây không phải đánh giá vòng đời.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c8ee3907-d5cc-44da-80d7-39b4a8e74996', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 8, 'B giảm điện 8% và rác 37,5% đã đủ để mua chưa?', 'Chưa. Đó là dữ liệu giả định. Cần kiểm tra hiệu quả phát hiện lỗi, an toàn, điều kiện vận hành, chi phí, phép đo thực tế và các tác động còn thiếu.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1b5ae2f3-820c-4bf6-9b1b-69a46a5843a9', '0c0953ac-233f-5928-8c22-045b5eea81b2', 1, 'Rủi ro và vấn đề đang xảy ra khác nhau ra sao?', 'Vấn đề là sự việc đã quan sát. Rủi ro là sự kiện bất định có thể ảnh hưởng mục tiêu. Một vấn đề đã xảy ra có thể là bằng chứng để dự báo rủi ro tái diễn.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a744f1a5-9624-4e71-a421-dc2cf1d75c28', '0c0953ac-233f-5928-8c22-045b5eea81b2', 2, 'P nhân I có phải tỷ lệ phần trăm thất bại?', 'Không. P và I trong bài là điểm thứ bậc 1-5. Tích chỉ giúp sàng lọc và thảo luận ưu tiên, không dùng như xác suất hay số tiền tổn thất.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('68e32849-51f9-43c0-9db8-93d8ec6c6e86', '0c0953ac-233f-5928-8c22-045b5eea81b2', 3, 'Điểm rủi ro trung bình có nghĩa được phép ký hợp đồng?', 'Không. Điều kiện bắt buộc về quyền sử dụng, an toàn và tính hợp lệ của bằng chứng cần được xác minh riêng, kể cả khi điểm thấp.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8ea32220-3b94-4bd4-bbb5-7a516b4e08a2', '0c0953ac-233f-5928-8c22-045b5eea81b2', 4, 'Bằng chứng “đã có” cần đạt điều gì?', 'Phải là tài liệu có thể kiểm tra được nguồn, hiệu lực, phạm vi và người xác nhận. Một file marketing hoặc khẳng định miệng chưa đủ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c1182aa8-efab-4831-ac9e-2a0427a36cff', '0c0953ac-233f-5928-8c22-045b5eea81b2', 5, 'Làm gì khi nhà cung cấp không cho xuất dữ liệu?', 'Yêu cầu tệp mẫu, tài liệu giao diện và phép thử chuyển đổi. Nếu không đáp ứng yêu cầu bắt buộc của doanh nghiệp, không chốt lựa chọn.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3ae7051f-3b23-4613-959b-7abd1de1bd1f', '0c0953ac-233f-5928-8c22-045b5eea81b2', 6, 'Có nên cộng điểm tất cả rủi ro để xếp hạng nhà cung cấp?', 'Không nên dùng phép cộng thô làm kết luận. Rủi ro khác nhau về loại hậu quả, điều kiện bắt buộc và mức tin cậy của điểm; cần phân loại và kiểm soát từng mục.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7d676a77-13ca-4ec4-9d77-72e7529cc119', '0c0953ac-233f-5928-8c22-045b5eea81b2', 7, 'Biện pháp viết trong kế hoạch có làm giảm điểm ngay không?', 'Không. Chỉ chấm lại rủi ro còn lại sau khi thực hiện biện pháp, có kết quả thử và người chịu trách nhiệm xác nhận.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7110ecd5-17f0-46ce-b856-657d5680c86a', '0c0953ac-233f-5928-8c22-045b5eea81b2', 8, 'Khi nào chuyển từ bảng rủi ro sang quyết định đầu tư?', 'Sau khi đóng cổng bắt buộc, thử các rủi ro trọng yếu, xác minh điều khoản với nhà cung cấp và có phê duyệt theo quy trình của doanh nghiệp.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('fd0493f4-86d9-4588-8d0e-46f1992909a9', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 1, 'Tìm chuyên gia khác tìm nhà cung cấp ở điểm nào?', 'Chuyên gia thường hỗ trợ đánh giá hoặc tư vấn chuyên môn; nhà cung cấp chịu trách nhiệm đề xuất và cung ứng giải pháp. Phạm vi phải ghi thành đầu ra và hợp đồng cụ thể.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('843a235b-72f4-45e0-bf41-a812ce26e64c', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 2, 'Có thể chọn một công ty làm cả tư vấn và cung cấp không?', 'Có thể xem xét, nhưng phải xác định phạm vi trách nhiệm, xung đột lợi ích và biện pháp kiểm chứng độc lập. Không mặc định ý kiến tự đánh giá là khách quan.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('4d494bcc-0478-4334-99cd-687aaa2104a9', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 3, 'Dự án từng làm ở ngành khác có đủ chứng minh năng lực không?', 'Không tự động đủ. Cần so điều kiện thiết bị, sản lượng, môi trường, người thực hiện và khả năng cung cấp bằng chứng tương đương.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('792c4357-47e5-494e-b251-67c111053087', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 4, 'Điểm 4,6 có nghĩa xác suất thành công 92% không?', 'Không. Điểm là thang sàng lọc 1-5 với trọng số minh họa, không được diễn giải thành xác suất hoàn thành.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ad46c46b-05ed-4411-b9f9-15e592ce94dd', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 5, 'Nhà tích hợp điểm cao nhưng hồ sơ chưa kiểm chứng có được mời không?', 'Có thể liên hệ để yêu cầu hồ sơ bổ sung. Chưa đưa vào danh sách đủ điều kiện cho buổi chuyên sâu cho đến khi bằng chứng được xác minh và quan hệ lợi ích rõ.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('13dab786-0aa2-4363-a186-4575ed51eab7', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 6, 'Xung đột lợi ích có nghĩa đối tác chắc chắn không đáng tin?', 'Không. Cần khai báo, xác minh và có biện pháp quản lý; một số nhiệm vụ đánh giá độc lập có thể phải giao cho bên khác.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b78469e1-70c8-4e3b-b80a-4169ee1fd611', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 7, 'Có nên gửi ngay bộ ảnh lỗi và dữ liệu khách hàng khi hỏi báo giá?', 'Không. Phân loại dữ liệu, xác định mục đích và người nhận; chỉ chia sẻ tối thiểu và đáp ứng yêu cầu bảo mật, quyền sử dụng trước khi chuyển.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('67b89fd0-1dc7-4b35-adc2-7ffc7581a8fa', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 8, 'Khi nào cuộc kết nối được coi là có kết quả?', 'Khi đã ghi rõ phương án tiếp cận, bằng chứng còn thiếu, người phụ trách, hạn phản hồi và điều kiện chuyển sang thử nghiệm hoặc thẩm định.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('40206f94-c94d-4e83-a701-70e0df0dde57', 'ff65e401-5641-52eb-92a0-b93256b41783', 1, 'Có cần chọn công nghệ ngay trong phiên kết nối không?', 'Không. Phiên sơ bộ có thể dùng để hiểu nhu cầu, phương án và yêu cầu bằng chứng. Quyết định mua sắm cần thẩm định, thẩm quyền và quy trình riêng.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('63c33ba2-9694-4e14-ac20-be9eefd230bf', 'ff65e401-5641-52eb-92a0-b93256b41783', 2, 'Ai phải điều phối khi doanh nghiệp và nhà cung cấp bất đồng?', 'Nên có điều phối viên được chỉ định. Người này ghi riêng tuyên bố của từng bên, điều kiện thử và việc cần kiểm; không tự kết luận thay chuyên gia.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('57835669-23d4-4f1e-a3b0-312b5366e288', 'ff65e401-5641-52eb-92a0-b93256b41783', 3, 'Agenda 45 phút có bắt buộc không?', 'Không. Đây là ví dụ thực hành. Thời lượng cần theo độ phức tạp, số bên và sản phẩm đầu ra; luôn dành thời gian chốt công việc.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('e061ff3d-d438-47dd-b802-9521c570f7a8', 'ff65e401-5641-52eb-92a0-b93256b41783', 4, 'Tuyên bố “99% chính xác” có đủ đưa vào biên bản như kết quả không?', 'Chỉ được ghi là tuyên bố của bên cung nếu chưa có bằng chứng. Cần mẫu, nhãn chuẩn, điều kiện, định nghĩa chỉ số và log thử để xác minh.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('e57bc7d4-f3ce-4b2b-b8cf-543c7258202a', 'ff65e401-5641-52eb-92a0-b93256b41783', 5, 'Một tài liệu brochure có được tính là bằng chứng thử không?', 'Brochure có thể xác nhận một thông số được công bố, nhưng không thay nhật ký và báo cáo phép thử trong điều kiện tương đương.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('adcb4cc6-d023-4d72-bba1-beb1b83cddd1', 'ff65e401-5641-52eb-92a0-b93256b41783', 6, 'Thời gian vượt kế hoạch có nghĩa phiên kết nối thất bại không?', 'Không tự động. Hãy xem phần vượt giờ có tạo sản phẩm cần thiết hay làm mất phần chốt việc. Bảng thời gian chỉ hỗ trợ quản lý cuộc họp.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('322764c3-ff3e-43bd-8fc9-b2c5e60d6fce', 'ff65e401-5641-52eb-92a0-b93256b41783', 7, 'Có nên chia sẻ toàn bộ ảnh lỗi, mã lô, dữ liệu khách hàng cho bên cung không?', 'Không mặc định. Phải phân loại dữ liệu, kiểm quyền truy cập và chỉ chia sẻ phần cần thiết theo điều kiện được phê duyệt.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d27ae558-3948-4f1d-a0f6-3afbb18a4cf5', 'ff65e401-5641-52eb-92a0-b93256b41783', 8, 'Làm sao biết một đầu việc sau họp đã được đóng?', 'Cần người phụ trách, hạn và tiêu chí hoàn thành cụ thể, ví dụ nhận đúng log thử phiên bản xác định, không chỉ có lời hứa qua điện thoại.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('56f055eb-d5e7-4852-9680-fdb622855815', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 1, 'PoC có phải thí điểm triển khai dây chuyền không?', 'Không nhất thiết. PoC thường kiểm một giả thuyết chức năng trong phạm vi hạn chế. Thí điểm vận hành cần đánh giá thêm ca sản xuất, tích hợp, con người và bảo trì.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b1f4e531-b9a1-4b26-b567-9cc1149696a4', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 2, 'Chỉ số “chính xác 96%” có đủ kết luận không?', 'Không. Trong ví dụ, chính xác chung 96%, phát hiện 96% nhưng loại nhầm 4%, vượt ngưỡng 3%. Cần nêu mẫu số và từng hậu quả.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d2fb9191-e326-4b75-b53a-220487c0d9db', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 3, 'Làm thế nào tránh nhà cung cấp thử trên bộ ảnh đã học trước?', 'Tách bộ hiệu chỉnh khỏi bộ đánh giá, niêm danh mục mẫu, lưu phiên bản và yêu cầu người có trách nhiệm độc lập kiểm nhãn chuẩn.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('48b4c880-c710-4293-9a6c-9e6b4289dd06', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 4, 'Có được tự đổi số đếm trong Excel để làm PoC đạt không?', 'Chỉ được đổi số để học cách dùng công thức. Hồ sơ thật phải ghi dữ liệu gốc của lần thử mới; mọi thay đổi có nguồn, phiên bản và nhật ký.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9582077f-521d-4a66-99b1-53aedd78d263', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 5, 'Nếu không có mẫu lỗi đủ nhiều thì xử lý thế nào?', 'Nêu hạn chế về số lượng và tính đại diện; thiết kế thêm cách thu mẫu hợp lệ. Không suy rộng tỷ lệ từ số mẫu ít mà không đánh giá độ không chắc chắn.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('4922bc0c-4d02-4cfd-bec4-45e268953d6c', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 6, 'Chi phí PoC có phải tổng chi phí sở hữu không?', 'Không. 18 triệu trong ví dụ chỉ là chi phí thử giả định. TCO phải xét đầu tư, vận hành, đào tạo, bảo trì, dữ liệu, kết thúc sử dụng và kỳ so sánh.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('411765e2-ea92-4e61-a6c8-5e0a56eec7b3', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 7, 'Nếu PoC đạt nhưng dữ liệu chưa được phép chia sẻ thì sao?', 'Không vượt cổng quyền dữ liệu. Phần sử dụng dữ liệu liên quan phải dừng hoặc thu hẹp cho đến khi được người có thẩm quyền cho phép.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('08460347-169d-4546-b9d8-2ef7a3184e21', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 8, 'Khi nào được đề xuất chuyển sang pilot?', 'Khi phép thử đủ tin cậy, chỉ số đạt ngưỡng đã thống nhất và các cổng bắt buộc được xác minh. Đề xuất pilot vẫn cần phê duyệt riêng.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a8dd37b4-d938-4d42-a86b-2eeb7f22f119', 'f18c0159-faed-555c-9ff4-5e727391c028', 1, 'PoC ở Bài 28 chưa đạt, sao Bài 29 đã có thí điểm?', 'Bài 29 là tình huống giả định độc lập về thí điểm sau một bước phê duyệt riêng. Không suy ra PoC ở Bài 28 đã đạt hoặc được phép triển khai thực tế.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5c6001c5-2c6a-40f0-b4f1-8620495e6a78', 'f18c0159-faed-555c-9ff4-5e727391c028', 2, 'Vì sao phải có cả tỷ lệ phát hiện và loại nhầm?', 'Hai tỷ lệ dùng hai mẫu số khác nhau. Bỏ sót mẫu lỗi và loại nhầm mẫu tốt có hậu quả vận hành khác nhau; chính xác chung không thay thế được.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('afa81e57-6733-4b6c-8a0b-47add7b8b7cd', 'f18c0159-faed-555c-9ff4-5e727391c028', 3, 'Có được lấy kết quả tuần 4 để chứng minh đạt không?', 'Chỉ khi đề cương đã định rõ tuần 4 là phạm vi nghiệm thu và có lý do có căn cứ. Ví dụ này đánh giá tổng bốn tuần, nên tỷ lệ gộp 94% chưa đạt.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8464c3fe-eb4c-40da-a499-9051a576c085', 'f18c0159-faed-555c-9ff4-5e727391c028', 4, 'Tại sao sẵn sàng không bằng 100% trừ mọi giờ nghỉ?', 'Mẫu số là giờ dự kiến chạy theo kế hoạch; giờ dừng trong phạm vi đo được định nghĩa trước. Nghỉ ca kế hoạch không mặc nhiên là sự cố thiết bị.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b7153344-e311-4827-accd-71fdcf404152', 'f18c0159-faed-555c-9ff4-5e727391c028', 5, 'Tốc độ trung bình 45,5 có chứng minh không còn tắc nghẽn không?', 'Không. Đó là bình quân bốn cửa sổ có độ dài bằng nhau, chưa kiểm khác biệt theo ca, sản phẩm, mức lỗi và công đoạn trước sau.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('960831bb-d027-4d55-a314-bb59c89d7a8a', 'f18c0159-faed-555c-9ff4-5e727391c028', 6, 'Nếu một cổng an toàn chưa kiểm thì điểm KPI cao có bù được không?', 'Không. Phần thử liên quan phải dừng đến khi có người có thẩm quyền xác minh và phê duyệt. Điểm KPI chỉ được xét sau cổng.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3be71b7a-7004-4070-a935-b2ea93e9e8cb', 'f18c0159-faed-555c-9ff4-5e727391c028', 7, 'Khi tỷ lệ phát hiện 94% thì có phải loại vĩnh viễn giải pháp?', 'Không mặc nhiên. Cần xem nguyên nhân, chi phí sửa, mức rủi ro và quyết định của người có thẩm quyền. Có thể điều chỉnh rồi tổ chức thử mới độc lập.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('94778ef9-f19e-457d-9d63-88bcab0938e5', 'f18c0159-faed-555c-9ff4-5e727391c028', 8, 'Khi nào được đề xuất nhân rộng?', 'Sau khi đủ cổng, đạt mọi KPI có chứng cứ, kiểm tính đại diện, phân tích chi phí và phương án vận hành. Kết quả pilot không tự phê duyệt mua sắm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d1e241a5-f770-4e32-9b7d-744385f37b9f', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 1, 'Bài 29 mặc định chưa đạt, tại sao Bài 30 nói đến tiếp nhận?', 'Bài 30 là tình huống đào tạo giả định có giai đoạn xử lý sai lệch, kiểm chứng lại và phê duyệt riêng. Không suy ra thí điểm trong Bài 29 đã đạt hoặc việc nhân rộng được phê duyệt.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f053252f-eb39-4559-9171-e422a983e2eb', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 2, 'Ký biên bản nghiệm thu là đủ để nhận công nghệ chưa?', 'Chưa. Cần khả năng kiểm tài liệu đúng phiên bản, truy cập cấu hình, thử SOP, chứng cứ chất lượng, sao lưu, quyền dữ liệu và trách nhiệm hỗ trợ. Biên bản phải liên kết các bằng chứng.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d61577e8-e6db-4819-bc88-a44ca89ee205', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 3, 'Vì sao số người đã học khác số người đủ năng lực?', 'Tham dự lớp chỉ xác nhận đã học. Đủ năng lực cần vượt kiểm tra thao tác theo vai trò, được người có trách nhiệm ký và lưu lại lỗi cần bồi dưỡng.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7ec3b0d0-98be-499f-8ede-b6db812e52ee', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 4, 'Tại sao dùng 13/16 chứ không phải 13/15?', 'Bài đo mức sẵn sàng nhân sự trên toàn bộ 16 vị trí cần có. 13/15 là tỷ lệ người đã học vượt bài thực hành, trả lời câu hỏi khác và không thay được tỷ lệ nhân sự sẵn sàng.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('851a92a2-29c7-4e23-9319-7f76ab567034', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 5, 'Có thể giảm ngưỡng đào tạo xuống sau khi thấy kết quả không?', 'Không tùy tiện. Ngưỡng phải có căn cứ và chốt trước khi đánh giá. Nếu phải điều chỉnh phải có kiểm tra rủi ro, phê duyệt, lưu phiên bản và áp dụng minh bạch.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('83c1848c-29b6-4fe9-84fb-84338b5af98c', 'fd3de369-9eb3-5db4-8ea7-7ad82868415e', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6906957a-1725-4f0f-be0f-f87a3ab6db6e', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 6, 'Nếu đủ KPI kỹ thuật nhưng cổng an toàn hoặc dữ liệu chưa kiểm thì sao?', 'Tạm dừng bước có liên quan cho tới khi có bằng chứng phù hợp. Không cộng điểm đạt kỹ thuật để bù điều kiện pháp lý, an toàn hoặc năng lực khôi phục.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ab97b8ea-a2a1-4d3d-b992-5ffbfb14b49d', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 7, 'Khi bổ sung đủ người, Excel hiện đề xuất mở rộng có nghĩa đã được duyệt?', 'Không. Phiếu chỉ nêu trạng thái đủ điều kiện sơ bộ để trình xét. Người có thẩm quyền còn phải đánh giá ngân sách, mức đại diện giữa ca, an toàn, hợp đồng và quyết định từng giai đoạn.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('df8ddfc8-1fde-4623-8e2f-cdc915905518', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 8, 'Mở rộng xong thì cần theo dõi thêm gì?', 'Theo dõi lỗi QC, loại nhầm, thời gian dừng, kỹ năng người vận hành, phiên bản và quyền dữ liệu, năng lực hỗ trợ, chi phí cùng các sự cố phải quay lui theo SOP.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8a6c6c85-3fe5-48a6-a105-3a267aa5a267', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Bản đồ công nghệ mới: những xu hướng đang thay đổi doanh nghiệp và sản xuất như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('09b1d932-f3ca-4067-8117-c0e1d4d4dae6', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('d6e33929-6648-4a6e-a1b4-123b2048292f', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('e5907997-5b3b-473d-a267-bd9a81051fc2', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5b5a4d9e-3872-47b1-a306-c9fd4db6a109', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 5, 'Chi phí thử nghiệm PoC thường chiếm bao nhiêu?', 'Thông thường khoảng 5-15% tổng chi phí dự án, giúp phòng ngừa 80% rủi ro thất bại.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('75e2107c-efe1-46e0-ad49-ec4a8f31a5f7', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('70125505-b066-4ef7-afb5-39cfc4097a43', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1a0fac41-8318-4b13-b0d6-2d713d68b567', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a98932cf-ec9d-4180-9a45-12f7d527ce2c', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 1, 'Một công nghệ được nhắc đến nhiều có đồng nghĩa đang được áp dụng rộng?', 'Không. Tần suất truyền thông là tín hiệu về mức quan tâm; cần dữ liệu áp dụng có phạm vi, nguồn và thời gian để kết luận về triển khai thực tế.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('01ef065d-759e-410c-bca2-4f7c0c434c5a', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 2, 'Có nên dùng một báo cáo từ nhà cung cấp để xếp hạng?', 'Có thể dùng để xác định đặc tính và câu hỏi tiếp theo, nhưng phải ghi lợi ích, xung đột lợi ích, mẫu thử, giới hạn và tìm bằng chứng có thể đối chiếu.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9f6743eb-682d-4af1-ab98-d4900469a65b', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 3, 'Nếu không có số liệu thị trường thì học viên chấm điểm thế nào?', 'Chỉ chấm trong tình huống An Bình giả định, nêu cơ sở chuyên gia cho từng điểm; không gán điểm thành số liệu thị trường hoặc dự báo.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('93c4ac0c-a5c9-4099-92d8-c64fb95017f0', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 4, 'Vì sao phải đảo chiều điểm phụ thuộc nhà cung cấp?', 'Thang 1-5 được định nghĩa 5 là phụ thuộc cao, nên tính mức thuận lợi là 6 trừ điểm phụ thuộc. Nếu nhân trực tiếp sẽ thưởng cho rủi ro cao.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c945fb96-2b2a-44fb-b986-2615003eef63', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 5, 'Điểm 4,35 có nghĩa OCR chắc chắn tốt hơn mọi giải pháp khác?', 'Không. Chỉ là kết quả minh họa theo mục tiêu, trọng số và giả định hiện có của An Bình. Khi thay tình huống hoặc bằng chứng, kết quả có thể thay đổi.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f35189fd-67ac-4cc7-b12f-a8d494794698', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 6, 'Đã kiểm nguồn có đồng nghĩa đã xác nhận hiệu năng thực tế?', 'Không. Trong phiếu, đã kiểm nguồn chỉ xác nhận xuất xứ, phiên bản và phạm vi hồ sơ sơ bộ. Hiệu năng cần thử có phương pháp và mẫu phù hợp.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('098e5b00-6e9e-4613-a49d-66ef290063da', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 7, 'Tại sao điểm B trên ngưỡng mà vẫn chưa đề nghị thử?', 'B chưa đối chiếu nguồn và các nội dung liên quan dữ liệu. Điểm số không bù cổng chứng cứ, quyền sử dụng hoặc an toàn.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('72c57a7a-5e8d-47a7-8442-1024a8abe3e8', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 8, 'Có cần cập nhật danh mục theo dõi?', 'Có. Lưu thời điểm, nguồn mới, người chấm và phiên bản trọng số; điều chỉnh theo vấn đề của doanh nghiệp và không thay đổi lịch sử bản đánh giá cũ.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6789c22f-8034-4bc0-ad59-e26b831f4eaa', '6721da87-6494-5fd4-9cc7-6163a275f01a', 1, 'Doanh nghiệp có cần dữ liệu lớn mới được bắt đầu AI?', 'Không có một số lượng chung cho mọi bài toán. Cần xét lỗi hiếm, độ đa dạng, nhãn, quyền dữ liệu và độ ổn định; có thể bắt đầu bằng đo và làm sạch dữ liệu.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7fcb3e82-178d-4462-b3bd-4aea91680c97', '6721da87-6494-5fd4-9cc7-6163a275f01a', 2, 'Khi nào không cần AI?', 'Nếu quy tắc, tra cứu có kiểm duyệt hoặc tự động hóa thông thường đã đạt KPI với chi phí và rủi ro hợp lý, không cần triển khai AI cho tác vụ đó.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ae5f45ac-6781-4cb3-9a4f-6980479cdcc4', '6721da87-6494-5fd4-9cc7-6163a275f01a', 3, 'Có 85% dữ liệu dùng được thì mô hình chắc chắn đủ tốt?', 'Không. 85% chỉ là tỷ lệ hồ sơ theo định nghĩa đã chọn. Cần kiểm mẫu đại diện, chất lượng nhãn, nhóm hiếm và kết quả trên bộ kiểm độc lập.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('399d2c97-50b5-4538-b5b2-3a48fcfe37ea', '6721da87-6494-5fd4-9cc7-6163a275f01a', 4, 'Có thể tải SOP lên trợ lý AI miễn phí không?', 'Không nên trước khi xác nhận quyền xử lý, chính sách dữ liệu, nơi lưu, truy cập và phê duyệt nội bộ. Không sử dụng dữ liệu thật trong bài tập.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('cfbb2ce6-741c-4d1e-b6d3-42cc37eda19c', '6721da87-6494-5fd4-9cc7-6163a275f01a', 5, 'Vì sao D đạt tác động cao mà chưa đưa vào thử?', 'Trong ví dụ, chỉ 12/30 sự cố được ghi đủ, tương đương 40%, thấp hơn ngưỡng sàng lọc giả định 75%. Cần bổ sung và đánh giá chất lượng sự cố.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('cbde1387-0cc9-459d-838e-00dedc53f79f', '6721da87-6494-5fd4-9cc7-6163a275f01a', 6, 'Điểm A bằng 4,53 có nghĩa AI đem lại lợi nhuận?', 'Không. Đây là điểm thứ tự ưu tiên, không phải ROI, xác suất thành công hay bằng chứng hiệu năng. Phải đo với đối chứng và các chi phí đầy đủ.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8fb04864-dade-4253-b2b0-db1b753d52bc', '6721da87-6494-5fd4-9cc7-6163a275f01a', 7, 'Cổng quyền dữ liệu chưa kiểm, có thể làm thử nội bộ?', 'Chỉ được thử khi phạm vi, quyền dữ liệu, an toàn, người phê duyệt đã được xác nhận theo quy trình của doanh nghiệp. Bảng mặc định giữ trạng thái chưa mở thử.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('116af754-3c84-46a8-b8f1-62402afd3f1e', '6721da87-6494-5fd4-9cc7-6163a275f01a', 8, 'Bước tiếp theo sau khi chọn bài toán là gì?', 'Lập brief thử nhỏ: chủ quy trình, đường cơ sở, cách không AI, bộ kiểm độc lập, KPI và ngưỡng, trần chi, rủi ro, điểm dừng và người duyệt.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0b9b2191-ed52-416d-bdfa-6167df6fedf0', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Nhà máy thông minh: lộ trình từ số hóa đến sản xuất thông minh như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0b2c6413-c465-429c-8b66-bbb1878175ce', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('8e40ac99-1c4d-47df-a274-bd7463142b24', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('02c90698-896b-4c80-83d1-7e15a0c490da', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('a6808aa0-2c2f-479f-b9a9-7d79191b4ef2', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 5, 'Chi phí thử nghiệm PoC thường chiếm bao nhiêu?', 'Thông thường khoảng 5-15% tổng chi phí dự án, giúp phòng ngừa 80% rủi ro thất bại.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2d40fdae-cfaf-4999-a275-3e8ef5dc24c6', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('9c008e37-486b-4fd5-ad81-f21ebb4a93b3', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c3eb33e3-1f16-4c08-b9ca-ebb8ed6d539a', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('e63e4939-1890-403e-998c-4cc6c00da28b', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 1, 'Bản đồ công nghệ có phải sơ đồ mạng máy tính hoặc danh sách thiết bị?', 'Không. Trong bài này, bản đồ mô tả công đoạn, năng lực, dữ liệu, KPI, phụ thuộc và chủ sở hữu. Sơ đồ thiết bị chỉ là một lớp thông tin.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('334213f3-d7b1-41d6-9d16-318e865088ce', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 2, 'Doanh nghiệp nhỏ có cần thang năng lực 1-5?', 'Không bắt buộc dùng thang này. Đây là quy ước học tập giúp nhóm đánh giá nhất quán; có thể dùng cấp độ khác nếu mô tả và bằng chứng rõ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('dd1d9d82-c440-4235-94c7-bd12527dc81f', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 3, 'Tại sao mục tiêu không mặc định là 5 ở mọi công đoạn?', 'Mức cần đạt phải gắn KPI, nhu cầu và nguồn lực. Đẩy mục tiêu lên cao khi không có lợi ích xác minh được sẽ làm sai khoảng trống.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('4c67d7e8-8a27-4307-85b7-3e0974a65c4b', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 4, 'Khoảng trống lớn có nghĩa phải đầu tư trước?', 'Không. Khoảng trống được kết hợp với tác động, độ sẵn sàng, phụ thuộc, chi phí và cổng. Điểm chỉ hỗ trợ sắp xếp việc xác minh.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ea71d643-edf5-4dec-b3a2-b81c25935a23', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 5, 'Vì sao C có điểm 4,40 nhưng chưa được triển khai?', 'Điểm được tính từ giả định. Cổng quyền dữ liệu và an toàn trong phiếu còn Chưa kiểm. Cần hoàn thành hồ sơ và quyết định phê duyệt riêng.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7bacdf6b-aac1-453c-a1ad-9a2b68835b5d', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 6, 'Có được coi A là công nghệ đã chứng minh hiệu quả?', 'Không. Thí điểm OCR minh họa tại Bài 29 có tỷ lệ phát hiện lỗi dưới ngưỡng giả định. Cần xác minh cải tiến rồi kiểm độc lập trước bước tiếp.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('ea28f9e6-5231-40ef-98d6-c20a3130360d', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 7, 'Nếu đổi trọng số thì thứ tự có thể thay đổi?', 'Có. Theo ví dụ 25/30/45, D lên 3,15 còn B xuống 2,80. Ghi lý do đổi, người duyệt và phạm vi thay đổi; không chọn trọng số chỉ để đẩy dự án ưa thích.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2908d5d6-199b-42ad-97e4-ae46ecd0d94f', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 8, 'Khi nào cần cập nhật bản đồ và danh mục?', 'Khi KPI, mục tiêu, năng lực, dữ liệu, nhà cung cấp, kết quả thử hoặc ngân sách thay đổi. Ghi ngày, phiên bản và người xác nhận để có thể truy vết.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('7e8ffd07-ee7a-43f8-a109-f04307e830e4', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 1, 'Lộ trình công nghệ khác kế hoạch mua thiết bị ở đâu?', 'Lộ trình bắt đầu từ KPI kinh doanh, có thứ tự phụ thuộc, nguồn lực, bằng chứng theo giai đoạn và cổng quyết định. Danh sách mua thiếu những yếu tố này.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5618c43c-457e-4a75-8360-8ddb02ca8878', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 2, 'Vì sao phải làm ba năm lõi rồi mới xét năm 4-5?', 'Càng xa thời điểm lập, giả định về nhu cầu, giá và khả năng vận hành càng phải được rà soát. Hai năm cuối của bài là phương án có điều kiện, không phải vốn đã cấp.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('e92e06c6-bc57-49b0-b38d-d0d8f4e15429', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 3, 'Bài 35 điểm C cao, có bắt buộc đầu tư trước?', 'Không. Điểm chỉ hỗ trợ sàng lọc. Khi lập lịch phải xét dữ liệu nền, người chịu trách nhiệm, nguồn lực và kết quả kiểm chứng; chuẩn mã sự cố có thể đi trước phân tích nâng cao.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0fb7fd94-f8a0-431f-8d3a-24a42d68a2c4', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 4, 'Bài 29 thử OCR chưa đạt, vì sao vẫn có P4 và P6?', 'P4 là đề xuất sửa lỗi và thử lại có điều kiện, không phải xác nhận đã đạt. P6 chỉ là tùy chọn sau khi P4 có kết quả đạt và cổng dữ liệu, an toàn đã kiểm.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('673346b1-a454-4bc7-9246-eaadfeb0945f', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 5, 'Nếu tổng ngân sách 5 năm nằm trong tổng trần thì có được vượt trần ở một năm?', 'Không tự động. Năm 4 trong ví dụ cần 280 triệu so trần 260, đồng thời 7 người-tháng so trần 6. Chuyển vốn giữa năm hoặc điều chỉnh trần cần thẩm quyền và phiên bản mới.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('1f77c11f-4558-4d61-93a1-4669286c1f29', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 6, 'Người-tháng có phải số nhân viên cần tuyển?', 'Không. Đây là nỗ lực lao động quy đổi; cần kiểm phân công, thời điểm có thể làm, kỹ năng và xung đột với sản xuất, trước khi suy ra nhu cầu tuyển.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2721e1a4-af94-47b8-a8d5-923d29ffef08', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 7, 'Làm sao xử lý khi thiếu 20 triệu năm 4?', 'Có thể chia giai đoạn triển khai hoặc đề xuất thay trần. Cả hai phải báo giá và tính lại nguồn lực; không tự giả định giảm một nửa phạm vi sẽ giảm một nửa chi phí.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('2ab21192-df2a-4319-98b8-ecdbbfa553c5', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 8, 'Khi nào phải mở lại lộ trình để xem xét?', 'Tại kỳ ngân sách hoặc khi KPI, dữ liệu, kết quả thử, quy định, nhà cung cấp, an toàn hay nguồn lực thay đổi. Lưu phiên bản, lý do thay đổi, người đề xuất và người phê duyệt.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('041726d6-1f6b-4b25-b7a1-be74545dc09a', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 1, 'AI tạo sinh có phải công cụ tìm kiếm nội bộ không?', 'Không đồng nhất. AI tạo sinh tạo văn bản, còn tra cứu nội bộ cần cơ chế tìm nguồn được phép, quản trị phiên bản và trả lời kèm căn cứ. Phải kiểm từng câu.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('4aef252a-1870-4219-b376-8580889359a9', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 2, 'Có thể đưa mọi SOP và dữ liệu khách hàng vào trợ lý để học không?', 'Không tự động. Cần phân loại dữ liệu, xác định quyền sử dụng, nơi xử lý, nhóm người truy cập, nhật ký và phê duyệt trước khi đưa vào môi trường thử.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('3d100b90-056e-4f2b-9435-7a418ca59d12', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 3, 'Vì sao prompt “chỉ trả lời đúng” vẫn không đủ?', 'Prompt có thể định hướng hành vi nhưng không bảo đảm độ chính xác, quyền truy cập hay không rò rỉ. Cần kiểm nguồn, phân quyền hệ thống và thử lỗi.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('621df52c-5b11-4473-b504-56cc113be42e', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 4, 'Từ chối trả lời có được chấm đạt không?', 'Có, khi kho được phép không chứa nguồn và trợ lý biết nói thiếu căn cứ, chuyển người có trách nhiệm. Từ chối đúng khác với không đáp được dù đã có nguồn.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f74ceb13-04ae-4f36-8e18-92abcbbd616e', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 5, 'Vì sao có 5/7 câu đạt mà vẫn phải dừng?', 'Tỷ lệ 71,4% dưới ngưỡng giả định 85%; còn một câu bịa nguồn và cổng quyền dữ liệu chưa kiểm. Một lỗi nghiêm trọng không được bù bằng điểm trung bình.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('6a43c27b-7867-4d2c-8894-b1d64608ee3b', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 6, 'Nếu đổi T7 trong Excel sang từ chối đúng, hệ thống đã được sửa chưa?', 'Chưa. Đổi ô chỉ mô phỏng công thức. Phải sửa hệ thống, chạy lại bộ kiểm độc lập, kiểm hồ sơ nguồn và có người duyệt kết quả thực tế.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('f565ceeb-cb30-4885-a104-e43bde45969e', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 7, 'Trợ lý có được tự thay đổi bước dừng máy hay nội dung SOP không?', 'Không. Trợ lý chỉ đưa đề xuất tra cứu hoặc bản nháp trong phạm vi cấp quyền. Việc sửa quy trình và quyết định an toàn vẫn theo thẩm quyền hiện có.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('5fb46c67-d266-410e-a3ff-35443f34d4ae', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 8, 'Khi nào xem xét mở thử cho một nhóm nhân viên?', 'Khi bộ câu đại diện đạt ngưỡng đã xác lập, không còn lỗi bịa nguồn theo quy tắc, đủ cổng tài liệu - dữ liệu - người duyệt, có giới hạn dùng và kế hoạch giám sát. Phê duyệt riêng vẫn bắt buộc.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('b9e86cb0-2ced-4932-9977-2b6e985d2741', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung AI thị giác máy cho kiểm tra chất lượng và giám sát sản xuất như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('aa6a8126-acd3-4849-a58f-226bd207ba0d', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 2, 'Ai là người chịu trách nhiệm chính trong việc thực hiện?', 'Cần có sự phối hợp giữa lãnh đạo doanh nghiệp, quản lý vận hành và bộ phận công nghệ.', 2);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('36bd9fff-a26a-4603-af48-4efcbe485b1c', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 3, 'Nếu chưa có dữ liệu đo lường thì làm thế nào?', 'Cần lập kế hoạch thu thập dữ liệu đường cơ sở tối thiểu từ 2-4 tuần trước khi quyết định.', 3);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('37bec8a9-cf0c-4664-a2db-d2b538410816', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 4, 'Làm sao để biết công nghệ có phù hợp với doanh nghiệp hay không?', 'Sử dụng bộ công cụ tự đánh giá năng lực hấp thụ và thực hiện thử nghiệm PoC quy mô nhỏ.', 4);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('cf3954e7-e6fd-4d00-8f3c-c2dcbfa290f7', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 5, 'Chi phí thử nghiệm PoC thường chiếm bao nhiêu?', 'Thông thường khoảng 5-15% tổng chi phí dự án, giúp phòng ngừa 80% rủi ro thất bại.', 5);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('16bb7e3f-aeb1-4b80-836e-42493bca538f', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 6, 'Có cần thiết phải mua sắm công nghệ đắt tiền nhất không?', 'Không. Công nghệ phù hợp nhất với năng lực vận hành và giải quyết đúng bài toán mới là tối ưu.', 6);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('00b162cd-1076-4c0c-b7e6-08a7a76041a3', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('bb0c0f19-4f7b-4803-a571-e2ed0db6e174', '78d888e3-1f17-553b-b60b-8bdeefcb1799', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('0e5da72a-1d27-495c-83be-e922fb138a43', 'cb466fb9-ebef-52a7-801a-a35c92b5f297', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung IoT công nghiệp và cảm biến thông minh: kết nối dữ liệu thời gian thực như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
