INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('c0f6e5a5-9a53-4f47-99f1-15515c6fe77f', '82ceedce-a9e5-5bb5-ba82-b2cf2c200cf5', 7, 'Nền tảng NacenTech hỗ trợ gì sau khi hoàn thành bài học?', 'Hệ thống hỗ trợ kết nối chuyên gia tư vấn 1-1 và đưa bài toán lên sàn kết nối cung - cầu công nghệ.', 7);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('08fbd073-f6d3-4418-9a29-27485ce63368', '82ceedce-a9e5-5bb5-ba82-b2cf2c200cf5', 8, 'Làm thế nào để nhận chứng nhận hoàn thành khóa học?', 'Học viên cần đạt điểm trắc nghiệm ≥ 60% và tự chấm bài thực hành đạt ≥ 11/14 điểm.', 8);
INSERT INTO lms.learning_faqs (id, material_id, question_number, question_text, answer_text, display_order) VALUES ('47370c7d-8c49-4269-91b3-f19b7c4daf0e', 'cf5de7e4-730f-51ed-8fb9-deb72ae61db9', 1, 'Doanh nghiệp nên bắt đầu áp dụng nội dung Truy xuất nguồn gốc và minh bạch chuỗi cung ứng như thế nào?', 'Nên bắt đầu từ chẩn đoán hiện trạng và xác định đúng điểm nghẽn trước khi tìm kiếm giải pháp.', 1);
