INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('a3197e63-1c53-578d-8d08-7e5866c64a04', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 1, 'EL-015-V15.1', 'VIDEO 15.1: ĐỌC ĐÚNG HỒ SƠ VÀ GIẢI MÃ CÁC THÔNG SỐ KỸ THUẬT', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Mở tình huống: hai con số hấp dẫn", "handwriting": "Hiện từng con số rồi khoanh dấu hỏi cạnh 99%. Chuyển camera góc phải khi hiển thị slide.", "slideContent": "Slide tiêu đề BÀI 15. Trái: ảnh minh họa camera soi nhãn. Phải: \"120 gói/phút\"; \"99% chính xác?\". Chân trang: TOÀN BỘ SỐ LIỆU LÀ GIẢ ĐỊNH.", "lectureScript": "Chào bạn. Doanh nghiệp An Bình đang xem xét một hệ thống camera đọc mã lô và kiểm tra nhãn trên dây chuyền đóng gói cà phê. Hồ sơ chào hàng ghi tốc độ tối đa một trăm hai mươi gói mỗi phút, và độ chính xác chín mươi chín phần trăm. Hai con số nghe rất tốt, nhưng đã đủ để mua chưa? Chưa. Chúng ta còn phải biết nhà cung cấp đo ở điều kiện nào, thiết bị có làm đúng việc của doanh nghiệp không, và dây chuyền hiện có có tiếp nhận được không. Trong bài này, bạn sẽ học cách đọc hồ sơ, đặt câu hỏi kiểm chứng và lập danh sách điều kiện phải xác nhận. Các thông số và doanh nghiệp trong ví dụ đều là giả định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Hồ sơ công nghệ gồm những tài liệu nào?", "handwriting": "Mở từng tập tài liệu; tô dấu kiểm vào tài liệu có bản, đặt dấu ? vào tài liệu còn thiếu.", "slideContent": "Slide 5 tập tài liệu: thông số kỹ thuật; hướng dẫn lắp đặt; mô tả chức năng; báo cáo thử; báo giá, bảo trì và bảo hành. Cột thứ hai: cơ quan ban hành và ngày cập nhật.", "lectureScript": "Trước khi đọc thông số, hãy xem hồ sơ gồm những tài liệu nào. Bản thông số kỹ thuật cho biết nhà sản xuất công bố khả năng của thiết bị. Hướng dẫn lắp đặt nói về điện, vị trí đặt máy và kết nối. Mô tả chức năng giúp xác định thiết bị nhận đầu vào gì và tạo ra đầu ra gì. Báo cáo thử nghiệm cho biết kết quả đã được đo như thế nào. Cuối cùng là điều kiện thương mại, bảo trì và hỗ trợ. Mỗi tài liệu trả lời một câu hỏi khác nhau. Nếu nhà cung cấp chỉ gửi một trang quảng cáo, bạn chưa có hồ sơ đủ để đánh giá ứng dụng. Hãy ghi rõ phiên bản, ngày lập, người phát hành và các tệp còn thiếu."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Phân biệt chức năng với tên thiết bị", "handwriting": "Viết tay đầu vào, đầu ra; bật Q1 sau lời giảng.", "slideContent": "Sơ đồ INPUT -> XỬ LÝ -> OUTPUT: camera nhận hình ảnh nhãn/mã lô -> đối chiếu quy tắc -> cảnh báo hoặc loại sản phẩm. Khung Q1: chức năng trọng tâm.", "lectureScript": "Bước đầu tiên là dịch tên thiết bị thành công việc cần thực hiện. Với An Bình, đầu vào là hình ảnh từng gói cà phê đi qua vị trí kiểm tra. Hệ thống phải phát hiện nhãn sai hoặc mã lô không đọc được, rồi tạo cảnh báo hoặc tín hiệu loại gói. Chúng ta cần hỏi: thiết bị đọc được loại mã nào, có kiểm đúng nội dung mã hay chỉ kiểm sự hiện diện, và khi không đọc được thì dây chuyền xử lý ra sao? Nếu chỉ nhìn dòng camera công nghiệp, bạn chưa biết nó có đáp ứng quy trình của mình hay không. Một hồ sơ tốt phải nối được chức năng công bố với từng bước thao tác thực tế của người dùng."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Đọc tốc độ danh định và điều kiện đo", "handwriting": "Gạch chân chữ \"tối đa\", nối mũi tên đến \"điều kiện thử\" và \"năng suất vận hành\".", "slideContent": "Bảng: \"Công bố: tối đa 120 gói/phút\" | \"Nhu cầu dây chuyền: 75 gói/phút\" | \"Chưa biết: loại nhãn, cự ly camera, tốc độ băng tải, cơ chế loại\".", "lectureScript": "Hồ sơ giả định ghi tốc độ tối đa một trăm hai mươi gói mỗi phút. Đây là mức được công bố, không tự động là năng suất đạt được khi lắp trên dây chuyền. An Bình cần xử lý bảy mươi lăm gói mỗi phút. Muốn so sánh, phải biết thiết bị đã thử với loại bao bì nào, kích thước mã in ra sao, ánh sáng có ổn định không và băng tải có dừng khi loại sản phẩm hay không. Chúng ta cũng cần hỏi năng suất được tính ở thời gian chạy liên tục hay đã trừ thời gian dừng. Khi hai con số không cùng điều kiện đo, không thể chỉ lấy một trăm hai mươi trừ bảy mươi lăm rồi kết luận còn dư năng lực."}, {"layout": "L2 -> L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Giải mã tuyên bố 99% chính xác", "handwriting": "Viết công thức nhận diện lỗi = đúng lỗi / toàn bộ mẫu lỗi; loại nhầm = mẫu tốt bị loại / toàn bộ mẫu tốt; bật Q2.", "slideContent": "Slide đối chiếu 4 chỉ tiêu: nhận diện lỗi, bỏ lọt, loại nhầm, độ đúng chung. Dòng quảng cáo 99% có dấu hỏi về mẫu số và điều kiện. Khung Q2.", "lectureScript": "Tiếp theo là dòng độ chính xác chín mươi chín phần trăm. Chính xác theo nghĩa nào? Nếu có một nghìn gói đạt và rất ít gói lỗi, hệ thống luôn cho qua cũng có thể cho tỷ lệ dự đoán đúng rất cao, nhưng bỏ lọt lỗi cần phát hiện. Vì vậy phải yêu cầu nhà cung cấp định nghĩa chỉ số. Tỷ lệ phát hiện lỗi lấy số gói lỗi được nhận diện chia cho toàn bộ gói thực sự lỗi. Tỷ lệ loại nhầm lấy số gói tốt bị loại chia cho số gói tốt. Hai chỉ số này ảnh hưởng đến chất lượng và sản lượng theo hai cách khác nhau. Chưa biết mẫu thử, cách gán nhãn và điều kiện chạy thì con số chín mươi chín phần trăm chưa đủ để nghiệm thu."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Chốt bộ câu hỏi để đọc hồ sơ", "handwriting": "Tích lần lượt 5 ô; hiện nhiệm vụ đọc lại hồ sơ thực tế đang có.", "slideContent": "Slide checklist: chức năng? giới hạn? điều kiện đo? bằng chứng? phần thiếu? Ở cuối: mở phiếu thực hành, mục A.", "lectureScript": "Đến đây bạn đã có cách đọc phần kỹ thuật đầu tiên. Hãy tìm đúng chức năng cần giải quyết, hiểu đơn vị và mẫu số của từng chỉ tiêu, rồi kiểm tra các điều kiện mà nhà cung cấp đã dùng khi công bố kết quả. Đừng bỏ qua những gì tài liệu chưa nói. Khi đọc một hồ sơ của doanh nghiệp mình, bạn hãy đánh dấu ba trạng thái: có thông tin, có nhưng chưa đủ bằng chứng, và chưa có. Trong phiếu thực hành, hãy ghi nguyên văn thông số được công bố vào cột minh họa hoặc cột của bạn, nhưng tách riêng nhận định đánh giá. Ở video sau, chúng ta sẽ xem thiết bị muốn vận hành được thì phải đáp ứng những điều kiện nào."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('83872c06-db46-5675-a8ee-b9241eb2dbc0', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 2, 'EL-015-V15.2', 'VIDEO 15.2: CHUYỂN THÔNG SỐ THÀNH ĐIỀU KIỆN ỨNG DỤNG TẠI DOANH NGHIỆP', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Từ thông số sang điều kiện lắp đặt", "handwriting": "Phóng đại từng điểm giao tiếp trên dây chuyền, không gán thông số máy thực tế.", "slideContent": "Hiển thị sơ đồ dây chuyền An Bình: in mã -> camera -> cơ cấu loại -> đóng thùng. Trên sơ đồ đặt ô \"vị trí - nguồn lực - người dùng\".", "lectureScript": "Chúng ta chuyển từ việc đọc hồ sơ sang kiểm tra nơi áp dụng. Một camera đọc mã lô không hoạt động độc lập. Nó phải nhận được hình ảnh đủ rõ, xử lý tín hiệu đúng thời điểm và phối hợp với băng tải cùng cơ cấu loại gói. Vì vậy tôi đặt sơ đồ công đoạn trước mặt: máy in mã, vị trí camera, điểm ra tín hiệu, cơ cấu loại và người xử lý gói bị loại. Bất cứ thông số kỹ thuật nào cũng phải được đối chiếu với sơ đồ này. Hãy hỏi từng bộ phận: cần lắp ở đâu, can thiệp vào thiết bị nào, người nào theo dõi cảnh báo và việc dừng hoặc thay đổi thiết bị có cần phê duyệt an toàn không."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Ràng buộc cơ khí, nguồn điện và an toàn", "handwriting": "Tô cam ô thiếu bản vẽ và hướng dẫn điện; không điền trị số không có nguồn.", "slideContent": "Bảng 4 hàng: kích thước và khoảng hở bảo trì; nguồn điện và công suất; gá lắp/độ rung; phương án an toàn khi loại gói. Cột \"đã xác nhận / cần khảo sát\".", "lectureScript": "Ở nhóm điều kiện vật lý, hãy yêu cầu bản vẽ kích thước thật và không gian cần để mở cửa bảo trì. Đừng chỉ đo chiều dài thân máy mà bỏ khoảng thao tác của kỹ thuật viên. Tiếp theo là nguồn điện, công suất, tiếp địa và khả năng chịu môi trường sản xuất. Một đầu mục khác là độ rung băng tải có làm hình ảnh mờ không. Quan trọng hơn, phương án loại gói không được gây nguy hiểm cho người vận hành hoặc làm hỏng thiết bị bên cạnh. Trong tình huống này, chúng ta chưa có bản vẽ lắp đặt hay thông số điện đã được xác nhận. Vì vậy bảng đánh giá phải ghi cần khảo sát, thay vì tự đưa ra con số cho đẹp hồ sơ."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Điều kiện tích hợp tín hiệu và dữ liệu", "handwriting": "Kẻ mũi tên dữ liệu và mũi tên điều khiển hai màu; bật Q3.", "slideContent": "Sơ đồ giao tiếp: camera -> bộ điều khiển -> cơ cấu loại -> nhật ký mã lô. Bên dưới: giao thức? định dạng? độ trễ? quyền truy cập? lưu ảnh? Q3.", "lectureScript": "Phần tích hợp thường bị bỏ sót vì hồ sơ chỉ nói thiết bị có cổng kết nối. Có cổng mạng không có nghĩa là phần mềm hiện tại đọc được dữ liệu. Ta cần hỏi giao thức tín hiệu, định dạng mã lô, cách đồng bộ thời điểm nhận dạng với vị trí gói trên băng tải, và cách xử lý khi mất kết nối. Nếu ảnh sản phẩm được lưu, ai có quyền truy cập và thời gian lưu được quy định thế nào? Dữ liệu thử nghiệm có được đưa ra ngoài doanh nghiệp không? Từng câu hỏi cần một đầu mối kỹ thuật hoặc phụ trách dữ liệu xác nhận. Khi chưa kiểm chứng tương thích, hãy đánh dấu dấu hỏi trong phiếu, không hứa rằng lắp vào là chạy ngay."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Vật liệu, môi trường và con người", "handwriting": "Đổi hình hai mẫu bao bì có độ phản xạ khác nhau; đánh dấu cần thử bằng mẫu thật.", "slideContent": "Bảng điều kiện: phản xạ trên bao bì bóng; màu mực và cỡ ký tự; ánh sáng; thay ca; thay loại gói; hướng dẫn vận hành và bảo trì.", "lectureScript": "Điều kiện ứng dụng không dừng ở thiết bị. Túi cà phê có thể bóng, mã in có thể nhòe, và vị trí mã thay đổi khi đổi quy cách bao bì. Một kết quả thử trên nhãn phẳng không bảo đảm kết quả tương tự trên túi thật đang chạy. Hãy yêu cầu thử đủ những loại nhãn và vật liệu doanh nghiệp sử dụng, kể cả trường hợp khó. Cũng phải xác định ai tạo bộ mẫu chuẩn, ai chỉnh ngưỡng nhận dạng, ai kiểm tra đầu ca và ai chịu trách nhiệm khi máy loại nhầm. Nếu không có quy trình thao tác và lịch bảo trì, hệ thống có thể cho kết quả tốt trong buổi trình diễn nhưng suy giảm sau khi bàn giao."}, {"layout": "L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Bằng chứng thử nghiệm và điều kiện thương mại", "handwriting": "Sắp thẻ bằng chứng từ yếu đến mạnh theo bối cảnh áp dụng; bật Q4.", "slideContent": "So sánh 4 mức: brochure -> video demo -> biên bản thử theo mẫu xác định -> thử tại hiện trường có người xác nhận. Bảng chi phí: mua, lắp, tích hợp, huấn luyện, giấy phép, bảo trì. Q4.", "lectureScript": "Một video trình diễn giúp ta nhìn thấy cách thiết bị hoạt động, nhưng không cho biết tỷ lệ bỏ lọt trên một tập mẫu đại diện. Báo cáo thử cần ghi số lượng mẫu lỗi, mẫu đạt, cách gán nhãn và người kiểm. Thử trên chính dây chuyền của doanh nghiệp thường trả lời tốt hơn về điều kiện tích hợp, nhưng vẫn phải xem phép thử có được thiết kế công bằng hay không. Song song là chi phí sở hữu: ngoài giá mua, còn lắp đặt, thay đổi dây chuyền, giấy phép phần mềm, huấn luyện, bảo trì và thời gian dừng. Hãy tách cam kết trong hợp đồng, nội dung chỉ được giới thiệu, và nội dung chưa thỏa thuận. Đó là những loại bằng chứng khác nhau."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Lập bảng khoảng trống triển khai", "handwriting": "Điền minh họa 3 dòng; giao bài điền phiếu phần A, B.", "slideContent": "Slide bảng 3 cột: Tài liệu / Chưa biết / Người xác minh. Ví dụ: sơ đồ đấu nối / độ trễ tín hiệu / kỹ thuật, IT; bộ mẫu / tỷ lệ lỗi / chất lượng.", "lectureScript": "Khi kết thúc bước đọc hồ sơ, bạn cần có một bảng khoảng trống thay cho một kết luận cảm tính. Mỗi hàng ghi rõ thông tin nào đã có, thông tin nào còn thiếu và ai sẽ xác minh. Với An Bình, chúng ta cần bản vẽ gá lắp, mô tả tín hiệu loại gói, dữ liệu mẫu kiểm và kế hoạch đào tạo người vận hành. Nếu đối tác chưa cung cấp, trạng thái của hạng mục đó là chưa xác minh. Đừng đánh đồng chưa có bằng chứng với công nghệ không đạt; ngược lại cũng đừng coi tài liệu thiếu là đã phù hợp. Video cuối sẽ dùng một phép thử giả định để bạn thấy cách kiểm tra các tuyên bố bằng con số."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('8a8dcd00-f79f-5a13-9ed1-9640234ce9f9', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 3, 'EL-015-V15.3', 'VIDEO 15.3: KIỂM CHỨNG TUYÊN BỐ VÀ KẾT LUẬN MỨC ĐỘ PHÙ HỢP', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đặt điều kiện nghiệm thu trước khi thử", "handwriting": "Hiện các điều kiện một lượt; gạch chân “thống nhất trước thử”.", "slideContent": "Slide yêu cầu thử giả định: 75 gói/phút; phát hiện >=98% mẫu lỗi; loại nhầm <=1% mẫu tốt; không tăng rủi ro an toàn. Ghi mọi ngưỡng là VÍ DỤ.", "lectureScript": "Bây giờ ta sẽ kiểm chứng phần hiệu năng. An Bình giả định yêu cầu chạy ở bảy mươi lăm gói mỗi phút, phát hiện ít nhất chín mươi tám phần trăm mẫu lỗi và loại nhầm không quá một phần trăm mẫu tốt. Các ngưỡng này chỉ để minh họa. Trước thử, doanh nghiệp phải thống nhất loại lỗi, người phân loại mẫu, cách ghi kết quả và điều kiện dừng khi có rủi ro an toàn. Nếu ngưỡng được đặt sau khi đã xem kết quả thì phép nghiệm thu mất tính khách quan. Ta cũng không thể dùng một buổi thử để kết luận độ bền hoặc hiệu quả tài chính dài hạn."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Lập mẫu thử và ma trận kết quả", "handwriting": "Viết số vào từng ô và tô tổng hàng; không dùng tổng 500 để thay mẫu số của mọi chỉ số.", "slideContent": "Ma trận 2x2: 100 gói lỗi (96 phát hiện, 4 bỏ lọt); 400 gói đạt (12 loại nhầm, 388 cho qua). Ghi: mẫu có chủ đích, không phải tỷ lệ lỗi thực tế.", "lectureScript": "Giả sử bộ phận chất lượng đã chuẩn bị năm trăm gói có nhãn đúng, sai được kiểm tra thủ công trước. Trong đó một trăm gói thật sự lỗi và bốn trăm gói đạt. Hệ thống phát hiện đúng chín mươi sáu gói lỗi, bỏ lọt bốn gói lỗi, đồng thời loại nhầm mười hai gói đạt và cho qua ba trăm tám mươi tám gói đạt.  Mẫu đã cố tình tăng tỷ lệ gói lỗi để thử hệ thống, nên không dùng tỷ lệ lỗi của bộ mẫu làm tỷ lệ lỗi ngoài sản xuất. "}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Tính đúng tỷ lệ phát hiện và loại nhầm", "handwriting": "Viết cả tử và mẫu; highlight 96% < 98%, 3% > 1%; bật Q5.", "slideContent": "Công thức: 96/(96+4)=96% phát hiện lỗi; 12/(12+388)=3% loại nhầm; 484/500=96,8% đúng chung. Q5.", "lectureScript": "Bây giờ tính từng chỉ số. Tỷ lệ phát hiện lỗi bằng chín mươi sáu chia cho một trăm, được chín mươi sáu phần trăm. Tỷ lệ loại nhầm bằng mười hai chia cho bốn trăm, được ba phần trăm. Nếu cộng số phân loại đúng rồi chia cho năm trăm, ta được chín mươi sáu phẩy tám phần trăm đúng chung.  Trong phép thử minh họa, tỷ lệ phát hiện chưa đạt ngưỡng chín mươi tám phần trăm; tỷ lệ loại nhầm cũng cao hơn ngưỡng một phần trăm. Chúng ta không thể lấy độ đúng chung để che hai điểm chưa đạt. Hãy thử nhập các số vào phiếu thực hành để Excel tính lại."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Kiểm tính đại diện của phép thử", "handwriting": "Đưa bốn ô lần lượt lên khung; gắn dấu ? tại điều kiện chưa thử.", "slideContent": "Slide 4 ô: các ca sản xuất; loại bao bì; tốc độ vận hành; thay đổi ánh sáng. Ghi “Không suy rộng khi điều kiện chưa tương đương”.", "lectureScript": "Kết quả số học vẫn chưa đủ để phê duyệt. Năm trăm gói thử có đại diện cho các ca sản xuất, vật liệu bao bì, loại mực và tốc độ vận hành thực tế không? Hệ thống có xử lý được khi băng tải rung, ánh sáng thay đổi, hoặc mã nằm lệch vị trí?  Với hồ sơ minh họa này, chúng ta cũng chưa có biên bản đo năng suất bảy mươi lăm gói mỗi phút trên dây chuyền. Vì vậy mục năng suất phải ghi chưa xác minh, dù tờ thông số công bố tối đa một trăm hai mươi."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Ra quyết định theo từng tiêu chí", "handwriting": "Đóng dấu trạng thái tương ứng, tuyệt đối không kết luận toàn bộ công nghệ vô dụng; bật Q6.", "slideContent": "Bảng đánh giá: phát hiện lỗi = chưa đạt; loại nhầm = chưa đạt; năng suất = chưa xác minh; tích hợp = chưa xác minh. Q6.", "lectureScript": "Ta tổng hợp các kết quả theo đúng trạng thái. Trong ví dụ, phát hiện lỗi và loại nhầm chưa đạt mục tiêu thử đã đặt ra. Năng suất thực tế, khả năng đấu nối và vận hành liên tục còn thiếu bằng chứng. Vì vậy không đủ căn cứ để chấp nhận giải pháp ngay. Bước hợp lý là yêu cầu đối tác điều chỉnh, bổ sung hồ sơ và đề xuất thử lại với phương pháp thống nhất. Cũng nên so với cách cải tiến in mã hoặc ánh sáng. Một phép thử chưa đạt không có nghĩa công nghệ vô dụng."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Viết yêu cầu phản hồi nhà cung cấp", "handwriting": "Gạch chân từng đầu ra tài liệu, gắn tên bộ phận xác minh.", "slideContent": "Slide thư trao đổi 5 câu hỏi: định nghĩa 99%; bộ mẫu; bảng tín hiệu; điều kiện chạy 75; bảo hành/huấn luyện và chi phí.", "lectureScript": "Trước khi liên hệ lại nhà cung cấp, hãy chuẩn bị các câu hỏi thật cụ thể. Thứ nhất, chỉ số chín mươi chín phần trăm đã được định nghĩa và đo trên tập mẫu nào? Thứ hai, đối tác có thể cung cấp ma trận lỗi và báo cáo thử không? Thứ ba, thiết bị truyền tín hiệu loại gói qua giao diện nào? Thứ tư, điều kiện cần thiết để chạy liên tục ở bảy mươi lăm gói mỗi phút là gì? Cuối cùng, phần lắp đặt, huấn luyện, bản quyền phần mềm và bảo trì nằm trong hạng mục nào? Bạn yêu cầu tài liệu kèm người chịu trách nhiệm trả lời và thời hạn xác nhận. "}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao phiếu đánh giá hồ sơ công nghệ", "handwriting": "Hiện 4 trạng thái: đạt / chưa đạt / chưa xác minh / không áp dụng. Kết thúc ở nhiệm vụ tự điền.", "slideContent": "Slide tổng kết: thông số công bố -> điều kiện áp dụng -> thử -> đánh giá bốn trạng thái; chỉ vào sheet PHIẾU THỰC HÀNH, BẢNG TỰ CHẤM và HỎI ĐÁP.", "lectureScript": "Sau bài này, bạn hãy chọn một hồ sơ công nghệ thực tế mà doanh nghiệp đang xem xét. Trước hết xác định chức năng và chỉ số cần đo. Sau đó rà soát điều kiện cơ khí, điện, dữ liệu, người vận hành và bảo trì. Tiếp theo, ghi nguồn của từng tuyên bố và thiết kế phép thử ở phạm vi có thể kiểm soát. Cuối cùng, đánh giá riêng từng tiêu chí: đạt, chưa đạt, chưa xác minh hoặc không áp dụng. Dùng số giả định để tập tính; hồ sơ nộp phải có dữ liệu thực và nguồn. Hoàn thành bảng tự chấm để tìm thông tin còn thiếu trước khi trao đổi với đối tác."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('8e5b7b68-add2-5fc3-99dc-40d026a744a5', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 1, 'EL-016-V1', 'Phần 1: Giới thiệu và Nguyên lý cốt lõi', 240, NULL, NULL, NULL, '[{"layout": "Đồ họa hoạt hình", "popupQuiz": "Q1", "sceneCode": "V1-1", "sceneName": "Mở đầu", "handwriting": "", "slideContent": "Khái niệm và định nghĩa", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('c60ba7fb-44d6-5bed-a14f-143c7e70c329', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 2, 'EL-016-V2', 'Phần 2: Phương pháp triển khai và Phân tích', 240, NULL, NULL, NULL, '[{"layout": "Slide tương tác", "popupQuiz": "Q2", "sceneCode": "V2-1", "sceneName": "Nội dung chính", "handwriting": "", "slideContent": "Các bước triển khai", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('8e16b500-7449-5f66-84b0-4c1a1af6d404', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 3, 'EL-016-V3', 'Phần 3: Bài học thực tiễn và Hành động', 240, NULL, NULL, NULL, '[{"layout": "Infographic tổng kết", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Tóm tắt", "handwriting": "", "slideContent": "3 điểm cần nhớ và hành động", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('9120d213-56a9-5115-886d-325d7bf60cd1', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 1, 'EL-017-V17.1', 'VIDEO 17.1: TRUY XUẤT NGUỒN DỮ LIỆU TRƯỚC KHI TIN MỘT KẾT QUẢ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Từ lời quảng cáo đến câu hỏi về bằng chứng", "handwriting": "Xuất hiện 99% rồi đặt dấu hỏi cạnh con số. Lần lượt mở ba nhãn. Giảng viên nhìn thẳng máy.", "slideContent": "Slide mở: BÀI 17. Trái: tờ giới thiệu camera “chính xác 99%”. Phải: ba nhãn NGUỒN - CÁCH ĐO - ĐIỀU KIỆN. Chú thích: TẤT CẢ DỮ LIỆU VÍ DỤ LÀ GIẢ ĐỊNH.", "lectureScript": "Chào bạn. Ở bài trước, chúng ta đã đọc hồ sơ một camera kiểm tra nhãn và mã lô cho cơ sở đóng gói cà phê An Bình. Giả sử nhà cung cấp gửi thêm video trình diễn, bảng số liệu và dòng giới thiệu rằng thiết bị chính xác chín mươi chín phần trăm. Có thêm tài liệu chưa có nghĩa đã có thêm bằng chứng đáng tin. Trước tiên phải xác định ai tạo dữ liệu, đo trên mẫu gì, dùng cách tính nào và kết quả có thể kiểm tra lại hay không. Bài này giúp bạn thẩm định chứng cứ trước khi đề xuất thử nghiệm hoặc đầu tư. An Bình, các con số và tài liệu trên màn hình đều là tình huống giả định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Một kết luận đi qua những mắt xích nào?", "handwriting": "Kẻ mũi tên và nhấn mạnh một mắt xích bị thiếu sẽ làm giảm khả năng kiểm chứng.", "slideContent": "Sơ đồ năm mắt xích: Người phát hành -> phiên bản dữ liệu -> bộ mẫu -> phương pháp thử -> kết luận. Dưới sơ đồ có ô “không truy được = chưa xác minh”.", "lectureScript": "Hãy hình dung đường đi của một kết luận kỹ thuật. Người phát hành nói thiết bị phát hiện lỗi tốt. Ta cần biết phiên bản thiết bị, phiên bản thuật toán, ngày thử và ai chịu trách nhiệm ghi nhận. Tiếp đó là bộ mẫu: ai lấy mẫu, vào ca nào, có những loại bao bì nào. Rồi đến quy trình đo: tiêu chuẩn xác định gói lỗi, tốc độ chạy và cách ghi lại trường hợp bỏ sót. Cuối cùng mới đến phép tính và lời kết luận. Nếu một mắt xích không truy xuất được, chúng ta phải ghi là chưa xác minh, chứ không tự thay bằng niềm tin vào tên hãng hay bằng một con số đẹp."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Kiểm tra xuất xứ và phiên bản tài liệu", "handwriting": "Tô bốn ô bắt buộc và viết “không rõ” cho ô trống. Hiện Q1 sau cảnh.", "slideContent": "Bảng hồ sơ: nguồn gửi; tác giả/đơn vị; ngày; mã cấu hình; ngày chạy thử; dữ liệu gốc; người xác nhận. Cạnh phải: Q1.", "lectureScript": "Tôi mở một tệp báo cáo giả định và kiểm tra phần thông tin đầu tiên. Tên tệp không đủ để chứng minh xuất xứ. Cần xem người lập, đơn vị ban hành, ngày thử, mã cấu hình, cách lưu dữ liệu gốc và ai phê duyệt kết quả. Ví dụ, báo cáo của phiên bản phần mềm cũ không tự động xác nhận hiệu năng của phiên bản đang chào. Nếu tệp đã được chỉnh sửa, hãy giữ bản gốc và ghi lại thay đổi. Khi người cung cấp không có nhật ký, chúng ta ghi rõ phần thiếu, yêu cầu làm rõ, rồi mới đánh giá giá trị chứng cứ. Bây giờ bạn thử chọn tài liệu có khả năng kiểm tra lại tốt nhất."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Dữ liệu gốc khác với bảng tổng hợp", "handwriting": "Hiện một dòng log mẫu rồi gộp thành bảng tổng hợp; đánh dấu các cột không được phép xóa.", "slideContent": "Minh họa: 500 dòng log kiểm tra -> bảng đếm TP/FN/FP/TN -> đồ thị/tuyên bố. Bảng log có mã mẫu, nhãn chuẩn, dự đoán, thời điểm và điều kiện.", "lectureScript": "Một bảng tổng hợp ghi nhận bốn trăm tám mươi bốn kết quả đúng vẫn chưa cho biết những trường hợp sai nằm ở đâu. Khi có dữ liệu gốc từng mẫu, doanh nghiệp có thể tìm lại gói bị nhận nhầm, ngày chạy, kiểu nhãn và hình ảnh liên quan nếu được phép lưu. Tệp tổng hợp hữu ích để báo cáo, còn dữ liệu gốc giúp kiểm tra phép đếm và phân tích lỗi. Bạn cần bảo đảm mã mẫu không bị trùng, thời điểm có cùng quy ước, và bản ghi đã loại bỏ có lý do. Nếu dữ liệu chứa thông tin nhạy cảm, chỉ yêu cầu mức truy cập phù hợp, không đòi nhà cung cấp chuyển toàn bộ dữ liệu cá nhân."}, {"layout": "L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Mẫu thử được chọn như thế nào?", "handwriting": "Đặt màu xanh lên mẫu bao bì tiêu chuẩn, màu cam lên mẫu phản sáng/nhòe; mở Q2.", "slideContent": "Hai hộp: lấy theo ca, loại bao bì, điều kiện ánh sáng; đối lập với chỉ chọn mẫu dễ nhận dạng. Dưới: Q2 “mẫu đẹp có đại diện không?”.", "lectureScript": "Chất lượng nguồn dữ liệu còn phụ thuộc cách lấy mẫu. Nếu nhà cung cấp chỉ thử những gói phẳng, mã in rõ và ánh sáng ổn định, kết quả có thể đúng trong buổi trình diễn nhưng chưa nói nhiều về ca sản xuất thực tế. Với An Bình, tôi muốn biết bộ mẫu có bao bì bóng, mã lệch vị trí, lô mực khác nhau và các ca vận hành hay không. Việc chọn tỷ lệ gói lỗi cao hơn thực tế để thử phát hiện là có thể chấp nhận, miễn ghi rõ thiết kế mẫu. Điều không được làm là che cách chọn mẫu rồi dùng kết quả đó để tuyên bố tỷ lệ lỗi của toàn nhà máy. Hãy phân biệt mục tiêu kiểm chứng với tính đại diện."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Danh sách tài liệu cần yêu cầu", "handwriting": "Đánh dấu ô kiểm khi nhắc đến; giữ lại dòng “thiếu bằng chứng = chưa kết luận”.", "slideContent": "Checklist bốn dòng: tài liệu gốc/phiên bản; mẫu và nhãn chuẩn; cách thử và nhật ký; người xác nhận. Hướng dẫn mở phiếu thực hành mục A.", "lectureScript": "Sau video đầu, bạn có thể viết một yêu cầu cung cấp bằng chứng rất cụ thể. Hãy hỏi bản báo cáo gốc của đúng cấu hình, danh sách mẫu đã sử dụng, quy tắc gán nhãn đúng sai, nhật ký chạy thử và người có thể giải thích dữ liệu. Nếu bên cung cấp chưa có một số tài liệu, ta ghi yêu cầu bổ sung và thời hạn, không tự suy ra công nghệ kém hay tốt. Trong phiếu thực hành, hãy điền sáu mục truy xuất nguồn dữ liệu. Đặt riêng cột thông tin đã thấy và cột còn phải kiểm. Ở video tiếp theo, chúng ta sẽ đọc một bảng thử nghiệm và xem phép tính đúng có đủ để tin vào kết luận không."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('17ac8dee-51c4-5d64-8567-61a79259be3a', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 2, 'EL-017-V17.2', 'VIDEO 17.2: ĐỌC PHÉP THỬ VÀ PHÁT HIỆN CÁC NGUỒN SAI LỆCH', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Thử nghiệm phải trả lời câu hỏi đã định", "handwriting": "Nối từng bước bằng mũi tên; tránh hiển thị tiêu chuẩn tưởng tượng.", "slideContent": "Slide: Câu hỏi đánh giá -> chỉ tiêu -> ngưỡng -> bộ mẫu -> cách chạy -> biên bản. Dòng phụ “khóa tiêu chí trước khi xem kết quả”.", "lectureScript": "Một báo cáo thử nghiệm chỉ hữu ích khi biết nó muốn trả lời câu hỏi nào. Với camera An Bình, ta có thể hỏi khả năng phát hiện gói có nhãn hoặc mã lô lỗi, đồng thời xem thiết bị có loại nhầm gói tốt hay không. Trước khi chạy, hai bên cần thống nhất định nghĩa lỗi, điều kiện dây chuyền, chỉ số, ngưỡng đánh giá và cách xử lý trường hợp thiếu dữ liệu. Ngưỡng trong bài chỉ để minh họa phép ra quyết định, không phải chuẩn áp dụng chung. Nếu người thử thay đổi tiêu chí sau khi thấy kết quả, việc đánh giá dễ thiên lệch theo kết luận muốn có. Phiếu thử phải ghi rõ điều gì đã được ấn định trước."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Đọc bốn ô của bảng kết quả", "handwriting": "Điền bốn ô theo thứ tự: đúng lỗi, bỏ lọt, loại nhầm, đúng tốt; tô rõ mẫu số từng hàng.", "slideContent": "Bảng TP=96, FN=4, FP=12, TN=388 trên tổng 500 gói. Hàng thực sự lỗi 100; hàng thực sự tốt 400. Ghi “giả định - mẫu chọn có chủ đích”.", "lectureScript": "Ta dùng bộ dữ liệu giả định đã gặp ở Bài 15. Nhóm thứ nhất có một trăm gói được người kiểm xác nhận là lỗi. Camera phát hiện đúng chín mươi sáu gói và bỏ lọt bốn gói. Nhóm thứ hai có bốn trăm gói được xác nhận là tốt. Camera lại loại nhầm mười hai gói và cho qua đúng ba trăm tám mươi tám gói. Bốn con số này tạo thành bảng đối chiếu giữa nhãn chuẩn và kết quả máy. Bạn phải yêu cầu phương pháp xác lập nhãn chuẩn, vì nếu người kiểm cũng gán nhãn sai, phép tính vẫn đúng số học nhưng kết luận hiệu năng có thể sai."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tính đúng chỉ số, không trộn mẫu số", "handwriting": "Viết ba phép tính; khoanh ba mẫu số khác nhau; hiển thị Q3 sau lời giảng.", "slideContent": "Công thức: phát hiện lỗi 96/(96+4)=96%; loại nhầm 12/(12+388)=3%; đúng chung (96+388)/500=96,8%. Q3.", "lectureScript": "Bây giờ chúng ta tính. Tỷ lệ phát hiện lỗi bằng chín mươi sáu chia một trăm, là chín mươi sáu phần trăm. Tỷ lệ loại nhầm bằng mười hai chia bốn trăm, là ba phần trăm. Tỷ lệ phân loại đúng chung là bốn trăm tám mươi bốn chia năm trăm, tương đương chín mươi sáu phẩy tám phần trăm. Ba chỉ số có mẫu số và ý nghĩa khác nhau. Đặc biệt, con số đúng chung chịu ảnh hưởng bởi tỷ trọng mẫu lỗi và mẫu tốt trong bộ thử. Không thể dùng nó thay cho tỷ lệ phát hiện lỗi. Trong phiếu thực hành, bạn có thể đổi bốn số đếm và các tỷ lệ sẽ được tính lại."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Đúng trên bộ thử chưa chắc đúng tại xưởng", "handwriting": "Gạch bỏ suy luận 100/500 là tỷ lệ lỗi tại nhà máy; làm nổi bật thiết kế chọn mẫu.", "slideContent": "Hai cột: “Bộ thử có chủ đích: 100 lỗi/400 tốt” và “Dây chuyền thực tế: cơ cấu lỗi chưa biết”. Nhãn đỏ “20% không phải tỷ lệ lỗi của xưởng”.", "lectureScript": "Trong bộ thử, một trăm trên năm trăm gói là mẫu lỗi, tức hai mươi phần trăm. Nhưng không được kết luận nhà máy có tỷ lệ sản xuất lỗi hai mươi phần trăm. Người thiết kế có thể chủ động đưa nhiều mẫu lỗi vào bài kiểm tra để đo khả năng phát hiện. Ta cũng chưa biết điều kiện ca đêm, tốc độ thực tế hoặc loại bao bì hiếm có được đưa vào không. Một phép thử có thể phản ánh tốt khả năng xử lý đúng bộ mẫu đó, nhưng chưa chứng minh kết quả sẽ giữ nguyên ở mọi điều kiện vận hành. Khi báo cáo, bạn phải mô tả phạm vi mẫu và giới hạn ngoại suy, ngay cả khi phép tính hoàn toàn chính xác."}, {"layout": "L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Kiểm soát sai lệch và khả năng lặp lại", "handwriting": "Lần lượt gắn cờ cho từng câu; hiển thị Q4.", "slideContent": "Sơ đồ 4 câu kiểm: ai gán nhãn chuẩn? mẫu đã dùng để hiệu chỉnh chưa? có log loại trừ? có lặp trên ca/lô khác? Q4.", "lectureScript": "Một phép kiểm chứng cần nhận diện những nguồn sai lệch có thể xảy ra. Nếu dùng chính những gói đã huấn luyện hoặc hiệu chỉnh camera để đánh giá cuối cùng, kết quả có thể lạc quan hơn khi gặp mẫu mới. Nếu người chọn gói biết trước loại lỗi mà chỉ lấy trường hợp dễ, bộ thử cũng thiên lệch. Nếu bản ghi thất bại bị bỏ ra mà không có nhật ký, tỷ lệ báo cáo mất tính đầy đủ. Vì vậy hãy hỏi bộ mẫu đánh giá có tách khỏi bước hiệu chỉnh không, cách gán nhãn chuẩn có được kiểm tra chéo không, và người khác có lặp lại phép thử theo cùng quy trình không. Không có các thông tin đó thì chưa đủ căn cứ kết luận ổn định."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Chốt kết luận đúng phạm vi bằng chứng", "handwriting": "Hiện bốn ô; đặt nhãn “Chưa xác minh” bên những phần thiếu.", "slideContent": "Slide bốn ô: kết quả đã đo; cách đo đã rõ; giới hạn mẫu; điều kiện chưa xác minh. Dòng cuối: “biên bản + dữ liệu thô + phương pháp”.", "lectureScript": "Kết thúc video này, bạn có thể nói một câu kết luận có giới hạn. Trong bộ dữ liệu minh họa, tỷ lệ phát hiện được tính là chín mươi sáu phần trăm và loại nhầm ba phần trăm. Nhưng tính toán không thay thế được kiểm chứng nguồn mẫu, cách gán nhãn, điều kiện chạy và tính lặp lại. Vì vậy, trước khi tin rằng công nghệ phù hợp, ta cần cả số đếm lẫn hồ sơ tạo ra các số đếm đó. Khi mở phiếu thực hành, hãy kiểm tra bốn ô đếm và ghi dấu hỏi cho mọi tài liệu chưa có. Video cuối sẽ giúp bạn phân cấp độ tin cậy của chứng cứ và lập yêu cầu thử lại có thể nghiệm thu."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('5e26cc6f-66eb-59ea-b930-136136a37ad4', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 3, 'EL-017-V17.3', 'VIDEO 17.3: XẾP MỨC TIN CẬY VÀ THIẾT KẾ BƯỚC KIỂM CHỨNG TIẾP THEO', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Không đánh đồng quảng cáo với thử nghiệm độc lập", "handwriting": "Từng tầng hiện theo thứ tự; đặt dấu hỏi ở hai tầng đầu.", "slideContent": "Thang bốn tầng: tuyên bố quảng cáo -> video demo -> báo cáo thử có phương pháp và log -> thử độc lập trên dây chuyền. Dòng phụ “tầng cao hơn vẫn phải đúng phạm vi”.", "lectureScript": "Một dòng quảng cáo là tuyên bố của bên bán. Video demo cho thấy thiết bị đã làm được một thao tác, nhưng thường không cho biết cách chọn mẫu. Báo cáo thử có phương pháp, nhật ký và người xác nhận giúp kiểm tra các con số. Thử độc lập bằng sản phẩm và điều kiện thật của doanh nghiệp giúp đánh giá trực tiếp hơn khả năng áp dụng. Tuy vậy, không cấp độ nào bảo đảm thiết bị sẽ đạt kết quả tương tự ở mọi nhà máy. Khi nêu kết luận, hãy ghi rõ cấu hình, loại mẫu, thời gian và điều kiện đo."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Bốn cửa kiểm chứng cho một hồ sơ", "handwriting": "Vẽ bốn ô kiểm; cột kết quả không cho phép “đủ” khi vẫn còn dấu hỏi.", "slideContent": "Ma trận 4 cột: 1 nguồn và phiên bản; 2 nhãn chuẩn và log; 3 mẫu và điều kiện; 4 thử lặp/độc lập. Trạng thái Có / Không / ?.", "lectureScript": "Tôi đề xuất bốn cửa kiểm chứng cho một bộ hồ sơ. Một: truy xuất được nguồn, ngày thử và phiên bản công nghệ. Hai: có nhãn chuẩn và nhật ký từng mẫu để đối soát. Ba: mô tả được nguồn mẫu, cách chọn và điều kiện chạy. Bốn: có cách lặp lại hoặc kiểm chứng độc lập. Trong phiếu thực hành, bạn chọn Có, Không hoặc dấu hỏi cho từng cửa. Chọn Có chỉ cho biết có tài liệu để đánh giá, không có nghĩa nội dung trong đó đã đúng. Khi còn dấu hỏi, kết luận phải ghi rõ giới hạn của bằng chứng."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Phân biệt thiếu chứng cứ và chứng cứ phản bác", "handwriting": "Chia màn hình, mũi tên khác màu đến hai kết luận; mở Q5.", "slideContent": "Hai ví dụ: A thiếu danh sách mẫu -> Chưa xác minh; B có biên bản cho tỷ lệ dưới ngưỡng -> Chưa đạt theo phép thử. Q5.", "lectureScript": "Thiếu tài liệu và kết quả không đạt là hai trạng thái khác nhau. Nếu không biết ai gán nhãn chuẩn, ta ghi chưa xác minh, bởi chưa đủ cơ sở kiểm tra. Nếu dữ liệu thử được đo hợp lệ nhưng nằm ngoài ngưỡng đã thống nhất, ta ghi chưa đạt tiêu chí của phép thử đó. Với camera An Bình, các tỷ lệ có thể tính được, nhưng nguồn nhãn và bộ mẫu chưa được xác minh. Vì vậy phải nêu riêng kết quả số học và mức độ tin cậy của chứng cứ."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thiết kế lần thử mới có thể kiểm toán", "handwriting": "Lần lượt điền biểu mẫu và đánh dấu thông tin chốt trước thử.", "slideContent": "Phiếu kế hoạch: mục tiêu; danh mục loại lỗi; nguồn và cỡ mẫu; chia ca/lô; cấu hình; ngưỡng; người gán nhãn; log; điều kiện dừng và an toàn.", "lectureScript": "Nếu bằng chứng thiếu, hãy đề xuất một phép thử mới, không chỉ yêu cầu chạy lại. Hai bên thống nhất loại lỗi, nguồn mẫu, số lượng và cách phân bổ theo ca hoặc loại bao bì. Tiếp theo, khóa phiên bản phần mềm, điều kiện ánh sáng, tốc độ, cách đếm và ngưỡng trước khi thử. Người có chuyên môn xác nhận nhãn chuẩn; bộ mẫu đánh giá nên tách khỏi mẫu dùng để hiệu chỉnh. Nhật ký phải ghi cả những trường hợp thành công và thất bại, cùng lý do loại trừ. Cuối cùng, phân công người quan sát và quy định khi nào phải dừng vì an toàn. Cỡ mẫu cần được thiết kế theo mục đích đo, không chọn tùy tiện."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Đọc kết quả theo ngưỡng đã thống nhất", "handwriting": "Khoanh 96 < 98 và 3 > 1; bật Q6 sau câu hỏi cuối.", "slideContent": "Ví dụ giả định: phát hiện 96% so với ngưỡng nội bộ >=98%; loại nhầm 3% so với ngưỡng nội bộ <=1%. Hộp màu cam “Chưa đạt theo số đo ví dụ”, hộp xám “Nguồn mẫu cần xác minh”. Q6.", "lectureScript": "Giả sử An Bình đặt ngưỡng minh họa: phát hiện ít nhất chín mươi tám phần trăm mẫu lỗi và loại nhầm không quá một phần trăm mẫu tốt. Bộ số hiện có cho kết quả chín mươi sáu và ba phần trăm. Hai chỉ tiêu tính được đều chưa đạt ngưỡng giả định. Nhưng chúng ta vẫn thiếu chứng cứ về nhãn chuẩn và cách chọn mẫu, nên không thể khẳng định đây là hiệu năng thật của mọi cấu hình camera. Cách xử lý là ghi chưa đạt theo bảng minh họa, yêu cầu kiểm lại dữ liệu, phân tích trường hợp sai và thử mới trên mẫu phù hợp. Không phê duyệt đầu tư dựa trên bảng này, cũng không suy rằng mọi camera đều thất bại."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Viết yêu cầu bằng chứng gửi nhà cung cấp", "handwriting": "Tô từng dòng email; hiện đầu ra yêu cầu tệp và người chịu trách nhiệm.", "slideContent": "Email mẫu 5 ý: phiên bản và nguồn; bộ mẫu và nhãn; log và công thức; điều kiện thử; kế hoạch thử độc lập. Không hiện tên/địa chỉ thật.", "lectureScript": "Khi trao đổi với nhà cung cấp, hãy gửi danh mục yêu cầu bằng chứng. Cần có báo cáo gốc đúng cấu hình, ngày thử, định nghĩa chỉ số, nguồn mẫu, cách gán nhãn và nhật ký đủ để tính lại kết quả. Xin nêu cả những mẫu bị loại khỏi phân tích và lý do loại. Tiếp theo, đề nghị phép thử với mẫu mới do hai bên thống nhất, người quan sát và tiêu chí khóa trước. Nếu tài liệu có dữ liệu cần bảo mật, có thể bố trí hình thức xem hoặc đối chiếu có kiểm soát."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao phiếu tự đánh giá mức độ tin cậy", "handwriting": "Dấu kiểm ba đầu ra, chuyển sang hướng dẫn điền ô vàng; kết bằng lời mời tự chấm.", "slideContent": "Slide đầu ra: 1 phiếu truy nguồn + 1 bảng tính chỉ số + 1 kế hoạch thử lại. Hiển thị mục C phiếu thực hành và bảng tự chấm 7 tiêu chí.", "lectureScript": "Để hoàn thành bài, hãy chọn một công nghệ doanh nghiệp đang đánh giá, hoặc dùng hồ sơ camera giả định. Điền sáu mục truy xuất thông tin, nhập bốn số đếm và kiểm tra tỷ lệ phát hiện, loại nhầm. Sau đó đánh dấu bốn cửa bằng chứng bằng Có, Không hoặc dấu hỏi. Với mỗi mục còn thiếu, ghi tài liệu phải bổ sung và người chịu trách nhiệm. Cuối cùng, viết kế hoạch thử tiếp có bộ mẫu, ngưỡng và điều kiện dừng trước khi chạy. Tự chấm bảy tiêu chí ở sheet bên cạnh. Sản phẩm của bạn phải phân biệt được điều đã đo, điều có thể kiểm tra lại và điều vẫn chỉ là tuyên bố."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('cbf80674-d93d-5d2a-9ab2-30ae4911669b', '355ab944-8895-5f38-b87f-89e187038e44', 1, 'EL-018-V18.1', 'VIDEO 18.1: NHẬN DIỆN TÀI SẢN TRÍ TUỆ ĐI CÙNG CÔNG NGHỆ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Mua thiết bị không đồng nghĩa mua mọi quyền", "handwriting": "Hiện máy camera trước, sau đó bật lần lượt các lớp phần mềm, dữ liệu, tài liệu; khoanh chữ QUYỀN SỬ DỤNG.", "slideContent": "Mở bài 18; ảnh minh họa camera kiểm tra mã lô, bên cạnh là biểu tượng phần mềm, dữ liệu ảnh và tài liệu vận hành. Chân trang: tình huống giả định.", "lectureScript": "Chào bạn. Cơ sở đóng gói cà phê An Bình đang cân nhắc một hệ thống camera đọc nhãn và mã lô. Nhà cung cấp báo giá cả thiết bị, phần mềm và gói hỗ trợ triển khai. Nếu An Bình trả tiền mua máy, doanh nghiệp có được tự ý sao chép phần mềm sang dây chuyền thứ hai không? Có được giao mã nguồn cho đơn vị bảo trì khác không? Chưa thể trả lời nếu chưa biết quyền nào thực sự được cấp. Bài này hướng dẫn bạn xác định tài sản trí tuệ nằm trong một giải pháp, kiểm tra bằng chứng quyền khai thác và ghi yêu cầu trước khi tiếp nhận. An Bình và nhà cung cấp S hoàn toàn là ví dụ giả định."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Vẽ bản đồ các lớp của một giải pháp", "handwriting": "Mỗi lớp xuất hiện có nhãn: AI NẮM QUYỀN? ĐƯỢC PHÉP LÀM GÌ? Ở ĐÂU? TRONG BAO LÂU?", "slideContent": "Sơ đồ sáu lớp: máy camera; phần mềm và mã nguồn; thuật toán/mô hình; bộ ảnh/dữ liệu; hướng dẫn và bí quyết hiệu chỉnh; tên và dấu hiệu thương mại.", "lectureScript": "Chúng ta tách giải pháp thành các lớp để tránh hỏi chung chung rằng công nghệ này có bản quyền hay không. Thiết bị vật lý là một phần. Phần mềm điều khiển có thể chịu những điều kiện sử dụng riêng. Bộ ảnh dùng để hiệu chỉnh mô hình đặt thêm câu hỏi về nguồn dữ liệu và sự cho phép. Quy trình hiệu chỉnh có thể gắn với tri thức chưa công bố. Nhãn hiệu trên vỏ máy lại là chuyện khác. Mỗi lớp có thể do một chủ thể nắm giữ và được cấp phép theo cách khác nhau. Khi lập hồ sơ, bạn không cần tự kết luận chế độ pháp lý cuối cùng; hãy ghi từng lớp, người tự nhận có quyền và tài liệu cần kiểm tra."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Nhận diện sáng chế và tình trạng bảo hộ", "handwriting": "Lật từng thẻ; nhấn mạnh đơn đăng ký không đồng nghĩa đã được cấp; hiện Q1 sau cảnh.", "slideContent": "Bảng phân biệt: đơn đăng ký; văn bằng/đăng ký đã được cấp; tình trạng hiệu lực; phạm vi yêu cầu bảo hộ; quốc gia hoặc vùng lãnh thổ. Góc phải Q1.", "lectureScript": "Nếu nhà cung cấp giới thiệu thiết bị có sáng chế, hãy yêu cầu số công bố hoặc số văn bằng, tên chủ thể, nơi đăng ký và tình trạng pháp lý tại thời điểm kiểm tra. Một đơn đang nộp khác với một quyền đã được cấp. Ngay cả khi tìm thấy một văn bằng, ta vẫn cần xem phạm vi và lãnh thổ được bảo hộ, rồi đối chiếu với sản phẩm đang mua. Kết quả tra cứu sơ bộ giúp phát hiện câu hỏi, không tự chứng minh quyền sử dụng của doanh nghiệp và cũng không chứng minh không xâm phạm quyền của bên thứ ba. Đây là điểm cần người có chuyên môn pháp lý xác minh khi giao dịch có rủi ro."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Phần mềm, tài liệu và giấy phép", "handwriting": "Thêm dấu hỏi vào các quyền chưa có trong hợp đồng; không đánh dấu mặc định là được phép.", "slideContent": "Hình thư mục phần mềm: bản cài; khóa kích hoạt; tài liệu cấu hình; thư viện thành phần; điều khoản cấp phép. Cột quyền: cài, chạy, sao lưu, sửa, giao đơn vị bảo trì.", "lectureScript": "Một hệ thống camera thường có phần mềm phân tích, giao diện hiển thị và tài liệu vận hành. Việc có bản cài không tự trả lời doanh nghiệp được cài trên bao nhiêu máy, lưu bản sao dự phòng ra sao hoặc nhờ bên khác sửa lỗi hay không. Những vấn đề đó cần đọc điều khoản cấp phép và các quyền khác có liên quan. Nếu nhà cung cấp tích hợp thư viện của bên thứ ba, phải hỏi họ được phép phân phối và triển khai thành phần ấy theo điều kiện nào. Đừng yêu cầu mã nguồn bằng một câu chung chung. Hãy bắt đầu từ nhu cầu kinh doanh: ai cần sửa, sửa phần nào, trong thời gian nào và cần quyền truy cập tới mức nào."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Bí quyết và dữ liệu cần được kiểm soát", "handwriting": "Hiển thị khóa bảo mật và người được truy cập; Q2 xuất hiện cuối cảnh.", "slideContent": "Hai thẻ: bí quyết cấu hình và bộ ảnh kiểm thử. Bảng phân biệt: dữ liệu do ai cung cấp; mục đích; được lưu; được sử dụng lại; được xóa khi nào. Q2.", "lectureScript": "Giả sử An Bình cung cấp ảnh sản phẩm lỗi và cách xử lý mã lô để nhà cung cấp hiệu chỉnh camera. Đây có thể là thông tin vận hành doanh nghiệp không muốn chia sẻ rộng. Trước khi chuyển dữ liệu, hai bên phải làm rõ mục đích sử dụng, phạm vi người truy cập, thời hạn giữ và việc sử dụng lại để phát triển sản phẩm cho khách hàng khác. Tương tự, công thức hiệu chỉnh hoặc quy trình kỹ thuật không công bố có thể cần thỏa thuận bảo mật. Tuy nhiên, gọi một thông tin là bí mật kinh doanh không đủ để kết luận thông tin đã đáp ứng mọi điều kiện bảo hộ. Việc đánh giá phải dựa trên đặc điểm thông tin và cách kiểm soát thực tế."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Lập danh mục quyền cần làm rõ", "handwriting": "Chọn hàng phần mềm và ảnh huấn luyện làm mẫu; hiện dấu hỏi tại cột tài liệu.", "slideContent": "Checklist bốn cột: thành phần; chủ thể tự nhận quyền; hành vi An Bình muốn làm; bằng chứng còn thiếu. Hướng dẫn mở phiếu thực hành A.", "lectureScript": "Sau video đầu, bạn có thể mở phiếu thực hành và ghi ít nhất sáu thành phần. Với mỗi thành phần, xác định ai giới thiệu mình là chủ thể có quyền, An Bình dự kiến sử dụng vào việc gì, và bằng chứng nào chưa có. Chẳng hạn, phần mềm cần được chạy trên một dây chuyền; ảnh lỗi chỉ được dùng để cấu hình tại dự án; tài liệu hướng dẫn cần được giao cho đội bảo trì. Một tên công nghệ không thay được danh mục quyền. Ở video tiếp theo, chúng ta sẽ kiểm tra chủ thể cấp quyền và phạm vi được phép khai thác, thay vì dừng lại ở lời quảng cáo."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('6fbc144f-76bd-5268-8dba-df9e2207ab48', '355ab944-8895-5f38-b87f-89e187038e44', 2, 'EL-018-V18.2', 'VIDEO 18.2: KIỂM TRA CHỦ THỂ QUYỀN VÀ PHẠM VI KHAI THÁC', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Bốn câu hỏi trước khi chấp nhận giấy phép", "handwriting": "Giảng viên lần lượt đọc bốn ô; đánh dấu chỗ chưa có giấy tờ.", "slideContent": "Slide bốn ô: Ai cấp? Cấp quyền gì? Cho ai và ở đâu? Trong bao lâu? Bên dưới: quyền có thể khác nhau giữa thành phần phần cứng và phần mềm.", "lectureScript": "Để đọc một đề xuất cấp phép, tôi bắt đầu bằng bốn câu hỏi. Ai có thẩm quyền cấp quyền? Bên được cấp là pháp nhân nào? Phạm vi hành vi được phép bao gồm cài đặt, vận hành, sao lưu hay chỉnh sửa? Và giới hạn về địa điểm, thời hạn, số người dùng hoặc số dây chuyền là gì? Với An Bình, văn bản có thể ghi quyền dùng phần mềm trên một máy điều khiển, trong khi quản lý sản xuất mong đưa lên hai dây chuyền. Khoảng chênh này cần được làm rõ trước khi nghiệm thu. Nếu văn bản không nói, đừng tự suy ra rằng doanh nghiệp được mở rộng vô hạn."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Chuyển nhu cầu vận hành thành ma trận quyền", "handwriting": "Tô quyền được cấp bằng xanh sau khi có điều khoản; ô chưa rõ dùng dấu hỏi.", "slideContent": "Ma trận cột: cài/khởi chạy; sao lưu; liên kết ERP; sửa cấu hình; thuê bảo trì; sử dụng thêm điểm sản xuất. Hàng: điều khoản đã thấy, còn thiếu, người xác nhận.", "lectureScript": "Hãy biến nhu cầu vận hành thành những hành vi cụ thể. Tại An Bình, kỹ thuật cần cài bản vá, bộ phận dữ liệu muốn nối kết quả camera với hệ thống quản trị, còn đơn vị bảo trì bên ngoài cần truy cập trong thời gian sửa lỗi. Ba việc này chưa chắc được bao phủ bởi cùng một quyền. Ma trận cho phép đối chiếu từng hành vi với điều khoản hợp đồng, tài liệu kỹ thuật và đầu mối xác nhận. Nếu quyền chỉ được nêu trong thư điện tử, cần thống nhất cách ghi nhận trong hồ sơ giao dịch. Một dấu tích trong bảng là trạng thái tài liệu đã được đối chiếu, không thay quyết định pháp lý về giá trị của điều khoản."}, {"layout": "L2 -> L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tra cứu công khai giúp được gì và không giúp được gì?", "handwriting": "Đặt đường ranh đỏ giữa tra cứu và kết luận pháp lý, bật Q3.", "slideContent": "Hai vùng: việc tra cứu hỗ trợ (đối tượng, chủ thể, hồ sơ, hiệu lực công khai); điều không thể suy ra tự động (quyền cấp phép, không xâm phạm, dữ liệu bí mật). Q3.", "lectureScript": "Khi tìm thông tin sáng chế hoặc nhãn hiệu, bạn nên ưu tiên cơ sở dữ liệu chính thức và ghi thời điểm tra cứu. Hãy so sánh tên chủ thể, tình trạng hồ sơ, phạm vi công bố với đề xuất mà nhà cung cấp đưa ra. Tuy nhiên, không tìm thấy kết quả trong một lần tra cứu chưa phải chứng cứ rằng mọi quyền của bên thứ ba đều không tồn tại. Tìm thấy hồ sơ cũng chưa đủ xác nhận người đang thương lượng có thẩm quyền cấp phép. Đánh giá khả năng tự do khai thác công nghệ, thường gọi là freedom to operate, cần xác định sản phẩm, hành vi, thị trường và quyền liên quan; với giao dịch quan trọng phải nhờ chuyên gia thẩm định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Thành phần bên thứ ba và giấy phép phần mềm mở", "handwriting": "Gắn thẻ BÊN THỨ BA với hai thư viện; ghi chú kiểm phiên bản, thông báo và nghĩa vụ cấp phép.", "slideContent": "Sơ đồ phần mềm camera gồm ứng dụng của nhà cung cấp, thư viện xử lý ảnh và mô-đun giao tiếp. Mỗi phần có hàng chứng từ và điều kiện.", "lectureScript": "Một ứng dụng có thể chứa nhiều thư viện và dịch vụ do các đơn vị khác phát triển. Nhà cung cấp phần mềm camera cần chỉ ra các thành phần đó, phiên bản và điều kiện sử dụng có liên quan. Với thành phần nguồn mở, quyền sử dụng có thể rộng nhưng vẫn có nghĩa vụ riêng tùy từng giấy phép và cách phân phối. Không có căn cứ để nói cứ phần mềm nguồn mở là được sử dụng vô điều kiện, hoặc cứ dùng thư viện nguồn mở thì phải công bố toàn bộ mã nguồn của mình. Điều cần làm là yêu cầu danh mục thành phần và nhờ người phụ trách pháp lý, kỹ thuật rà đúng nghĩa vụ áp dụng."}, {"layout": "L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Quyền đối với dữ liệu và kết quả phát sinh", "handwriting": "Mũi tên hai chiều; bôi rõ quyền đối với dữ liệu đầu vào và quyền đối với kết quả là hai câu hỏi khác nhau; mở Q4.", "slideContent": "Bảng hai hướng: An Bình giao ảnh lỗi và thông tin quy trình -> Nhà cung cấp cung cấp báo cáo, cấu hình, mô hình đã hiệu chỉnh. Các cột mục đích, truy cập, lưu giữ, sử dụng lại, bàn giao/xóa. Q4.", "lectureScript": "Trong một dự án camera, An Bình có thể cung cấp ảnh lỗi, dữ liệu mã lô và điều kiện dây chuyền. Nhà cung cấp có thể tạo báo cáo, tham số hiệu chỉnh hoặc một phiên bản mô hình điều chỉnh cho dự án. Hai bên cần ghi rõ quyền truy cập, phạm vi sử dụng, bảo mật, thời hạn lưu và nghĩa vụ xử lý dữ liệu khi chấm dứt hợp tác. Nếu có dữ liệu cá nhân hoặc thông tin của bên thứ ba, phải xem thêm quy định áp dụng trước khi chia sẻ. Đừng mặc định bên trả tiền đương nhiên sở hữu mọi dữ liệu và kết quả; cũng không mặc định nhà cung cấp được mang toàn bộ dữ liệu của khách hàng đi huấn luyện sản phẩm khác."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Nhận diện dấu hiệu đỏ trong hồ sơ quyền", "handwriting": "Bật cảnh báo màu cam, không dùng dấu kết luận xâm phạm quyền khi chưa có thẩm định.", "slideContent": "Danh sách dấu hiệu: không xác định được chủ thể; giấy phép khác pháp nhân; điều khoản mâu thuẫn; thiếu danh mục bên thứ ba; không rõ quyền sau hết hạn; thiếu quy trình bàn giao. Cuối slide: yêu cầu chứng từ chủ thể quyền, giấy phép, phần mềm thứ ba, dữ liệu và bàn giao.", "lectureScript": "Khi hồ sơ có tên bên bán khác với chủ thể ghi trên chứng từ, hãy hỏi căn cứ đại diện hoặc chuyển quyền. Nếu hợp đồng ghi thời hạn ba năm nhưng kế hoạch khấu hao, vận hành của doanh nghiệp dài hơn, bạn phải làm rõ điều kiện gia hạn và chi phí. Nếu hệ thống cần được thuê bên khác bảo trì mà hợp đồng cấm hoặc chưa nói, hãy yêu cầu phương án hỗ trợ. Tương tự, thiếu danh mục thư viện hoặc thiếu điều kiện bàn giao dữ liệu là những khoảng trống cần xử lý. Các dấu hiệu ấy chưa tự chứng minh giao dịch vi phạm pháp luật; chúng cho biết nơi cần làm rõ trước khi cam kết. Sau khi nêu khoảng trống, bạn hãy lập văn bản yêu cầu chứng từ quyền, giấy phép dự kiến, danh mục thư viện và điều khoản dữ liệu. Chỉ đánh dấu đã xác minh khi có tài liệu để đối chiếu."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('b7263826-4835-5832-a750-771e74728aa7', '355ab944-8895-5f38-b87f-89e187038e44', 3, 'EL-018-V18.3', 'VIDEO 18.3: TỪ RÀ SOÁT QUYỀN ĐẾN HỒ SƠ TIẾP NHẬN CÔNG NGHỆ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đọc một bộ hồ sơ giả định của An Bình", "handwriting": "Hiện từng dòng cùng dấu hỏi; phân biệt dữ kiện đã biết và thông tin còn thiếu.", "slideContent": "Bảng bốn hàng: máy camera; giấy phép phần mềm; ảnh lỗi doanh nghiệp; bí quyết hiệu chỉnh. Cột tình trạng: có báo giá; điều khoản chưa rõ; chưa có quy tắc sử dụng lại; chưa có cam kết bàn giao.", "lectureScript": "An Bình mới có báo giá camera, bản cài thử và lời hứa hỗ trợ hiệu chỉnh. Những giấy tờ ấy chứng minh cuộc trao đổi đang diễn ra, chưa chứng minh quyền vận hành lâu dài. Hồ sơ vẫn thiếu điều khoản phần mềm, danh mục thành phần bên thứ ba, quy định sử dụng ảnh lỗi và tài liệu bảo trì. Vì thế, ở phiếu thực hành chúng ta ghi chưa xác minh. Nếu nhà cung cấp đã đưa máy tới xưởng, trạng thái hồ sơ cũng không tự thay đổi. Điều cần làm là chỉ ra từng tài liệu còn thiếu và người chịu trách nhiệm cung cấp."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Bốn cửa kiểm tra trước khi tiếp nhận", "handwriting": "Giải thích màu xanh chỉ xác nhận đủ tài liệu để xét, màu cam cần kiểm; gắn công thức kiểm tình trạng.", "slideContent": "Bảng bốn cửa: chủ thể có quyền; phạm vi cấp phép; thành phần bên thứ ba và dữ liệu; bảo mật, bàn giao, duy trì sử dụng. Trạng thái Có/Không/?; không hiển thị điểm rủi ro pháp lý.", "lectureScript": "Tôi dùng bốn cửa để rà hồ sơ. Cửa một: ai có quyền cấp phép và bằng chứng ở đâu? Cửa hai: doanh nghiệp được cài đặt, sử dụng, bảo trì trong phạm vi nào? Cửa ba: quyền liên quan đến thư viện bên thứ ba, dữ liệu và kết quả hiệu chỉnh có rõ không? Cửa bốn: bảo mật, bàn giao và sử dụng tiếp khi hết hợp tác. Bạn chọn Có, Không hoặc dấu hỏi. Có nghĩa là có chứng cứ để xem xét, không đồng nghĩa đã hợp pháp. Nếu còn dấu hỏi, hãy ghi yêu cầu làm rõ, đừng tự điền đạt."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Ma trận điều khoản phải đàm phán", "handwriting": "Gạch chân cơ chế giao tài liệu, quyền tiếp tục dùng và người xử lý; xuất Q5.", "slideContent": "Ma trận sáu hàng: đối tượng giao; phạm vi sử dụng; dữ liệu và cải tiến; hỗ trợ - cập nhật; khi có khiếu nại của bên thứ ba; khi chấm dứt. Q5.", "lectureScript": "Trước khi ký, hãy chuyển mỗi khoảng trống thành nội dung có thể kiểm tra trong thỏa thuận. Xác định phiên bản thiết bị, phần mềm và tài liệu phải bàn giao. Ghi số máy, địa điểm, thời hạn và quyền bảo trì doanh nghiệp cần. Nêu cách sử dụng, lưu giữ và hoàn trả dữ liệu cùng kết quả hiệu chỉnh. Phân công ai cung cấp bản vá và ai xử lý khi có khiếu nại của bên thứ ba. Cuối cùng, làm rõ quyền tiếp tục vận hành sau khi hợp đồng kết thúc. Danh sách này để chuẩn bị thẩm định, không thay văn bản do người có chuyên môn soạn."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Phân biệt thiếu chứng cứ và rủi ro đã xác định", "handwriting": "Mũi tên từ ghi nhận khoảng trống -> yêu cầu bằng chứng -> quyết định kiểm soát.", "slideContent": "Ba cột: chưa xác minh; phát hiện điều kiện không phù hợp; đã được thẩm định có điều kiện. Ví dụ phần mềm chỉ được cài một máy nhưng kế hoạch cần hai.", "lectureScript": "Bạn cần phân biệt ba tình huống. Chưa có giấy phép thì ghi chưa xác minh; không kết luận nhà cung cấp vi phạm. Nếu giấy phép đã ghi chỉ cho cài một máy nhưng kế hoạch An Bình cần hai máy, ta có chênh lệch cụ thể phải đàm phán. Nếu các chứng từ đã đủ để xem, hồ sơ chuyển sang thẩm định có điều kiện. Mỗi tình huống dẫn đến một việc: xin tài liệu, sửa phạm vi cấp phép hoặc đề nghị kiểm tra chuyên môn. Tránh viết chung rằng vấn đề sở hữu trí tuệ đã xử lý xong khi chưa nêu được căn cứ."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Theo dõi số lượng hạng mục đã có bằng chứng", "handwriting": "Cho thay bốn số nhập, hiển thị tỷ lệ bao phủ tài liệu; chú thích không phải điểm an toàn pháp lý.", "slideContent": "Phiếu thực hành: tổng hạng mục = 6; đã có tài liệu đối chiếu = 2; chưa xác minh = 4; có vướng mắc đã phát hiện = 0. Tỷ lệ tài liệu = 2/6 = 33,3%.", "lectureScript": "Trong phiếu thực hành, bộ số hoàn toàn giả định có sáu hạng mục: hai nhóm đã có tài liệu, bốn nhóm chưa xác minh, chưa ghi nhận vướng mắc rõ. Tỷ lệ đầy đủ hồ sơ là hai chia sáu, bằng ba mươi ba phẩy ba phần trăm. Chỉ số này dùng theo dõi tiến độ thu thập chứng từ, tuyệt đối không phải tỷ lệ an toàn pháp lý. Khi bạn thay số liệu ở ô vàng, Excel tính lại tỷ lệ và trạng thái. Nếu tổng các nhóm không bằng sáu, bảng sẽ yêu cầu kiểm tra số đếm trước khi xem kết quả."}, {"layout": "L2", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Khi nào phải chuyển chuyên gia rà soát?", "handwriting": "Đánh dấu cần tư vấn cho rủi ro xác định hoặc không thể xác minh; bật Q6.", "slideContent": "Bảng phân loại: có tranh chấp hoặc khiếu nại; chuỗi chuyển quyền không rõ; quyền xuyên biên giới; quyền dùng dữ liệu nhạy cảm; quyền cần mở rộng hệ thống. Q6.", "lectureScript": "Khi chuỗi quyền qua nhiều bên không rõ, có dấu hiệu tranh chấp, việc sử dụng vượt lãnh thổ hoặc có dữ liệu chịu hạn chế, cần chuyển hồ sơ cho người có chuyên môn trước khi cam kết. Càng khó thay công nghệ trên dây chuyền, càng phải làm rõ quyền duy trì vận hành. Pháp luật sở hữu trí tuệ và chuyển giao công nghệ Việt Nam đã có sửa đổi có hiệu lực từ tháng tư năm hai nghìn không trăm hai mươi sáu. Giao dịch thật phải kiểm quy định áp dụng tại thời điểm ký, tình trạng quyền và từng hành vi dự kiến. Phiếu học tập không phải kết luận pháp lý."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Bàn giao hồ sơ kết nối và thực hành", "handwriting": "Hiện sản phẩm bài tập theo bốn phần; giảng viên nói lời kết rõ hành động.", "slideContent": "Slide cuối: danh mục tài sản; bảng quyền; bốn cửa bằng chứng; danh sách câu hỏi bổ sung; người xử lý và thời hạn. Mở phiếu thực hành và bảng tự chấm.", "lectureScript": "Để hoàn thành bài, hãy chọn công nghệ doanh nghiệp đang cân nhắc hoặc dùng hồ sơ camera An Bình. Liệt kê sáu thành phần quyền, chủ thể tự nhận quyền và cách doanh nghiệp muốn dùng. Đánh dấu bốn cửa bằng chứng, cập nhật số hạng mục đã có tài liệu, rồi ghi những điều còn thiếu. Chọn hai khoảng trống ảnh hưởng trực tiếp tới vận hành để gửi nhà cung cấp làm rõ. Cuối cùng, nêu người xử lý, thời hạn và việc nào cần thẩm định pháp lý. Bạn tự chấm bảy tiêu chí của bài tập; không dùng tổng điểm đó để phê duyệt mua công nghệ."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('ce98fe1c-dfd4-5990-9a56-81449c582634', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 1, 'EL-019-V19.1', 'VIDEO 19.1: TỪ NHU CẦU CÔNG NGHỆ ĐẾN TẬP PHƯƠNG ÁN ĐỦ RỘNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Vì sao cần một danh sách ngắn", "handwriting": "Hiện lần lượt nhãn NHU CẦU, PHƯƠNG ÁN, DANH SÁCH NGẮN; ghi chú “tình huống giả định”.", "slideContent": "Bìa Bài 19. Bên trái: bản mô tả nhu cầu; bên phải: sáu phương án giả định A-F, giữa là phễu sàng lọc giữ 3-5 lựa chọn.", "lectureScript": "Chào bạn. Một bản mô tả nhu cầu công nghệ tốt giúp doanh nghiệp đặt câu hỏi đúng, nhưng chưa trả lời ngay nên dùng giải pháp nào. Khi tìm kiếm trên thị trường, ta có thể gặp hàng loạt hồ sơ giới thiệu với các mức độ chi tiết khác nhau. Chỉ liên hệ một nhà cung cấp dễ khiến doanh nghiệp bỏ qua cách giải quyết khác. Nhưng gửi yêu cầu cho quá nhiều đơn vị lại tốn thời gian đánh giá. Vì thế, trong bài này chúng ta sẽ lập danh sách ngắn khoảng ba đến năm phương án có căn cứ để trao đổi chuyên sâu. Danh sách ngắn là đầu ra của vòng sàng lọc, chưa phải quyết định mua sắm. Chúng ta sẽ dùng một ví dụ hoàn toàn giả định tại cơ sở đóng gói cà phê An Bình."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Chốt nhu cầu trước khi tìm giải pháp", "handwriting": "Khoanh hai chức năng bắt buộc, đánh dấu các thông số vận hành cần khảo sát tại hiện trường.", "slideContent": "Phiếu yêu cầu: kiểm nhãn hiện diện; đọc và đối chiếu mã lô từng túi; khoảng 55 túi/phút là số liệu giả định; nhật ký lỗi; an toàn và vị trí lắp.", "lectureScript": "Trước khi mở danh sách nhà cung cấp, chúng ta thống nhất nhiệm vụ cần giải quyết. Trong ví dụ, An Bình muốn kiểm tra nhãn có hiện diện trên từng túi cà phê và mã lô có khớp lệnh sản xuất hay không. Năng suất khoảng năm mươi lăm túi một phút chỉ là giả định để làm bài. Hệ thống cần ghi được kết quả kiểm tra và không tạo thêm rủi ro an toàn cho người vận hành. Những điều kiện như kiểu mã lô, kích thước túi, ánh sáng và vị trí lắp vẫn phải khảo sát. Đừng bắt đầu bằng câu “cần trí tuệ nhân tạo”. Tên công nghệ là một hướng có thể xem xét, không phải điều kiện chức năng của bài toán."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Tạo tập phương án trước sàng lọc", "handwriting": "Xếp các thẻ theo cơ chế hoạt động thay vì thương hiệu; bật Q1 hỏi độ rộng của tập phương án.", "slideContent": "Sáu thẻ kiến trúc: A camera OCR trên băng tải; B đầu đọc Data Matrix + cảm biến nhãn; C in-kiểm tra đồng bộ; D trạm camera lắp ngoài; E cân trọng lượng; F phần mềm đối soát đơn hàng. Q1 cuối cảnh.", "lectureScript": "Tập phương án ban đầu nên đại diện cho các cơ chế xử lý khác nhau. Ta thử liệt kê sáu hướng giả định. A là camera đọc mã in trên băng tải. B kết hợp đầu đọc mã hai chiều và cảm biến phát hiện nhãn. C là bộ in và kiểm tra đồng bộ. D là trạm camera độc lập bổ sung vào dây chuyền. E là cân kiểm tra trọng lượng. F là phần mềm đối soát đơn hàng. Chưa kết luận hướng nào tốt nhất. Việc đưa cả E và F vào tập ban đầu giúp ta thử xem tiêu chí loại trừ có thực sự hoạt động. Mỗi phương án cần mô tả nó tác động vào công đoạn nào, nhận đầu vào gì và phát hiện được lỗi nào. Không dùng câu “giải pháp hiện đại” thay cho cơ chế."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Tìm ứng viên từ nhiều kênh, tránh trùng lặp", "handwriting": "Đánh dấu trường hợp ba brochure cùng một nền tảng chỉ tính là một kiến trúc cho vòng sàng lọc.", "slideContent": "Bảng kênh tìm: hồ sơ công nghệ; chuyên gia; nhà cung cấp; kết quả nghiên cứu; tham chiếu triển khai. Cột cùng một kiến trúc/khác phiên bản.", "lectureScript": "Trong thực tế, ta có thể tìm phương án từ cơ sở dữ liệu công nghệ, chuyên gia ngành, hồ sơ triển khai công khai hoặc các nhà cung cấp. Điều quan trọng là lưu nguồn, ngày nhận và phiên bản tài liệu. Ba brochure đến từ ba đại lý có thể mô tả cùng một công nghệ. Nếu đếm chúng thành ba lựa chọn độc lập, danh sách trông phong phú nhưng không mở rộng cách giải quyết. Ngược lại, một kiến trúc có thể có nhiều nhà cung cấp; ở vòng này cần tách giải pháp kỹ thuật khỏi bên bán. Hãy ghi mã ứng viên, cơ chế, nguồn thông tin và những khác biệt có thể kiểm chứng. Sau đó mới loại bản trùng, hồ sơ không còn hiệu lực hoặc lựa chọn không phù hợp phạm vi."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Nhận diện thiếu bằng chứng ngay từ đầu", "handwriting": "Tách màu cho số đo hiện trường, lời quảng cáo và hạng mục cần thử; xuất Q2.", "slideContent": "Bảng ba nhãn bằng chứng: Đã có tài liệu; Nhà cung cấp tuyên bố; Chưa xác minh. Ví dụ tốc độ 55 túi/phút; mã Data Matrix; vị trí lắp. Q2 cuối cảnh.", "lectureScript": "Vấn đề thường gặp là biến thông tin quảng cáo thành dữ kiện đã kiểm chứng. Nhà cung cấp có thể ghi tốc độ tối đa, nhưng tốc độ đó được đo trên sản phẩm nào, dưới ánh sáng nào và với tỷ lệ lỗi ra sao? Một phương án đọc Data Matrix chỉ phù hợp khi mã lô thực tế có cấu trúc tương ứng, hoặc khi có thể thay đổi quy trình in một cách chấp nhận được. Nếu chưa có mẫu thử, hãy đánh dấu chưa xác minh. Điều này không có nghĩa phương án thất bại. Nó cho biết câu hỏi nào phải đưa vào yêu cầu thử nghiệm. Khi đưa giải pháp vào danh sách ngắn, mỗi dòng cần đi kèm mức độ bằng chứng hiện tại và người chịu trách nhiệm làm rõ."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Giao bảng tập phương án cho học viên", "handwriting": "Lần lượt bật bốn cột và trỏ vào sáu hàng ví dụ trong phiếu.", "slideContent": "Tóm tắt bốn cột đầu vào: Mã phương án - Cơ chế - Chức năng đáp ứng - Bằng chứng/điểm chưa rõ. Chỉ dẫn mở phiếu thực hành.", "lectureScript": "Sau video thứ nhất, bạn hãy mở phiếu thực hành, ghi lại sáu phương án và rà từng chức năng bắt buộc. Nếu làm với doanh nghiệp của mình, bạn có thể thay toàn bộ tên công nghệ bằng các phương án đang tìm thấy. Cần lưu ý một nguyên tắc: lựa chọn để đưa vào vòng xem xét tiếp theo phải có khả năng đáp ứng nhu cầu, chứ không phải chỉ có giá hấp dẫn hoặc được quảng cáo nhiều. Giữ nguyên những chỗ chưa xác minh, vì đó chính là đầu việc của giai đoạn sau. Video tiếp theo chúng ta sẽ dùng điều kiện loại trừ để thu hẹp tập phương án, không dùng điểm cộng để che một thiếu sót bắt buộc."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('f2372605-e168-5eb6-9195-5af05c232793', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 2, 'EL-019-V19.2', 'VIDEO 19.2: SÀNG LỌC THEO ĐIỀU KIỆN BẮT BUỘC VÀ BẰNG CHỨNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Phân biệt điều kiện loại trừ và tiêu chí so sánh", "handwriting": "Gạch dưới chữ BẮT BUỘC, không cho phép bù trừ bằng điểm số cao ở tiêu chí khác.", "slideContent": "Hai vùng: điều kiện bắt buộc như kiểm cả nhãn và mã lô; tiêu chí so sánh như thời gian đào tạo, chi phí vòng đời, mức linh hoạt.", "lectureScript": "Khi đã có tập phương án, chúng ta cần phân biệt hai loại tiêu chí. Điều kiện bắt buộc là điều nếu không đáp ứng thì phương án không thể giải quyết đúng bài toán. Trong ví dụ, chỉ cân trọng lượng sẽ không đọc được nội dung mã lô, vì vậy không thể được chọn chỉ nhờ giá rẻ. Tiêu chí so sánh như chi phí, thời gian huấn luyện hay mức linh hoạt sẽ dùng ở vòng đánh giá chuyên sâu sau này. Bạn không nên chấm điểm có trọng số quá sớm rồi để một điểm mạnh bù cho việc thiếu chức năng cốt lõi. Cách làm đúng ở vòng sàng lọc là xác định các cửa điều kiện trước, ghi bằng chứng sau, rồi mới quyết định có giữ để kiểm chứng hay loại."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Bốn cửa sàng lọc sơ bộ", "handwriting": "Đánh dấu các cửa G1-G4 cùng ba trạng thái Có/Không/?; gạch chéo riêng hạng mục chưa đủ bằng chứng.", "slideContent": "Bốn hàng: G1 kiểm nhãn + mã lô; G2 nhịp, chỗ lắp, tích hợp; G3 đo phát hiện lỗi và loại nhầm; G4 an toàn, dữ liệu, bảo trì.", "lectureScript": "Trong tình huống An Bình, ta lập bốn cửa sàng lọc. Một là khả năng kiểm hiện diện nhãn và đối chiếu mã lô theo từng túi. Hai là khả năng hoạt động ở nhịp sản xuất và lắp được vào tuyến hiện có. Ba là có cách thử định lượng tỷ lệ phát hiện lỗi và tỷ lệ loại nhầm. Bốn là có phương án xử lý an toàn, dữ liệu, vận hành và bảo trì. Ở mỗi cửa, chỉ ghi có, không hoặc chưa xác minh khi có căn cứ tương ứng. Dấu hỏi không được đổi thành dấu có vì nhân viên kinh doanh nói miệng. Nhưng một dấu hỏi cũng chưa đủ lý do loại phương án khi có thể tổ chức phép thử phù hợp."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Loại giải pháp lệch chức năng trước", "handwriting": "Ẩn E và F sau khi cho người học dự đoán; Q3 xuất hiện khi đã gạch E/F.", "slideContent": "Sơ đồ sáu phương án. Gạch E cân trọng lượng và F đối soát đơn hàng vì không kiểm trực tiếp nhãn và mã lô trên từng túi; còn A-D.", "lectureScript": "Ta áp điều kiện thứ nhất vào sáu phương án. Cân trọng lượng có thể hỗ trợ phát hiện sai khối lượng, nhưng không cho biết mã lô in đúng hay sai. Phần mềm đối soát đơn hàng lại xử lý dữ liệu quản trị, không tự nhìn thấy nhãn trên từng túi. Vì vậy E và F ra khỏi danh sách ngắn cho bài toán hiện tại. Điều đó không có nghĩa hai công nghệ ấy kém hoặc vô ích. Chúng có thể giải quyết một nhu cầu khác. Bốn phương án A đến D tiếp tục được xem xét, trong đó B chỉ khả thi nếu cấu trúc mã lô phù hợp với đầu đọc và D phải chứng minh vận hành được trên dây chuyền. Chúng ta không nên ghi các điều kiện chưa rõ thành kết quả đạt."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Kiểm tra tính tương đương của phương án B", "handwriting": "Bật hai nhánh kết quả; đặt dấu ? cho dữ liệu đầu vào chưa được khảo sát.", "slideContent": "Bảng phóng to B: đầu đọc Data Matrix + cảm biến hiện diện nhãn. Hai cột: mã lô là chuỗi chữ thường / mã lô nằm trong Data Matrix.", "lectureScript": "Ví dụ B minh họa một lỗi ra quyết định dễ gặp. Nếu mã lô chỉ được in thành chuỗi ký tự và không có mã hai chiều chứa thông tin tương ứng, đầu đọc Data Matrix không tự động nhận dạng được chuỗi chữ đó. Khi ấy B không thể được xem là đáp ứng đầy đủ nếu giữ nguyên hiện trạng. Nhưng nếu doanh nghiệp cho phép chuẩn hóa mã in theo dạng có thể quét và đã kiểm tra khả năng đọc, B có thể tiếp tục. Thay vì kết luận ngay, bạn phải ghi điều kiện đầu vào và yêu cầu mẫu thử cụ thể. Danh sách ngắn giữ B ở trạng thái có điều kiện, kèm câu hỏi về thay đổi quy trình in và trách nhiệm tích hợp."}, {"layout": "L2 -> L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Thống nhất mức bằng chứng và số phương án giữ lại", "handwriting": "Điền từng phương án A-D và thử thay trạng thái B thành Chờ xác minh; bật Q4.", "slideContent": "Bảng A-D với cột “Giữ để kiểm chứng”, “Bằng chứng hiện có”, “Giả định còn mở”, “Bước thử”. Gắn nhãn danh sách ngắn = 4. Q4.", "lectureScript": "Sau khi loại hai phương án không đúng chức năng, chúng ta tạm giữ bốn hướng để kiểm chứng: camera đọc chữ trên băng tải, bộ đọc mã có cảm biến nhãn, hệ in-kiểm tra đồng bộ và trạm camera bổ sung. Số bốn nằm trong khoảng mục tiêu ba đến năm, nhưng không vì thế mà được coi là bốn phương án đã qua thẩm định. Với mỗi hướng, ta phải ghi rõ tài liệu có sẵn, phần nào chỉ là tuyên bố, câu hỏi còn mở và phép thử cần thực hiện. Nếu B không thể đáp ứng định dạng mã lô đã chốt, bảng phải cập nhật loại B. Khi đó số lượng danh sách ngắn thay đổi theo bằng chứng, không sửa ngược tiêu chí để đủ số."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Dừng sàng lọc nếu đầu vào chưa thống nhất", "handwriting": "Đưa hình dấu hỏi cạnh hai điều kiện, chỉ sang bảng yêu cầu thông tin trong phiếu thực hành.", "slideContent": "Hai ví dụ: chưa chốt định dạng mã lô; chưa biết có khoảng trống cho trạm. Bảng người phụ trách và thời hạn cần xác minh.", "lectureScript": "Khi nhiều điều kiện bắt buộc chưa rõ, bước tiếp theo không phải ép phương án vào danh sách ngắn bằng một điểm số. Bạn có thể tạm phân loại “chờ xác minh”, phân công người kiểm tra và đặt mốc trả lời. Những dữ kiện cần hỏi lại An Bình gồm kiểu mã thực tế, mẫu túi, năng suất theo ca, chỗ lắp và cách nối vào hệ thống dữ liệu. Cũng cần xác nhận đội vận hành có cho phép thay đổi công đoạn in hay không. Các câu hỏi này khác với việc đánh giá giá chào bán. Sau video thứ hai, hãy thử thay trạng thái của từng phương án trong phiếu Excel để thấy số lượng danh sách ngắn thay đổi và tự hỏi bằng chứng nào khiến sự thay đổi đó hợp lý."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('3949d8dc-e99c-59b6-8ae4-e8da82e227af', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 3, 'EL-019-V19.3', 'VIDEO 19.3: LẬP DANH SÁCH NGẮN CÓ THỂ MANG ĐI KẾT NỐI', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Danh sách ngắn phải có cấu trúc", "handwriting": "Giảng viên giới thiệu từng cột; dòng nào chưa rõ có dấu ?.", "slideContent": "Bảng 4 hàng A-D, cột: kiến trúc công nghệ, nhu cầu đáp ứng, giới hạn, nguồn hồ sơ, trạng thái, người liên hệ.", "lectureScript": "Ở video cuối, chúng ta chuyển bốn phương án còn lại thành một danh sách có thể sử dụng khi kết nối với chuyên gia và nhà cung cấp. Một tên công nghệ đơn lẻ chưa đủ. Mỗi dòng nên có cơ chế giải quyết, chức năng bắt buộc mà phương án dự kiến đáp ứng, điều kiện giới hạn và nguồn hồ sơ đã xem. Ta thêm trạng thái bằng chứng, câu hỏi chưa được trả lời và đầu mối cần liên hệ. Với phương án A, câu hỏi có thể là khả năng đọc chuỗi mã trên nền túi bóng. Với B là định dạng mã in. Với C là khả năng thay đổi thiết bị in hiện tại. Với D là vị trí lắp và tốc độ chuyển túi. Không suy đoán giá bán hoặc số hiệu sản phẩm."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Chuẩn hóa yêu cầu thông tin gửi nhà cung cấp", "handwriting": "Bật các dòng bên bán cần trả lời bằng văn bản; khoanh câu hỏi không nên công bố dữ liệu nhạy cảm khi chưa kiểm soát.", "slideContent": "Mẫu thư hỏi gồm: mẫu túi, kiểu lỗi, nhịp dây chuyền, giao tiếp dữ liệu, quyền thử, dữ liệu mẫu cần chia sẻ, tài liệu xác minh.", "lectureScript": "Để đánh giá công bằng, hãy gửi cùng một mô tả nhu cầu cho các bên cung cấp giải pháp. Hồ sơ nên nêu loại túi, biến thể nhãn, cách in mã lô và vị trí cần kiểm. Doanh nghiệp có thể yêu cầu mô tả nguyên lý, giới hạn điều kiện vận hành, phương án tích hợp và tài liệu kết quả thử tương tự. Chưa cần báo giá ràng buộc khi phạm vi còn thiếu. Nếu phải chia sẻ ảnh sản phẩm hoặc dữ liệu nội bộ, cần thống nhất mục đích, người truy cập và điều kiện bảo mật phù hợp. Ghi phiên bản tài liệu để tránh so sánh brochure cũ với kết quả thử mới."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Thiết kế phép thử so sánh chung", "handwriting": "Vẽ mũi tên từ lỗi yêu cầu tới mẫu kiểm thử; ghi số lượng cụ thể do dự án thiết kế sau khảo sát.", "slideContent": "Bảng mẫu thử dùng chung: 100 túi đạt, túi thiếu nhãn, túi sai mã, túi nhàu/bóng; thống nhất cách gắn nhãn chuẩn; tốc độ thực tế phải đo.", "lectureScript": "Một danh sách ngắn chỉ hữu ích khi các phương án có thể được kiểm tra bằng cùng bộ yêu cầu. Hãy lập nhóm sản phẩm đúng và nhóm lỗi cần phát hiện, đặc biệt lỗi thiếu nhãn hoặc mã lô không khớp lệnh. Trước thử nghiệm, phải xác định nhãn chuẩn bằng quy trình có người kiểm chứng, cách tính tỷ lệ phát hiện lỗi và tỷ lệ loại nhầm. Chốt số mẫu, thứ tự chạy và điều kiện ánh sáng trước khi thử. Với phương án phải thay đổi định dạng in, hãy ghi đây là biến thể quy trình khác; không so sánh như thể mọi thứ đều giữ nguyên. Một ca thử chưa chứng minh được độ ổn định giữa các ca."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Tách điều kiện bắt buộc và điểm so sánh", "handwriting": "Để tiêu chí thứ cấp ở vòng sau; Q5 đã xuất hiện cuối V3-3, không phát lại tại cảnh này.", "slideContent": "Sơ đồ hai vòng: vòng 1 điều kiện bắt buộc; vòng 2 chi phí vòng đời, bảo trì, tốc độ triển khai, mức phụ thuộc, đào tạo.", "lectureScript": "Khi các ứng viên đã được xác minh về chức năng và an toàn, doanh nghiệp mới nên đi vào phân tích sâu hơn. Khi đó mới so sánh chi phí vòng đời, tích hợp, bảo trì và mức phụ thuộc nhà cung cấp. Nhưng bảng điểm tổng hợp không thay được một điều kiện bắt buộc. Nếu không đọc đúng mã lô, điểm cao về giá hoặc tiện dụng vẫn không giải quyết bài toán. Không dùng riêng phép thử do bên bán chọn để kết luận vượt trội. Chúng ta cần giữ hồ sơ bằng chứng nhất quán và ghi những bất định chưa được kiểm chứng trước khi đàm phán sâu."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Quy tắc cập nhật danh sách ngắn", "handwriting": "Dùng bảng nhật ký quyết định gồm thay đổi, chứng cứ, người duyệt, ngày; không sửa lại lịch sử.", "slideContent": "Ba trường hợp cập nhật: A qua thử; B không đáp ứng định dạng mã và bị loại; C cần thay đổi máy in quá phạm vi; D cần kiểm tra an toàn lắp.", "lectureScript": "Danh sách ngắn không phải một file cố định. Khi có kết quả thử, bạn cập nhật từng dòng và giữ lịch sử quyết định. Giả sử phương án B không đọc được định dạng mã lô đang sử dụng và doanh nghiệp không chấp nhận thay đổi công đoạn in, hãy chuyển B ra khỏi danh sách ngắn, kèm biên bản thử. Nếu C phải thay máy in, cần kiểm thêm chi phí và phạm vi. Nếu D chưa có thiết kế an toàn, yêu cầu bổ sung. Danh sách có thể xuống dưới ba phương án; lúc đó mở rộng tìm kiếm có kiểm soát, không lén nới điều kiện bắt buộc."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Bàn giao shortlist và nhiệm vụ liên hệ", "handwriting": "Đánh dấu từng đầu việc: một bản nhu cầu, một nguồn tài liệu, một câu hỏi kiểm chứng.", "slideContent": "Mẫu bảng bàn giao: bốn phương án; dữ liệu thiếu; câu hỏi cần gửi; người phụ trách; mốc trả lời; điều kiện quyết định vòng sau.", "lectureScript": "Khi gửi danh sách ngắn cho nhóm dự án, tôi muốn nhìn thấy một bảng đủ để người khác tiếp tục làm việc mà không phải hỏi lại toàn bộ từ đầu. Bảng gồm bốn phương án đang xem xét, lý do giữ mỗi phương án, điều kiện còn thiếu và ai phải xác minh. Dùng chung bộ yêu cầu thông tin cho các bên. Ghi rõ nếu một lựa chọn đòi thay đổi quy trình. Nếu chưa có tài liệu để nói một thông số đã đáp ứng, hãy giữ nhãn chưa xác minh. Hoàn thành phiếu chưa phải cơ sở chọn nhà cung cấp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Tổng kết và giao bài thực hành", "handwriting": "Mở phiếu bài tập; hiện Q6 nếu chưa hiển thị; khoanh nơi nhập trạng thái để học viên thử thay phương án.", "slideContent": "Checklist nộp bài: tập phương án; lọc chức năng; danh sách 3-5; bốn cửa; bộ câu hỏi; kế hoạch thử và nhật ký quyết định.", "lectureScript": "Sau ba video, bạn hãy hoàn thiện phiếu thực hành trên một nhu cầu thật hoặc dùng tình huống An Bình. Bắt đầu bằng sáu ứng viên, phân loại từng phương án theo điều kiện bắt buộc, rồi lập danh sách ngắn nếu có đủ căn cứ. Viết một câu rõ ràng cho mỗi lựa chọn: giữ để kiểm chứng vì điều gì, còn thiếu chứng cứ gì. Tiếp đó, xây bộ câu hỏi chung để liên hệ chuyên gia hoặc nhà cung cấp, xác định mẫu thử và người chịu trách nhiệm. Làm thêm mười câu trắc nghiệm và tự chấm bảy tiêu chí. Nếu kết quả chưa đủ ba phương án, hãy ghi nhu cầu tìm bổ sung thay vì chọn cho đủ số. Bài này chưa quyết định đầu tư."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('fa82b636-ccd6-59c8-9c5a-5bf577b7f9ec', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 1, 'EL-020-V1', 'Phần 1: Giới thiệu và Nguyên lý cốt lõi', 240, NULL, NULL, NULL, '[{"layout": "Đồ họa hoạt hình", "popupQuiz": "Q1", "sceneCode": "V1-1", "sceneName": "Mở đầu", "handwriting": "", "slideContent": "Khái niệm và định nghĩa", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('c9bb977e-f788-5ad9-a408-c7f8cbf5f7f5', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 2, 'EL-020-V2', 'Phần 2: Phương pháp triển khai và Phân tích', 240, NULL, NULL, NULL, '[{"layout": "Slide tương tác", "popupQuiz": "Q2", "sceneCode": "V2-1", "sceneName": "Nội dung chính", "handwriting": "", "slideContent": "Các bước triển khai", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('c3e3ceb8-9973-525c-af48-7fc750deede7', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 3, 'EL-020-V3', 'Phần 3: Bài học thực tiễn và Hành động', 240, NULL, NULL, NULL, '[{"layout": "Infographic tổng kết", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Tóm tắt", "handwriting": "", "slideContent": "3 điểm cần nhớ và hành động", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('495d554b-7338-5fcd-957b-f20486a319f6', '60488501-198f-51f9-b9a3-e9d658985077', 1, 'EL-021-V21.1', 'VIDEO 21.1: PHÙ HỢP BẮT ĐẦU TỪ VẤN ĐỀ CỦA DOANH NGHIỆP', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Chọn công nghệ: nhanh nhất có chắc là tốt nhất?", "handwriting": "Hiện ba mức tự động hóa cùng dấu hỏi; gắn nhãn tình huống giả định.", "slideContent": "Bìa Bài 21; ba hình minh họa: người kiểm thủ công, camera OCR tích hợp, hệ thống AI tự động có robot. Câu hỏi: công nghệ nào hợp với dây chuyền hiện hữu?", "lectureScript": "Chào bạn. Khi xem một giải pháp công nghệ, chúng ta thường bị thu hút bởi tốc độ cao, nhiều tính năng hoặc tên thuật toán mới. Nhưng doanh nghiệp không mua một bảng thông số để trưng bày. Doanh nghiệp phải giải quyết một công việc cụ thể, trong những giới hạn rất thật về mặt bằng, tiền, dữ liệu và nhân sự. Một thiết bị đạt công suất lớn ở nhà máy mẫu có thể không chạy tốt trên dây chuyền của bạn. Trong bài này, tôi sẽ dùng ba phương án giả định để minh họa cách chọn công nghệ theo mức độ phù hợp. Mục tiêu không phải tìm phương án nhiều chức năng nhất, mà là nhận diện điều kiện nào cần kiểm chứng trước khi đầu tư."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Bắt đầu bằng nhiệm vụ và đường cơ sở", "handwriting": "Khoanh hai chức năng bắt buộc, hiển thị tốc độ cao điểm và ghi dấu ? tại vị trí dữ liệu chưa đo.", "slideContent": "Sơ đồ An Bình: in mã -> dán nhãn -> đóng túi -> kiểm tra. Nhiệm vụ kiểm hiện diện nhãn, đúng mã lô; nhịp cao điểm 55 túi/phút giả định.", "lectureScript": "Hãy xét cơ sở đóng gói cà phê An Bình. Đây là tình huống giả định đã dùng ở các bài trước. Dây chuyền cần kiểm tra nhãn có hiện diện và mã lô in trên từng túi có đúng lệnh sản xuất hay không. Nhịp cao điểm giả định là năm mươi lăm túi một phút. Ta còn cần biết tỷ lệ lỗi hiện tại, sản phẩm thay đổi bao nhiêu lần mỗi ca, ánh sáng tại nơi lắp camera và ai xử lý khi máy báo lỗi. Những dữ liệu ấy xác định bài toán lựa chọn. Nếu chỉ ghi “muốn dùng AI”, ta chưa biết AI phải làm nhiệm vụ nào hoặc điều kiện đo thành công là gì. Khi thiếu dữ liệu, hãy ghi cần khảo sát, không điền bằng ước đoán."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Ba mức giải pháp không đồng nghĩa ba mức phù hợp", "handwriting": "Xếp A-B-C theo mức tự động hóa. Đặt dưới mỗi thẻ ba ô: cần gì, đòi hỏi gì, chưa biết gì. Hiện Q1 cuối cảnh.", "slideContent": "Ba thẻ A: camera hỗ trợ người kiểm; B: camera quy tắc + OCR lắp trên băng tải; C: AI thị giác + cơ cấu loại tự động.", "lectureScript": "Giả sử ta có ba phương án. Phương án A là công cụ camera hỗ trợ một nhân viên kiểm tra; chi phí ban đầu thấp nhưng bị giới hạn bởi nhịp thao tác. Phương án B lắp camera nhận dạng ký tự và logic kiểm tra ngay trên băng tải. Phương án C sử dụng hệ thống thị giác AI kèm cơ cấu loại sản phẩm tự động, nhiều tính năng hơn và có thể chạy rất nhanh. Từ mô tả đó, không thể kết luận C là lựa chọn tốt nhất. Ta chưa xác minh tốc độ trên túi thật, độ chính xác, tích hợp máy, thời gian dừng lắp đặt và năng lực vận hành. Đây là ba kiến trúc minh họa, không phải tên sản phẩm đang bán. Ở bước đầu, hãy so khả năng giải quyết đúng lỗi mục tiêu."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Phân biệt công suất quảng cáo và công suất hữu ích", "handwriting": "Vẽ vạch 55; thêm nhãn điều kiện sản phẩm, ca, lỗi đọc, thời gian chuyển đổi.", "slideContent": "Hai biểu đồ: tốc độ công bố và tốc độ thực đo sau chuyển đổi mã, vệ sinh, dừng máy; ghi nhịp yêu cầu 55 túi/phút.", "lectureScript": "Một nhà cung cấp có thể công bố tốc độ một trăm bốn mươi túi một phút, nhưng con số đó được đo với bao bì nào? Có tính thời gian dừng đổi mã, vệ sinh ống kính hoặc xử lý túi bị loại không? Công suất hữu ích của một hệ thống phụ thuộc vào toàn bộ quá trình, không chỉ thiết bị nhanh nhất. Nếu dây chuyền hiện tại chỉ chạy khoảng năm mươi lăm túi một phút, đầu tư thêm công suất rất lớn chưa chắc đem lại lợi ích ngay. Ngược lại, một thiết bị quá chậm có thể tạo nút thắt mới. Khi đánh giá, bạn cần yêu cầu chạy trên mẫu túi thật, ở nhịp cao điểm và trong thời gian đủ để quan sát lỗi cùng thời gian dừng."}, {"layout": "L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Bốn câu hỏi về mức độ phù hợp", "handwriting": "Đánh dấu bốn nhóm; ghi ví dụ một giải pháp điểm mạnh về tốc độ nhưng chưa đáp ứng tích hợp. Hiện Q2 cuối cảnh.", "slideContent": "Ma trận bốn câu hỏi: giải quyết đúng lỗi? lắp được? đội ngũ vận hành được? chi phí vòng đời chấp nhận được?", "lectureScript": "Tôi đề nghị bạn dùng bốn nhóm câu hỏi khi đọc một hồ sơ. Thứ nhất, giải pháp có thực hiện được hai chức năng kiểm nhãn và mã lô trên từng túi không? Thứ hai, nó có lắp được vào không gian, băng tải và hệ thống dữ liệu hiện có không? Thứ ba, đội ngũ có thể hiệu chỉnh, bảo trì và giải thích cảnh báo không? Thứ tư, chi phí mua, vận hành và rủi ro dừng máy có nằm trong mức doanh nghiệp chấp nhận được không? Một phương án tốt phải vượt các điều kiện bắt buộc rồi mới được so bằng điểm. Bạn đừng dùng một điểm mạnh về tốc độ để bù cho việc không kiểm được mã lô. Đó là lỗi lựa chọn thường gặp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Bài tập nhỏ sau video đầu", "handwriting": "Nhấn lần lượt các từ khóa; trỏ đến trường nhu cầu và các hàng A-C trong phiếu.", "slideContent": "Slide 4 từ khóa: bài toán - nhịp thực - tích hợp - năng lực đội ngũ. Hướng dẫn mở phiếu thực hành.", "lectureScript": "Sau video thứ nhất, bạn hãy mở phiếu thực hành và ghi bốn điều kiện tối thiểu của dự án mình chọn. Trong ví dụ An Bình, hai chức năng kiểm nhãn, đối chiếu mã lô là bắt buộc; nhịp cao điểm và khả năng tích hợp cần được đo và xác nhận. Sau đó, hãy tự thử trả lời: nếu không nêu tên công nghệ, yêu cầu có còn rõ không? Nếu có, bạn đang mô tả đúng nhu cầu. Video tiếp theo chúng ta sẽ nhìn vào tiền đầu tư và chi phí vận hành, rồi thử đặt chúng cạnh khả năng triển khai. Điểm cần nhớ là mọi con số của ví dụ đều để học phương pháp, không phải dữ liệu một cơ sở có thật."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('2ed0cc21-6a75-5d49-9502-63999a3fad38', '60488501-198f-51f9-b9a3-e9d658985077', 2, 'EL-021-V21.2', 'VIDEO 21.2: SO CHI PHÍ, NĂNG LỰC VÀ KHẢ NĂNG TÍCH HỢP', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Giá mua không phải toàn bộ chi phí", "handwriting": "Tô màu hai nhóm chi phí đã có ví dụ và nhóm chưa được ước lượng.", "slideContent": "Sơ đồ khối: đầu tư ban đầu + vận hành hằng năm + tích hợp + đào tạo + thời gian dừng + nâng cấp; nhấn mạnh giả định kỳ ba năm.", "lectureScript": "Ở phần trước, chúng ta đã thấy công nghệ phải khớp với nhu cầu. Bây giờ đến câu hỏi tiền. Giá niêm yết chỉ là một phần của quyết định. Doanh nghiệp còn có thể phải trả tiền điện, giấy phép phần mềm, phụ tùng, bảo trì, đào tạo và tích hợp với máy cũ. Thậm chí thời gian dừng dây chuyền khi lắp đặt cũng tạo ra tổn thất. Trong ví dụ này, tôi sẽ dùng phép cộng đơn giản cho ba năm để học cách so sánh, chứ chưa gọi đó là tổng chi phí sở hữu đầy đủ. Nếu chưa ước lượng chi phí dừng máy hoặc nâng cấp, phải ghi rõ chúng đang thiếu. So sánh chỉ có ý nghĩa khi cùng phạm vi và cùng thời hạn."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Đặt ba phương án lên cùng bảng số liệu", "handwriting": "Bật từng hàng; thêm chú thích tốc độ B,C là tuyên bố cần thử thực tế.", "slideContent": "Bảng A: đầu tư 120 triệu, vận hành 95 triệu/năm, 35 túi/phút; B: 420, 100, 70; C: 1.200, 210, 140. Toàn bộ là giả định.", "lectureScript": "Hãy xem bộ số liệu giả định. A cần đầu tư một trăm hai mươi triệu đồng và vận hành khoảng chín mươi lăm triệu mỗi năm; nhịp tham chiếu ba mươi lăm túi một phút. B cần đầu tư bốn trăm hai mươi triệu và vận hành một trăm triệu mỗi năm; tài liệu giả định công bố bảy mươi túi một phút. C cần đầu tư một tỷ hai trăm triệu và vận hành hai trăm mười triệu mỗi năm; tốc độ công bố một trăm bốn mươi túi. Không có con số nào là báo giá thực tế. Ta cũng chưa biết B và C có đạt mức ấy khi đọc mã lô trên bao bì của An Bình. Vì vậy, bảng này chỉ giúp hình thành câu hỏi, chưa thể dùng để phê duyệt đầu tư."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tính chi phí ba năm theo cùng cách", "handwriting": "Viết phép tính 420 + 3 x 100 = 720. Hiện Q3 cuối cảnh.", "slideContent": "Công thức chi phí sơ bộ = đầu tư + 3 x vận hành mỗi năm. A=405, B=720, C=1.830 triệu đồng.", "lectureScript": "Với kỳ so sánh ba năm, chi phí sơ bộ của A bằng một trăm hai mươi cộng ba lần chín mươi lăm, tức bốn trăm lẻ năm triệu đồng. B bằng bốn trăm hai mươi cộng ba lần một trăm, là bảy trăm hai mươi triệu. C bằng một nghìn hai trăm cộng ba lần hai trăm mười, là một nghìn tám trăm ba mươi triệu. Đây là phép tính có chủ đích đơn giản, chưa tính chi phí tích hợp một lần, tổn thất dừng máy, giá trị còn lại hay chiết khấu. Nhờ cùng kỳ ba năm, ta nhìn thấy khoảng cách chi phí. Nhưng phương án rẻ nhất chưa chắc đạt chức năng và năng suất. Hãy đặt kết quả tài chính cạnh điều kiện vận hành, không dùng một mình nó để chốt mua."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Nhịp dây chuyền và thay đổi sản phẩm", "handwriting": "Gạch A dưới vạch tối thiểu; đặt dấu hỏi B,C. Nhấn mạnh thử trên nhiều mã và ca.", "slideContent": "Sơ đồ yêu cầu 55 túi/phút, A 35, B 70 tuyên bố, C 140 tuyên bố. Thẻ đổi mã, bao bì bóng, thiếu sáng.", "lectureScript": "Khi đưa năng suất vào, A chỉ đạt ba mươi lăm túi một phút theo giả định, dưới nhịp tối thiểu năm mươi lăm. Nếu đây là năng lực thực tế đã đo, A không thể đảm nhận kiểm tra toàn bộ túi ở giờ cao điểm mà không đổi cách tổ chức sản xuất. B và C có mức công bố cao hơn, nhưng còn dấu hỏi về túi phản quang, kiểu chữ mã lô và thời gian chỉnh máy sau khi đổi sản phẩm. Doanh nghiệp phải xác minh bằng một bộ mẫu đại diện, gồm cả ca thuận lợi và ca khó. Một tỷ lệ phát hiện cao ở bản trình diễn không tự động bảo đảm đạt yêu cầu trong môi trường sản xuất. Cần ghi kết quả vào biên bản để so sánh công bằng."}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Chi phí tích hợp và khả năng của người dùng", "handwriting": "Khoanh rủi ro dừng lắp đặt và yêu cầu huấn luyện; hiển thị Q4 cuối cảnh.", "slideContent": "Bảng phụ thuộc: PLC/băng tải, mạng dữ liệu, an toàn loại túi, bảo trì, nhân viên hiệu chỉnh; mức phải thay đổi A/B/C.", "lectureScript": "Có một phần thường bị bỏ quên khi so công nghệ, đó là mức độ thay đổi doanh nghiệp phải chịu. Hệ thống C có thể cần cơ cấu loại túi tự động, đường tín hiệu điều khiển và nhân sự hiểu cách quản lý mô hình AI. Nếu ca trưởng không thể xử lý cảnh báo sai, dây chuyền sẽ bị phụ thuộc vào nhà cung cấp. B cũng cần kiểm tra giao tiếp với máy đang có, nhưng có thể đòi hỏi ít thay đổi hơn trong tình huống giả định. Chúng ta không nên giả định cứ càng tự động hóa thì chi phí con người càng giảm. Doanh nghiệp cần hỏi ai cấu hình mã mới, ai lưu nhật ký lỗi, ai bảo trì và thời gian khôi phục nếu hệ thống dừng. Những câu trả lời đó quyết định mức phù hợp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Đọc bảng chi phí với giới hạn của nó", "handwriting": "Bật các dấu cảnh báo và gạch chữ “nhỏ nhất = tốt nhất”.", "slideContent": "Slide ba dòng: cùng đơn vị/kỳ; đánh dấu khoản chưa tính; chưa kết luận chọn mua. Hướng dẫn tự thay số trong phiếu.", "lectureScript": "Sau video này, bạn có thể vào phiếu và thay vốn đầu tư, chi phí vận hành, số năm so sánh. Excel sẽ tính lại tổng chi phí sơ bộ của từng phương án. Thử đổi kỳ từ ba năm sang năm năm, rồi quan sát khoảng cách chi phí thay đổi như thế nào. Nếu giá vốn của giải pháp lớn nhưng chi phí vận hành thấp hơn, thứ tự chi phí có thể đổi theo thời gian. Nhưng trong mọi trường hợp, trước khi so điểm, ta vẫn phải kiểm tra chức năng cốt lõi và nhịp vận hành. Video cuối sẽ hướng dẫn xếp hạng có điều kiện và thiết kế thí điểm để chuyển từ dự đoán sang bằng chứng."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('a33e2e9b-0d04-5e77-a093-93b88c2580e2', '60488501-198f-51f9-b9a3-e9d658985077', 3, 'EL-021-V21.3', 'VIDEO 21.3: QUYẾT ĐỊNH THEO ĐIỀU KIỆN BẮT BUỘC VÀ THỬ NGHIỆM', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đừng chấm điểm trước khi kiểm điều kiện loại", "handwriting": "Chặn đường A ở cổng nhịp; B,C đi tiếp với nhãn chờ kiểm chứng.", "slideContent": "Hai bước: cổng điều kiện bắt buộc -> ma trận đánh giá -> quyết định thử. Điều kiện: kiểm nhãn+mã lô và nhịp >=55 túi/phút.", "lectureScript": "Một ma trận điểm rất dễ tạo cảm giác khách quan, nhưng có thể dẫn đến kết luận sai nếu lập không đúng thứ tự. Trước khi chấm, doanh nghiệp phải kiểm những điều kiện không thể thiếu. Với An Bình, hệ thống cần kiểm được nhãn và mã lô trên từng túi, đáp ứng nhịp cao điểm và có phương án vận hành an toàn. Theo giả định, A chậm hơn nhịp tối thiểu nên bị loại sơ bộ cho nhiệm vụ kiểm toàn bộ sản phẩm. B và C chưa bị loại, nhưng tốc độ công bố, tỷ lệ đọc đúng và tích hợp vẫn phải thử thực tế. Nó giúp phân biệt một ứng viên đáng thử với công nghệ đã được chứng minh phù hợp."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Đặt trọng số theo ưu tiên kinh doanh", "handwriting": "Viết phép tổng; phân biệt tỷ trọng minh họa với tiêu chuẩn bắt buộc.", "slideContent": "Bốn trọng số minh họa: đáp ứng bài toán 40%, tích hợp 25%, năng lực đội ngũ 20%, chi phí 15%. Tổng đúng 100%.", "lectureScript": "Khi các điều kiện loại trừ đã được xét, ta có thể chấm sơ bộ những khía cạnh còn có thể đánh đổi. Trong ví dụ, trọng số dành cho mức đáp ứng bài toán là bốn mươi phần trăm; tích hợp hai mươi lăm; năng lực đội ngũ hai mươi; và chi phí mười lăm. Nếu nhà máy đang thiếu người bảo trì, trọng số năng lực vận hành có thể lớn hơn. Điểm từ một đến năm cũng phải có thang mô tả và bằng chứng. Thiếu thông tin thì ghi điểm tạm và kế hoạch đo, không biến đánh giá cảm tính thành kết quả đã kiểm chứng."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Tính điểm: công nghệ hiện đại nhất có thể đứng sau", "handwriting": "Lần lượt tính B: 4x40%+4x25%+4x20%+4x15%=4,00. Hiện Q5.", "slideContent": "Ma trận A=3,60; B=4,00; C=3,05 với điểm 1-5 theo bốn tiêu chí và trọng số trên. Đính kèm trạng thái cổng.", "lectureScript": "Giả sử A được đánh giá hai điểm về đáp ứng bài toán, năm điểm tích hợp, bốn điểm nhân sự và năm điểm chi phí. Điểm có trọng số là ba phẩy sáu, nhưng A vẫn không qua cổng nhịp. B được bốn điểm ở cả bốn nhóm, nên có điểm bốn phẩy không. C đạt năm điểm về tính năng, nhưng chỉ hai điểm tích hợp, hai điểm nhân sự và một điểm chi phí, nên tổng là ba phẩy không năm. B đang có điểm cao hơn trong kịch bản này, dù C hiện đại và có công suất công bố lớn hơn. Đừng hiểu điểm bốn là bảo đảm B thành công. Đó chỉ là thứ tự ưu tiên để tổ chức kiểm chứng tiếp."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Đổi bối cảnh thì thứ tự có thể đổi", "handwriting": "Nêu điều kiện tăng sản lượng là giả thuyết phải có dự báo; nhấn mục đổi trọng số trong phiếu.", "slideContent": "Hai kịch bản: nhu cầu ổn định 55 túi/phút và tương lai tăng sản lượng, nhiều loại bao bì. Thanh trượt trọng số và giả định.", "lectureScript": "Điều gì sẽ xảy ra nếu doanh nghiệp nhận được đơn hàng lớn, phải mở rộng nhiều dây chuyền và có đội kỹ thuật chuyên về dữ liệu? Khi đó phương án C có thể trở nên đáng xem xét hơn. Nhưng muốn thay đổi kết luận, ta phải thay các giả định về quy mô, cấu trúc chi phí, người vận hành và nhu cầu thực tế, chứ không nâng điểm theo sở thích. Điểm số và thứ tự có thể thay đổi, nhưng một phương án không đạt điều kiện bắt buộc không được trở lại chỉ vì tổng điểm cao. Đó là cách kết hợp kiểm tra độ nhạy với các cổng điều kiện để không chạy theo trào lưu công nghệ."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Thí điểm để kiểm chứng mức độ phù hợp", "handwriting": "Đánh dấu phương án B và C là hai ứng viên thử có điều kiện; hiển thị Q6.", "slideContent": "Kế hoạch thử: cùng lô túi và kiểu mã; thời lượng chạy; nhãn chuẩn; tỷ lệ phát hiện lỗi, loại nhầm, nhịp thực tế, dừng máy.", "lectureScript": "Trước khi chọn nhà cung cấp, tôi đề nghị tổ chức phép thử dùng chung cho B và C. Cả hai nên chạy trên cùng các loại túi, có nhãn chuẩn về lỗi nhãn và mã lô, trong điều kiện ánh sáng và tốc độ được ghi lại. Đánh giá cả tỷ lệ phát hiện túi lỗi, tỷ lệ loại nhầm túi tốt, nhịp xử lý hữu ích, thời gian chuyển mã và số lần can thiệp của người vận hành. Ngưỡng đạt phải thống nhất trước khi thử. Nếu chỉ xem màn hình trình diễn đẹp, chúng ta không biết công nghệ có giải quyết bài toán của An Bình hay không. Sau thử nghiệm, hãy yêu cầu báo cáo số đếm, nhật ký dừng và những điều kiện giới hạn."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Gắn quyết định với bằng chứng và phương án dự phòng", "handwriting": "Xuất nhãn chưa phê duyệt đầu tư; ghi đầu mối kỹ thuật và chất lượng.", "slideContent": "Bảng quyết định: loại sơ bộ / thử thêm / xem xét đề xuất đầu tư; người xác minh, hạn hoàn tất, phương án ứng phó khi thử trượt.", "lectureScript": "Sau vòng thử, doanh nghiệp có thể đi đến ba trạng thái: loại vì không đạt điều kiện bắt buộc; yêu cầu thử hoặc làm rõ thêm; hoặc đủ cơ sở để đưa vào quy trình xem xét đầu tư. Trạng thái thứ ba không thay thế phê duyệt tài chính, an toàn và hợp đồng. Bạn cũng cần ghi rõ rủi ro nếu thiết bị hoạt động sai, cách quay về quy trình kiểm thủ công và trách nhiệm hỗ trợ của nhà cung cấp. Nhờ đó quyết định có thể được xem lại khi điều kiện doanh nghiệp thay đổi."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao nhiệm vụ: chọn phương án phù hợp cho doanh nghiệp", "handwriting": "Chiếu phiếu với các ô vàng và nhắc người học thay số liệu; kết cảnh với lời mời tự làm.", "slideContent": "Slide tổng hợp: cổng bắt buộc -> chi phí theo kỳ -> ma trận điểm -> kế hoạch thí điểm; chỉ dẫn ba nhiệm vụ viết và bảng tự chấm.", "lectureScript": "Bây giờ, bạn hãy mở phiếu thực hành. Trước hết, thay nhịp yêu cầu bằng nhịp thực đo của doanh nghiệp và xác định phương án nào không đáp ứng. Tiếp theo, nhập chi phí trong cùng một đơn vị, chọn kỳ so sánh và tính điểm theo trọng số phù hợp. Cuối cùng, viết ba việc phải kiểm trước khi đề nghị đầu tư. Nếu bạn chỉ có một brochure, kết luận đúng có thể là chưa đủ bằng chứng, chứ không phải cố chọn một phương án. Bài học này kết thúc ở năng lực lựa chọn theo điều kiện thực tế, không ở tên một công nghệ. Bạn có thể dùng bảng tự đánh giá để tìm các phần còn thiếu trong hồ sơ của mình."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('415b0e9e-b613-5b75-820d-bfac26ae7146', '05cd1d76-9728-5680-8053-975784ac47d1', 1, 'EL-022-V22.1', 'VIDEO 22.1: TỪ NHU CẦU ĐẾN TIÊU CHÍ CÓ THỂ ĐO', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Vì sao cần bộ tiêu chí trước khi so máy", "handwriting": "Giữ năm bước thành một đường tiến trình, làm nổi bước lập tiêu chí.", "slideContent": "Bìa: Bài 22, giảng viên Bùi Diệu Linh. Sơ đồ: nhu cầu -> điều kiện bắt buộc -> tiêu chí -> ma trận -> thử nghiệm. Ví dụ An Bình; nhịp yêu cầu 55 túi/phút.", "lectureScript": "Chào bạn. Trong bài trước, doanh nghiệp nhận ra rằng hệ thống có nhiều tính năng chưa chắc giải quyết đúng công việc. Bây giờ chúng ta cần một cách so sánh các phương án công nghệ đủ rõ để những người khác nhau có thể kiểm tra kết luận. Hãy xét cơ sở đóng gói cà phê An Bình, đây là tình huống giả định. Dây chuyền cần kiểm nhãn và mã lô trên từng túi, với nhịp cao điểm tối thiểu năm mươi lăm túi một phút. Nếu chỉ ghi giải pháp nào hiện đại, rẻ hoặc dễ dùng thì chưa đủ. Bài này sẽ giúp bạn đặt tiêu chí đo được, chấm điểm có giải thích và xác định việc phải thử trước khi quyết định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Từ nhu cầu sang đầu ra đo được", "handwriting": "Nối các cụm từ của bản nhu cầu sang từng ô.", "slideContent": "Slide ba ô: Kết quả cần đạt / Điều kiện phải thỏa / Các yếu tố có thể đánh đổi. Ví dụ kiểm đúng mã, nhịp 55, độ thuận tiện.", "lectureScript": "Bước đầu là đọc lại bản mô tả nhu cầu. Doanh nghiệp cần nhận ra túi thiếu nhãn hoặc sai mã lô trước khi xuất kho. Ta phải biết sản phẩm nào được kiểm, nhịp nào cần đạt, dữ liệu nào được cung cấp và ai xác nhận kết quả. Những yêu cầu này khác với câu quảng cáo như nhận diện thông minh hay công nghệ thế hệ mới. Tôi đề nghị viết một câu kiểm chứng được cho mỗi kết quả. Ví dụ, hệ thống đối chiếu mã in trên túi với mã của lệnh sản xuất hiện hành. Nếu chưa xác định dữ liệu lệnh sản xuất ở đâu, hãy ghi đó là điều kiện cần xác minh thay vì tự cho điểm tối đa."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Cổng bắt buộc không được bù bằng điểm", "handwriting": "Kéo A vào cổng nhịp rồi cho dừng; B,C,D có dấu hỏi ở bằng chứng nhịp. Hiện Q1.", "slideContent": "Hai tầng: cổng điều kiện (chức năng kiểm nhãn/mã lô, nhịp >=55, an toàn tích hợp) và tiêu chí chấm sau cổng. Thẻ A 35 túi/phút.", "lectureScript": "Không phải điều kiện nào cũng đem ra chấm từ một đến năm. Nếu phương án không đọc được mã lô bắt buộc, hoặc nhịp thực đã kiểm chỉ đạt ba mươi lăm túi một phút trong khi dây chuyền cần năm mươi lăm, điểm giá rẻ không thể bù phần thiếu đó. Tôi gọi đây là cổng bắt buộc. Trong ví dụ, phương án A không đạt ngưỡng nhịp. Với B, C và D, tốc độ hiện mới là số công bố; chúng ta để trạng thái chờ xác minh, chưa coi là đạt. Nhớ rằng một phương án được phép so điểm sơ bộ chưa có nghĩa nó đã được chấp nhận để mua."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Tạo tiêu chí có tên và phép đo", "handwriting": "Gạch dưới từ mơ hồ \"dễ dùng\", thay bằng thời gian đào tạo, xử lý lỗi và số thao tác.", "slideContent": "Bảng 4 tiêu chí: đáp ứng chức năng; tích hợp; vận hành/hỗ trợ; chi phí vòng đời. Thêm cột cách quan sát và ai xác nhận.", "lectureScript": "Sau cổng bắt buộc, ta chọn những yếu tố có thể đánh đổi. Với An Bình, bốn nhóm minh họa là mức đáp ứng nhiệm vụ, khả năng tích hợp, năng lực vận hành và hỗ trợ, cùng chi phí trong một kỳ xác định. Mỗi nhóm phải có cách quan sát. Khả năng tích hợp chẳng hạn cần sơ đồ kết nối, giao diện dữ liệu, cơ cấu loại túi và trách nhiệm bảo trì. Chi phí cần thống nhất kỳ so sánh, không chỉ xem giá mua. Bộ tiêu chí này chưa phải bộ chuẩn bắt buộc cho mọi doanh nghiệp. Khi bài toán thay đổi, bạn phải cân nhắc đổi tiêu chí, chứ không chỉ thay điểm trong một bảng có sẵn."}, {"layout": "L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Chỉ số tốt phải có định nghĩa và nguồn", "handwriting": "Tạo thẻ dữ liệu gồm đơn vị, mẫu, thời điểm và nguồn. Hiện Q2.", "slideContent": "Ví dụ thẻ \"Nhịp hữu ích\": đơn vị túi/phút; quy tắc đo; số ca/kiểu túi; người xác nhận. Phản ví dụ \"máy chạy nhanh\".", "lectureScript": "Hãy kiểm tra một tiêu chí bằng bốn câu hỏi ngắn. Đang đo đại lượng gì? Đơn vị nào? Trong điều kiện nào? Ai cung cấp hoặc xác nhận số liệu? Chẳng hạn nhịp hữu ích cần biết số túi kiểm được trong một khoảng thời gian chạy có định nghĩa rõ, đồng thời ghi thời gian dừng và đổi mã. Nếu một bên báo tốc độ tối đa, bên kia báo tốc độ trung bình của cả ca, không thể lấy hai con số đặt cạnh nhau rồi chấm. Với độ chính xác cũng vậy, phải chỉ ra loại lỗi, cách đếm và mẫu thử. Khi thiếu bằng chứng, bạn ghi chưa xác minh thay vì tự bù bằng cảm tính."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Bài tập nhỏ: tách cổng và tiêu chí", "handwriting": "Kéo thẻ chức năng, an toàn, nhịp vào cổng; thẻ hỗ trợ, tích hợp, chi phí vào ma trận tùy bối cảnh.", "slideContent": "Slide hai cột: Điều kiện phải đạt / Yếu tố để so. Mời học viên phân loại 6 yêu cầu giả định và mở phiếu.", "lectureScript": "Sau video đầu, bạn hãy mở phiếu thực hành và kiểm ba dòng của hồ sơ An Bình. Việc đọc đúng mã lô và ngưỡng nhịp là những điều kiện phải xem trước. Chi phí, tiện ích vận hành và mức hỗ trợ là những yếu tố dùng để cân nhắc sau đó, với điều kiện doanh nghiệp đã chốt tiêu chuẩn tối thiểu cần thiết. Đừng vội chấm điểm cho phương án chưa biết có chạy được trong điều kiện thực hay không. Ở video tiếp theo, chúng ta sẽ thiết kế thang điểm để người kỹ thuật và người tài chính hiểu cùng một ý nghĩa khi ghi điểm bốn hoặc điểm năm."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('123e3321-1b23-53e2-b710-f5ac29f64bec', '05cd1d76-9728-5680-8053-975784ac47d1', 2, 'EL-022-V22.2', 'VIDEO 22.2: THIẾT KẾ THANG CHẤM VÀ MA TRẬN TRỌNG SỐ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Vì sao hai người cùng chấm lại khác điểm?", "handwriting": "Hiện hai điểm cạnh nhau và nhãn \"chưa thống nhất căn cứ\".", "slideContent": "Cùng tiêu chí \"tích hợp\", hai người cho 2 và 4. Thiếu thang mô tả mức điểm.", "lectureScript": "Một ma trận so sánh dễ trở thành bảng số mang vẻ khách quan. Hai người có thể cho cùng một phương án điểm hai hoặc bốn về tích hợp, vì mỗi người hiểu chữ dễ tích hợp theo cách riêng. Lỗi nằm ở việc chưa định nghĩa mức điểm, nguồn bằng chứng và ranh giới giữa thông tin đã kiểm với nhận định. Do đó, trước khi tính tổng, hãy thống nhất người chấm, phạm vi tiêu chí và cách phân biệt mức thấp với mức cao. Ma trận giúp ghi lại suy luận để có thể tranh luận và sửa, không phải máy tự động cho ra quyết định đúng."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Viết thang điểm 1-5 có điểm neo", "handwriting": "Viết điểm 1,3,5 trước, rồi đặt mô tả 2,4.", "slideContent": "Thang 1-5 cho tích hợp: 1 không đáp ứng; 2 phải sửa lớn; 3 cần điều chỉnh đáng kể; 4 ít điều chỉnh; 5 đã thử tích hợp đáp ứng. Các mức cần bằng chứng.", "lectureScript": "Ta thử thiết kế thang cho khả năng tích hợp. Điểm một nghĩa là không đáp ứng giao diện bắt buộc. Điểm ba nghĩa là tích hợp được về nguyên lý nhưng phải bổ sung phần kết nối, hiệu chỉnh hoặc nhân lực đáng kể. Điểm năm chỉ nên dành cho phương án đã có bằng chứng đáp ứng điều kiện tích hợp đã chốt tại doanh nghiệp, không phải chỉ vì nhà cung cấp nói lắp đặt dễ. Điểm hai và bốn nằm giữa những mốc mô tả này. Đối với chi phí, cũng cần thống nhất cùng thời hạn, những khoản đã tính và khoản chưa ước lượng."}, {"layout": "L2", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Trọng số phản ánh ưu tiên kinh doanh", "handwriting": "Hiển thị tổng =100%, minh họa không nhân phần trăm hai lần.", "slideContent": "Bốn trọng số minh họa: đáp ứng 35%, tích hợp 25%, vận hành/hỗ trợ 20%, chi phí vòng đời 20%. Tổng 100%.", "lectureScript": "Tiếp theo là trọng số. Ta dùng ví dụ ba mươi lăm phần trăm cho mức đáp ứng chức năng, hai mươi lăm phần trăm cho tích hợp, hai mươi phần trăm cho năng lực vận hành và hỗ trợ, hai mươi phần trăm cho chi phí vòng đời. Tổng phải bằng một trăm phần trăm. Đây là lựa chọn minh họa của một nhóm đánh giá, không có con số phổ quát cho mọi dự án. Người phụ trách kinh doanh cần giải thích tại sao tiêu chí này đáng quan tâm hơn tiêu chí khác. Nếu doanh nghiệp thay đổi mục tiêu hoặc giới hạn nguồn lực, trọng số cũng phải được xem lại. Quan trọng hơn, trọng số không được dùng để hợp thức hóa một phương án đã trượt điều kiện bắt buộc."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Chấm thử bốn phương án A-D", "handwriting": "Viết phép tính B=4 x (0,35+0,25+0,20+0,20)=4,00; đối chiếu D=3,85.", "slideContent": "Ma trận A: 3-5-5-5; B: 4-4-4-4; C: 5-2-2-2; D: 4-5-3-3. Cột tổng điểm. Cột cổng A không đạt; B,C,D chờ xác minh.", "lectureScript": "Bây giờ ta chấm bốn phương án giả định. Điểm các nhóm đều từ một đến năm, dùng chung thang vừa mô tả. Phương án B được bốn điểm ở cả bốn tiêu chí, vì vậy tổng có trọng số là bốn phẩy không. Phương án D được bốn, năm, ba, ba, cho kết quả ba phẩy tám mươi lăm. Phương án C điểm chức năng cao nhưng tích hợp và vận hành khó hơn nên tổng thấp hơn. Riêng A có thể đạt điểm trung bình khá nhưng đã trượt nhịp tối thiểu. Vì thế bảng tính sẽ không xếp A vào danh sách ứng viên hợp lệ để so tiếp. Các điểm ở đây là giả định, chưa phản ánh hiệu suất thiết bị thật."}, {"layout": "L2 -> L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Đọc đúng trạng thái thay vì chỉ nhìn hạng", "handwriting": "Tô đỏ A ở cổng; tô vàng B,C,D; hiển thị Q4.", "slideContent": "Cột riêng: Không đạt / Chờ xác minh / Đạt cổng. Các cột tổng điểm chỉ là xếp ưu tiên kiểm chứng.", "lectureScript": "Điểm tổng không thay cho cột trạng thái. Tôi muốn bạn nhìn kết quả thành hai lớp: có qua cổng bắt buộc hay không, và nếu đủ điều kiện để xem tiếp thì điểm so sánh là bao nhiêu. Ở bảng minh họa, A không đạt; B, C và D đang chờ kiểm chứng tốc độ, an toàn tích hợp hoặc số liệu hoạt động. Vì thế B đứng đầu theo điểm sơ bộ nhưng chưa được kết luận là phương án thắng thầu hay phù hợp nhất. Bạn có thể xếp mức ưu tiên thử nghiệm theo điểm, sau đó dùng cùng phép thử trên các kiểu túi và mã lô đại diện. Nếu bằng chứng mới khác giả định, phải sửa điểm."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Tự thay điểm và trọng số trong Excel", "handwriting": "Zoom cột C-F và ô kiểm tổng trọng số ở hàng 21.", "slideContent": "Chụp vùng ma trận ở phiếu; các ô điểm và trọng số màu vàng, điểm tổng tự tính. Hướng dẫn nhập số 1-5 và tổng 100%.", "lectureScript": "Bạn hãy vào sheet Phiếu thực hành, xem mỗi tiêu chí được đánh giá bằng bằng chứng gì, rồi thử đổi một điểm. Sau đó đổi trọng số, ví dụ giảm phần chức năng và tăng phần tích hợp, nhưng vẫn giữ tổng bằng một trăm phần trăm. Quan sát thứ tự điểm có thay đổi hay không. Excel giúp tính nhanh; Excel không biết điểm bạn nhập có căn cứ hay không. Vì vậy bên cạnh bảng số phải có người xác nhận, nguồn thông tin và điều kiện cần đo bổ sung. Video cuối sẽ hướng dẫn kiểm tra độ nhạy trước khi gửi một kiến nghị có điều kiện."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('9b0a9546-5c85-53e2-9b74-5c30bdbd67af', '05cd1d76-9728-5680-8053-975784ac47d1', 3, 'EL-022-V22.3', 'VIDEO 22.3: ĐỌC KẾT QUẢ, THỬ ĐỘ NHẠY VÀ LẬP BƯỚC KIỂM CHỨNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Xếp hạng có thể thay đổi khi giả định đổi", "handwriting": "Cho biểu đồ điểm thay đổi; nhãn \"ví dụ giả định\".", "slideContent": "Slide hai bảng trọng số: gốc 35-25-20-20; thử 25-35-20-20. Câu hỏi: có đổi thứ tự không?", "lectureScript": "Chúng ta đã tính được một thứ tự điểm sơ bộ. Nhưng thứ tự đó phụ thuộc cả trọng số lẫn những điểm mà nhóm đánh giá đưa vào. Thay vì chỉ lưu bảng kết quả, doanh nghiệp nên hỏi: khi giả định thay đổi trong giới hạn hợp lý, thứ hạng có bền không? Chẳng hạn nếu tích hợp trở thành ưu tiên cao hơn chức năng mở rộng, ta có thể chuyển mười điểm phần trăm từ trọng số chức năng sang tích hợp. Đây là phép kiểm tra độ nhạy, không phải cách điều chỉnh trọng số cho vừa phương án mình thích. Mỗi thay đổi phải có lý do."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Phân tích độ nhạy của B và D", "handwriting": "Viết D: 4x25%+5x35%+3x20%+3x20%=3,95.", "slideContent": "B=4,00 ở cả 2 kịch bản; D=3,85 với 35/25, tăng 3,95 với 25/35. So sánh ranh giới và bằng chứng.", "lectureScript": "Ta xem phép tính cụ thể. Với phương án B được bốn điểm ở mọi tiêu chí, đổi trọng số nhưng tổng vẫn một trăm phần trăm thì điểm B vẫn là bốn. Phương án D có điểm tích hợp năm, vì vậy khi tăng trọng số tích hợp lên ba mươi lăm phần trăm, điểm tổng tăng từ ba phẩy tám mươi lăm lên ba phẩy chín mươi lăm. D vẫn xếp sau B trong ví dụ này, nhưng khoảng cách hẹp đi rõ rệt. Nếu điểm vận hành hoặc điểm chức năng thay đổi sau thử nghiệm, thứ hạng có thể đảo. Đó là lý do cần lưu cả kịch bản và những giả định dẫn tới mỗi điểm."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Kiểm tra căn cứ cho điểm cao", "handwriting": "Thêm cột bằng chứng, đánh dấu cần thử với mọi điểm chưa xác minh; hiện Q5.", "slideContent": "Phiếu kiểm: thang mô tả, nguồn chứng cứ, ngày thử, số mẫu, người xác nhận. Ví dụ B tích hợp 4 có bản vẽ nhưng chưa thử chạy.", "lectureScript": "Bây giờ trở lại dữ liệu. Điểm bốn về tích hợp của B được ai đề xuất? Có sơ đồ kết nối và quy trình vận hành, hay mới là một tuyên bố? Hai phương án có thể có điểm giống nhau nhưng mức tin cậy khác nhau nếu một bên được thử tại nhà máy, bên kia chỉ có tài liệu giới thiệu. Hãy để phiếu đánh giá ghi rõ nguồn, ngày cung cấp, điều kiện, người kiểm và khoảng trống bằng chứng. Nếu thông tin chỉ là quảng cáo, đánh dấu cần xác minh. Thiếu bằng chứng thì tạm hoãn kết luận, không tự giảm điểm."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Tránh đếm đôi và bỏ sót tiêu chí", "handwriting": "Gạch hai tiêu chí trùng nghĩa; chuyển an toàn thiết yếu về cổng.", "slideContent": "Ví dụ tiêu chí \"chi phí đầu tư\" và \"giá mua\" trùng lắp; tiêu chí \"độ chính xác\" chưa định nghĩa; an toàn bị đưa vào điểm tùy chọn.", "lectureScript": "Có ba lỗi cần rà soát ở bộ tiêu chí. Một là đếm đôi: giá mua và chi phí đầu tư ban đầu rất có thể là cùng một khoản, nếu chấm thành hai mục riêng sẽ tăng trọng số giá ngoài chủ ý. Hai là tiêu chí mơ hồ: độ chính xác cao chưa đủ nếu không có loại lỗi, mẫu số và điều kiện đo. Ba là biến điều kiện an toàn hoặc tuân thủ bắt buộc thành một mục có thể bù bằng điểm. Khi rà soát, bạn nên xem bộ tiêu chí có bao phủ đúng nhiệm vụ, có chỗ nào chồng lấn và có điều kiện nào phải chuyển ra cổng sàng lọc."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Lập phép thử chung cho các phương án còn lại", "handwriting": "Các bước: thử mẫu -> ghi số đếm -> kiểm nhịp -> biên bản; hiện Q6.", "slideContent": "Kế hoạch thử B,C,D: cùng bộ túi, ánh sáng, mã lô, nhịp, nhãn chuẩn; đo phát hiện lỗi, loại nhầm, dừng máy, dữ liệu xuất.", "lectureScript": "Để thay giả định bằng bằng chứng, ta thiết kế phép thử chung cho B, C và D. Dùng các kiểu túi và mã lô đại diện, thống nhất cách gán nhãn chuẩn, điều kiện ánh sáng và nhịp chạy. Ghi số túi lỗi phát hiện đúng, số túi tốt bị loại nhầm, thời gian dừng và kết quả giao tiếp với dữ liệu lệnh sản xuất. Phải xác định trước ngưỡng chấp nhận, ai đo và ai xác nhận. Nếu mỗi nhà cung cấp chọn bộ mẫu thuận lợi riêng, điểm không thể so sánh công bằng. Sau thử, nhóm đánh giá cập nhật cả cổng bắt buộc, điểm và trạng thái bằng chứng."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Viết biên bản ma trận có thể truy vết", "handwriting": "Điền người phụ trách và thời điểm thử vào phiếu; trạng thái chưa phê duyệt đầu tư.", "slideContent": "Biểu mẫu quyết định: bộ tiêu chí phiên bản, điểm và trọng số, bản ghi họp, các bất đồng, nguồn dữ liệu, quyết định điều kiện.", "lectureScript": "Trước khi gửi kiến nghị, hãy lưu phiên bản bộ tiêu chí và bảng điểm. Ghi người tham gia đánh giá, nguồn cho từng điểm, bất đồng nếu có, ngày cập nhật và lý do thay đổi trọng số. Khi phát sinh kết quả thử mới, chúng ta cần biết vì sao điểm của một phương án tăng hoặc giảm. Kết luận nên ở dạng có điều kiện: tiếp tục thẩm định, yêu cầu kiểm thử bổ sung hoặc loại phương án do không đáp ứng điều kiện bắt buộc. Chỉ một bảng xếp hạng không đủ để đề xuất mua máy; còn phải xét hợp đồng, bảo trì, nguồn lực, chi phí và phê duyệt của doanh nghiệp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao nhiệm vụ: hoàn thiện ma trận công nghệ", "handwriting": "Tích dấu vào từng việc, hiện vùng ô vàng của phiếu và bảng tự chấm.", "slideContent": "Slide tổng kết 5 việc: đặt tiêu chí -> mô tả điểm -> đặt trọng số -> kiểm cổng -> thử độ nhạy/bằng chứng. Mở phiếu và tự chấm.", "lectureScript": "Bây giờ bạn hãy hoàn thiện bảng so sánh bằng trường hợp thực của đơn vị mình hoặc tình huống An Bình. Trước hết chốt yêu cầu nào bắt buộc. Tiếp theo viết nghĩa của điểm một, ba và năm cho từng tiêu chí, rồi chấm các ứng viên với cùng cách hiểu. Hãy thay một bộ trọng số có lý do và ghi mức thay đổi thứ hạng. Cuối cùng, nêu ít nhất hai dữ kiện cần xác minh để biến kết luận sơ bộ thành kết luận có thể kiểm tra. Bạn có thể dùng bảng tự chấm bảy tiêu chí để xem hồ sơ đã đủ rõ chưa. Đây là đầu ra của Bài 22."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('6331708a-175f-592d-a1b0-8ed3003238bf', '3bee64ab-aa58-568d-9644-4fcc98021485', 1, 'EL-023-V23.1', 'VIDEO 23.1: PHÂN RÃ VỐN ĐẦU TƯ VÀ CHI PHÍ VẬN HÀNH', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Từ giá mua tới bức tranh chi phí", "handwriting": "Cho xuất hiện lần lượt bốn ô; giữ ô giá máy nhỏ hơn tổng các ô còn lại.", "slideContent": "Bìa Bài 23 - Vũ Quang Sơn. Hình hộp: GIÁ MÁY / CHI PHÍ TRIỂN KHAI / VẬN HÀNH / LỢI ÍCH TIỀN. Dòng chân trang: Tình huống An Bình giả định.", "lectureScript": "Chào bạn. Ở Bài 21 và 22, chúng ta đã so sánh công nghệ theo mức phù hợp và các điều kiện triển khai. Hôm nay tôi sẽ cùng bạn trả lời một câu hỏi khác: một phương án tốn bao nhiêu tiền trong suốt thời gian sử dụng, và bao lâu mới thu hồi được vốn bỏ ra? Giả sử cơ sở đóng gói cà phê An Bình định lắp camera đọc nhãn và mã lô. Nhà cung cấp báo giá thiết bị là bốn trăm hai mươi triệu đồng. Nếu doanh nghiệp chỉ ghi đúng con số đó rồi trình duyệt, bản dự toán sẽ thiếu chi phí lắp đặt, đào tạo và vận hành. Toàn bộ số liệu chúng ta dùng là giả định để luyện phương pháp, không phải báo giá thật."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Phân loại hai dòng chi phí", "handwriting": "Kéo từng thẻ chi phí vào đúng cột; gạch chân câu hỏi \"trả lúc nào?\".", "slideContent": "Slide hai cột: CAPEX - chi phí đầu tư ban đầu; OPEX - chi phí vận hành lặp lại. Ví dụ đầu tư: thiết bị, tích hợp, đào tạo, dừng lắp đặt. Ví dụ vận hành: bảo trì, phần mềm, điện, vật tư.", "lectureScript": "Đầu tiên, ta phân loại theo thời điểm và tính chất dòng tiền. CAPEX trong bài là khoản chi ban đầu để đưa phương án vào sử dụng: giá mua máy, tích hợp, huấn luyện và chi phí dừng dây chuyền khi lắp đặt. OPEX là khoản chi lặp lại trong quá trình hoạt động: bảo trì, giấy phép phần mềm, điện và vật tư. Đây là phân loại phục vụ lập dòng tiền dự án; việc hạch toán kế toán hoặc vốn hóa một khoản mục còn phụ thuộc quy định áp dụng. Khi lập dự toán, hãy ghi rõ khoản tiền phát sinh lúc nào và đã nằm trong báo giá nào, để tránh ghi trùng."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Bóc tách khoản đầu tư", "handwriting": "Viết phép cộng 420+35+15+10=480; đóng khung 480 và hiện Q1 cuối cảnh.", "slideContent": "Bảng CAPEX (triệu đồng): máy 420; tích hợp 35; đào tạo 15; dừng lắp đặt 10; cộng = 480. Chú thích chi phí chỉ mang tính giả định.", "lectureScript": "Ta mở phiếu thực hành, phần A. Bốn khoản đầu tư ban đầu được giả định như sau: mua camera và bộ điều khiển bốn trăm hai mươi triệu; kết nối dữ liệu với dây chuyền ba mươi lăm triệu; đào tạo mười lăm triệu; tổn thất do dừng dây chuyền khi lắp đặt mười triệu. Cộng lại, nhu cầu vốn ban đầu là bốn trăm tám mươi triệu đồng. Tôi cố ý tách giá máy khỏi phần triển khai. Nếu hạng mục tích hợp đã được tính trong hợp đồng trọn gói, phải loại khỏi dòng bổ sung, chứ không cộng lần nữa. Câu hỏi tương tác thứ nhất sẽ kiểm tra cách bạn phân biệt giá thiết bị với tổng vốn thực chi."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Dự toán vận hành hằng năm", "handwriting": "Hiện lần lượt số 45, 30, 12, 13; kết nối sang ô OPEX/năm = 100.", "slideContent": "Bảng OPEX/năm (triệu đồng): bảo trì 45; giấy phép 30; điện 12; vật tư 13; tổng 100. Mốc kỳ phân tích 3 năm.", "lectureScript": "Bây giờ ta lập chi phí vận hành. Với hệ thống camera giả định, mỗi năm An Bình trả bốn mươi lăm triệu cho bảo trì, ba mươi triệu cho giấy phép phần mềm, mười hai triệu điện và mười ba triệu vật tư phụ trợ. Tổng là một trăm triệu đồng mỗi năm. Hãy để ý đơn vị ở đầu mỗi cột. Bốn trăm tám mươi triệu là khoản tại thời điểm đầu tư; một trăm triệu là chi phí theo năm. Không được cộng trực tiếp hai số để gọi là tổng chi phí ba năm. Ta còn phải nhân khoản hằng năm với thời gian sử dụng và kiểm tra các khoản bất thường có thể phát sinh trong từng năm."}, {"layout": "L2 -> L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Bỏ sót và đếm trùng chi phí", "handwriting": "Tô màu hai dòng \"bỏ sót\" và \"đếm trùng\"; bật Q2 cuối cảnh.", "slideContent": "Slide: bảng kiểm 6 câu hỏi - báo giá đã bao gồm thuế? tích hợp? bản quyền? đào tạo? bảo trì? dừng máy? Cảnh báo: kỳ và phạm vi phải thống nhất.", "lectureScript": "Có hai lỗi khi lập dự toán. Lỗi thứ nhất là bỏ sót, chẳng hạn chỉ lấy báo giá máy và quên chi phí duy trì giấy phép, đổi mã sản phẩm hoặc nhân sự cần học vận hành. Lỗi thứ hai là đếm trùng: hợp đồng đã bao gồm đào tạo mà bảng nội bộ vẫn tính thêm một dòng đào tạo nữa. Trước khi chốt con số, bạn nên hỏi bên cung cấp giá đã gồm những gì, khoản nào là một lần, khoản nào trả hằng năm, và điều kiện áp dụng là gì. Nếu chưa rõ, ghi trạng thái chờ xác minh. Đừng tự biến khoản chưa có báo giá thành số không. Câu hỏi thứ hai sẽ giúp bạn nhận diện lỗi đếm trùng."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Chốt đầu vào tài chính", "handwriting": "Đóng dấu GIẢ ĐỊNH lên cả hai con số; mũi tên sang Video 23.2.", "slideContent": "Sơ đồ khóa đầu vào: vốn ban đầu 480 triệu; OPEX 100 triệu/năm; kỳ so sánh 3 năm; giả định đồng nhất; hồ sơ báo giá cần kiểm.", "lectureScript": "Sau video đầu, bạn cần một bảng đã tách rõ vốn đầu tư ban đầu và chi phí lặp lại, có đơn vị tiền tệ, kỳ thời gian và nguồn dữ liệu. Trong ví dụ An Bình, vốn ban đầu là bốn trăm tám mươi triệu đồng; OPEX tạm tính một trăm triệu mỗi năm. Đây mới là đầu vào, chưa phải quyết định nên đầu tư. Bạn hãy mở phiếu thực hành, thay các ô số liệu bằng báo giá hoặc dự toán thật nếu có. Nếu chưa có bằng chứng, giữ chú thích giả định. Sang video tiếp theo, chúng ta sẽ đưa các khoản về cùng kỳ để tính tổng chi phí sở hữu."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('93a1ccf8-8317-562a-8451-d26034c6ca6e', '3bee64ab-aa58-568d-9644-4fcc98021485', 2, 'EL-023-V23.2', 'VIDEO 23.2: TÍNH TCO THEO KỲ SO SÁNH THỐNG NHẤT', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Vì sao giá rẻ chưa chắc rẻ khi dùng", "handwriting": "Chuyển biểu đồ từ một cột giá sang các dòng tiền theo năm.", "slideContent": "Bìa Video 23.2. Cùng thiết bị: giá mua 420; vốn đưa vào vận hành 480; chi phí hằng năm 100. Trục thời gian năm 0-3.", "lectureScript": "Chúng ta vừa thống nhất cách liệt kê dòng tiền. Bây giờ hãy xem hệ thống công nghệ như một khoản sở hữu và vận hành trong nhiều năm. Nếu chỉ so giá mua, bạn chưa biết phương án nào thực sự tốn ít chi phí hơn. Một thiết bị có giá mua thấp nhưng phải trả giấy phép hoặc bảo trì cao có thể trở nên đắt sau vài năm. Trong video này, tôi sẽ cùng bạn tính tổng chi phí sở hữu, thường gọi là TCO. Ta dùng cùng kỳ ba năm để không so lệch. Khi tính, cần nêu rõ những hạng mục đang có và những khoản chưa đưa vào mô hình."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Lập trục thời gian năm 0 đến năm 3", "handwriting": "Viết mũi tên dòng tiền và chú giải chi ra là dấu âm.", "slideContent": "Trục thời gian: năm 0 = -480; năm 1 = -100; năm 2 = -100; năm 3 = -100; chưa tính giá trị còn lại. Tất cả số liệu giả định.", "lectureScript": "Hãy tưởng tượng dòng tiền trên một trục thời gian. Tại năm không, doanh nghiệp chi bốn trăm tám mươi triệu để đưa hệ thống vào sử dụng. Năm một, năm hai và năm ba, mỗi năm chi thêm một trăm triệu để vận hành. Ta đang giả định các khoản vận hành không đổi, thanh toán vào cuối mỗi năm và chưa phát sinh sửa chữa lớn. Thực tế, bảo trì có thể tăng, giấy phép có thể thay đổi và máy có thể phải thay linh kiện. Nếu có dữ liệu đó, hãy lập dòng tiền riêng theo từng năm; đừng ép tất cả về một con số bình quân chỉ vì bảng mẫu đang đơn giản."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Công thức TCO theo cùng kỳ", "handwriting": "Viết phép tính với đơn vị triệu đồng; bật Q3 sau cảnh.", "slideContent": "Công thức minh họa: TCO 3 năm = CAPEX + OPEX/năm × 3 - giá trị còn lại có căn cứ. Thay số: 480 + 100 × 3 - 0 = 780 triệu.", "lectureScript": "Với giả định chi phí vận hành ổn định, tổng chi phí sở hữu trong ba năm được tính bằng vốn ban đầu cộng ba lần chi phí vận hành, rồi trừ giá trị thu hồi cuối kỳ nếu có căn cứ. Phiếu thực hành đang để giá trị thu hồi bằng không vì chưa có chứng cứ bán lại hoặc tái sử dụng. Ta có bốn trăm tám mươi cộng một trăm nhân ba, bằng bảy trăm tám mươi triệu đồng. Đây là TCO giản lược theo dòng tiền danh nghĩa, không phải giá trị hiện tại thuần. Hãy nhìn công thức trong Excel: khi đổi số năm hoặc chi phí vận hành, kết quả phải tự thay đổi. Câu hỏi thứ ba kiểm tra đúng phép tính này."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Cùng kỳ, cùng phạm vi và chi phí biên", "handwriting": "Đánh dấu bốn điều kiện so sánh; hiện ví dụ hai báo giá khác cấu phần.", "slideContent": "Bảng so sánh: cùng thời hạn; cùng mức sản lượng; cùng thuế và ranh giới chi phí; chi phí phát sinh thêm so với hiện trạng; không trộn giá danh nghĩa và giá chiết khấu.", "lectureScript": "Khi so hai phương án, ta phải dùng cùng kỳ và cùng phạm vi. Một bên báo giá đã gồm triển khai, bên kia mới báo thiết bị, thì chưa thể đặt hai số cạnh nhau rồi chọn. Tương tự, phương án tăng sản lượng đòi hỏi thêm người hoặc điện thì chi phí đó phải được tính. Một điểm cần lưu ý là chi phí dự án phải được đánh giá theo chênh lệch so với phương án tiếp tục làm như hiện tại. Tiền đã chi trong quá khứ và không thể thu hồi không nên trở thành lý do để tiếp tục đầu tư. Ta cần ghi rõ ranh giới tính chi phí, thời hạn và loại giá đang sử dụng."}, {"layout": "L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Vì sao TCO chưa nói được hoàn vốn", "handwriting": "Gạch dưới \"chi phí\" và \"lợi ích\"; bật Q4 cuối cảnh.", "slideContent": "Hai cột: TCO = dòng tiền chi; LỢI ÍCH TĂNG THÊM = tiết kiệm tiền hoặc thu tiền có thể chứng minh. Mũi tên tới dòng tiền thuần.", "lectureScript": "TCO cho biết doanh nghiệp dự kiến chi bao nhiêu trong kỳ xét, nhưng chưa cho biết hệ thống có tạo ra đủ lợi ích để bù chi phí hay không. Muốn xét hoàn vốn, ta còn cần dữ liệu tiết kiệm tiền hoặc doanh thu tăng thêm có thể quy cho dự án. Ví dụ: giảm sản phẩm bỏ, giảm chi phí làm thêm giờ và giảm hao hụt vật tư. Tuy nhiên, giảm số phút thao tác không đương nhiên là tiết kiệm tiền mặt. Nếu nhân viên vẫn làm đủ giờ và không giảm khoản chi nào, ta phải giải thích lợi ích đó dưới dạng năng lực hoặc thời gian, không tự cộng thành dòng tiền. Câu hỏi thứ tư kiểm tra sự phân biệt này."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Bảng TCO là đầu vào thẩm định", "handwriting": "Tô cam các trường cần xác minh; mũi tên Video 23.3.", "slideContent": "Slide tổng: CAPEX 480; OPEX/năm 100; 3 năm; TCO 780; ô chưa có số liệu: thuế, lạm phát, giá trị thu hồi, nâng cấp.", "lectureScript": "Sau video hai, bạn đã có phép tính TCO và bảng giả định rõ ràng. Trong ví dụ, kết quả ba năm là bảy trăm tám mươi triệu đồng, chưa xét thuế, lạm phát, chi phí vốn và các khoản bất thường. Bạn cần dùng kết quả này để hỏi báo giá đã đầy đủ chưa, chứ không dùng một mình nó để phê duyệt mua máy. Để đánh giá giá trị kinh tế, bước tiếp theo là dự toán dòng tiền tăng thêm so với hiện trạng. Ở video cuối, tôi sẽ hướng dẫn tính hoàn vốn đơn giản, thử điều kiện xấu đi và xác định khi nào cần phân tích sâu hơn bằng giá trị hiện tại thuần."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('db571fb0-50fa-57ad-9cf6-e2ddd64c8521', '3bee64ab-aa58-568d-9644-4fcc98021485', 3, 'EL-023-V23.3', 'VIDEO 23.3: HOÀN VỐN ĐƠN GIẢN VÀ THỬ ĐỘ NHẠY', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Giới thiệu câu hỏi hoàn vốn", "handwriting": "Đặt dấu hỏi giữa \"tiết kiệm gộp\" và \"tiền thuần\".", "slideContent": "Bìa Video 23.3: vốn ban đầu 480 triệu; chi thêm mỗi năm 100 triệu; tiết kiệm gộp 300 triệu/năm, tất cả giả định.", "lectureScript": "Trong hai video trước, chúng ta đã tính được vốn ban đầu và tổng chi phí sở hữu của một phương án. Giờ câu hỏi là: bao lâu doanh nghiệp thu hồi được khoản vốn ban đầu? Để trả lời, trước hết phải ước tính phần tiền tiết kiệm tăng thêm so với hoạt động hiện tại. Tôi nhấn mạnh chữ tiền: những cải thiện chất lượng, tốc độ và sự hài lòng có giá trị, nhưng chỉ đưa vào phép tính hoàn vốn khi đã có cách xác định dòng tiền phù hợp. Tình huống An Bình tiếp tục dùng số liệu giả định để minh họa từng bước."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Tính tiết kiệm gộp và dòng tiền thuần", "handwriting": "Viết phép tính 140+100+60=300; 300-100=200 và chú thích không đếm trùng.", "slideContent": "Bảng lợi ích tiền/năm: giảm phế phẩm 140; giảm làm thêm giờ 100; giảm hao hụt 60; tổng 300. Trừ OPEX 100 còn 200 triệu/năm.", "lectureScript": "Giả sử sau khi lắp hệ thống, An Bình tránh được một trăm bốn mươi triệu chi phí phế phẩm, một trăm triệu tiền làm thêm giờ và sáu mươi triệu hao hụt nguyên liệu mỗi năm. Tổng tiền tiết kiệm gộp là ba trăm triệu. Nhưng doanh nghiệp còn phải chi một trăm triệu mỗi năm để hệ thống chạy. Vì vậy dòng tiền thuần tăng thêm chỉ là hai trăm triệu một năm. Cẩn thận với sự đếm trùng: nếu chi phí phế phẩm đã bao gồm vật tư hao hụt, hai dòng phải được tách lại. Khoản tiết kiệm cũng cần có dữ liệu đường cơ sở và giả định sản lượng tương ứng."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Công thức hoàn vốn đơn giản", "handwriting": "Viết 480/200=2,40; gắn nhãn \"không chiết khấu\". Bật Q5 cuối cảnh.", "slideContent": "Hoàn vốn đơn giản (năm) = CAPEX / dòng tiền thuần tăng thêm hằng năm nếu dòng tiền dương và ổn định. 480/200=2,4 năm.", "lectureScript": "Nếu dòng tiền thuần tăng thêm dương và ổn định hằng năm, thời gian hoàn vốn đơn giản bằng vốn đầu tư ban đầu chia cho dòng tiền thuần tăng thêm mỗi năm. Thay số, bốn trăm tám mươi chia hai trăm bằng hai phẩy bốn năm. Phép tính này giả định tiền về đều trong năm và không có khoản chi đột biến. Nó không giống việc lấy bốn trăm tám mươi chia ba trăm, vì ba trăm chỉ là tiết kiệm gộp trước chi phí vận hành. Và nếu dòng tiền thuần bằng không hoặc âm, không có thời gian hoàn vốn hữu hạn theo giả định này. Câu hỏi thứ năm yêu cầu bạn chọn đúng mẫu số."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thử độ nhạy: lợi ích giảm", "handwriting": "Thay trực tiếp số ở ô vàng, quan sát thời gian hoàn vốn đổi; giải thích vượt kỳ ba năm.", "slideContent": "Bảng ba kịch bản: cơ sở 300-100=200 -> 2,40 năm; tiết kiệm giảm 20% còn 240-100=140 -> 3,43 năm; OPEX tăng 20% còn 300-120=180 -> 2,67 năm.", "lectureScript": "Không nên trình bày hai phẩy bốn năm như một kết quả chắc chắn. Nếu tiền tiết kiệm thực tế thấp hơn hai mươi phần trăm, lợi ích gộp chỉ còn hai trăm bốn mươi triệu. Trừ một trăm triệu vận hành, dòng tiền thuần còn một trăm bốn mươi triệu. Khi đó hoàn vốn kéo dài khoảng ba phẩy bốn ba năm, vượt kỳ ba năm mà ta đang xét. Trong một kịch bản khác, nếu chi phí vận hành tăng hai mươi phần trăm, dòng tiền thuần còn một trăm tám mươi triệu và hoàn vốn khoảng hai phẩy sáu bảy năm. Thay số trong phiếu để thấy quyết định phụ thuộc giả định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Giới hạn của hoàn vốn và NPV", "handwriting": "Khoanh cụm \"không xét chiết khấu\"; hiện bảng kiểm đầu vào NPV nếu được yêu cầu.", "slideContent": "Slide cảnh báo: hoàn vốn đơn giản không xét giá trị thời gian tiền; không phản ánh đầy đủ lợi ích sau mốc hoàn vốn; không đo rủi ro. NPV/IRR thuộc bước thẩm định sâu.", "lectureScript": "Thời gian hoàn vốn đơn giản giúp nhìn nhanh tốc độ thu hồi vốn, nhưng có giới hạn rõ ràng. Nó không xét giá trị thời gian của tiền, không cho thấy đầy đủ dòng tiền phát sinh sau mốc hoàn vốn và không tự phản ánh rủi ro của các giả định. Để phê duyệt khoản đầu tư lớn, doanh nghiệp cần xem dòng tiền theo từng năm, phương án tiếp tục hoạt động hiện tại, chi phí vốn và có thể dùng NPV hoặc IRR. Giáo trình quản trị vận hành cũng phân biệt ba cách phân tích này. Trong bài học ngắn, chúng ta dừng ở hoàn vốn đơn giản có kiểm tra độ nhạy, không tự tuyên bố dự án đã đạt hiệu quả tài chính toàn diện."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Lập danh mục bằng chứng và cổng quyết định", "handwriting": "Tick từng mục và làm mờ các mục chưa có bằng chứng; bật Q6 cuối cảnh.", "slideContent": "Checklist: báo giá cấu phần; năng suất thực tế; tỷ lệ lỗi nền; chi phí làm thêm; tiền tiết kiệm hiện thực hóa; phí duy trì; chi phí rủi ro; người phê duyệt.", "lectureScript": "Trước khi gửi đề xuất, bạn cần ghi rõ thông tin nào đã có bằng chứng. Phần đầu tư cần báo giá có phạm vi và điều khoản. Phần vận hành cần giá giấy phép, bảo trì, điện và điều kiện tăng giá. Phần lợi ích cần số liệu phế phẩm, làm thêm giờ và khoản tiền thực sự giảm sau thí điểm. Hãy xác nhận thời gian đo cùng mức sản lượng, tránh nhận công lao của công nghệ cho một thay đổi khác vừa xảy ra. Khi số liệu chưa đủ, kết luận đúng là cần kiểm chứng thêm. Câu hỏi tương tác cuối cùng hỏi bạn nên xử lý như thế nào khi hoàn vốn theo kịch bản xấu vượt kỳ dự án."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao nhiệm vụ nộp bảng dự toán", "handwriting": "Lần lượt hiện sáu bước; kết thúc bằng ô nộp bài và cảnh báo giả định.", "slideContent": "Slide tổng: phân loại chi phí -> TCO -> tiết kiệm tiền -> dòng tiền thuần -> hoàn vốn -> độ nhạy. Nhiệm vụ: hoàn thành phiếu, ba câu viết và tự chấm.", "lectureScript": "Kết thúc Bài 23, bạn hãy hoàn thành phiếu thực hành với ít nhất một phương án công nghệ: ghi chi phí đầu tư theo hạng mục, vận hành theo năm, kỳ phân tích, lợi ích tiền có nguồn, thời gian hoàn vốn và hai kịch bản thay đổi. Sau đó viết một đoạn giải thích vì sao kết quả vẫn là sơ bộ. Đừng chỉ nộp một con số hoàn vốn; người xem cần biết nó được tính từ dòng tiền nào, còn thiếu khoản gì và điều kiện nào có thể làm kết quả đổi khác. Khi có dữ liệu vận hành thực tế, bạn cập nhật lại toàn bộ bảng trước bước thẩm định đầu tư."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('5b117b6a-38a6-5a90-b7c4-650cb5785988', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 1, 'EL-024-V24.1', 'VIDEO 24.1: ĐO ĐÚNG PHẠM VI, ĐÚNG MẪU SỐ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Một công nghệ có thực sự tiết kiệm tài nguyên?", "handwriting": "Hiện số túi đạt, đồng hồ điện và thùng rác theo từng phương án; không gắn nhãn xanh cho phương án nào.", "slideContent": "Tiêu đề Bài 24, giảng viên Vũ Quang Sơn. Ảnh dựng ba lựa chọn A kiểm thủ công, B camera OCR, C AI đa camera; nhãn GIẢ ĐỊNH.", "lectureScript": "Chào bạn. Sau khi so tiêu chí và chi phí công nghệ, doanh nghiệp còn phải hỏi: phương án này dùng bao nhiêu điện, tạo bao nhiêu chất thải và có ảnh hưởng gì tới người vận hành? Ta quay lại cơ sở đóng gói cà phê An Bình, một tình huống hoàn toàn giả định. Phương án A đang kiểm nhãn bằng người. Phương án B thêm camera OCR. Phương án C dùng nhiều camera và phần mềm phân tích phức tạp hơn. Đừng mặc định phương án có tự động hóa cao nhất là thân thiện môi trường nhất. Tôi sẽ cùng bạn kiểm tra điều đó bằng số liệu có cùng phạm vi."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Xác định ranh giới đo và điều kiện so sánh", "handwriting": "Khoanh phạm vi từ đầu dây chuyền đóng gói đến túi đạt; ghi rõ CHƯA tính sản xuất thiết bị, vận tải, xử lý cuối vòng đời.", "slideContent": "Sơ đồ công đoạn đóng gói - kiểm nhãn; tô khung ranh giới điện công đoạn. Các phần ngoài ranh giới để nét đứt.", "lectureScript": "Đầu tiên phải vẽ ranh giới. Trong bài này, điện được đo cho công đoạn đóng gói và kiểm nhãn trong một tháng. Rác vật liệu là phần bao bì loại ra tại công đoạn đó. Chúng ta chưa tính điện rang cà phê, vận chuyển, sản xuất camera, máy chủ từ xa hay xử lý rác cuối vòng đời. Nếu bên cung cấp chỉ đưa điện tiêu thụ riêng của camera, trong khi doanh nghiệp đo toàn bộ dây chuyền, hai con số không thể đặt cạnh nhau. Hãy viết rõ ranh giới trước khi mở bảng tính. Phần không đo được ghi là chưa đánh giá, không tự xem bằng không."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Lấy sản phẩm đạt làm mẫu số", "handwriting": "Viết công thức kWh/túi đạt = kWh công đoạn / số túi đạt; hiện Q1.", "slideContent": "Bảng giả định A/B/C đều 10.000 túi đạt/tháng. Điện A 1.000, B 920, C 1.150 kWh/tháng.", "lectureScript": "Giả sử cả ba phương án được so ở cùng đầu ra mười nghìn túi đạt mỗi tháng. A cần một nghìn ki lô oát giờ điện; B cần chín trăm hai mươi; C cần một nghìn một trăm năm mươi. Bạn có thể thấy B dùng ít điện hơn A, còn C dùng nhiều hơn. Nhưng để so các tháng có sản lượng khác nhau, hãy dùng chỉ số cường độ: lấy điện trong phạm vi chia cho số túi đạt. Với A, kết quả là không phẩy một ki lô oát giờ trên túi. Câu hỏi đầu sẽ kiểm tra bạn phải chọn mẫu số nào."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Tại sao không chỉ nhìn tổng điện?", "handwriting": "Đổi ví dụ minh họa sản lượng khác nhau; hiển thị quy tắc kiểm chuẩn sản lượng và chế độ chạy.", "slideContent": "Hai đồ thị: tổng kWh/tháng và kWh/1.000 túi đạt. Cảnh báo: số ngày hoạt động và mức sử dụng công suất khác nhau.", "lectureScript": "Hãy hình dung tháng sau dây chuyền chạy ít đơn hàng hơn. Tổng điện giảm chưa chắc là hiệu quả năng lượng tăng, vì thời gian chạy cũng giảm. Ngược lại, một máy dùng điện nhiều hơn theo tháng có thể tạo ra nhiều sản phẩm đạt hơn. Vì vậy, báo cáo phải có cả tổng lượng và cường độ tính theo sản phẩm đạt. Ta còn phải ghi chế độ vận hành, loại bao bì, số ca, thời gian dừng và cách đo điện. Trong phiếu, nếu sản lượng giữa hai phương án khác nhau, bạn vẫn so được cường độ, nhưng không được coi chênh lệch tổng điện là lợi ích tương đương sản lượng."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Nhìn sang rác và phế phẩm vật liệu", "handwriting": "Điền phép tính 80/10.000, 50/10.000, 35/10.000; hiện Q2.", "slideContent": "Bảng rác bao bì A 80 kg, B 50 kg, C 35 kg/tháng; hình phân loại rác và ghi kg/1.000 túi đạt.", "lectureScript": "Điện không phải chỉ tiêu duy nhất. Với cùng mười nghìn túi đạt, giả sử công đoạn A có tám mươi ki lô gam bao bì loại bỏ, B năm mươi và C ba mươi lăm. Theo một nghìn túi đạt, ba phương án lần lượt phát sinh tám, năm và ba phẩy năm ki lô gam. C giảm rác nhiều nhất trong bộ số giả định, dù lại dùng điện cao hơn. Bạn phải ghi rõ rác nào được cân: túi hỏng, màng thừa hay bao bì hỗn hợp, và có phân loại để tái chế hay không. Câu hỏi thứ hai hỏi cách chọn đơn vị so sánh phù hợp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Khóa bảng đường cơ sở", "handwriting": "Đóng dấu GIẢ ĐỊNH lên số liệu. Mũi tên sang video thứ hai về chỉ số phát thải gián tiếp từ điện.", "slideContent": "Bảng chốt: phạm vi, kỳ một tháng, 10.000 túi đạt, điện kWh, rác kg, người đo, điều kiện thử.", "lectureScript": "Cuối video đầu, bạn đã có cách lập đường cơ sở đúng: ghi rõ phạm vi công đoạn, số túi đạt, điện năng và khối lượng rác trong cùng kỳ. Khi cần so công nghệ, ta chuẩn hóa mỗi chỉ số theo đơn vị sản phẩm đạt. Đừng chọn riêng số liệu tốt nhất của tháng này để so với tháng xấu nhất của phương án kia. Trong thực tế, An Bình phải có nhật ký đo, hóa đơn hoặc đồng hồ điện có thể phân bổ, biên bản cân rác và người xác nhận. Chúng ta sẽ dùng bộ giả định này để tiếp tục tính tỷ lệ thay đổi và một chỉ số CO₂e có giới hạn."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('bab2cf5b-a7b9-524a-8468-5ad8877d2b9a', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 2, 'EL-024-V24.2', 'VIDEO 24.2: QUY ĐỔI ĐIỆN, RÁC VÀ CO₂e THEO PHẠM VI', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Từ điện đến chỉ số CO₂e có giới hạn", "handwriting": "Tách đơn vị kWh và kg CO₂e; ký hiệu minh họa không phải hệ số chính thức.", "slideContent": "Mở video 24.2. Bảng điện 1.000 / 920 / 1.150 kWh; hệ số 0,60 kg CO₂e/kWh ghi rõ GIẢ ĐỊNH.", "lectureScript": "Trong video này, ta biến dữ liệu sử dụng tài nguyên thành các chỉ số có thể kiểm tra. Điện được đo bằng ki lô oát giờ. Phát thải khí nhà kính gắn với điện có thể được ước tính khi nhân lượng điện với hệ số phát thải phù hợp. Để bạn luyện công thức, tôi đặt hệ số bằng không phẩy sáu ki lô gam CO hai tương đương trên một ki lô oát giờ. Đây là con số giả định, không phải hệ số điện lưới chính thức của Việt Nam. Hồ sơ thực tế phải tra hệ số phù hợp năm, phạm vi, phương pháp báo cáo và ghi nguồn rõ ràng."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Tính phát thải gắn với điện", "handwriting": "Nhân 1.000×0,60; 920×0,60; 1.150×0,60; giữ chữ CHỈ TỪ ĐIỆN trong ô kết quả.", "slideContent": "Công thức kg CO₂e = kWh × kg CO₂e/kWh. Bảng A: 600, B: 552, C: 690 kg CO₂e/tháng.", "lectureScript": "Ta nhân lượng điện của từng phương án với hệ số minh họa. A có một nghìn nhân không phẩy sáu, bằng sáu trăm ki lô gam CO hai tương đương trong tháng. B tương ứng năm trăm năm mươi hai. C là sáu trăm chín mươi. Số này chỉ là ước tính từ điện đã khai báo, không phải toàn bộ dấu chân carbon công nghệ. Nó bỏ qua vật liệu sản xuất camera, linh kiện thay thế, vận tải, xử lý chất thải và các nguồn phát thải khác. Vì vậy, nếu bạn ghi báo cáo, tiêu đề đúng phải là phát thải ước tính gắn với điện trong phạm vi đã chọn."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tính phần trăm thay đổi có mẫu số rõ", "handwriting": "Gạch dưới mẫu số A và đơn vị túi đạt; hiện Q3 cuối cảnh.", "slideContent": "Công thức tỷ lệ = (chỉ số phương án - chỉ số A) / chỉ số A. Ví dụ điện/túi B giảm 8%, C tăng 15%.", "lectureScript": "Bây giờ ta đánh giá thay đổi so với A. Lấy cường độ điện của phương án trừ cường độ điện đường cơ sở, rồi chia cho cường độ của A. Với B, chỉ số giảm tám phần trăm. Với C, chỉ số tăng mười lăm phần trăm. Dấu âm có nghĩa là giảm, dấu dương là tăng, chưa tự nói tốt hay xấu cho tất cả mục tiêu. Nếu muốn tính theo năm, trước hết phải kiểm chứng rằng số tháng, sản lượng và điều kiện sản xuất đại diện. Đừng lấy chênh lệch một tháng rồi khẳng định cả năm đều như vậy."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Rác giảm nhưng điện có thể tăng", "handwriting": "Đưa hai phương án lên trục X/Y; chú thích đánh đổi, không cộng hai tỷ lệ thành một điểm.", "slideContent": "Biểu đồ 2 chiều: % thay đổi điện/túi, % thay đổi rác/túi; B (-8%, -37,5%); C (+15%, -56,25%).", "lectureScript": "Hãy đặt điện và rác lên cùng một bảng nhưng giữ riêng đơn vị. Trong ví dụ, B giảm tám phần trăm cường độ điện và giảm ba mươi bảy phẩy năm phần trăm cường độ rác. C giảm rác nhiều hơn, năm mươi sáu phẩy hai lăm phần trăm, nhưng điện tăng mười lăm phần trăm. Có một đánh đổi cần giải thích. Không được lấy ki lô gam rác cộng thẳng với ki lô gam CO hai tương đương, vì bản chất hai đại lượng khác nhau. Muốn gộp thành điểm tổng hợp phải xác định phương pháp, trọng số và chứng cứ riêng, không tự gán một nhãn xanh."}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Đọc chất thải, an toàn và các tác động khác", "handwriting": "Hiển thị cột đã đo / chưa đo, đánh dấu Q4 sau kiểm tra.", "slideContent": "Bảng kiểm: loại vật liệu; khả năng tái chế; tiếng ồn; nhiệt; hóa chất; công thái học; thiết bị điện tử hết tuổi.", "lectureScript": "Các chỉ số điện và rác mới phản ánh một phần tác động môi trường. Một hệ thống camera có thể tạo thêm thiết bị điện tử phải xử lý khi hết tuổi thọ. Một thiết bị khác có thể gây tiếng ồn hoặc sinh nhiệt ở chỗ người lao động đứng cả ca. Doanh nghiệp còn phải hỏi rác được phân loại, có thể tái sử dụng hay xử lý thế nào. Giáo trình quản trị vận hành cũng nhắc đến năng lượng, vật liệu, phát thải, tiếng ồn và an toàn sức khỏe. Trong bài thực hành, ta chưa định lượng tất cả các mặt này. Hãy đánh dấu chưa có số liệu và giao người phụ trách kiểm chứng, thay vì bỏ chúng khỏi quyết định."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Chốt bảng so sánh có ghi phạm vi", "handwriting": "Mũi tên sang Video 24.3: cân bằng đánh đổi và chuẩn bị thử nghiệm.", "slideContent": "Tổng hợp A/B/C: điện, rác trên 1.000 túi đạt; CO₂e ước tính riêng từ điện; vùng thiếu dữ liệu khoanh cam.", "lectureScript": "Sau video thứ hai, bạn có ba loại thông tin. Thứ nhất là cường độ điện trên sản phẩm đạt. Thứ hai là lượng rác vật liệu trên sản phẩm đạt, có cách cân và phân loại. Thứ ba là CO hai tương đương gắn với điện, chỉ mang ý nghĩa minh họa cho đến khi có hệ số chính thức. Các chỉ số được trình bày riêng, chưa dùng để chứng nhận phương án bền vững. Hãy đối chiếu số liệu đầu vào với người phụ trách chất lượng và kỹ thuật. Nếu con số chỉ lấy từ catalogue, phải ghi đó là dữ liệu công bố, chưa phải kết quả thử tại dây chuyền."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('6cf8a023-31a1-51ce-8851-5e980532763c', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 3, 'EL-024-V24.3', 'VIDEO 24.3: ĐỌC ĐÁNH ĐỔI VÀ LẬP PHÉP THỬ BỀN VỮNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Một bảng không tự quyết định thay người", "handwriting": "Gắn nhãn KẾT LUẬN SƠ BỘ; không vẽ biểu tượng chọn mua.", "slideContent": "Mở video 24.3. B giảm điện và rác, C giảm rác nhiều hơn nhưng tăng điện. Cả hai chưa có thử nghiệm thực tế.", "lectureScript": "Chúng ta đã thấy B và C có kết quả môi trường khác nhau trong bộ số minh họa. Vậy có thể mua ngay phương án B vì nó tiết kiệm điện hơn không? Chưa thể. Ta mới có giả định, chưa có đo thử trên cùng điều kiện thực tế. Quyết định cần bắt đầu từ yêu cầu bắt buộc: máy phải bảo đảm chất lượng kiểm nhãn, an toàn và nhịp sản xuất. Sau đó mới so năng lượng, vật liệu và các mặt khác. Điểm môi trường tốt không cho phép bỏ qua điều kiện an toàn."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Đặt điều kiện bắt buộc trước khi cho điểm", "handwriting": "Mô phỏng cổng không đạt: đưa phương án sang xác minh hoặc loại; không tăng điểm bù trừ.", "slideContent": "Ba cổng: an toàn/tuân thủ; chất lượng kiểm nhãn; đủ năng lực sản xuất. Mỗi cổng có trạng thái Đạt / Chưa rõ / Không đạt.", "lectureScript": "Giả sử một phương án tiêu thụ ít điện nhưng không bảo đảm chức năng phát hiện lỗi mã lô. Khi đó, doanh nghiệp không thể gọi nó là lựa chọn tốt chỉ vì con số kWh thấp. Tương tự, nếu hồ sơ an toàn điện hoặc xử lý chất thải có điểm chưa rõ, cần yêu cầu bên cung cấp chứng minh. Cổng bắt buộc phải được kiểm tra riêng. Cách làm này ngăn một chỉ tiêu tốt che khuất một rủi ro mà doanh nghiệp không được phép chấp nhận."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Đọc bảng so sánh trên 1.000 túi đạt", "handwriting": "Viết rõ ba cột đơn vị, khoanh đánh đổi B/C. Hiện Q5.", "slideContent": "Bảng: điện A100, B92, C115 kWh/1.000 túi; rác A8, B5, C3,5 kg/1.000 túi; CO₂e từ điện A60, B55,2, C69 kg/1.000 túi.", "lectureScript": "Hãy nhìn bảng cuối của phiếu thực hành. Cứ một nghìn túi đạt, A cần một trăm ki lô oát giờ điện, B chín mươi hai và C một trăm mười lăm. Rác vật liệu tương ứng là tám, năm và ba phẩy năm ki lô gam. Chỉ số CO hai tương đương từ điện, theo hệ số hoàn toàn giả định, là sáu mươi, năm mươi lăm phẩy hai và sáu mươi chín ki lô gam. B đang thuận lợi ở hai chỉ số; C có đánh đổi rõ giữa điện và rác. "}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thiết kế phép thử công bằng", "handwriting": "Lần lượt hiển thị nguồn đo, người đo, thời gian, tiêu chí chấp nhận.", "slideContent": "Kế hoạch thử: cùng loại bao bì, cỡ lô, số ca; công tơ điện; cân rác theo loại; báo cáo túi đạt và túi loại.", "lectureScript": "Để biến giả định thành bằng chứng, hãy thiết kế thử tại dây chuyền. Chọn loại bao bì và yêu cầu nhãn giống nhau. Ghi số túi đầu vào, túi đạt, thời gian chạy, dừng máy và điện theo công tơ có ranh giới rõ. Cân rác tại điểm phát sinh, tách màng thừa và túi phải loại. Nếu phương án được chạy vào ca ít đơn hàng hoặc với loại túi dễ hơn, dữ liệu đó chưa thể so trực tiếp. Trước thử nghiệm, thống nhất ai ghi số, ai kiểm tra chéo và ngưỡng sai lệch chấp nhận. "}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Đưa tác động vòng đời vào danh sách cần kiểm", "handwriting": "Hiển thị cột dữ liệu có / chưa có; ngăn suy diễn từ Scope điện thành toàn bộ vòng đời.", "slideContent": "Bảng mở rộng: chế tạo thiết bị, linh kiện thay, điện phần mềm, vận tải, tái chế, an toàn người lao động.", "lectureScript": "Có những tác động chưa nằm trong bảng định lượng nhưng vẫn ảnh hưởng lựa chọn. Camera và máy tính cần linh kiện, vật liệu, việc bảo dưỡng và cuối cùng là xử lý sau khi hết tuổi sử dụng. Nếu phần mềm xử lý dữ liệu trên máy chủ ngoài công đoạn, điện đó có thể chưa nằm trong công tơ mà ta đo. Mặt khác, một thiết bị giảm phế phẩm có thể giúp giảm sử dụng bao bì đầu vào. Đây là những câu hỏi cần thu thập dữ liệu vòng đời, không phải số đã được chứng minh. "}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Viết kết luận có điều kiện và người xác minh", "handwriting": "Bật Q6; tô vàng ô kế hoạch đo và nguồn hệ số.", "slideContent": "Mẫu kết luận: theo số giả định, B giảm điện và rác; C giảm rác nhưng tăng điện. Chưa xác minh cổng bắt buộc và tác động vòng đời.", "lectureScript": "Cách viết kết luận đúng có ba phần. Nêu dữ liệu đang có và phạm vi áp dụng. Chỉ ra điều chưa được đo hoặc chưa đạt bằng chứng. Cuối cùng, đề xuất phép thử với đầu mối chịu trách nhiệm. Chẳng hạn: với cùng mười nghìn túi đạt trong tháng giả định, B giảm tám phần trăm điện trên túi và ba mươi bảy phẩy năm phần trăm rác trên túi so với A. Chưa thể kết luận phương án nào bền vững hơn toàn diện. Cần kiểm chứng chất lượng kiểm nhãn, an toàn vận hành, năng lượng thực đo và dữ liệu xử lý rác. "}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao sản phẩm thực hành Bài 24", "handwriting": "Hiện từng mục và kết thúc bằng yêu cầu điền phiếu, tự chấm và ba câu viết.", "slideContent": "Slide checklist nộp: phạm vi, mẫu số, điện, rác, CO₂e điện giả định, đánh đổi, thử nghiệm và người phụ trách.", "lectureScript": "Kết thúc Bài 24, bạn hãy điền phiếu thực hành với một công nghệ đang được cân nhắc. Giữ nguyên đơn vị chức năng khi so các phương án, ghi đường cơ sở và nguồn đo. Tự tính điện và rác trên một nghìn sản phẩm đạt; nếu quy đổi khí nhà kính từ điện, phải ghi rõ hệ số và nguồn phù hợp. Sau đó, mô tả ít nhất một đánh đổi và viết kế hoạch thí điểm. Hãy tự chấm trước bước lựa chọn công nghệ."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('083fdd19-19f9-5db1-8ab6-0f5dd26f97eb', '0c0953ac-233f-5928-8c22-045b5eea81b2', 1, 'EL-025-V25.1', 'VIDEO 25.1: GHI ĐÚNG SỰ KIỆN VÀ PHÂN LOẠI NĂM NHÓM RỦI RO', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Mở đầu: công nghệ tốt vẫn có thể gây gián đoạn", "handwriting": "Cảnh đóng gói chạy bình thường, sau đó xuất hiện ba thẻ: cảnh báo sai, mất dữ liệu, thiếu phụ tùng.", "slideContent": "Bài 25; Vũ Quang Sơn; sơ đồ dây chuyền cà phê An Bình và camera OCR kiểm tra nhãn, mã lô.", "lectureScript": "Chào bạn. Khi chọn công nghệ, chúng ta thường xem chức năng, tốc độ và chi phí. Nhưng một thiết bị đạt điểm tốt vẫn có thể làm sản xuất gián đoạn. Giả sử cơ sở đóng gói cà phê An Bình đang cân nhắc camera đọc nhãn và mã lô. Camera thử tốt ban ngày, nhưng có nguy cơ bỏ sót mã trong ca tối. Nhà cung cấp chỉ hỗ trợ từ xa, còn dữ liệu ảnh nằm trên máy chủ của họ. Trước khi ký hợp đồng, doanh nghiệp cần đánh giá những nguy cơ này. Trong bài, bạn sẽ lập sổ rủi ro, chấm mức độ và xây kế hoạch kiểm soát. Các tình huống, điểm số đều giả định để học tập."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Rủi ro là sự kiện bất định gắn với mục tiêu", "handwriting": "Tô màu phần còn bất định; điền mẫu câu “Nếu... thì... làm ảnh hưởng...”.", "slideContent": "Sơ đồ: mục tiêu - sự kiện có thể xảy ra - hậu quả; so sánh rủi ro với vấn đề đã xảy ra.", "lectureScript": "Trước hết, rủi ro là khả năng một sự kiện chưa chắc xảy ra nhưng có thể ảnh hưởng mục tiêu. Nếu một lỗi đã xuất hiện và được ghi nhận, đó là vấn đề hiện hữu cần xử lý; còn nguy cơ lỗi tái diễn trong điều kiện khác là rủi ro. Cách ghi rủi ro cần đủ ba phần: sự kiện, nguyên nhân hoặc điều kiện có thể kích hoạt, và hậu quả đối với doanh nghiệp. Ví dụ: nếu camera không nhận rõ chữ trên túi phản quang khi ánh sáng thay đổi, túi sai mã có thể đi qua khâu kiểm tra. Câu “công nghệ không ổn” không giúp thiết kế phép thử. Hãy viết cụ thể sự kiện và chỉ số chịu ảnh hưởng."}, {"layout": "L2 -> L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Năm nhóm rủi ro cần rà soát", "handwriting": "Hiện từng nhóm với một ví dụ An Bình; bật câu hỏi Q1.", "slideContent": "Bảng năm nhóm: kỹ thuật; dữ liệu; sở hữu trí tuệ; nhà cung cấp; phụ thuộc công nghệ.", "lectureScript": "Với An Bình, ta rà năm nhóm. Kỹ thuật gồm lỗi nhận dạng, tích hợp băng tải và xử lý khi thiết bị dừng. Dữ liệu gồm mẫu thiếu đại diện, nhãn chuẩn sai, quyền truy cập và sao lưu. Sở hữu trí tuệ đòi hỏi làm rõ giấy phép phần mềm, mô hình OCR và quyền dùng ảnh. Nhà cung cấp liên quan thời gian hỗ trợ, phụ tùng, bàn giao. Phụ thuộc công nghệ xuất hiện khi không xuất được nhật ký hoặc muốn đổi nhà cung cấp mà không thể tiếp tục vận hành. Một rủi ro có thể chạm nhiều nhóm. Ta chọn nhóm chịu trách nhiệm chính để theo dõi nhưng không bỏ qua các nhóm liên quan."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Viết sự kiện rủi ro có thể kiểm chứng", "handwriting": "Gạch bỏ câu mơ hồ; viết hoàn chỉnh sự kiện - hệ quả; hiển thị người xác minh.", "slideContent": "Bảng ba câu: “Camera kém”; “Nếu ánh sáng yếu...”; “Nếu dữ liệu không xuất được...”.", "lectureScript": "Giờ hãy thử biến một nhãn mơ hồ thành dòng dùng được trong sổ. “Phần mềm có rủi ro dữ liệu” là câu quá rộng. Có thể viết: nếu ảnh lỗi và nhật ký chỉ lưu trong định dạng riêng, đội chất lượng không tự kiểm tra lại các cảnh báo khi đổi nhà cung cấp. Hậu quả là mất khả năng truy xuất và phụ thuộc vào một đối tác. Tiếp theo, chỉ rõ bằng chứng cần tìm: mẫu tệp xuất, tài liệu giao diện và một lần khôi phục thử. Khi có sự kiện cụ thể, ta mới quyết định ai kiểm tra, kiểm tra bằng phương pháp nào và điều kiện nào phải dừng thử. Đừng biến suy đoán thành sự cố đã được chứng minh."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Bằng chứng chưa có không có nghĩa rủi ro thấp", "handwriting": "Tô ô G9 và G10 trong phiếu; bật câu hỏi Q2.", "slideContent": "Ba mức bằng chứng: Đã có - Thiếu - Chưa xác minh; ví dụ hồ sơ quyền sử dụng phần mềm.", "lectureScript": "Một sai lầm hay gặp là ghi mức rủi ro thấp chỉ vì chưa thấy xảy ra. Nếu chưa chạy thử ca đêm, ta chưa có căn cứ nói camera ít bỏ sót lỗi trong ca đó. Nếu chưa đọc giấy phép phần mềm, chưa thể kết luận doanh nghiệp được quyền cập nhật hay chuyển giao cho bên khác. Trong phiếu thực hành, cột bằng chứng có ba trạng thái: đã có tài liệu kiểm được, còn thiếu, hoặc chưa xác minh tính hiệu lực. Đây là trạng thái của hồ sơ, không phải một phép đo mức nguy hiểm. Cần yêu cầu đúng bằng chứng, nêu chủ thể xác nhận và ghi hạn bổ sung. Với điều kiện bắt buộc, thiếu chứng cứ phải chặn việc chốt quyết định."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Chốt sản phẩm video một", "handwriting": "Tô sáu dòng R1-R6; chuyển sang phần chấm điểm.", "slideContent": "Mẫu 6 dòng sổ rủi ro, nhãn GIẢ ĐỊNH; 5 nhóm và nguồn bằng chứng.", "lectureScript": "Sau video một, bạn hãy viết ít nhất năm sự kiện rủi ro, trong đó có đủ năm nhóm. Không cần bắt đầu bằng danh sách thật dài. Hãy ưu tiên những sự kiện có thể cản trở mục tiêu giảm lỗi nhãn, truy xuất mã lô hoặc vận hành ổn định. Mỗi dòng phải nói được sự kiện, hậu quả và bằng chứng đang có hay còn thiếu. Ở video sau, chúng ta dùng thang điểm để sắp thứ tự việc cần kiểm tra. Điểm chỉ là công cụ tổ chức thảo luận, không thay thế kết quả thử nghiệm hoặc quyền quyết định của người chịu trách nhiệm. Bạn có thể mở sheet Phiếu thực hành ngay sau video này."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('7ab21d70-64a6-593c-8399-25eb093562c7', '0c0953ac-233f-5928-8c22-045b5eea81b2', 2, 'EL-025-V25.2', 'VIDEO 25.2: CHẤM P, I VÀ KIỂM CỔNG BẮT BUỘC', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Đánh giá để phân công nguồn lực", "handwriting": "Nổi bật thang 1-5 và dòng R1 trong bảng.", "slideContent": "Mục tiêu video hai: P, I, mức ưu tiên và cổng bắt buộc.", "lectureScript": "Ở video hai, ta quyết định nên kiểm tra rủi ro nào trước. Một lỗi nhận dạng xảy ra thường xuyên nhưng tác động nhẹ khác với sự cố hiếm hơn mà làm mất truy xuất mã lô. Vì vậy, phiếu dùng hai điểm: khả năng xảy ra P và mức tác động I, mỗi điểm từ một đến năm. Với P, một là ít khả năng trong điều kiện được xét; năm là rất đáng lo. Với I, một là hậu quả nhỏ; năm là hậu quả nghiêm trọng. Khi áp dụng thực tế, nhóm phải định nghĩa từng mức theo bối cảnh vận hành. Không được đọc P bằng ba thành xác suất ba mươi phần trăm."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Tính điểm sàng lọc P nhân I", "handwriting": "Viết R1: 4 x 4 = 16; R4: 4 x 3 = 12; vòng tròn vào mức cao.", "slideContent": "Thang P/I 1-5; công thức P x I; dải 1-5, 6-12, 15-25.", "lectureScript": "Tôi minh họa hai dòng. R1 là camera bỏ sót mã khi thiếu sáng. Nhóm giả định P bằng bốn, I bằng bốn, nên điểm là mười sáu. R4 là nhà cung cấp chậm thay linh kiện, có P bằng bốn và I bằng ba, điểm mười hai. Phiếu dùng mức thấp từ một đến năm, trung bình từ sáu đến mười hai, cao từ mười lăm trở lên. Với phép nhân hai số nguyên một đến năm, điểm mười ba và mười bốn không xuất hiện. Đây là thang minh họa để sắp thứ tự kiểm tra, không phải xác suất sự cố và cũng không phải giá trị tiền tổn thất."}, {"layout": "L2", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Chấm điểm phải có căn cứ và người chấm", "handwriting": "Từ điểm P/I bật Q3; hiện nhãn điểm sơ bộ.", "slideContent": "Bảng R1: phạm vi ca ngày/đêm; mẫu ảnh; nhật ký bỏ sót; xác nhận QC.", "lectureScript": "Cùng một rủi ro, kỹ thuật có thể cho điểm P bằng hai, còn đội chất lượng cho bằng bốn. Trước khi tranh luận ai đúng, hãy hỏi mỗi bên dựa vào dữ liệu nào. Họ đã chạy những ca nào, gặp bao nhiêu lần, có đối chứng nhãn chuẩn không, và điều kiện nào chưa thử? Với camera OCR, một bộ ảnh do nhà cung cấp chọn sẵn không đủ đại diện cho tất cả loại túi, tốc độ và điều kiện chiếu sáng. Nếu chưa có bằng chứng, ghi rõ điểm tạm và người phải xác minh. Trong thực tế, ta nên thống nhất thang chấm theo hậu quả vận hành và rà lại sau thử nghiệm. Một con số được ghi cẩn thận vẫn có thể chỉ là giả thuyết."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Cổng bắt buộc không được bù bằng điểm", "handwriting": "Cho R2, R3 cổng bắt buộc chưa có chứng cứ; hiển thị quyết định tạm dừng.", "slideContent": "Hai cột: cổng Bắt buộc/Thông thường, bằng chứng Đã có/Thiếu/Chưa xác minh.", "lectureScript": "Bây giờ có một nguyên tắc không được bỏ qua. Một điểm tổng hợp thấp không làm hợp lệ việc sử dụng phần mềm khi quyền chưa rõ; tương tự, không thể bỏ qua yêu cầu an toàn chỉ vì rủi ro được chấm ở mức trung bình. Phiếu có cột cổng bắt buộc. Chẳng hạn R2 liên quan tính đại diện của dữ liệu thử trước khi nghiệm thu, còn R3 liên quan quyền dùng phần mềm và ảnh. Cả hai đang thiếu bằng chứng hoặc chưa xác minh. Công thức đếm số cổng còn mở và trả trạng thái dừng chốt quyết định. Dừng ở đây nghĩa là chưa phê duyệt triển khai hoặc ký theo giả định, không có nghĩa buộc loại vĩnh viễn công nghệ."}, {"layout": "L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Đọc bảng tổng hợp mà không cộng sai", "handwriting": "Hiển thị công thức COUNTIF/COUNTIFS; bật Q4.", "slideContent": "Bảng phiếu: ba rủi ro cao; hai cổng thiếu; bốn dòng cần bổ sung bằng chứng.", "lectureScript": "Hãy xem bảng tổng hợp minh họa. Ba rủi ro được chấm từ mười lăm điểm trở lên: R1, R2 và R3. Hai dòng có điều kiện bắt buộc chưa đủ bằng chứng: R2 và R3. Bốn dòng chưa có hoặc chưa xác minh tài liệu gồm R2, R3, R4, R5. Ba con số trả lời ba câu hỏi khác nhau. Đừng cộng tất cả điểm rủi ro thành một số rồi gọi đó là xác suất dự án thất bại. Việc ưu tiên phải xét hậu quả thực tế, khả năng kiểm soát, quy định liên quan và thời điểm quyết định. Nếu thay đổi một điểm hoặc trạng thái tài liệu trong ô vàng, các ô tổng hợp tự cập nhật và bạn cần đọc lại kết luận."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Chốt thứ tự xử lý bằng cổng và bằng chứng", "handwriting": "Đưa mũi tên sang video ba.", "slideContent": "Lưu đồ: kiểm cổng -> giảm rủi ro cao -> thử có kiểm soát -> đánh giá lại.", "lectureScript": "Kết thúc video hai, bạn có thể sàng lọc việc cần xử lý. Trước hết, đóng những cổng bắt buộc chưa có chứng cứ. Tiếp theo, ưu tiên các rủi ro cao và các điểm có thể tạo hậu quả khó khắc phục. Sau đó thiết kế phép thử để kiểm lại P và I, thay vì giữ nguyên điểm ban đầu như một sự thật. Với An Bình, việc cần làm ngay là kiểm dữ liệu ca đêm và làm rõ quyền sử dụng phần mềm, dữ liệu. Việc nhà cung cấp thiếu cam kết hỗ trợ cũng phải đưa vào điều kiện hợp đồng. Video cuối sẽ chuyển từng rủi ro thành hành động, người chịu trách nhiệm và chứng cứ phải nộp."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('ed0324ec-cea2-5af7-bcea-e7cabdbfe634', '0c0953ac-233f-5928-8c22-045b5eea81b2', 3, 'EL-025-V25.3', 'VIDEO 25.3: LẬP KẾ HOẠCH KIỂM SOÁT VÀ CHỐT BƯỚC XÁC MINH', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Không thể chỉ lập bảng rồi để đó", "handwriting": "Hiện bảng R1-R6 với cột biện pháp và bằng chứng.", "slideContent": "Mục tiêu video ba: biện pháp, chủ sở hữu, hạn và tiêu chí chấp nhận.", "lectureScript": "Một sổ rủi ro không tạo kết quả nếu thiếu người xử lý. Mỗi dòng cần một người chịu trách nhiệm, biện pháp kiểm soát, bằng chứng xác nhận và thời điểm đánh giá lại. Biện pháp không nhất thiết là mua thiết bị. Có trường hợp phải đổi cách lấy mẫu, sửa quy trình bàn giao hoặc bổ sung điều khoản hợp đồng. Ở video này, bạn sẽ lập kế hoạch cho năm nhóm rủi ro của An Bình và kiểm tra xem điều kiện nào chưa được đáp ứng. Các con số của An Bình chỉ là giả định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Kiểm soát kỹ thuật bằng phép thử có thể lặp", "handwriting": "Cho bảng thử nhiều điều kiện; minh họa lưu log và cơ chế dừng an toàn.", "slideContent": "R1 và R6; tình huống ánh sáng yếu, cơ chế cảnh báo, người xác nhận.", "lectureScript": "Với R1, hãy thử camera trong các điều kiện chiếu sáng, bề mặt túi và tốc độ dự kiến. Cần mẫu lỗi thật, nhãn chuẩn độc lập và nhật ký các trường hợp nhận dạng sai. Không nên chỉ nhận tỷ lệ chính xác nhà cung cấp công bố. Với R6, hãy kiểm tra điều gì xảy ra khi người vận hành bỏ qua cảnh báo: có ghi nhật ký không, ai được phân quyền, lỗi có bị chặn không? Biện pháp có thể gồm cảnh báo kép và quy trình xử lý ngoại lệ. Mỗi biện pháp cần tiêu chí nghiệm thu cụ thể và người xác nhận trước khi chạy diện rộng."}, {"layout": "L2 -> L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Dữ liệu và sở hữu trí tuệ cần xác minh riêng", "handwriting": "Đánh dấu yêu cầu hồ sơ; bật Q5.", "slideContent": "R2: dữ liệu ca/loại túi; R3: giấy phép phần mềm, quyền dữ liệu và bên thứ ba.", "lectureScript": "R2 liên quan dữ liệu thử. Đội chất lượng phải lấy mẫu đủ ca, loại túi và nhóm lỗi, kiểm tra nhãn chuẩn, rồi đo tỷ lệ bỏ sót và loại nhầm. R3 lại liên quan quyền: ai được dùng phần mềm, cập nhật mô hình, lưu và xuất ảnh, thành phần nào thuộc bên thứ ba? Hai vấn đề phải kiểm riêng. Một camera nhận dạng tốt vẫn có thể thiếu quyền khai thác. Hãy yêu cầu giấy phép, phụ lục dữ liệu và xác nhận của người phụ trách pháp lý. Khi thiếu bằng chứng bắt buộc, chưa được ghi trạng thái đủ điều kiện tiếp nhận."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Ràng buộc nhà cung cấp và phương án thoát", "handwriting": "Kéo hai hàng kiểm soát, trình bày thử xuất dữ liệu bằng tệp mẫu.", "slideContent": "R4: SLA và linh kiện; R5: giao diện, định dạng xuất và khả năng chuyển nhà cung cấp.", "lectureScript": "Rủi ro nhà cung cấp đòi hỏi cam kết cụ thể. Khi camera dừng, nhà cung cấp phản hồi, khôi phục và thay linh kiện sau bao lâu? Cần SLA và điều khoản kiểm tra được. Với phụ thuộc công nghệ, hãy thử xuất nhật ký, ảnh và mã lô sang định dạng đọc được; kiểm tra tài liệu giao diện và khả năng chuyển dữ liệu sang hệ thống khác. Hợp đồng cần làm rõ quyền dùng dữ liệu khi chấm dứt, cũng như trách nhiệm hỗ trợ chuyển đổi. Đó là hai nhóm rủi ro khác nhau."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Kiểm tra lại rủi ro còn lại sau biện pháp", "handwriting": "Ghi điểm cũ cạnh điểm chờ xác minh, không tự động giảm điểm khi mới lập kế hoạch.", "slideContent": "Sơ đồ trước kiểm soát -> hành động -> thử lại -> P/I còn lại.", "lectureScript": "Sau khi đề xuất biện pháp, không tự động giảm điểm rủi ro. R1 từ mười sáu điểm không thể thành bốn chỉ vì nhóm dự kiến lắp thêm đèn. Cần thực hiện phép thử, lưu kết quả và có người xác nhận. Khi biện pháp đã hoạt động, nhóm mới chấm lại P và I, ghi lý do thay đổi và lưu điểm trước kiểm soát. Rủi ro còn lại phải có người có thẩm quyền chấp nhận. Đôi khi phải đổi phạm vi triển khai. Điểm số không thay quyết định chấp nhận rủi ro."}, {"layout": "L2 -> L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Đưa ra quyết định theo cổng và bằng chứng", "handwriting": "Bật Q6; hiện kết quả mặc định C18=2 và C20 dừng chốt.", "slideContent": "Lưu đồ: thiếu cổng bắt buộc -> tạm dừng; đủ cổng -> xét rủi ro cao và thử nghiệm.", "lectureScript": "Phiếu hiện có hai cổng bắt buộc chưa đủ bằng chứng. Đề xuất là tạm dừng việc chốt lựa chọn, giao người bổ sung tài liệu và ấn hạn xác minh. Khi hai cổng đã được đóng, bảng mới chuyển sang xem xét các rủi ro cao. Khi ấy doanh nghiệp vẫn cần phép thử có kiểm soát, xem tác động và chi phí của biện pháp trước quyết định đầu tư. Bạn cần phân biệt “chuyển thẩm định tiếp” với “được phê duyệt”. Phân quyền quyết định, yêu cầu an toàn và điều khoản hợp đồng phải được xem xét theo quy trình riêng."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao sản phẩm thực hành và tự đánh giá", "handwriting": "Bật từng đầu mục trên mẫu nộp và dẫn sang các sheet thực hành, tự chấm.", "slideContent": "Checklist: sổ rủi ro; chứng cứ; chủ sở hữu; biện pháp; điều kiện thử lại.", "lectureScript": "Để hoàn thành Bài 25, bạn hãy điền sáu dòng rủi ro, kiểm tra P và I theo tình huống, rồi đổi một trạng thái bằng chứng để xem cảnh báo thay đổi. Tiếp theo, lập kế hoạch kiểm soát cho đủ năm nhóm, ghi người chịu trách nhiệm, bằng chứng cần nộp và thời điểm đánh giá lại. Trả lời mười câu trắc nghiệm, ba nhiệm vụ viết và tự chấm bảy tiêu chí. Nếu dùng phiếu cho doanh nghiệp thật, hãy thay số giả định bằng hồ sơ có thể kiểm chứng. Mục tiêu là có quyết định theo điều kiện rõ ràng và có người chịu trách nhiệm."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('0553384a-230a-51e6-8577-d59cff39f363', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 1, 'EL-026-V26.1', 'VIDEO 26.1: XÁC ĐỊNH NHIỆM VỤ, VAI TRÒ VÀ NGUỒN TÌM ĐẦU MỐI', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Mở đầu: đúng đối tác cho đúng việc", "handwriting": "Hiện cảnh dây chuyền, nêu câu hỏi: cần người tư vấn hay người bán thiết bị?", "slideContent": "Bài 26; Vũ Quang Sơn; An Bình; nhu cầu kiểm tra nhãn và mã lô; hai lối tìm đối tác.", "lectureScript": "Chào bạn. Cơ sở đóng gói cà phê An Bình đã xác định nhu cầu giảm lỗi nhãn và mã lô. Doanh nghiệp nhận được nhiều lời giới thiệu về camera, phần mềm và trí tuệ nhân tạo. Nhưng gọi ngay một nhà bán máy đến báo giá chưa chắc đã giải quyết đúng việc. Có phần cần chuyên gia kiểm chứng phương pháp thử; có phần cần đơn vị tích hợp hiểu dây chuyền; có phần cần nhà cung cấp chứng minh năng lực vận hành và bảo trì. Bài này hướng dẫn bạn xác định ai cần tham gia, tìm đầu mối từ những nguồn kiểm tra được và chuẩn bị một cuộc trao đổi có kết quả. An Bình và tất cả đầu mối trong ví dụ đều là giả định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Bắt đầu từ nhiệm vụ, không từ tên đơn vị", "handwriting": "Viết từ mục tiêu đến nhiệm vụ, sau đó nối với vai trò tương ứng.", "slideContent": "Bốn đầu việc: đánh giá phương pháp; chọn giải pháp; tích hợp; đánh giá điều kiện pháp lý và dữ liệu.", "lectureScript": "Trước khi tìm người, hãy mở lại bản mô tả nhu cầu. An Bình cần phát hiện nhãn sai, truy xuất mã lô và không làm chậm băng tải. Từ đó tách ra bốn nhiệm vụ: xác định bộ thử có đại diện hay không; đánh giá phương án camera; tích hợp với băng tải và phần mềm hiện có; kiểm tra quyền sử dụng phần mềm cùng dữ liệu ảnh. Một nhà cung cấp có thể làm vài nhiệm vụ, nhưng không nên mặc định họ đủ độc lập để tự kiểm chứng mọi tuyên bố của mình. Câu hỏi phải là ai chịu trách nhiệm cho đầu ra nào, chứ không phải đơn vị nào nổi tiếng nhất."}, {"layout": "L2 -> L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Phân vai chuyên gia, đơn vị tích hợp và nhà cung cấp", "handwriting": "Tô hai cột: đầu ra cần bàn giao và dấu hiệu xung đột lợi ích; dừng Q1.", "slideContent": "Ma trận vai trò: chuyên gia độc lập; nhà cung cấp giải pháp; đơn vị tích hợp; chuyên gia quyền và dữ liệu.", "lectureScript": "Chuyên gia độc lập có thể giúp thiết kế phép thử, phân tích lỗi và phản biện dữ liệu. Nhà cung cấp chịu trách nhiệm giới thiệu giải pháp, cấu hình, giấy phép và nghĩa vụ hỗ trợ theo thỏa thuận. Đơn vị tích hợp kết nối camera với băng tải, hệ điều khiển và quy trình của nhà máy. Chuyên gia dữ liệu hoặc pháp lý chỉ nên kết luận trong đúng phạm vi chuyên môn và hồ sơ được tiếp cận. Vai trò không phải chức danh cố định: cùng một công ty có thể kiêm nhiệm. Điều cần hỏi là họ sẽ chịu trách nhiệm điều gì, có đủ năng lực kiểm chứng không, và lợi ích thương mại có ảnh hưởng tính độc lập của ý kiến không."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Viết nhiệm vụ đặt hàng bằng đầu ra kiểm tra được", "handwriting": "Biến câu mơ hồ “cần chuyên gia AI” thành yêu cầu đánh giá mẫu lỗi.", "slideContent": "Mẫu yêu cầu: mục tiêu; phạm vi; dữ liệu có thể chia sẻ; kết quả bàn giao; điều kiện nghiệm thu.", "lectureScript": "Ví dụ An Bình định đăng: cần chuyên gia AI giỏi. Thông tin này không đủ để người nhận biết việc phải làm. Ta sửa thành: cần một chuyên gia có kinh nghiệm thị giác máy kiểm tra thiết kế phép thử camera OCR trên ba ca sản xuất. Đầu ra mong muốn là danh mục điều kiện thử, cách xác lập nhãn chuẩn, bảng đo lỗi bỏ sót và loại nhầm, cùng khuyến nghị giới hạn của kết quả. Nêu rõ những dữ liệu doanh nghiệp có thể cung cấp và thời điểm dự kiến. Mô tả như vậy cho phép chuyên gia trả lời có nhận việc được không; nó cũng giúp người mua đánh giá chất lượng hồ sơ nhận về."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Tìm ứng viên ở đâu và kiểm chứng nguồn", "handwriting": "Đánh dấu nguồn tìm và nguồn xác minh; dừng Q2.", "slideContent": "Nguồn: công bố nghiên cứu; hiệp hội nghề; hội thảo chuyên ngành; đối tác giới thiệu; hồ sơ dự án tham chiếu.", "lectureScript": "Nguồn tìm kiếm chỉ cung cấp tên đầu mối. Chuyên gia có thể xuất hiện trong bài báo, hội thảo nghề nghiệp, phòng thí nghiệm hoặc qua doanh nghiệp từng làm dự án. Nhà cung cấp có thể được giới thiệu từ nhà sản xuất thiết bị gốc, đối tác tích hợp hay người dùng đã triển khai. Đừng dừng ở danh thiếp hoặc trang quảng cáo. Hãy đối chiếu công việc họ từng thực hiện, người có thể xác nhận, phạm vi trách nhiệm và thời điểm của dự án. Một trường hợp tham chiếu trong ngành khác có thể hữu ích, nhưng chưa đủ chứng minh phù hợp tốc độ băng tải của An Bình. Bắt đầu bằng vài nguồn độc lập để tránh phụ thuộc một lời giới thiệu."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Đầu ra bước một: bản đồ vai trò", "handwriting": "Chuyển sang bảng ứng viên sáu dòng của phiếu thực hành.", "slideContent": "Bốn nhóm việc, các đầu ra, người chịu trách nhiệm và nguồn tìm kiếm.", "lectureScript": "Cuối video một, bạn có thể hoàn thành một bảng ngắn gồm nhiệm vụ, đầu ra cần có và loại đối tác nên tìm. Với An Bình, ít nhất phải có năng lực kiểm chứng độ chính xác, năng lực tích hợp và đầu mối cung cấp giải pháp. Phần quyền phần mềm và dữ liệu cần người hiểu hợp đồng, bảo mật hoặc thẩm định chuyên môn phù hợp. Đừng gộp tất cả vào yêu cầu “có kinh nghiệm công nghệ cao”. Hãy ghi rõ nguồn nào đã tìm được, nguồn nào chỉ là giới thiệu và tài liệu nào còn thiếu. Ở video hai, chúng ta sẽ sàng lọc ứng viên mà không để điểm tổng che khuất xung đột lợi ích."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('9971d7b8-88ac-5771-8733-89a109dce846', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 2, 'EL-026-V26.2', 'VIDEO 26.2: KIỂM CHỨNG NĂNG LỰC, SÀNG LỌC VÀ QUẢN LÝ XUNG ĐỘT', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Đánh giá một đầu mối theo nhiệm vụ cụ thể", "handwriting": "Hiện sáu đầu mối giả định, nhãn E1, I1, N1, N2, E2, N3.", "slideContent": "Các tiêu chí: đúng phạm vi việc, kinh nghiệm tương đương, bằng chứng kiểm được, điều kiện phối hợp.", "lectureScript": "Chúng ta có sáu đầu mối giả định: chuyên gia thị giác công nghiệp, đơn vị tích hợp băng tải, nhà cung cấp camera OCR, đơn vị nền tảng AI dùng đám mây, chuyên gia dữ liệu và một đơn vị thương mại tổng hợp. Đừng xếp hạng tất cả như thể họ bán cùng một sản phẩm. Mỗi người có thể phục vụ nhiệm vụ khác nhau. Với từng đầu mối, trước tiên hỏi họ có làm đúng việc đang thiếu không. Sau đó yêu cầu một dự án tương đồng, đầu ra đã bàn giao, người xác nhận và những điều kiện họ cần từ doanh nghiệp. Hứa hẹn miệng hay nhiều lượt theo dõi trên mạng không thay thế được bằng chứng năng lực."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Thang điểm phù hợp sơ bộ 1 đến 5", "handwriting": "Viết ví dụ E1: 5 x 0,6 + 4 x 0,4 = 4,6.", "slideContent": "Hai cột: khớp phạm vi D và năng lực sơ bộ E; điểm F = 0,6D + 0,4E.", "lectureScript": "Phiếu thực hành có hai điểm minh họa từ một đến năm. D là mức khớp với nhiệm vụ An Bình đặt ra. E là mức năng lực sơ bộ dựa trên thông tin đang thu thập. Để dễ luyện, ta cho trọng số sáu mươi phần trăm và bốn mươi phần trăm. Chuyên gia E1 được chấm năm và bốn, điểm là bốn phẩy sáu. Điểm này giúp quyết định nên kiểm tra hồ sơ ai trước, không phải xác suất làm việc thành công. Việc đánh giá phải ghi cùng một định nghĩa thang điểm. Nếu bạn chưa có thông tin, hãy để trống thay vì tự cho điểm trung bình."}, {"layout": "L2", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Chặn kết luận khi bằng chứng chưa đủ", "handwriting": "Tô dòng đơn vị tích hợp I1; dừng Q3.", "slideContent": "Ba trạng thái hồ sơ: Đã kiểm; Chưa đủ; Chưa xác minh. Ví dụ I1 có điểm 5,0 nhưng chưa xác minh.", "lectureScript": "Điểm cao chưa làm hồ sơ trở nên đáng tin. Đơn vị tích hợp I1 trong ví dụ có điểm sơ bộ năm, vì mô tả năng lực trông rất khớp. Nhưng chưa có biên bản dự án tương đương hay đầu mối tham chiếu xác minh được. Trạng thái bằng chứng là chưa xác minh. Vì vậy I1 chưa được đưa vào danh sách đủ điều kiện mời buổi trao đổi chuyên sâu, dù điểm cao nhất. Người phụ trách cần hỏi hồ sơ nghiệm thu, vai trò thực tế của I1, nhân sự sẽ triển khai và khả năng hỗ trợ tại hiện trường. Khi tài liệu được xác minh, ta mới cập nhật trạng thái; không tự hạ hoặc nâng điểm chỉ để đạt đủ số người trong danh sách."}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-4", "sceneName": "Xung đột lợi ích và tính độc lập", "handwriting": "Tô cột H; ví dụ kết luận độc lập cần công bố quan hệ; dừng Q4.", "slideContent": "Ba trạng thái: Không xung đột; Chưa rõ; Có xung đột; ví dụ người tư vấn hưởng hoa hồng từ nhà cung cấp.", "lectureScript": "Một chuyên gia có thể đồng thời nhận phí tư vấn từ An Bình và hoa hồng bán hàng từ nhà cung cấp. Quan hệ ấy phải được khai báo, đánh giá và quản lý trước khi xem ý kiến là độc lập. Trong phiếu, chúng ta tạm dùng ba trạng thái: không có xung đột đã được kiểm tra, chưa rõ hoặc có xung đột cần xử lý. Nhãn không xung đột chỉ được nhập khi đã có cơ sở xác minh, không phải vì người được hỏi tự nói mình khách quan. Với đầu mối có xung đột, doanh nghiệp có thể tiếp tục thu thập thông tin thương mại, nhưng không giao riêng họ nhiệm vụ đánh giá độc lập. Ghi rõ ai kiểm tra và cách xử lý."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-5", "sceneName": "Đọc sáu dòng của bảng sàng lọc", "handwriting": "Hiện công thức COUNTIFS: F>=3,5; G=\"Đã kiểm\"; H=\"Không xung đột\".", "slideContent": "Sáu đầu mối; ba đủ cổng ví dụ; ba thiếu hồ sơ; ba xung đột chưa đóng.", "lectureScript": "Hãy nhìn bảng mặc định. E1 là chuyên gia thị giác, N1 là nhà cung cấp camera và E2 là chuyên gia dữ liệu; cả ba có điểm từ ba phẩy năm trở lên, bằng chứng được đánh dấu đã kiểm và không còn xung đột chưa giải quyết. Đây là ba đầu mối có thể mời trao đổi sơ bộ theo vai trò riêng. Ba đầu mối khác còn thiếu hoặc chưa xác minh hồ sơ. Trong đó hai dòng chưa rõ xung đột và một dòng ghi có xung đột. Công thức đếm cho ta biết còn việc phải làm, chứ không bảo rằng E1 tốt hơn một nhà cung cấp ở nhiệm vụ tích hợp. Hãy rà từng cổng trước khi gửi lời mời."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Tạo danh sách đầu mối có lý do", "handwriting": "Giao thực hành: sửa một cổng, quan sát công thức đếm.", "slideContent": "Bảng danh sách ngắn: nhiệm vụ, ứng viên, căn cứ, điểm còn thiếu và người xác minh.", "lectureScript": "Danh sách mời nên nói rõ vì sao từng đầu mối có mặt. Chuyên gia thị giác được mời phản biện phép thử. Nhà cung cấp camera được mời chứng minh điều kiện chạy máy và giấy phép. Chuyên gia dữ liệu được mời góp ý khả năng lưu trữ và xuất nhật ký. Đơn vị tích hợp I1 đang chờ tài liệu; việc chờ không có nghĩa đánh giá họ kém. Bạn hãy thử đổi trạng thái của I1 sau khi giả định đã xác minh hồ sơ và không có xung đột. Quan sát số đầu mối đủ cổng tăng lên. Sau đó trả lại trạng thái ban đầu để hiểu vì sao hai cột bằng chứng và xung đột phải đứng tách khỏi điểm."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('e6cd24b4-778e-59d7-a997-915ff14a6fab', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 3, 'EL-026-V26.3', 'VIDEO 26.3: LIÊN HỆ, TRAO ĐỔI VÀ THEO DÕI BẰNG CHỨNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Buổi kết nối cần một đề bài rõ", "handwriting": "Hiện bản brief một trang và câu hỏi: chia sẻ dữ liệu gì ở lần đầu?", "slideContent": "Luồng tiếp xúc: giới thiệu vắn tắt; gửi đề bài; nhận phản hồi; trao đổi; đối chiếu chứng cứ.", "lectureScript": "Khi đã có danh sách đầu mối, cần gửi một đề bài rõ. Hãy nêu mục tiêu giảm lỗi nhãn và mã lô, điều kiện dây chuyền, loại hỗ trợ cần tìm và đầu ra mong muốn. Trong lần liên hệ đầu, chỉ chia sẻ thông tin đủ để đối tác xác định phạm vi tham gia. Ảnh khách hàng, dữ liệu cá nhân hoặc bí mật vận hành phải được phân loại trước; khi cần chia sẻ, phải có điều kiện bảo mật thích hợp."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Viết thư mời hoặc yêu cầu thông tin một trang", "handwriting": "Viết mẫu 6 dòng yêu cầu, giữ chỗ dữ liệu còn thiếu.", "slideContent": "Brief gồm: bối cảnh; mục tiêu; nhiệm vụ; đầu ra; điều kiện; câu hỏi; đầu mối phản hồi.", "lectureScript": "Một brief liên hệ có thể nằm trên một trang. Đầu tiên ghi vấn đề của dây chuyền và mục tiêu cần đo, chẳng hạn tỷ lệ phát hiện nhãn sai trên mẫu do doanh nghiệp xác lập. Sau đó nói rõ bạn đang cần thiết kế phép thử, cung cấp camera hay tích hợp hệ thống. Ghi điều kiện sản xuất, dữ liệu có thể cung cấp, thời hạn phản hồi và đầu mối liên hệ. Không hứa hẹn độ chính xác tuyệt đối khi chưa có phép đo phù hợp."}, {"layout": "L2", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Đặt câu hỏi để phân biệt bằng chứng và lời quảng cáo", "handwriting": "Nối câu hỏi với tài liệu phải nộp; dừng Q5.", "slideContent": "Bảng câu hỏi: công việc tương tự; nhân sự thật; điều kiện thử; quyền dữ liệu; quy trình xử lý lỗi.", "lectureScript": "Với nhà cung cấp, cần biết thiết bị đã thử trên loại túi, nhịp máy và ánh sáng nào; ai xác lập nhãn chuẩn; tỷ lệ bỏ sót và loại nhầm được đo ra sao. Với đơn vị tích hợp, hỏi sơ đồ kết nối và cơ chế dừng an toàn. Với chuyên gia độc lập, hỏi phương pháp đánh giá, dự án tương tự và mối quan hệ lợi ích. Mỗi câu trả lời nên dẫn đến tài liệu, phép thử hoặc người tham chiếu."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Tổ chức cuộc trao đổi 30 phút có biên bản", "handwriting": "Bật đồng hồ từng chặng; minh họa hai câu hỏi làm rõ.", "slideContent": "Lịch họp minh họa: 5 phút vấn đề; 10 phút phương pháp; 10 phút bằng chứng; 5 phút hành động.", "lectureScript": "Ta có thể bố trí một cuộc họp sơ bộ ba mươi phút. Năm phút đầu An Bình nêu bài toán và giới hạn phạm vi. Mười phút sau đối tác trình bày cách làm, nhân sự và điều kiện cần thiết. Mười phút tiếp theo cùng xem dự án tham chiếu, phương pháp thử và các tài liệu còn thiếu. Năm phút cuối chốt ai gửi tài liệu nào, hạn bao lâu và bước cần phê duyệt tiếp theo. Phân công người ghi biên bản và người xác nhận nội dung kỹ thuật."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Không bỏ qua quyền, bảo mật và chi phí tiếp xúc", "handwriting": "Tô đỏ thông tin chưa được phép chia sẻ; cho ví dụ cần thỏa thuận trước.", "slideContent": "Bốn nhãn: bảo mật; sở hữu kết quả thử; phí tư vấn; quyền sử dụng dữ liệu và đầu ra.", "lectureScript": "Trước khi gửi ảnh lỗi, mã lô hoặc phần mềm thử, doanh nghiệp cần xác định dữ liệu nào là bí mật, ai được phép truy cập và mục đích sử dụng. Nếu nhà cung cấp muốn dùng ảnh để huấn luyện mô hình, hỏi rõ thời gian lưu, nơi xử lý và quyền xuất hoặc xóa dữ liệu. Thỏa thuận bảo mật không tự động giải quyết mọi quyền sở hữu trí tuệ. Những điều khoản pháp lý cụ thể phải được người có thẩm quyền thẩm định theo hồ sơ thực tế. Không gửi dữ liệu nhạy cảm chỉ để xin báo giá sơ bộ."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Chốt bằng bằng chứng và người phụ trách", "handwriting": "Đánh dấu nhiệm vụ chờ, đã nhận, đã xác minh; dừng Q6.", "slideContent": "Bảng theo dõi: câu hỏi; tài liệu cần nhận; người phụ trách; hạn; trạng thái.", "lectureScript": "Sau cuộc họp, hãy phân biệt đã nhận tài liệu, đã xác minh tài liệu và còn thiếu. Chuyên gia cần gửi phương pháp thử, nhà cung cấp gửi cấu hình và điều kiện bảo hành; đơn vị tích hợp gửi sơ đồ kết nối và đầu mối triển khai. Người phụ trách An Bình kiểm tra từng mục, ghi hạn và cập nhật trạng thái. Nếu quyền sử dụng dữ liệu hoặc xung đột lợi ích chưa rõ, không chuyển thẳng sang quyết định mua sắm."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Kết bài: từ đầu mối đến bước đánh giá", "handwriting": "Giao bài: sáu đầu mối, ba thư mời, biên bản và bảng kiểm.", "slideContent": "Bốn bước: đúng việc; đúng vai; bằng chứng; kế hoạch xác minh.", "lectureScript": "Đến đây, bạn đã có quy trình tìm đúng người. Viết đúng nhiệm vụ và đầu ra; tìm chuyên gia, nhà cung cấp hoặc đơn vị tích hợp theo vai trò; kiểm tra kinh nghiệm, lợi ích thương mại và dữ liệu được phép chia sẻ. Sau cuộc trao đổi, ghi câu hỏi còn mở, người phụ trách và hạn bổ sung chứng cứ. Với An Bình, ba đầu mối đủ điều kiện ban đầu chỉ được mời trao đổi, chưa phải trúng thầu hoặc được phê duyệt đầu tư. Nếu hồ sơ thiếu, ghi rõ thiếu gì thay vì tự điền giả định thuận lợi."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('1921e2df-4b73-5b40-8eea-ddee25b36f5e', 'ff65e401-5641-52eb-92a0-b93256b41783', 1, 'EL-027-V27.1', 'VIDEO 27.1: CHUẨN BỊ MỤC TIÊU, THÀNH PHẦN VÀ CHƯƠNG TRÌNH KẾT NỐI', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Mở bài: một cuộc gặp có sản phẩm gì?", "handwriting": "Mở minh họa một buổi họp nhiều người, sau đó thu hẹp vào bảng đầu ra có người và hạn.", "slideContent": "An Bình; nhu cầu kiểm nhãn và mã lô; trước cuộc gặp - trong cuộc gặp - sau cuộc gặp.", "lectureScript": "Cơ sở đóng gói cà phê An Bình đã mô tả nhu cầu kiểm nhãn và mã lô. Họ đã tìm được vài đầu mối chuyên gia và nhà cung cấp. Bây giờ đặt lịch một buổi kết nối cung cầu công nghệ. Nếu sau buổi họp mọi người chỉ nói rằng giải pháp rất thú vị, doanh nghiệp vẫn chưa biết phải làm gì tiếp. Một phiên có ích cần làm rõ vấn đề, nhận và kiểm tra bằng chứng, nêu câu hỏi chưa có lời giải, rồi giao người và hạn phản hồi. An Bình và mọi chi tiết cuộc gặp đều là giả định đào tạo."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Xác định mục đích và giới hạn trước khi mời", "handwriting": "So sánh hai câu mời họp: chung chung và có mục tiêu kiểm chứng.", "slideContent": "Mục đích: xác minh phương án thử OCR; không phê duyệt giá hay ký hợp đồng.", "lectureScript": "Ta bắt đầu bằng một câu có thể kiểm tra: sau 45 phút, An Bình muốn thống nhất những dữ liệu cần bổ sung để đánh giá giải pháp kiểm tra nhãn và mã lô trên dây chuyền. Mục tiêu như vậy giúp giới hạn thảo luận. Nếu người bán chuyển ngay sang đề nghị ký hợp đồng, điều phối viên có cơ sở đưa cuộc họp trở lại việc kiểm chứng năng lực. Ghi thêm những gì phiên này không quyết định: giá cuối, lựa chọn nhà thầu, kết luận pháp lý và độ chính xác khi chưa thử trên mẫu thật. Đầu ra của phiên là kế hoạch xác minh, không phải biên bản mua thiết bị."}, {"layout": "L2 -> L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Đúng người và đúng quyền quyết định", "handwriting": "Ghép mỗi người với loại thông tin được xác nhận; dừng Q1.", "slideContent": "Doanh nghiệp: vận hành, QC, CNTT, mua sắm; bên ngoài: E1, N1 và E2 theo giả định Bài 26.", "lectureScript": "Trong tình huống An Bình, quản lý vận hành mô tả tốc độ băng tải và thời điểm đổi mã hàng. Nhân sự chất lượng xác nhận định nghĩa nhãn sai và dữ liệu lỗi. CNTT giải thích hệ thống lưu dữ liệu và quyền truy cập; mua sắm ghi nhận phạm vi thương mại chưa được quyết định. Bên ngoài có chuyên gia E1 hỗ trợ thiết kế thử, nhà cung cấp N1 mô tả giải pháp và chuyên gia dữ liệu E2 nêu yêu cầu quản lý ảnh. Hãy chỉ rõ ai trình bày, ai có quyền xác nhận dữ liệu và ai được giao việc sau buổi họp. Một người bán hàng không thể tự xác nhận kết quả thử độc lập."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Brief một trang và bộ tài liệu gửi trước", "handwriting": "Hiện trang mẫu tô những trường còn thiếu cần người phụ trách hoàn thiện.", "slideContent": "Brief: vấn đề, đường cơ sở, điều kiện, câu hỏi mở, giới hạn chia sẻ.", "lectureScript": "Gói chuẩn bị tối thiểu gồm một trang mô tả vấn đề, sơ đồ dây chuyền ở mức được phép chia sẻ, ba yêu cầu chức năng và danh mục câu hỏi. Tỷ lệ lỗi hở mép hàn ba phần trăm ở bài trước không đo hiệu quả OCR. Với OCR, cần xác định riêng tỷ lệ sai nhãn, lỗi nhận dạng và mẫu kiểm. Không đem một chỉ số của công đoạn khác làm căn cứ hứa hẹn hiệu quả. Mỗi dữ liệu trong brief cần ghi nguồn, kỳ đo và người xác nhận. Các ảnh có dữ liệu khách hàng hay thông tin bí mật chỉ chia sẻ sau khi phân loại quyền truy cập."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Lập chương trình và quy tắc cuộc gặp", "handwriting": "Dựng timeline sáu đoạn; hiển thị mốc tài liệu nào phải được ghi lại; dừng Q2.", "slideContent": "45 phút: mở mục tiêu 5; bài toán 7; điều kiện 8; giải pháp 10; phản biện 10; chốt 5.", "lectureScript": "Tôi đề xuất chương trình 45 phút gồm sáu phần. Năm phút đầu nêu mục tiêu và giới hạn. Bảy phút tiếp theo xác nhận hiện trạng. Tám phút dành cho điều kiện dây chuyền. Mười phút để bên cung trình bày phương án và bằng chứng. Mười phút phản biện các giả định, đặc biệt dữ liệu, quyền dùng và hỗ trợ vận hành. Năm phút cuối giao việc. Đây là lịch minh họa, không phải công thức bắt buộc cho mọi cuộc họp. Chỉ định điều phối, thư ký và quy tắc chia sẻ dữ liệu. Câu hỏi chưa trả lời được phải đưa vào danh mục theo dõi."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Điểm chặn trước giờ họp", "handwriting": "Cho ví dụ hai tài liệu có thể gửi trước và hai tài liệu phải xin phép.", "slideContent": "Checklist: mục tiêu - vai trò - brief - dữ liệu - chương trình - quyền chia sẻ.", "lectureScript": "Trước khi bắt đầu, điều phối viên kiểm sáu việc: mục đích rõ, người đúng, brief đã gửi, câu hỏi ưu tiên đã thống nhất, dữ liệu được phép chia sẻ và phương án ghi nhận đầu việc. Nếu thiếu người có thể xác nhận tốc độ dây chuyền, đừng cố chốt thông số tại cuộc gặp. Nếu chuyên gia chưa nhận được mẫu dữ liệu đã phân loại, cũng không nên yêu cầu họ kết luận độ chính xác. Hãy hoãn phần cần bằng chứng hoặc đánh dấu rõ giả định. Ô tích hoàn thành không thay tài liệu thật. Sang video hai, chúng ta thực hành điều phối cuộc trao đổi khi các bên có lợi ích và cách nói khác nhau."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('4305db71-69dd-555b-bdc7-95c46cb091b5', 'ff65e401-5641-52eb-92a0-b93256b41783', 2, 'EL-027-V27.2', 'VIDEO 27.2: ĐIỀU PHỐI ĐỐI THOẠI VÀ KIỂM CHỨNG BẰNG CHỨNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Mở phiên đúng kỳ vọng", "handwriting": "Giảng viên mô phỏng câu mở đầu 30 giây của điều phối viên.", "slideContent": "Mẫu câu điều phối: vấn đề cần giải, giới hạn quyết định, sản phẩm cuối buổi.", "lectureScript": "Trong phần mở đầu, điều phối viên cần nói ngắn: hôm nay An Bình muốn làm rõ khả năng thử OCR trên dây chuyền, chưa lựa chọn công nghệ hay ký hợp đồng. Chúng ta có 45 phút và sẽ kết thúc bằng danh sách bằng chứng, người phụ trách, hạn phản hồi. Sau đó giới thiệu đúng vai trò từng bên. Quy tắc đầu tiên là câu hỏi nào liên quan trực tiếp đến yêu cầu kỹ thuật được đưa lên trước; thông tin quảng bá chung chỉ ghi nhận khi phục vụ quyết định kiểm chứng. Người ghi biên bản phải phân biệt ai đưa ra một nhận định và ai đã xác nhận được nó."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Để doanh nghiệp xác nhận vấn đề trước", "handwriting": "Nối lời mô tả của vận hành với chỉ số và hồ sơ cần kiểm.", "slideContent": "Sơ đồ: nhãn sai, mã lô khó đọc, tốc độ băng tải, điều kiện ca sản xuất.", "lectureScript": "Đừng hỏi nhà cung cấp mô tả tính năng trước khi bên cầu thống nhất vấn đề. Quản lý vận hành của An Bình nêu tình huống đổi mã sản phẩm liên tục, còn bộ phận chất lượng mô tả những loại lỗi cần phát hiện. Người điều phối hỏi: mã lô được in ở đâu, có bao nhiêu dạng bao bì, công nhân xử lý túi nghi lỗi thế nào, số mẫu lỗi đã được gán nhãn chuẩn hay chưa? Nếu câu trả lời là chưa biết, biên bản phải viết chưa có dữ liệu thay vì chọn một con số thuận tiện. "}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Kiểm tra tuyên bố bằng bốn câu hỏi", "handwriting": "Hiện bốn ô kiểm chứng và bảng dữ liệu TP, FN, FP, TN; dừng Q3.", "slideContent": "Tuyên bố “OCR 99%”; hỏi mẫu, nhãn chuẩn, điều kiện, lỗi bị bỏ sót.", "lectureScript": "Giả sử N1 trình bày hệ thống OCR chính xác 99 phần trăm. Không kết luận ngay. Hãy hỏi chỉ số đó được tính trên bao nhiêu ảnh, gồm loại lỗi nào, ai lập nhãn chuẩn và mẫu thử có cùng ánh sáng, tốc độ, bao bì với An Bình hay không. Tiếp theo hỏi tỷ lệ bỏ sót lỗi và tỷ lệ loại nhầm túi tốt; hai tỷ lệ này có hậu quả vận hành khác nhau. Một báo cáo chỉ có tỷ lệ chính xác chung dễ che khuất lỗi ít gặp nhưng nghiêm trọng. Yêu cầu bản ghi thử, phiên bản phần mềm và phương pháp lấy mẫu. "}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-4", "sceneName": "Điều phối khi bên cung và bên cầu bất đồng", "handwriting": "Tách ba nhãn trên slide: tuyên bố - điều kiện - việc cần kiểm; dừng Q4.", "slideContent": "Ví dụ tốc độ công bố 140 túi/phút nhưng doanh nghiệp cần xem tốc độ đạt trên ba ca.", "lectureScript": "Nếu nhà cung cấp nói camera chạy 140 túi mỗi phút còn quản lý vận hành lo rằng dây chuyền có nhiều lần dừng và đổi mã, đừng để cuộc họp biến thành tranh cãi ai đúng. Hãy ghi đây là tốc độ công bố, sau đó hỏi điều kiện thử và năng suất đạt ở nhịp thực tế. Người điều phối chuyển bất đồng thành phép thử: trong ba ca sản xuất, đo số túi đạt, thời gian dừng, số lần đổi mã và tỷ lệ lỗi. Nếu bên cung không có dữ liệu tương đương, trạng thái vẫn là cần kiểm chứng. Không lấy lời hứa cung cấp tài liệu thay cho kết quả đã nhận. "}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V2-5", "sceneName": "Khoanh vùng dữ liệu, quyền sử dụng và trách nhiệm", "handwriting": "Tô màu các câu chưa có người trả lời; chuyển thành nhiệm vụ sau họp.", "slideContent": "Cổng: dữ liệu ảnh; vị trí lưu trữ; quyền phần mềm; tích hợp PLC; hỗ trợ khi lỗi.", "lectureScript": "Một phiên kết nối dễ bỏ qua câu hỏi ai có quyền dùng ảnh lỗi và mã lô sau thử nghiệm. Hãy yêu cầu bên cung nêu nơi lưu dữ liệu, thời hạn giữ, quyền truy xuất, thành phần phần mềm bên thứ ba và cơ chế xóa hoặc xuất dữ liệu khi kết thúc hợp tác. Đơn vị tích hợp cần nói rõ ranh giới trách nhiệm với điều khiển băng tải, liên động dừng và an toàn. Người ghi biên bản không tự kết luận tuân thủ pháp lý chỉ vì nhà cung cấp nêu đã có chứng nhận. Tài liệu pháp lý và bảo mật phải được kiểm qua đầu mối có thẩm quyền. "}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Giữ nhịp và xử lý câu hỏi ngoài phạm vi", "handwriting": "Dừng đồng hồ ở phút 35; cho thấy vì sao cần giữ năm phút chốt việc.", "slideContent": "Bảng điều phối: nói đúng trọng tâm; tạm giữ vấn đề ngoài phạm vi; lịch hẹn tiếp.", "lectureScript": "Khi một bên trình bày quá dài, điều phối viên có thể ngắt bằng câu: chúng ta ghi nhận đề xuất, nhưng trước hết cần hoàn tất điều kiện thử ở dây chuyền. Những câu về giá cuối, độc quyền hay phạm vi hợp đồng có thể đưa sang buổi thẩm định riêng, cùng người phụ trách mua sắm hoặc pháp lý. Cần bảo vệ năm phút cuối để chốt việc. Kết luận tốt của phần điều phối là biết chính xác câu hỏi nào đã được trả lời bằng tài liệu, câu hỏi nào chỉ là ý kiến và ai sẽ bổ sung phần thiếu. Video ba sẽ dùng Excel để ghi nhận kết quả."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('f93ffd0a-45d1-5fa8-9095-50eba41ae27b', 'ff65e401-5641-52eb-92a0-b93256b41783', 3, 'EL-027-V27.3', 'VIDEO 27.3: GHI BIÊN BẢN, CHỐT ĐẦU VIỆC VÀ THEO DÕI SAU PHIÊN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Từ cuộc họp sang biên bản có cấu trúc", "handwriting": "Mở sheet PHIẾU THỰC HÀNH, giải thích ô vàng là đầu vào.", "slideContent": "Sáu dòng chương trình; cột phút dự kiến, thực tế, bằng chứng, chủ việc.", "lectureScript": "Trong phiếu thực hành Bài 27, bạn thấy sáu dòng tương ứng sáu phần của cuộc họp giả định. Cột D là số phút dự kiến, cột E là phút thực tế. Cột F tự tính chênh lệch, còn G ghi trạng thái bằng chứng và H cho biết việc đã có người nhận hay chưa. Bằng chứng chưa nhận cũng không có nghĩa giải pháp kém, chỉ có nghĩa chưa thể xác minh. Hãy sửa số liệu trên phiếu để thấy những trạng thái này thay đổi độc lập."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Đọc chênh lệch thời gian đúng dấu", "handwriting": "Điền sáu mốc dự kiến 5,7,8,10,10,5 và thực tế 5,8,9,10,11,7.", "slideContent": "Kế hoạch 45 phút, thực tế 50 phút; mỗi hàng E trừ D; tổng vượt 5 phút.", "lectureScript": "Theo bộ số liệu giả định, chương trình dự kiến 45 phút. Thực tế là 50 phút, vượt năm phút. Chênh lệch ở từng hàng bằng thời gian thực tế trừ thời gian dự kiến. Giá trị dương nghĩa là kéo dài, bằng không nghĩa là đúng lịch, còn âm nghĩa là kết thúc sớm. Khi dữ liệu phút bị xóa, bảng phải cảnh báo chưa đủ dữ liệu chứ không mặc nhiên coi phút bằng không."}, {"layout": "L2", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Đánh dấu bằng chứng chứ không đánh dấu cảm nhận", "handwriting": "Tô dòng trình bày phương án và phản biện vì còn thiếu log thử; dừng Q5.", "slideContent": "Trạng thái G: Đã ghi / Cần bổ sung; bốn mục đã ghi, hai mục mở.", "lectureScript": "Một câu nói rằng hệ thống chạy tốt không phải là biên bản thử nghiệm. Ta chỉ đánh dấu đã ghi khi có nội dung đủ rõ để truy vết: tên tài liệu, phiên bản, người cung cấp hoặc đường dẫn lưu nội bộ. Trong ví dụ, bốn trong sáu phần có thông tin đã ghi. Hai phần còn lại cần log thử và điều kiện dữ liệu. Nếu bạn đổi một mục từ cần bổ sung sang đã ghi, Excel tăng số mục hoàn tất. Nhưng để ghi đúng trong dự án thật, phải kiểm tra tài liệu đã được nhận và có đúng nội dung yêu cầu hay không."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Giao người, hạn và tiêu chí đóng đầu việc", "handwriting": "Minh họa một việc thiếu người: kiểm quyền dùng ảnh, sau đó sửa biên bản.", "slideContent": "H: Đã giao / Chưa giao; mỗi đầu việc phải có người chịu trách nhiệm và hạn.", "lectureScript": "Trong bảng minh họa, năm phần đã có đầu mối nhận việc và một phần chưa giao rõ. Đối với câu hỏi quyền dùng ảnh thử, viết “bên cung sẽ xem lại” là chưa đủ. Biên bản nên nêu bên nào trả lời, ai tại An Bình kiểm tra, tài liệu cần nhận và thời hạn. Nhập đã giao vào Excel chỉ khi việc đã được nêu cụ thể và người đó xác nhận nhận trách nhiệm. Nếu chưa thể chốt trong họp, trạng thái là chưa giao và điều phối viên phải theo dõi sau. "}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Chốt bốn mục trong biên bản phiên kết nối", "handwriting": "Mẫu bảng hành động năm dòng ở cuối phiếu thực hành.", "slideContent": "Bốn mục: kết luận có chứng cứ; câu hỏi mở; người - hạn; điều kiện bước tiếp.", "lectureScript": "Biên bản cuối buổi chỉ nên chốt những gì đã được xác nhận. Ví dụ: An Bình thống nhất sẽ thử OCR trên ba ca nếu bộ mẫu và nhãn chuẩn được phê duyệt; nhà cung cấp gửi bản ghi thử và thông số cấu hình; chuyên gia kiểm tra phương pháp đo; CNTT rà quyền lưu ảnh. Điều phối viên cần ghi ai thực hiện và hạn phản hồi, không viết chung rằng các bên tiếp tục hợp tác. Mỗi việc phải có tiêu chí đóng, như đã nhận tệp log đúng phiên bản hoặc đã có văn bản xác nhận quyền dùng dữ liệu. "}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Ra quyết định đúng mức sau cuộc họp", "handwriting": "Dùng C20 trên phiếu thực hành, thay G hoặc H và quan sát; dừng Q6.", "slideContent": "Trạng thái: còn việc chưa đóng; chưa chuyển thẩm định; không ký mua.", "lectureScript": "Khi thời gian thực tế vượt 45 phút, còn hai phần thiếu bằng chứng và một phần chưa giao người, kết luận đúng là biên bản chưa đóng. Bảng sẽ cảnh báo để điều phối viên tiếp tục nhận tài liệu, xử lý việc chưa giao và xác minh dữ liệu. Kể cả khi mọi ô đều được đánh dấu đã ghi và đã giao, điều đó chỉ cho thấy việc quản trị cuộc họp đã được hoàn thành. Chuyên gia và doanh nghiệp vẫn phải xem xét chất lượng phép thử, quyền dữ liệu, tính khả thi và các thủ tục trước khi quyết định đầu tư. "}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Bài tập cuối: chuẩn bị phiên kết nối của bạn", "handwriting": "Hiện danh mục sản phẩm nộp, chuyển sang phiếu tự chấm.", "slideContent": "Nộp brief, chương trình họp, nhật ký chứng cứ, bảng hành động và câu hỏi mở.", "lectureScript": "Bạn hãy chọn một nhu cầu công nghệ có thật trong doanh nghiệp hoặc dùng tình huống An Bình. Viết mục tiêu phiên kết nối trong một câu, chọn đúng những người có thể xác nhận thông tin, lập chương trình có thời lượng, rồi chuẩn bị câu hỏi để kiểm chứng phương án. Sau phiên mô phỏng, ghi lại điều đã được chứng minh, điều còn thiếu, người nhận việc và hạn phản hồi. Cuối cùng tự chấm theo bảy tiêu chí trong file. Những câu hỏi còn mở phải có người tiếp tục xử lý."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('6572848d-6f87-552e-b95e-b1222a2f164b', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 1, 'EL-028-V28.1', 'VIDEO 28.1: VIẾT GIẢ THUYẾT VÀ THIẾT KẾ POC CÓ GIỚI HẠN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Sau phiên kết nối, cần kiểm điều gì?", "handwriting": "Hiện sơ đồ tiến trình; dừng ở bước PoC trước biểu tượng đầu tư lớn.", "slideContent": "An Bình: biên bản kết nối Bài 27 -> câu hỏi chưa trả lời -> PoC -> quyết định bước tiếp.", "lectureScript": "Ở bài trước, An Bình đã tổ chức phiên kết nối với chuyên gia và nhà cung cấp hệ thống camera kiểm tra nhãn, mã lô. Sau cuộc họp, họ có danh sách câu hỏi và lời hứa gửi tài liệu. Nhưng nhận được báo giá không có nghĩa giải pháp đã chạy được trên dây chuyền. Bài này hướng dẫn thiết kế một thử nghiệm khái niệm, viết tắt là PoC. Ta dùng phạm vi nhỏ, chi phí được khống chế và dữ liệu có thể đối chiếu để kiểm xem một giả thuyết kỹ thuật có đứng vững hay không. Tình huống An Bình và mọi con số đều là giả định. PoC thành công cũng chưa phải quyết định mua thiết bị."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Viết giả thuyết có thể bác bỏ", "handwriting": "Viết từ lời hứa “OCR nhận tốt” thành giả thuyết có tập mẫu và chỉ số.", "slideContent": "Cấu trúc: với mẫu A, điều kiện B, chức năng C, đạt ngưỡng D.", "lectureScript": "Giả sử nhà cung cấp nói camera nhận mã lô rất tốt. Câu này chưa đủ để thử vì không có định nghĩa tốt. Hãy đổi thành giả thuyết: trên bộ ảnh bao bì An Bình đã gán nhãn chuẩn, ở điều kiện chụp xác định, hệ thống phát hiện ít nhất 95 phần trăm mẫu có lỗi nhãn hoặc mã lô và loại nhầm không quá 3 phần trăm mẫu tốt. Hai ngưỡng vừa nêu là mục tiêu giả định do bài tập đặt ra, không phải chuẩn ngành. Khi viết được giả thuyết như vậy, ta biết số liệu nào cần thu và kết quả nào sẽ khiến giả thuyết bị bác bỏ."}, {"layout": "L2 -> L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Phân biệt PoC, thí điểm và nghiệm thu", "handwriting": "Bảng ba cột có phạm vi, mục tiêu và quyết định tiếp theo; dừng Q1.", "slideContent": "PoC: chứng minh chức năng hẹp; pilot: thử quy trình thực; nghiệm thu: kiểm điều khoản và kết quả đã cam kết.", "lectureScript": "PoC trả lời câu hỏi giải pháp có thực hiện được chức năng cốt lõi trong bộ điều kiện đã xác định không. Thí điểm vận hành đi xa hơn: đánh giá người sử dụng, tích hợp, bảo trì và kết quả qua các ca sản xuất. Còn nghiệm thu kiểm xem hạng mục giao theo hợp đồng đã đáp ứng điều kiện được thỏa thuận chưa. Nếu gộp ba bước, doanh nghiệp dễ mua sắm sau một buổi trình diễn được chuẩn bị sẵn. Trong ví dụ này, PoC trước tiên có thể chạy trên bộ ảnh tách khỏi dây chuyền. Chỉ sau khi hiểu giới hạn của kết quả, An Bình mới quyết định có nên thử trên dây chuyền thật hay dừng."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Chốt phạm vi và mẫu kiểm trước khi chạy", "handwriting": "Vẽ hai nhóm ảnh gán nhãn; tách bộ hiệu chỉnh và bộ dùng để đánh giá.", "slideContent": "Tập mẫu: 100 túi có lỗi, 400 túi tốt; nhãn chuẩn do QC xác nhận; mẫu và điều kiện là giả định.", "lectureScript": "Trong mô phỏng, An Bình chuẩn bị 500 ảnh, gồm 100 ảnh thực sự có lỗi và 400 ảnh tốt. Bộ phận chất lượng cần thống nhất trước thế nào là mã không đọc được, nhãn sai và mẫu chấp nhận được. Mỗi ảnh phải có mã truy vết, nhãn chuẩn và điều kiện chụp. Tránh để nhà cung cấp điều chỉnh phần mềm trực tiếp trên chính bộ ảnh sẽ dùng để báo cáo kết quả, vì như vậy con số dễ đẹp hơn khả năng áp dụng ngoài thực tế. Cần tách ảnh để hiệu chỉnh và ảnh đánh giá; nếu số ảnh lỗi ít, phải ghi nhận hạn chế thay vì suy rộng kết luận."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Đặt hai chỉ số và điều kiện dừng", "handwriting": "Đồng hồ hai chỉ số; giải thích hai mẫu số bằng hình 100 lỗi, 400 tốt; dừng Q2.", "slideContent": "Tỷ lệ phát hiện = TP/(TP+FN); tỷ lệ loại nhầm = FP/(FP+TN); ngưỡng 95% và 3%.", "lectureScript": "Tôi không chọn một con số chính xác chung để quyết định. Ta đo riêng tỷ lệ phát hiện trong nhóm thật sự có lỗi và tỷ lệ loại nhầm trong nhóm thật sự tốt. Nếu camera bỏ sót nhãn sai, lô hàng có thể không được chặn kịp. Nếu loại nhầm quá nhiều túi tốt, công nhân phải kiểm lại và dây chuyền có thể dừng. Hai hệ quả khác nhau nên cần hai chỉ số. Ngưỡng bài tập là phát hiện từ 95 phần trăm và loại nhầm tối đa 3 phần trăm. Còn an toàn, quyền dùng dữ liệu và giới hạn ngân sách là điều kiện phải kiểm riêng, không thể lấy điểm trung bình bù."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Chốt bản thiết kế PoC một trang", "handwriting": "Ghép biểu mẫu một trang, tô chỗ phải có chữ ký xác nhận trước khi thử.", "slideContent": "Đầu ra: giả thuyết, chủ mẫu, phạm vi, ngưỡng, ngân sách, điều kiện dừng, người nhận kết quả.", "lectureScript": "Bản đề xuất PoC cần có người chịu trách nhiệm về mẫu, người duyệt quyền dùng ảnh, kỹ thuật viên vận hành, nhà cung cấp và người kiểm kết quả. Viết rõ thời hạn thử, thiết bị được dùng, cách lập nhật ký phiên bản và khoản chi tối đa. Trong ví dụ, chúng ta sẽ dùng giới hạn 20 triệu đồng, chỉ để tính toán trong bài. Không có căn cứ nói PoC thật sẽ tốn đúng mức đó. Nếu chưa được phép truy cập ảnh, chưa có người chịu trách nhiệm an toàn hoặc không thống nhất nhãn chuẩn, phải dừng trước khi chạy. Video tiếp theo hướng dẫn cách đọc bằng chứng thu được."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('301d75a1-06d9-521f-9a50-aa09b3c4894e', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 2, 'EL-028-V28.2', 'VIDEO 28.2: THU THẬP BẰNG CHỨNG VÀ ĐỌC CHỈ SỐ POC', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Từ ảnh thử đến bảng đếm có thể kiểm", "handwriting": "Đưa 2x2 confusion matrix với nhãn chuẩn ở hàng, kết quả máy ở cột.", "slideContent": "Bốn ô kết quả: phát hiện đúng TP, bỏ sót FN, loại nhầm FP, chấp nhận đúng TN.", "lectureScript": "Ta đã có giả thuyết và bộ mẫu. Bây giờ mỗi ảnh cần được đối chiếu giữa nhãn chuẩn do QC xác nhận với quyết định của camera. Với mẫu thật sự có lỗi, máy báo lỗi là phát hiện đúng, ký hiệu TP; máy cho qua là bỏ sót, ký hiệu FN. Với mẫu thật sự tốt, máy báo lỗi sai là FP; máy cho qua đúng là TN. Bốn số đếm phải cộng lại bằng tổng ảnh đã đánh giá. Đừng dùng từ chính xác nếu chưa nói rõ tử số và mẫu số. Nhật ký cần lưu cả ảnh đầu vào, nhãn chuẩn, kết quả máy và phiên bản thuật toán đã chạy."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Kiểm tra mẫu số và nguồn nhãn chuẩn", "handwriting": "Điền bảng 2x2 từng ô và công thức tổng; nêu ai xác nhận nhãn.", "slideContent": "Mẫu lỗi: TP+FN = 100; mẫu tốt: FP+TN = 400; tổng 500.", "lectureScript": "Ví dụ giả định có 96 mẫu lỗi được máy phát hiện và 4 mẫu lỗi bị bỏ sót. Trong 400 mẫu tốt, máy loại nhầm 16 và cho qua đúng 384. Ta kiểm trước khi tính: 96 cộng 4 là 100 mẫu lỗi; 16 cộng 384 là 400 mẫu tốt; cả hai nhóm cộng lại là 500. Nếu một ảnh bị trùng mã hoặc có nhãn không thống nhất, cần xử lý theo quy tắc đã đặt trước. Không được bỏ riêng những ảnh khó rồi mới công bố kết quả. Mọi lần sửa nhãn chuẩn phải có người phê duyệt và lưu vết."}, {"layout": "L2 -> L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tỷ lệ phát hiện và lỗi bỏ sót", "handwriting": "Hiện máy tính trong slide, tô tử và mẫu; dừng Q3.", "slideContent": "TP = 96; FN = 4; phát hiện = 96/100 = 96%; bỏ sót = 4/100 = 4%.", "lectureScript": "Tỷ lệ phát hiện của mẫu lỗi bằng 96 chia cho 96 cộng 4, tức 96 phần trăm. Ngưỡng bài tập yêu cầu ít nhất 95 phần trăm, nên chỉ tiêu này đạt trên bộ mẫu đang xét. Nhưng vẫn còn bốn ảnh lỗi bị cho qua. Ta cần xem bốn ảnh đó thuộc loại mã mờ, nhãn lệch hay điều kiện chụp nào. Khi tỷ lệ phát hiện đạt, ta chỉ có thể khẳng định một điều giới hạn: chức năng phát hiện đáp ứng ngưỡng trên bộ mẫu đánh giá này. Chưa có bằng chứng rằng hiệu quả sẽ giữ nguyên qua mọi ca, tốc độ băng tải và chất liệu bao bì."}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-4", "sceneName": "Tỷ lệ loại nhầm và tác động vận hành", "handwriting": "Đánh dấu 16 túi tốt bị loại trên hình 400 túi; dừng Q4.", "slideContent": "FP = 16; TN = 384; loại nhầm = 16/400 = 4%; giới hạn 3%.", "lectureScript": "Bây giờ xét nhóm túi tốt. Máy báo lỗi sai 16 ảnh trong 400 ảnh tốt, tức tỷ lệ loại nhầm 4 phần trăm. Mục tiêu đặt ra là không quá 3 phần trăm. Vì vậy dù tỷ lệ phát hiện 96 phần trăm đã đạt, PoC vẫn chưa đạt bộ tiêu chí đầy đủ. Một người xem tỷ lệ chính xác chung có thể bỏ qua vấn đề này. Trong thực tế, tỷ lệ loại nhầm liên quan đến công kiểm tra lại và nguy cơ gián đoạn, nhưng bài tập chưa lượng hóa các chi phí đó. Đừng tự cộng lợi ích tiền bạc khi chưa đo đủ dữ liệu. Cần điều chỉnh và thử lại trên mẫu đánh giá mới."}, {"layout": "L2 -> L3", "popupQuiz": "", "sceneCode": "V2-5", "sceneName": "Đọc mức tin cậy và sai lệch phép thử", "handwriting": "Hiện bảng “đủ để nói / chưa đủ để nói” với cùng số liệu 500 ảnh.", "slideContent": "Kiểm nhãn, mẫu độc lập, điều kiện sáng, tốc độ, bao bì, phiên bản, nhật ký.", "lectureScript": "Một tỷ lệ đo được không tự nói mẫu đó đại diện cho dây chuyền. Hãy hỏi bao nhiêu loại bao bì đã xuất hiện, ảnh lấy ở ca nào, ánh sáng có thay đổi không, bản phần mềm nào được dùng và người gán nhãn có biết trước kết quả máy không. Nếu ảnh lỗi được chọn toàn những trường hợp dễ nhận, tỷ lệ phát hiện sẽ bị thổi cao. Nếu kết quả chỉ xuất từ màn hình trình diễn, không có tệp gốc, cần kiểm nguồn trước khi sử dụng. PoC có thể cho bằng chứng về một chức năng trong một phạm vi hẹp; không đủ để chứng minh khả năng vận hành liên tục."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Cổng an toàn, dữ liệu và trách nhiệm", "handwriting": "Đánh dấu những trường phải được xác minh trước khi đặt thiết bị lên dây chuyền.", "slideContent": "Cổng kiểm: quyền ảnh; an toàn cơ cấu loại; nhật ký phiên bản; người kiểm; dừng an toàn.", "lectureScript": "Bên cạnh hai tỷ lệ còn có điều kiện bắt buộc. Ai được xem ảnh chứa mã lô hoặc dữ liệu khách hàng? Có quyền dùng phần mềm và chuyển dữ liệu ra khỏi hệ thống thử không? Cơ cấu đẩy túi bị nghi lỗi sẽ tương tác với người vận hành thế nào? Nếu phải kết nối điều khiển băng tải, cần đánh giá an toàn và quyền thao tác bởi nhân sự có thẩm quyền. Một PoC chạy trên ảnh ngoại tuyến chưa xác nhận những điều kiện đó. Hãy phân biệt rõ điều kiện đã kiểm và điều kiện chưa kiểm trong hồ sơ, giao đầu mối cụ thể. Video ba sẽ chuyển toàn bộ thông tin sang phiếu thực hành."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('9726996e-aec5-5ae9-95dd-9f6d5ee337d8', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 3, 'EL-028-V28.3', 'VIDEO 28.3: TÍNH TRÊN EXCEL VÀ QUYẾT ĐỊNH BƯỚC TIẾP THEO', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đọc phiếu PoC trên Excel", "handwriting": "Mở sheet PHIẾU THỰC HÀNH; khoanh các ô vàng D8:D13 và các ô kết quả C17:C20.", "slideContent": "Sáu đầu vào: TP, FN, FP, TN, chi phí PoC, trần ngân sách.", "lectureScript": "Mở phiếu thực hành Bài 28. Sáu ô đầu vào gồm TP bằng 96, FN bằng 4, FP bằng 16, TN bằng 384; chi phí thử 18 triệu và trần 20 triệu đồng. Tất cả là giả định. Mỗi dòng có trạng thái chứng cứ và người xác nhận. Kết quả phía dưới được tính tự động. Khi làm thật, chỉ dùng dữ liệu đã xác minh, không dùng số mẫu làm kết quả của nhà cung cấp."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Tự tính hai tỷ lệ và phần ngân sách còn lại", "handwriting": "Kích hoạt bảng kết quả C17:C19 và ngưỡng D17:D18.", "slideContent": "Phát hiện 96%; loại nhầm 4%; ngân sách còn 20 - 18 = 2 triệu đồng.", "lectureScript": "Excel lấy TP chia tổng TP và FN để tính tỷ lệ phát hiện. Nó lấy FP chia tổng FP và TN để tính tỷ lệ loại nhầm. Phần ngân sách còn lại bằng trần ngân sách trừ chi phí thử. Với dữ liệu mẫu, hai kết quả lần lượt là 96 phần trăm, 4 phần trăm và 2 triệu đồng chưa dùng. Hãy kiểm bằng tay, rồi thay đầu vào để quan sát. Nếu thiếu dữ liệu hoặc mẫu số bằng không, tỷ lệ để trống thay vì báo lỗi. Còn ngân sách không bù được chỉ số kỹ thuật chưa đạt."}, {"layout": "L2", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Kiểm điều kiện cổng trước khi kết luận", "handwriting": "Nối dữ liệu G8:H13 và D25:G29 tới ô kết luận; dừng Q5.", "slideContent": "Năm cổng: an toàn, quyền dữ liệu, nhãn chuẩn, nhật ký thử, trách nhiệm và chi phí.", "lectureScript": "Sau phép tính, hãy nhìn trạng thái chứng cứ và người phụ trách. Phiếu có thêm năm điều kiện phải kiểm: an toàn, quyền dùng dữ liệu, chất lượng nhãn chuẩn, nhật ký phiên bản và trách nhiệm khi kết thúc thử. Nếu một trạng thái chưa xác minh hoặc thiếu người nhận, bảng cảnh báo thiếu cổng dù tỷ lệ đẹp. Trong bài tập, các giấy tờ được giả định đã kiểm; doanh nghiệp thật vẫn phải xác minh. Q5 hỏi chỉ số khiến lần thử chưa đạt."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thử độ nhạy và quy tắc không làm đẹp số", "handwriting": "Hiện đổi hai ô D10:D11, tỷ lệ loại nhầm 3%; nêu điều kiện mẫu đánh giá mới.", "slideContent": "Giữ tổng mẫu tốt 400; chuyển FP từ 16 thành 12, TN từ 384 thành 388.", "lectureScript": "Giả sử sau khi điều chỉnh, ở một lần thử mới và độc lập, máy loại nhầm 12 mẫu tốt, cho qua đúng 388 mẫu tốt. Khi đó tỷ lệ loại nhầm là 12 trên 400, bằng 3 phần trăm, vừa chạm ngưỡng. Bạn có thể thay hai ô để quan sát công thức. Nhưng trong hồ sơ thực, không được tự sửa 16 thành 12 để làm đẹp kết quả; đó phải là số liệu một phép thử mới có tệp gốc, phiên bản và nhãn chuẩn. Hãy ghi rõ lần thử nào đã dùng để hiệu chỉnh, lần nào chỉ để đánh giá. Nếu không giữ được tính độc lập, kết luận phải hạ mức tin cậy."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Giới hạn chi phí và điểm dừng", "handwriting": "Đổi chi phí lên 22 để hiện thiếu ngân sách; sau đó khôi phục mặc định.", "slideContent": "D12 = 18; D13 = 20 (triệu đồng); trần chi = 20; phần còn 2.", "lectureScript": "Với PoC, doanh nghiệp nên xác định trước trần chi, thời hạn và ai có quyền duyệt thay đổi phạm vi. Nếu phát sinh thêm yêu cầu tích hợp, đừng tự kéo dài thử không giới hạn. Trong bài tập, chi phí 18 triệu đồng đang thấp hơn trần 20 triệu đồng, nhưng khi bạn thay thành 22 triệu đồng, điều kiện chi phí sẽ không đạt. Đây chỉ là cơ chế kiểm ngân sách rất giản lược, chưa phải tổng chi phí sở hữu của giải pháp. Ghi vào biên bản thời điểm dừng và công việc cần khắc phục."}, {"layout": "L2 -> L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Ba khả năng sau khi đọc kết quả", "handwriting": "Sơ đồ nhánh theo cổng bắt buộc và chỉ tiêu; dừng Q6.", "slideContent": "Dừng; điều chỉnh rồi thử lại; đề xuất thí điểm có kiểm soát. Không có nút “mua ngay”.", "lectureScript": "Kết quả có thể dẫn tới ba quyết định. Nếu phát hiện vi phạm an toàn hoặc quyền dữ liệu chưa được cho phép, phải dừng hoạt động liên quan cho đến khi xử lý. Nếu cổng đã rõ nhưng một chỉ số chưa đạt, hãy ghi nguyên nhân, giới hạn sửa và điều kiện thử lại. Chỉ khi dữ liệu đủ tin cậy, chỉ số đạt và điều kiện bắt buộc được xác minh mới đề xuất một thí điểm vận hành có kiểm soát. Ngay cả lúc đó, doanh nghiệp vẫn cần đánh giá chi phí, rủi ro, năng lực vận hành và thẩm quyền đầu tư. Q6 hỏi quyết định nào phù hợp sau một PoC đạt trong phạm vi hẹp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao bài: hồ sơ PoC có thể phản biện", "handwriting": "Hiện checklist bảy sản phẩm, mở sheet tự chấm sau câu cuối.", "slideContent": "Nộp giả thuyết; mẫu và nhãn chuẩn; ma trận TP/FN/FP/TN; ngưỡng; cổng; quyết định và phép thử sau.", "lectureScript": "Bài thực hành cuối là soạn hồ sơ PoC một đến hai trang cho một nhu cầu công nghệ mà bạn biết. Hãy ghi giả thuyết có thể bị bác bỏ, nguồn và số mẫu, nhãn chuẩn, hai chỉ số có mẫu số, giới hạn chi phí, các điều kiện bắt buộc cùng người xác nhận. Dựa trên số liệu giả định của An Bình, bạn phải giải thích vì sao tỷ lệ phát hiện đạt nhưng PoC chưa đạt toàn bộ do tỷ lệ loại nhầm còn cao. Sau đó đề xuất lần thử tiếp theo và cách giữ dữ liệu độc lập. Bảng tự chấm chỉ rà phần thiếu, không cấp quyền triển khai."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('6d332125-8ba0-56a2-bfdf-e03a018f13cd', 'f18c0159-faed-555c-9ff4-5e727391c028', 1, 'EL-029-V29.1', 'VIDEO 29.1: THIẾT KẾ THÍ ĐIỂM VÀ CHỐT TIÊU CHÍ TRƯỚC KHI ĐO', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Mở đầu: phân biệt PoC và thí điểm", "handwriting": "Xuất hiện ba nhãn: kiểm tính khả thi - kiểm vận hành - quyết định có điều kiện.", "slideContent": "Bài 29 | Từ PoC đến thí điểm vận hành. Ba đầu ra: bộ chỉ số; điều kiện dừng; biên bản quyết định.", "lectureScript": "Chào anh chị. Ở bài trước, chúng ta thiết kế một phép thử khái niệm, gọi là PoC, để xem công nghệ có thực hiện được chức năng cốt lõi hay không. Thí điểm vận hành trả lời câu hỏi khác: khi đưa giải pháp vào quy trình làm việc thật, kết quả có ổn định, an toàn và đủ tốt để cân nhắc tiếp tục không? Hôm nay, chúng ta sẽ lập kế hoạch thí điểm, theo dõi chỉ số qua nhiều kỳ và kết luận bằng quy tắc đã thống nhất từ trước. Tình huống An Bình hoàn toàn giả định. Bài học cũng không giả định rằng PoC trong bài trước đã đạt: trước khi mở thí điểm ngoài thực tế, doanh nghiệp phải hoàn tất kiểm chứng và phê duyệt riêng."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Chốt phạm vi và giả thuyết thí điểm", "handwriting": "Hiện ranh giới phạm vi, dòng dữ liệu, người chịu trách nhiệm; không vẽ mở rộng toàn nhà máy.", "slideContent": "Phiếu phạm vi: một dây chuyền; một ca thử có người giám sát; nhãn/mã lô; so với quy trình hiện tại.", "lectureScript": "Giả sử An Bình muốn thử camera OCR kiểm nhãn và mã lô trên một đoạn dây chuyền. Giả thuyết cần viết thành câu có thể bác bỏ: trong điều kiện vận hành được xác định, camera phát hiện ít nhất chín mươi lăm phần trăm mẫu lỗi, loại nhầm không quá ba phần trăm mẫu tốt, đồng thời bảo đảm mức sẵn sàng và tốc độ tối thiểu. Phạm vi chỉ gồm sản phẩm, ca chạy và người vận hành được nêu trong kế hoạch. Không được xem kết quả của một ca dễ dàng là kết quả cho mọi ca. Trước thử nghiệm, phải thống nhất phương án chạy song song hoặc chuyển về kiểm thủ công nếu hệ thống trục trặc."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Định nghĩa mẫu số và dữ liệu gốc", "handwriting": "Viết hai phân số: TP/(TP+FN); FP/(FP+TN). Chỉ rõ người xác nhận nhãn chuẩn.", "slideContent": "Bảng nhãn chuẩn: TP = báo đúng lỗi; FN = bỏ sót; FP = loại nhầm; TN = cho qua đúng.", "lectureScript": "Một thí điểm không thể đánh giá chỉ bằng câu nói máy nhận diện khá tốt. Chúng ta phải biết kết quả lấy từ đâu. Mỗi mẫu cần có mã định danh, nhãn chuẩn do người có trách nhiệm xác nhận, thời điểm, ca vận hành và phiên bản phần mềm. Với mẫu thật sự lỗi, máy báo đúng là TP và cho qua nhầm là FN. Với mẫu thật sự tốt, máy báo lỗi nhầm là FP và cho qua đúng là TN. Tỷ lệ phát hiện lấy TP chia TP cộng FN. Tỷ lệ loại nhầm lấy FP chia FP cộng TN. Hai mẫu số khác nhau. Nếu không kiểm tra điều này, một bảng tổng tỷ lệ chính xác rất đẹp vẫn có thể che khuất lỗi nghiêm trọng."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Ngưỡng bắt buộc đặt trước khi chạy", "handwriting": "Hiện nhãn GIẢ ĐỊNH trên cả bốn ngưỡng và đường phân cách chỉ tiêu/cổng an toàn.", "slideContent": "Thẻ 4 KPI: phát hiện >=95%; loại nhầm <=3%; sẵn sàng >=95%; tốc độ >=45 túi/phút.", "lectureScript": "Trong ví dụ đào tạo, nhóm dự án đề xuất bốn ngưỡng. Phát hiện lỗi không thấp hơn chín mươi lăm phần trăm. Loại nhầm mẫu tốt không vượt ba phần trăm. Thời gian sẵn sàng vận hành ít nhất chín mươi lăm phần trăm thời gian đã lên kế hoạch. Tốc độ ổn định trung bình từ các cửa sổ đo bằng nhau đạt ít nhất bốn mươi lăm túi một phút. Đây là số giả định, không phải chuẩn ngành. Ở dự án thật, doanh nghiệp phải giải thích căn cứ chọn ngưỡng và chốt bằng văn bản trước khi có kết quả. Thay ngưỡng sau khi nhìn số liệu mà không ghi thay đổi sẽ làm mất giá trị của phép so sánh."}, {"layout": "L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Điều kiện loại trừ và phương án rút lui", "handwriting": "Dấu khóa trên điều kiện chưa kiểm; sơ đồ tuyến dự phòng kiểm thủ công.", "slideContent": "5 cổng: an toàn; quyền dữ liệu; nhãn chuẩn; nhật ký phiên bản; người quyết định và dự phòng.", "lectureScript": "Có những điều kiện không thể bù trừ bằng điểm KPI. An toàn thao tác và phương án chuyển về kiểm thủ công phải được duyệt. Quyền sử dụng ảnh, mã lô và dữ liệu sản xuất phải rõ. Nhãn chuẩn, nhật ký và phiên bản phần mềm cần được lưu để kiểm tra lại. Người có thẩm quyền phải biết khi nào tạm dừng. Nếu một trong những cổng này chưa được xác minh, phần thử liên quan phải tạm dừng cho đến khi có bằng chứng. Một thí điểm thành công về tốc độ vẫn chưa được phép tiếp tục nếu làm phát sinh rủi ro an toàn chưa kiểm soát."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Kết thúc video 29.1", "handwriting": "Tích lần lượt từng đầu ra và chuyển video kế tiếp.", "slideContent": "Đầu ra 29.1: phạm vi, giả thuyết, bốn KPI, năm cổng. Chuyển sang sổ theo dõi.", "lectureScript": "Đến đây, anh chị đã có bộ khung để bắt đầu một thí điểm có kiểm soát: phạm vi rõ, giả thuyết có thể kiểm, dữ liệu gốc có định nghĩa, ngưỡng chốt trước và những cổng không được bỏ qua. Hãy mở sheet Phiếu thực hành để xem bảng bốn tuần giả định. Ở video tiếp theo, chúng ta sẽ tổng hợp đúng mẫu số, đọc biến động giữa các tuần và kiểm tra xem một chỉ số tốt trong tuần cuối có đủ để kết luận toàn thí điểm đạt hay chưa."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('9efcd7e5-9d8a-591b-b0b4-998ef7ac2e55', 'f18c0159-faed-555c-9ff4-5e727391c028', 2, 'EL-029-V29.2', 'VIDEO 29.2: TỔNG HỢP DỮ LIỆU VÀ ĐÁNH GIÁ KPI QUA BỐN TUẦN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Đọc nhật ký thí điểm nhiều kỳ", "handwriting": "Hiện bốn dòng tuần với mã W1-W4, khóa công thức ở dòng tổng.", "slideContent": "Sổ bốn tuần: TP, FN, FP, TN, giờ dự kiến, giờ dừng. Dữ liệu toàn bộ là GIẢ ĐỊNH.", "lectureScript": "Chúng ta chuyển sang nhật ký thí điểm. Trong bảng minh họa, mỗi tuần có hai nhóm mẫu: mẫu lỗi thật và mẫu tốt thật. Bốn số TP, FN, FP, TN đều được lưu riêng, kèm số giờ dự kiến vận hành và số giờ hệ thống phải dừng. Đây là số liệu dựng để học cách tính, không phải log của một doanh nghiệp. Người giám sát ngoài thực tế còn phải lưu thời điểm, nguyên nhân dừng, ca, mã lô và số lần phải can thiệp thủ công. Trước khi tổng hợp, hãy kiểm tra các tuần dùng cùng định nghĩa lỗi và cùng quy trình xác nhận nhãn chuẩn."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Đừng lấy trung bình phần trăm của các tuần", "handwriting": "Viết tổng tử số và mẫu số, không lấy trung bình cộng tỷ lệ tuần.", "slideContent": "Tổng 4 tuần: TP 188, FN 12, FP 49, TN 1.751. Phát hiện: 188/200 = 94%.", "lectureScript": "Cách tính dễ sai nhất là lấy bốn tỷ lệ phát hiện từng tuần rồi cộng lại chia bốn. Cách đó chỉ hợp lý nếu các mẫu số bằng nhau và mục đích thật sự là bình quân không trọng số. Trong bảng này, ta cộng số đếm trước. Bốn tuần có một trăm tám mươi tám lần phát hiện đúng và mười hai lần bỏ sót trên tổng hai trăm mẫu lỗi. Tỷ lệ phát hiện gộp là chín mươi bốn phần trăm, thấp hơn ngưỡng chín mươi lăm. Tuần cuối có cải thiện, nhưng không được dùng riêng tuần cuối thay cho kết quả của toàn giai đoạn đã đăng ký."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tính tỷ lệ loại nhầm với đúng mẫu số", "handwriting": "Viết công thức, làm tròn hai chữ số thập phân, giữ số đếm gốc.", "slideContent": "FP 49; TN 1.751; FP/(FP+TN)=49/1.800=2,72%.", "lectureScript": "Tiếp theo là tỷ lệ loại nhầm. Bốn tuần ghi nhận bốn mươi chín mẫu tốt bị camera báo lỗi, và một nghìn bảy trăm năm mươi mốt mẫu tốt được cho qua đúng. Mẫu số là một nghìn tám trăm mẫu thật sự tốt. Bốn mươi chín chia một nghìn tám trăm bằng khoảng hai phẩy bảy hai phần trăm, tức đạt ngưỡng không quá ba phần trăm của ví dụ. Chú ý: chỉ số đạt không có nghĩa mọi mẫu đều được kiểm đúng, và cũng không bù được chỉ số phát hiện lỗi đang thiếu một điểm phần trăm. Hai mục tiêu phải được đánh giá riêng."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Tỷ lệ sẵn sàng: thời gian có thể chạy", "handwriting": "Đường thời gian: giờ kế hoạch / dừng vì lỗi công nghệ / giờ khả dụng.", "slideContent": "160 giờ kế hoạch; 6,7 giờ dừng; tỷ lệ sẵn sàng (160-6,7)/160 = 95,81%.", "lectureScript": "Chỉ số thứ ba là mức sẵn sàng vận hành. Trong bốn tuần, giả định hệ thống được lên kế hoạch chạy một trăm sáu mươi giờ và có tổng sáu phẩy bảy giờ dừng vì sự cố thuộc phạm vi theo dõi. Thời gian còn lại là một trăm năm mươi ba phẩy ba giờ. Chia số này cho một trăm sáu mươi, chúng ta được khoảng chín mươi lăm phẩy tám mốt phần trăm, vượt ngưỡng chín mươi lăm. Điều quan trọng là quy tắc ghi giờ dừng phải nhất quán. Nghỉ ca theo lịch không được tùy tiện tính thành sự cố, và thời gian dừng để sửa lỗi không được giấu khỏi nhật ký."}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Tốc độ và khả năng duy trì kết quả", "handwriting": "Đặt đồ thị bốn điểm, nhấn bằng nhau về độ dài cửa sổ quan sát.", "slideContent": "Bốn cửa sổ đo bằng nhau: 42, 45, 47, 48 túi/phút. Bình quân 45,5 túi/phút.", "lectureScript": "Trong bốn cửa sổ đo tốc độ có độ dài bằng nhau, số đo giả định là bốn mươi hai, bốn mươi lăm, bốn mươi bảy và bốn mươi tám túi một phút. Trung bình là bốn mươi lăm phẩy năm, đáp ứng mức tối thiểu bốn mươi lăm của ví dụ. Tuy nhiên, đây là bình quân của bốn cửa sổ, chưa thay thế phép đo phân bố theo ca và theo loại bao bì. Nếu các cửa sổ khác độ dài, cần tính bình quân có trọng số theo thời gian hoặc sản lượng tương ứng. Tốc độ tăng dần đáng để điều tra, nhưng chưa chứng minh nguyên nhân do camera nếu nhân sự, vật liệu hoặc lịch sản xuất cũng thay đổi."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Kết thúc video 29.2", "handwriting": "Hiện dấu gạch ở KPI đầu, tích ba KPI sau; không hiển thị chữ phê duyệt.", "slideContent": "Bảng 4 KPI: 94% (không đạt), 2,72% (đạt), 95,81% (đạt), 45,5 (đạt).", "lectureScript": "Nhìn toàn bộ bảng, tỷ lệ phát hiện gộp không đạt, còn ba chỉ số khác đạt các ngưỡng minh họa. Chúng ta không lấy bình quân điểm của bốn chỉ số để cho qua chỉ số chưa đạt. Công việc tiếp theo là kiểm tra cổng bắt buộc, xem log lỗi và viết quyết định có người nhận việc. Trong video cuối, anh chị sẽ thực hiện điều đó ngay trên sheet thực hành; sau đó thử thay một số đầu vào để xem vì sao kết luận có thể thay đổi."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('3a25ea6d-830c-5306-9c9f-c03a5a9a3920', 'f18c0159-faed-555c-9ff4-5e727391c028', 3, 'EL-029-V29.3', 'VIDEO 29.3: RA QUYẾT ĐỊNH VÀ KẾ HOẠCH THỬ LẠI CÓ KIỂM SOÁT', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Từ số liệu tới quyết định có điều kiện", "handwriting": "Xuất hiện từng nhánh, ưu tiên nhánh thiếu cổng an toàn.", "slideContent": "Sơ đồ: Đủ dữ liệu? -> Cổng đã kiểm? -> 4 KPI đạt? -> Điều chỉnh/thử lại hay đề xuất tiếp tục.", "lectureScript": "Trong video cuối, chúng ta không bắt đầu bằng câu hỏi có nên mua thiết bị không. Câu hỏi trước mắt là kết quả thí điểm có đủ tin cậy để đề xuất bước tiếp hay chưa. Bảng quyết định đi theo thứ tự: dữ liệu có đủ không, cổng bắt buộc đã được kiểm chưa, rồi bốn ngưỡng KPI có đồng thời đạt hay không. Nếu thiếu cổng an toàn hay quyền dữ liệu, phải tạm dừng phần liên quan. Nếu dữ liệu đủ và cổng đã xác minh nhưng một KPI không đạt, nhóm dự án cần điều chỉnh giả thuyết hoặc cách vận hành và thử lại."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-2", "sceneName": "Thao tác số liệu trên Excel", "handwriting": "Quay màn hình trực tiếp. Chỉ sửa ô màu vàng. Zoom vào ô C17, C18, C19, C20.", "slideContent": "Sheet PHIẾU THỰC HÀNH: C8:H11 nhập tuần; C12:H12 tổng; C13:F13 tốc độ; C17:C20 kết quả.", "lectureScript": "Hãy mở sheet Phiếu thực hành. Mỗi dòng từ tám đến mười một tương ứng một tuần. Cột C và D là TP, FN; E và F là FP, TN. Hai cột tiếp theo là giờ kế hoạch và giờ dừng. Dòng mười hai tự cộng số đếm; dòng mười ba nhận tốc độ từ bốn cửa sổ bằng nhau. Các ô kết quả ở dòng mười bảy đến hai mươi sử dụng công thức, không nhập đè. Anh chị có thể thử thay một số đếm để xem tỷ lệ gộp thay đổi. Nếu xóa mẫu số, bảng phải báo thiếu dữ liệu, chứ không được tự cho rằng tỷ lệ lỗi bằng không."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-3", "sceneName": "Đọc kết luận mẫu: điều chỉnh và thử lại", "handwriting": "Hiện ô C20: ĐIỀU CHỈNH / THỬ LẠI. Không gắn chữ đầu tư.", "slideContent": "Kết quả giả định: phát hiện 94% < 95%; loại nhầm 2,72%; sẵn sàng 95,81%; tốc độ 45,5.", "lectureScript": "Với dữ liệu mẫu, tất cả cổng đã được đánh dấu kiểm và có người nhận việc; riêng tỷ lệ phát hiện còn thấp hơn ngưỡng. Vì thế ô kết luận trả về điều chỉnh và thử lại. Nhóm dự án cần đọc nhật ký mười hai lần bỏ sót, tìm tình huống lỗi xuất hiện, xem ánh sáng, vị trí nhãn và thay đổi vật liệu có liên quan hay không. Sau khi điều chỉnh, phải tổ chức một phép thử mới với dữ liệu phù hợp; không được sửa đè kết quả bốn tuần cũ để biến báo cáo thành đạt."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thử kịch bản và giữ nguyên lịch sử", "handwriting": "Minh họa sao chép sheet thực hành, gắn nhãn GIẢ LẬP, không xóa log gốc.", "slideContent": "Kịch bản thay đổi: FN tăng, giờ dừng tăng hoặc thiếu cổng. Lưu bản gốc trước khi thử.", "lectureScript": "Để kiểm tra độ nhạy, anh chị hãy sao chép sheet trước khi thay số. Thử tăng giờ dừng và quan sát chỉ số sẵn sàng. Cuối cùng đổi trạng thái an toàn thành chưa kiểm: khi ấy, hệ thống phải chuyển sang cảnh báo cổng bắt buộc, cho dù các tỷ lệ vẫn đẹp. Đây là thao tác học tập trên dữ liệu giả lập. Không dùng mô phỏng để thay cho bằng chứng thử nghiệm."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Kế hoạch hành động và tiêu chí thử lại", "handwriting": "Điền ví dụ: log FN, xác minh nhãn chuẩn, điều kiện ánh sáng, thử độc lập.", "slideContent": "Bảng 4 cột: Vấn đề; bằng chứng cần tìm; người phụ trách; hạn và điểm kiểm tra.", "lectureScript": "Một kết luận tốt phải dẫn đến hành động kiểm được. Với tỷ lệ phát hiện chưa đạt, chúng ta lập danh sách mẫu bỏ sót, giao người phụ trách kiểm lại nhãn chuẩn và điều kiện ánh sáng, rồi xác định bộ mẫu độc lập cho lần đánh giá tiếp theo. Người vận hành ghi lỗi hiện trường, kỹ thuật kiểm tham số và chất lượng đối chiếu nhãn. Trưởng dự án chốt phạm vi được phép thay đổi, ngân sách và ngày kiểm lại. Sau thử lại, nhóm phải báo cáo đồng thời tỷ lệ phát hiện, tỷ lệ loại nhầm, mức sẵn sàng và tốc độ. Không chỉ công bố chỉ tiêu vừa được cải thiện."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Ba kết quả có thể xảy ra", "handwriting": "Dùng ba trạng thái và nhãn chưa phê duyệt đầu tư.", "slideContent": "Điều kiện: thiếu cổng -> tạm dừng; không đạt KPI -> điều chỉnh; đủ cổng + đạt KPI -> đề xuất tiếp tục có điều kiện.", "lectureScript": "Khi tổng hợp, có ba hướng xử lý mẫu. Thiếu điều kiện bắt buộc thì tạm dừng phần liên quan. Đủ cổng nhưng KPI chưa đạt thì điều chỉnh và thử lại, hoặc dừng dự án nếu chi phí và rủi ro không còn chấp nhận được; quyết định dừng hẳn thuộc người có thẩm quyền. Khi tất cả KPI cùng đạt và bằng chứng tin cậy, nhóm có thể đề xuất tiếp tục sang thẩm định quy mô lớn hơn. Cần kiểm tra lại chi phí vòng đời, năng lực tiếp nhận, an toàn và điều khoản với nhà cung cấp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Tổng kết và giao bài thực hành", "handwriting": "Hiện checklist 5 mục và dẫn ba bài viết, 10 câu hỏi, bảng tự chấm.", "slideContent": "Nộp 1 trang: phạm vi, bốn chỉ số, năm cổng, kết luận và kế hoạch thử lại.", "lectureScript": "Anh chị hãy hoàn thành ba việc. Thứ nhất, rà dữ liệu bốn tuần và diễn giải đúng bốn chỉ số. Thứ hai, đối chiếu năm cổng bắt buộc, ghi bằng chứng còn thiếu. Cuối cùng, viết biên bản một trang nêu quyết định điều chỉnh hay tiếp tục, người nhận việc, điều kiện để xét lại và giới hạn của kết luận. Sau đó làm mười câu trắc nghiệm và tự chấm theo bảy tiêu chí trong file. Hãy nhớ: kết quả thí điểm chỉ có ý nghĩa trong phạm vi đã đo và với dữ liệu có thể truy vết."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('571a872e-15ca-5b6a-ab0a-2d7c961aa739', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 1, 'EL-030-V30.1', 'VIDEO 30.1: TIẾP NHẬN CÔNG NGHỆ VÀ HỒ SƠ BÀN GIAO', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Sau thí điểm: ba việc chưa thể bỏ qua", "handwriting": "Sơ đồ bốn bước có cổng kiểm giữa từng bước, nhãn TOÀN BỘ SỐ LIỆU GIẢ ĐỊNH.", "slideContent": "Bài 30 | Tiếp nhận -> huấn luyện -> quản trị thay đổi -> mở rộng theo giai đoạn.", "lectureScript": "Chào anh chị. Ở bài trước, kết quả thí điểm giả định của An Bình chưa đạt tỷ lệ phát hiện lỗi. Vì thế, bài hôm nay không có nghĩa là doanh nghiệp ấy đã được phép mở rộng ngay. Chúng ta giả sử có một giai đoạn sửa lỗi, kiểm chứng lại và được phê duyệt riêng trước khi chuẩn bị tiếp nhận. Nhiệm vụ mới là chuyển hệ thống từ tay đơn vị cung cấp sang người vận hành của doanh nghiệp, để chất lượng được duy trì khi chuyên gia rời hiện trường. Ba đầu ra chúng ta sẽ lập là hồ sơ bàn giao, kế hoạch đào tạo theo vị trí công việc và điều kiện quyết định mở rộng theo giai đoạn."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Điều kiện đầu vào trước khi nhận hệ thống", "handwriting": "Hiện bảng hồ sơ, đánh dấu mục nào cần phê duyệt bằng chứng.", "slideContent": "Cổng đầu vào: phê duyệt thử lại; KPI và an toàn; hợp đồng/quyền; ngân sách, người chịu trách nhiệm.", "lectureScript": "Muốn tiếp nhận, trước tiên nhóm dự án phải có căn cứ để tiếp tục. Đó có thể là báo cáo thí điểm lại, biên bản xử lý điểm không đạt, xác nhận an toàn và quyết định của người có thẩm quyền. Không dùng phiếu tự chấm trong bài để thay cho các tài liệu đó. Tiếp theo cần xác định rõ phạm vi nghiệm thu: thiết bị nào, phiên bản phần mềm nào, điểm kết nối với dây chuyền nào và mức hỗ trợ sau bàn giao. Với bài tập An Bình, chúng ta chỉ giả định các tài liệu đầu vào đã được kiểm; khi thực hành thật, bất kỳ mục chưa rõ nào đều phải đưa vào danh sách vướng mắc và giữ cổng chưa hoàn thành."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Bộ hồ sơ bàn giao kiểm tra được", "handwriting": "Dùng bảng checklist 7 thành phần, thể hiện bản ghi, người giao, người nhận, ngày phiên bản.", "slideContent": "Bộ hồ sơ: cấu hình; sơ đồ I/O; SOP; tiêu chí nghiệm thu; tài khoản/phân quyền; nhật ký; vật tư dự phòng.", "lectureScript": "Bàn giao không chỉ là nhận chìa khóa và bật nguồn máy. Hồ sơ tối thiểu phải chỉ rõ cấu hình được nghiệm thu, sơ đồ tín hiệu với băng tải, quy trình vận hành chuẩn và hướng dẫn xử lý lỗi. Cần bàn giao cách sao lưu, khôi phục và xuất dữ liệu, danh sách tài khoản có quyền truy cập, cùng đầu mối hỗ trợ. Mỗi tài liệu phải có mã phiên bản, ngày cập nhật, người giao và người nhận. Khi một tệp cấu hình không mở được hoặc một tài khoản chỉ nằm trong máy của nhà cung cấp, hãy ghi nhận là chưa nghiệm thu mục đó. Phiếu ký tên mà thiếu bằng chứng vẫn chưa giải quyết được rủi ro vận hành."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Chia rõ trách nhiệm sau chuyển giao", "handwriting": "Hiện bảng RACI đơn giản cho báo lỗi, đổi tham số, phê duyệt thay đổi, khôi phục.", "slideContent": "Vai trò: vận hành ca; QC; IT/dữ liệu; bảo trì/trưởng ca; nhà cung cấp; người phê duyệt.", "lectureScript": "Một nguyên nhân phổ biến khiến công nghệ mới bị bỏ dùng là trách nhiệm không rõ. Người vận hành cần biết khi camera báo nhầm thì báo ai và có được bỏ qua cảnh báo không. QC cần quyền kiểm nhãn chuẩn và xử lý ngoại lệ. IT quản lý dữ liệu, sao lưu và phân quyền; bảo trì quản lý thiết bị, cảm biến và phụ tùng. Nhà cung cấp có trách nhiệm hỗ trợ trong thời hạn thỏa thuận. Người có thẩm quyền phải quyết định khi nào thay ngưỡng hay dừng dây chuyền. Hãy ghi một người chịu trách nhiệm cuối cho từng sự cố, tránh để hai phòng ban cùng nghĩ rằng bên kia đã xử lý."}, {"layout": "L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Cổng an toàn và quyền dữ liệu không bù trừ", "handwriting": "Hiện biểu tượng khóa: thiếu một cổng thì dừng bước triển khai liên quan.", "slideContent": "5 cổng: an toàn/SOP; nghiệm thu QC; quyền công nghệ; sao lưu/khôi phục; người duyệt và đường lui.", "lectureScript": "Trong bảng thực hành có năm cổng bắt buộc. An toàn thao tác và hướng dẫn dừng khẩn phải được duyệt. QC phải xác minh quy trình nghiệm thu và bộ mẫu độc lập. Quyền sử dụng phần mềm, dữ liệu và hỗ trợ kỹ thuật phải được làm rõ. Sao lưu, phục hồi và chuyển về thao tác thủ công phải thử được, không chỉ viết trên giấy. Cuối cùng là trách nhiệm của người quyết định, người trực xử lý sự cố và đường báo cáo. Nếu một cổng chưa kiểm, hệ thống phải hiện cảnh báo tạm dừng. Một lớp đào tạo có điểm cao không được dùng để hợp thức hóa thiếu sót về an toàn hoặc quyền sử dụng."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Chốt đầu ra của video 30.1", "handwriting": "Tích sáu loại hồ sơ, chuyển sang sơ đồ đào tạo theo vai trò.", "slideContent": "Đầu ra: hồ sơ cấu hình; SOP; bằng chứng nghiệm thu; quyền dữ liệu; phân vai và cổng.", "lectureScript": "Sau video đầu, anh chị hãy tự kiểm xem bộ hồ sơ tiếp nhận đã đủ để một ca vận hành mới thực hiện được công việc chưa. Một người khác có thể tìm đúng SOP, chạy thử, xác nhận mã lô, xử lý cảnh báo và gọi hỗ trợ hay không? Nếu câu trả lời dựa vào lời hứa miệng của nhà cung cấp, cần bổ sung tài liệu. Ở video tiếp theo, chúng ta chuyển các thao tác đó thành yêu cầu năng lực cho từng nhóm nhân sự, rồi tính số người đã học và số người thực sự vượt qua kiểm tra thao tác."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('3de074fd-dd95-5b7b-a554-16c344f57153', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 2, 'EL-030-V30.2', 'VIDEO 30.2: ĐÀO TẠO THEO VAI TRÒ VÀ XÁC NHẬN NĂNG LỰC', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Đào tạo theo nhiệm vụ, không chỉ theo danh sách dự lớp", "handwriting": "Xuất hiện bảng vai trò và nhiệm vụ, không dùng tên người thật.", "slideContent": "Bốn nhóm: vận hành ca 8; QC 3; IT 2; trưởng ca/bảo trì 3 người (GIẢ ĐỊNH).", "lectureScript": "Chúng ta chuyển sang năng lực tiếp nhận. Giả sử An Bình cần mười sáu người đủ khả năng thực hiện các nhiệm vụ liên quan tới camera OCR. Trong đó có tám người vận hành ca, ba người QC, hai người IT và ba người phụ trách trưởng ca hoặc bảo trì. Số lượng này hoàn toàn do tình huống giả định đặt ra. Không phải mọi người đều học cùng một nội dung. Người vận hành cần thao tác thường ngày và nhận biết cảnh báo; QC cần xác nhận lỗi và nhãn chuẩn; IT phải làm được sao lưu và cấp quyền; trưởng ca cần biết khi nào dừng, phân công và báo cáo. Mỗi vai trò phải có bài kiểm tra phù hợp nhiệm vụ."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Thiết kế học, thực hành và xác nhận năng lực", "handwriting": "Hiện ba mẫu tình huống: mã mờ; mất tín hiệu; khôi phục sau lỗi.", "slideContent": "Ba bước: học SOP; diễn tập tình huống; kiểm tra thực hành với người đánh giá độc lập.", "lectureScript": "Một buổi thuyết trình cách dùng máy không đủ để chứng minh sẵn sàng vận hành. Người học cần xem quy trình, thực hành có giám sát và được kiểm tra trên tình huống gần thực tế. Chẳng hạn người vận hành phải xử lý mã in mờ mà không tự bỏ cảnh báo. Nhân sự IT phải sao lưu và khôi phục một bản cấu hình thử. QC phải phân biệt mẫu lỗi thật với mẫu tốt bị báo nhầm. Người đánh giá cần ghi tiêu chí đạt, lần kiểm tra và phần nào phải học lại. Nếu chỉ có danh sách ký tham dự mà không có kết quả thực hành, chúng ta mới chứng minh được sự có mặt, chưa chứng minh năng lực."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tính tỷ lệ bao phủ đào tạo", "handwriting": "Viết công thức tỷ lệ số đã học / số phải có; tô vàng ô dữ liệu.", "slideContent": "Tổng yêu cầu 16; đã học 15; tỷ lệ bao phủ = 15/16 = 93,75%.", "lectureScript": "Hãy nhìn sheet Phiếu thực hành. Bốn nhóm yêu cầu lần lượt tám, ba, hai và ba người, tổng cộng mười sáu. Số đã tham gia học tương ứng tám, ba, hai và hai, tổng cộng mười lăm. Tỷ lệ bao phủ đào tạo bằng mười lăm chia mười sáu, tức chín mươi ba phẩy bảy lăm phần trăm. Trong bài, nhóm đặt ngưỡng giả định chín mươi lăm phần trăm, nên chỉ tiêu này chưa đạt. Đó là một cảnh báo về tổ chức nhân sự, chưa nói người đã học có thao tác tốt hay chưa. Muốn kết luận năng lực, phải tính tiếp số người thực sự đạt bài kiểm tra."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Tính tỷ lệ người đạt kiểm tra thao tác", "handwriting": "Viết 13/16, so với 13/15; phân biệt hai mẫu số và mục đích.", "slideContent": "Số đạt thực hành 13 trên 16 phải có = 81,25%; ngưỡng giả định 90%.", "lectureScript": "Trong cùng bảng, số người vượt qua bài thực hành là sáu, ba, hai và hai, cộng thành mười ba. Nếu mục đích là kiểm tra tỷ lệ nhân sự cần thiết đã đủ năng lực, mẫu số vẫn là mười sáu người phải có, nên tỷ lệ bằng tám mươi mốt phẩy hai lăm phần trăm. Nếu muốn đánh giá hiệu quả lớp học, ta có thể dùng mười ba trên mười lăm người đã tham dự, nhưng đó là một chỉ tiêu khác. Bài này dùng tỷ lệ năng lực sẵn sàng trên toàn bộ yêu cầu biên chế, với ngưỡng giả định chín mươi phần trăm. Vì vậy, cả tỷ lệ bao phủ lẫn tỷ lệ thực hành đều chưa đạt."}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Quản trị thay đổi và phản hồi từ ca sản xuất", "handwriting": "Sơ đồ ghi nhận lỗi -> phân loại -> duyệt thay đổi -> thông báo -> huấn luyện lại.", "slideContent": "Kênh phản hồi: nhật ký hiện trường; họp 15 phút; xử lý yêu cầu đổi SOP; phê duyệt phiên bản.", "lectureScript": "Đào tạo xong vẫn chưa hết việc. Khi công nghệ đổi cách làm cũ, người vận hành có thể gặp thao tác mới, thời gian chờ hoặc cảnh báo khó hiểu. Cần một kênh ghi nhận phản hồi mà không khuyến khích tự ý tắt chức năng kiểm soát. Mỗi đề xuất thay đổi phải có mô tả vấn đề, người đánh giá tác động, phiên bản tài liệu mới và cách thông báo cho những ca còn lại. Nếu sửa ngưỡng camera hay thay quy trình xử lý túi bị loại, QC và kỹ thuật phải thống nhất trước khi áp dụng. Giai đoạn đầu nên theo dõi số lần gọi hỗ trợ, lỗi thao tác và việc phải quay về phương án thủ công."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Đầu ra video 30.2: kế hoạch nâng năng lực", "handwriting": "Chiếu danh sách sáu đầu việc, không gắn ngày thật.", "slideContent": "Bảng: nhóm chưa đủ người; kỹ năng còn thiếu; người kèm cặp; hạn; kiểm tra lại.", "lectureScript": "Kết quả bài tập đang chỉ ra khoảng thiếu rõ ràng. Trưởng ca còn một người chưa tham dự; nhóm vận hành có hai người đã học nhưng chưa đạt thao tác. Việc cần làm không phải xóa tên họ khỏi báo cáo. Chúng ta phải tổ chức lớp bổ sung hoặc kèm cặp, giao người đánh giá độc lập và đặt ngày kiểm tra lại. Bằng chứng giữ nguyên cả lần chưa đạt và lần kiểm tra sau. Khi một người mới đạt, hãy cập nhật số liệu trên phiếu để xem tỷ lệ thay đổi. Ở video cuối, chúng ta sẽ dùng kết quả đào tạo cùng với năm cổng tiếp nhận để quyết định có được đề xuất mở rộng theo giai đoạn hay chưa."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('0463cca6-78fe-5b57-a8c0-5176779bd869', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 3, 'EL-030-V30.3', 'VIDEO 30.3: QUẢN TRỊ THAY ĐỔI VÀ NHÂN RỘNG THEO GIAI ĐOẠN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Mở rộng công nghệ cần cổng theo từng giai đoạn", "handwriting": "Bản đồ ba giai đoạn có cổng an toàn, năng lực và KPI tại mỗi bước.", "slideContent": "Giai đoạn 1 một ca -> Giai đoạn 2 thêm ca -> Giai đoạn 3 thêm dây chuyền, mỗi bước kiểm lại.", "lectureScript": "Một ca chạy tốt chưa bảo đảm kết quả ở ca khác hoặc dây chuyền khác. Vì vậy ta chia mở rộng thành ba bước giả định: duy trì ca đã kiểm chứng, thêm ca mới, rồi mới xem xét dây chuyền tiếp theo. Mỗi bước cần phạm vi, người chịu trách nhiệm, ngưỡng kỹ thuật và năng lực nhân sự. Không được gộp thành quyết định triển khai toàn nhà máy. Kết quả thí điểm chỉ hỗ trợ đề xuất. Từng bước vẫn cần xét rủi ro, chi phí, an toàn và phê duyệt riêng của doanh nghiệp."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-2", "sceneName": "Đọc quy tắc quyết định trên phiếu", "handwriting": "Sơ đồ bốn nhánh, cổng bắt buộc đi trước kiểm ngưỡng đào tạo.", "slideContent": "Thiếu dữ liệu -> chưa kết luận; thiếu cổng -> tạm dừng; thiếu đào tạo -> bổ sung; đủ -> đề xuất theo giai đoạn.", "lectureScript": "Bảng quyết định trước hết kiểm số liệu. Số người phải không âm; đã học không vượt số cần có; đạt thao tác không vượt số đã học. Tiếp đó kiểm năm cổng bàn giao và người nhận việc. Thiếu cổng thì tạm dừng. Đủ cổng nhưng tỷ lệ đào tạo hoặc thực hành dưới ngưỡng thì bổ sung năng lực, chưa nhân rộng. Chỉ khi dữ liệu hợp lệ, mọi cổng được xác minh và các ngưỡng đồng thời đạt, bảng mới nêu đề xuất mở theo giai đoạn. Người có thẩm quyền vẫn phải quyết định."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-3", "sceneName": "Thao tác thay số và đọc kết quả thực hành", "handwriting": "Quay màn hình phần bảng; sửa đúng ô vàng, không gõ đè công thức.", "slideContent": "C8:E11 số người; C12:E12 cộng; C13/D13 tỷ lệ; C20 kết luận; D25:G29 cổng.", "lectureScript": "Mở sheet Phiếu thực hành. Dòng tám đến mười một là bốn nhóm người. Cột C ghi số cần, D số đã học, E số đạt thao tác. Dòng mười hai tính tổng; dòng mười ba tính hai tỷ lệ. Dòng hai mươi đưa ra kết luận từ tỷ lệ và năm cổng. Hãy thử tăng số người đạt trong nhóm vận hành và quan sát kết quả. Nếu nhập số đạt lớn hơn đã học hoặc xóa một đầu vào, bảng phải báo không hợp lệ. Đây chỉ là mô hình tính trên dữ liệu giả định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Kịch bản chưa đạt và xử lý khoảng thiếu", "handwriting": "Hiện trạng thái BỔ SUNG ĐÀO TẠO - CHƯA NHÂN RỘNG.", "slideContent": "Mặc định: 15/16 = 93,75% bao phủ; 13/16 = 81,25% đạt thao tác; ngưỡng 95%/90%.", "lectureScript": "Dữ liệu mẫu có mười lăm trên mười sáu người đã học và mười ba người đạt thao tác. Tỷ lệ tương ứng là chín mươi ba phẩy bảy lăm và tám mươi mốt phẩy hai lăm phần trăm. Cả hai dưới ngưỡng giả định. Kết luận là bổ sung đào tạo, chưa nhân rộng, dù năm cổng đã được đánh dấu kiểm. Cần xác định người chưa học, kỹ năng chưa đạt, người kèm cặp và thời điểm kiểm tra lại. Không được sửa con số chỉ để chuyển trạng thái trong Excel."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Thử thay đổi một điều kiện bắt buộc", "handwriting": "Hiện trước-sau thay đổi ô D27 và trạng thái C20.", "slideContent": "Thao tác thử: đổi D27 thành Chưa kiểm, quan sát C20 chuyển sang TẠM DỪNG.", "lectureScript": "Giả sử quyền sử dụng phần mềm hoặc dữ liệu chưa được xác minh. Hãy đổi ô D27 thành chưa kiểm. Kết luận chuyển sang tạm dừng phần triển khai liên quan, cho dù tỷ lệ đào tạo có thể đạt một trăm phần trăm. Không dùng điểm số để bỏ qua quyền dữ liệu, an toàn hoặc khôi phục hệ thống. Chỉ cập nhật cổng khi đã có chứng cứ và người chịu trách nhiệm xác nhận. Thao tác đổi trạng thái hôm nay chỉ là mô phỏng; hồ sơ dự án thật phải có kiểm tra độc lập và biên bản."}, {"layout": "L2", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Theo dõi sau mở rộng và phương án quay lui", "handwriting": "Hiện trục tuần 1-4 sau chuyển giao, điểm dừng và đường quay lại quy trình cũ.", "slideContent": "Theo dõi theo ca: KPI QC; thời gian dừng; thao tác sai; hỗ trợ nhà cung cấp; chi phí phát sinh.", "lectureScript": "Khi được duyệt mở rộng một bước, công việc theo dõi vẫn tiếp diễn. QC ghi tỷ lệ bỏ sót và loại nhầm; vận hành ghi giờ dừng và khó khăn thao tác. IT kiểm quyền dữ liệu, nhật ký phiên bản và sao lưu; bảo trì theo dõi sự cố thiết bị. Khi chỉ số vượt ngưỡng dừng hoặc có vấn đề an toàn, người trực phải biết ai được quyền dừng và chuyển về kiểm thủ công. Hợp đồng hỗ trợ cần ghi kênh liên hệ, thời gian phản hồi và cách bàn giao log. Như vậy việc kiểm soát không phụ thuộc vào chuyên gia thường trực."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Giao bài và giới hạn kết luận", "handwriting": "Hiện bốn đầu ra, dẫn tới trắc nghiệm và thang tự chấm.", "slideContent": "Sản phẩm nộp: checklist bàn giao; bảng năng lực; quyết định có điều kiện; kế hoạch mở rộng.", "lectureScript": "Anh chị hãy hoàn thành bảng đào tạo, tính hai tỷ lệ và đánh dấu đúng năm cổng. Sau đó viết kế hoạch tiếp nhận một trang gồm hồ sơ, người chịu trách nhiệm, nội dung thực hành, cách đánh giá và lộ trình mở rộng theo ca. Ghi cả ngưỡng dừng và phương án quay về kiểm thủ công. Mười câu trắc nghiệm cùng bảng tự chấm giúp kiểm lại bản kế hoạch. Đừng coi danh sách tham dự là năng lực, hoặc kết quả thí điểm là quyền nhân rộng. Mọi cổng cần có chứng cứ trước khi thay đổi vận hành thực tế."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('2763b367-0ef5-59e3-a700-ae2125658f43', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 1, 'EL-031-V1', 'Phần 1: Giới thiệu và Nguyên lý cốt lõi', 240, NULL, NULL, NULL, '[{"layout": "Đồ họa hoạt hình", "popupQuiz": "Q1", "sceneCode": "V1-1", "sceneName": "Mở đầu", "handwriting": "", "slideContent": "Khái niệm và định nghĩa", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('05d08086-e37b-5d97-b5e7-be14ec90c6bb', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 2, 'EL-031-V2', 'Phần 2: Phương pháp triển khai và Phân tích', 240, NULL, NULL, NULL, '[{"layout": "Slide tương tác", "popupQuiz": "Q2", "sceneCode": "V2-1", "sceneName": "Nội dung chính", "handwriting": "", "slideContent": "Các bước triển khai", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('c469136c-2bd2-593c-a44f-2efe5774182b', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', 3, 'EL-031-V3', 'Phần 3: Bài học thực tiễn và Hành động', 240, NULL, NULL, NULL, '[{"layout": "Infographic tổng kết", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Tóm tắt", "handwriting": "", "slideContent": "3 điểm cần nhớ và hành động", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('54d94eec-ee34-5a53-b110-d8bf911c4d14', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 1, 'EL-032-V32.1', 'VIDEO 32.1: NHẬN BIẾT TÍN HIỆU VÀ TRÁNH NHẦM TRÀO LƯU', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Từ tin công nghệ đến quyết định doanh nghiệp", "handwriting": "Mở bằng hai mẩu tin giả định rồi đặt câu hỏi ba tầng. Hiện nhãn VÍ DỤ GIẢ ĐỊNH.", "slideContent": "Bài 32 | Đọc xu hướng không chạy theo trào lưu. Ba câu: Tin nói gì? Chứng cứ đâu? Có liên quan An Bình không?", "lectureScript": "Chào anh chị. Một bên nói trí tuệ nhân tạo sẽ thay quy trình kiểm tra. Bên khác đề nghị xây bản sao số của cả nhà máy. Không phải thông tin nào cũng sai, nhưng không thể từ một lời giới thiệu chuyển thẳng sang quyết định đầu tư. Trong bài này, chúng ta dùng cơ sở đóng gói cà phê An Bình hoàn toàn giả định. Doanh nghiệp cần kiểm nhãn, mã lô và duy trì thiết bị ổn định. Tôi sẽ hướng dẫn anh chị tách tín hiệu từ nguồn, kiểm tra mức độ đáng tin rồi đối chiếu với một vấn đề cụ thể. Sản phẩm cuối là danh mục theo dõi và một đề xuất thử nhỏ, không phải danh sách công nghệ phải mua."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Ba tầng: tín hiệu, giả thuyết, quyết định", "handwriting": "Lần lượt đẩy ba thẻ lên màn hình, tô đậm phần chưa có bằng chứng.", "slideContent": "TÍN HIỆU: lời công bố hoặc trường hợp áp dụng. GIẢ THUYẾT: giá trị có thể đem lại. QUYẾT ĐỊNH: cần kiểm gì?", "lectureScript": "Khi đọc xu hướng, tôi đề nghị phân biệt ba tầng. Tầng thứ nhất là tín hiệu: một hồ sơ kỹ thuật mới, một thử nghiệm được công bố, hay một doanh nghiệp nói đã ứng dụng. Tầng thứ hai là giả thuyết: công nghệ ấy có thể giảm lỗi, rút thời gian hoặc hỗ trợ một vai trò. Đây vẫn chỉ là điều cần kiểm tra. Tầng thứ ba mới là quyết định của An Bình: đưa vào danh sách theo dõi, tìm thêm bằng chứng, hoặc tổ chức thử nghiệm giới hạn. Chẳng hạn, một video trình diễn nhận đúng vài mẫu mã lô không chứng minh hệ thống sẽ hoạt động ổn định trên mọi ca sản xuất."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Ghi hồ sơ nguồn trước khi đọc thông điệp", "handwriting": "Hiện checklist sáu trường, chèn ví dụ minh họa tài liệu giới thiệu và nhật ký hiện trường.", "slideContent": "Phiếu nguồn: ai công bố? ngày nào? dữ liệu gì? mẫu thử nào? phương pháp? phạm vi? có thể kiểm chứng không?", "lectureScript": "Một tín hiệu chỉ hữu ích khi truy được nguồn. Gặp một bài trình bày, trước hết ghi ai công bố, thời điểm công bố và họ thực sự đã đo gì. Tiếp theo hỏi số mẫu, điều kiện thử, giới hạn áp dụng và bên nào xác nhận. Một lời giới thiệu từ nhà cung cấp có thể giúp tìm đặc tính để hỏi sâu, nhưng không thay được kết quả thử ở điều kiện doanh nghiệp. Vì vậy, mỗi dòng danh mục phải lưu được đường dẫn tài liệu, phiên bản, ngày thu thập và người kiểm tra. Nếu thiếu các trường ấy, anh chị đánh dấu chưa đối chiếu, không tự cho điểm tin cậy tối đa."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Đọc theo thời gian và bối cảnh áp dụng", "handwriting": "Không dùng đường cong dự báo doanh số; diễn giải bằng bốn mốc bằng chứng có thể kiểm.", "slideContent": "Sơ đồ: lần đầu giới thiệu -> thử có đối chứng -> ứng dụng trong phạm vi xác định -> vận hành lặp lại.", "lectureScript": "Một công nghệ có thể được bàn luận nhiều trong khi bằng chứng vận hành còn ít. Thay vì đo sự hấp dẫn bằng số lần được nhắc tên, anh chị hãy lập mốc bằng chứng. Đã có nguyên mẫu hay chưa? Thử trên dữ liệu ngoài bộ mẫu phát triển chưa? Có số liệu vận hành trong nhiều ca hay chỉ một lần trình diễn? Có hướng dẫn bảo trì, quyền dữ liệu và hỗ trợ sau thử không? Các câu hỏi ấy giúp xác định điều gì đã biết ở một phạm vi cụ thể. Chúng không cho phép suy ra tốc độ phổ biến của cả thị trường nếu chúng ta chưa có số liệu đại diện."}, {"layout": "L2", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Bẫy trào lưu và hiệu ứng chọn mẫu", "handwriting": "Hiện hai số liệu cùng tử số nhưng mẫu số khác nhau. Đóng khung chữ BẰNG CHỨNG KHÔNG TƯƠNG ĐƯƠNG.", "slideContent": "Ba phép kiểm: có mẫu thất bại? có mẫu số? cùng điều kiện đầu vào? Không dùng lượt xem làm ROI.", "lectureScript": "Giả sử một bản quảng bá cho biết hệ thống nhận đúng chín mươi tám hình ảnh. Nếu không biết tổng số hình và cách chọn mẫu, chúng ta không thể gọi đó là tỷ lệ chính xác chín mươi tám phần trăm. Một phép thử khác có cả trường hợp mã mờ, nhãn lệch và ánh sáng thay đổi sẽ đặt câu hỏi khó hơn. Khi đọc bài báo hay video trình diễn, hãy tìm cả kết quả không đạt, chi phí tích hợp và điều kiện khiến mô hình lỗi. Tập hợp chỉ những ca thành công là thiên lệch chọn mẫu. Còn lượt xem, số bài viết hay lời khen từ người bán là tín hiệu truyền thông, không phải dòng tiền tiết kiệm cho An Bình."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Bước giao bài: nhật ký tín hiệu", "handwriting": "Tích đủ năm thành phần; chuyển sang bốn phương án giả định ở video 32.2.", "slideContent": "Mỗi tín hiệu = Nguồn + nội dung kiểm được + giới hạn + giả thuyết tác động + việc cần xác minh.", "lectureScript": "Kết thúc video đầu, anh chị chưa cần chọn công nghệ. Hãy chọn hai thông tin đang gặp trong công việc và ghi thành nhật ký tín hiệu. Nêu nguồn và ngày công bố, tách phần có thể kiểm chứng với phần nhà cung cấp tự nhận, rồi viết một giả thuyết gắn với công đoạn thực tế. Với An Bình, giả thuyết có thể là giảm bỏ sót mã lô hoặc phát hiện dấu hiệu hỏng thiết bị sớm hơn. Trong video tiếp theo, chúng ta sẽ chuyển nhật ký nguồn thành một bộ lọc, để công nghệ có nhiều tin tức nhưng thiếu dữ liệu vẫn phải chờ kiểm chứng."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('56862947-ed56-5e57-b1b6-e20a3e8fc63b', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 2, 'EL-032-V32.2', 'VIDEO 32.2: ĐỌC BẰNG CHỨNG VÀ SÀNG LỌC PHƯƠNG ÁN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Từ bốn tín hiệu đến bảng sàng lọc", "handwriting": "Bốn thẻ, mỗi thẻ có mục tiêu nội bộ và nhãn GIẢ ĐỊNH, không có tên hãng.", "slideContent": "Giả định bốn ứng viên: OCR xử lý tại máy; trợ lý AI soạn SOP; cảm biến theo dõi bảo trì; mô phỏng số toàn dây chuyền.", "lectureScript": "Bây giờ chúng ta thử sàng lọc bốn hướng công nghệ cho An Bình. Hướng thứ nhất là kiểm mã lô bằng OCR xử lý tại máy, giải bài toán nhãn và kết nối băng tải. Hướng thứ hai là trợ lý AI soạn bản nháp quy trình vận hành chuẩn. Hướng thứ ba dùng cảm biến theo dõi tình trạng máy để hỗ trợ bảo trì. Hướng cuối là mô phỏng số cả dây chuyền. Bốn hướng phục vụ bốn mức bài toán khác nhau, nên không được so bằng danh tiếng công nghệ. Chúng ta sẽ cho điểm ở quy mô nhu cầu giả định, rồi kiểm xem bằng chứng và nguồn lực nào còn thiếu."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Đánh giá nguồn, không chấm độ hào nhoáng", "handwriting": "Hiện hai trạng thái ĐÃ ĐỐI CHIẾU HỒ SƠ SƠ BỘ / CHƯA ĐỐI CHIẾU; chú thích giới hạn.", "slideContent": "Đã đối chiếu = có tài liệu, tác giả, phạm vi và điểm cần hỏi; không có nghĩa công nghệ đã đạt KPI.", "lectureScript": "Ở phiếu thực hành, cột tình trạng bằng chứng có hai lựa chọn: đã kiểm và chưa kiểm. Đã kiểm trong bài chỉ có nghĩa hồ sơ nguồn sơ bộ đã được đối chiếu với xuất xứ, phiên bản và phạm vi. Nó không chứng minh công nghệ đạt tỷ lệ phát hiện lỗi hay sẵn sàng ký hợp đồng. Với OCR, chúng ta giả định có nhật ký lỗi nội bộ và một tài liệu mô tả phép thử. Với trợ lý soạn quy trình, bản trình diễn chưa kèm kiểm tra độ chính xác và quyền sử dụng dữ liệu, nên đánh dấu chưa kiểm. Sự khác biệt về trạng thái này sẽ quyết định liệu một điểm số đẹp có được dùng để đề xuất thử nhỏ hay không."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Bốn tiêu chí có chiều tác động khác nhau", "handwriting": "Viết thang 1-5 và mũi tên đảo chiều rủi ro: 5 rủi ro cao -> 1 điểm tốt.", "slideContent": "35% giá trị vấn đề; 30% khả thi thử; 20% nguồn lực; 15% rủi ro phụ thuộc (đảo chiều).", "lectureScript": "Chúng ta dùng bộ chấm minh họa gồm bốn tiêu chí. Giá trị giải quyết vấn đề chiếm ba mươi lăm phần trăm. Khả thi thử ở quy mô nhỏ chiếm ba mươi phần trăm. Nguồn lực sẵn có chiếm hai mươi phần trăm. Rủi ro phụ thuộc nhà cung cấp chiếm mười lăm phần trăm. Ba cột đầu chấm từ một đến năm, điểm cao là thuận lợi. Cột phụ thuộc thì ngược lại: năm nghĩa là phụ thuộc nhiều, vì thế phải đảo thành sáu trừ điểm rủi ro trước khi nhân trọng số. Nếu quên phép đảo, công nghệ lệ thuộc cao sẽ được thưởng điểm."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Kiểm giả định và dữ liệu đầu vào", "handwriting": "Cho thấy tổng trọng số sai 110% và ô điểm trống làm cảnh báo chưa hợp lệ.", "slideContent": "Mỗi 1-5 phải có lý do; trọng số tổng 100%; thiếu bằng chứng -> không đủ quyền kết luận.", "lectureScript": "Một ma trận không đáng tin chỉ vì nó có công thức. Khi nhập điểm phù hợp năm, người chấm phải nêu vấn đề nào được giải quyết và vì sao. Điểm khả thi thử bốn cần đi cùng phạm vi thử, thời hạn và vật tư. Cuối cùng, các trọng số phải cộng thành một trăm phần trăm. Excel được thiết kế để cảnh báo nếu thiếu điểm, điểm ngoài thang hoặc tổng trọng số sai. Nhưng ngay cả khi mọi ô đều hợp lệ, kết quả vẫn là đánh giá chuyên gia sơ bộ. Doanh nghiệp cần so sánh mức độ nhạy của kết quả với thay đổi trọng số, rồi kiểm chứng bằng thử nghiệm có phạm vi."}, {"layout": "L2", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Điều kiện loại trừ trước khi xếp ưu tiên", "handwriting": "Tô vàng trạng thái chưa đối chiếu; hiện trường hợp B điểm khá nhưng vẫn giữ lại.", "slideContent": "Cổng: nguồn đã đối chiếu; giá trị vấn đề >=3; phụ thuộc <=3; điểm >=3,60. Không tự phê duyệt.", "lectureScript": "Chấm điểm chưa phải bước cuối. Trong ví dụ, ứng viên thử nhỏ phải có nguồn sơ bộ đã đối chiếu, điểm giá trị vấn đề không dưới ba, mức phụ thuộc không quá ba và điểm có trọng số từ ba phẩy sáu trở lên. Đây là ngưỡng giả định để luyện cách ra quyết định, không phải ngưỡng pháp lý. Trợ lý AI có thể nhận điểm tổng khá, nhưng nếu chưa kiểm quyền dữ liệu và kết quả thử, nó không được vượt cổng. Kết luận đúng phải kèm hồ sơ cần bổ sung, người chịu trách nhiệm và câu hỏi muốn được trả lời."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Bản phân loại đưa sang video thực hành", "handwriting": "Hiện thứ tự ưu tiên việc cần làm chứ không vẽ bảng xếp hạng thị trường.", "slideContent": "Bốn nhãn: ứng viên thử nhỏ; theo dõi; chưa kiểm nguồn; chưa đủ điều kiện.", "lectureScript": "Sau video thứ hai, anh chị có bộ lọc với hai tầng. Tầng bằng chứng và điều kiện giữ lại những phương án chưa thể đề xuất hành động. Đừng đổi chữ theo dõi thành bỏ hẳn: nhiều công nghệ có thể cần dữ liệu, nguồn lực hoặc thời điểm khác. Cũng đừng gọi ứng viên thử nhỏ là giải pháp được phê duyệt. Ở video cuối, chúng ta đọc trực tiếp bốn dòng của phiếu, thử thay điểm và trọng số, sau đó viết kế hoạch xác minh có người phụ trách. Đầu ra của bài là một quyết định có điều kiện, có thể kiểm tra lại khi nguồn thông tin thay đổi."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('633a0d44-2089-58a6-a829-294425629d02', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 3, 'EL-032-V32.3', 'VIDEO 32.3: MA TRẬN, ĐỘ NHẠY VÀ PHÉP THỬ CÓ ĐIỀU KIỆN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đọc ma trận trên tình huống An Bình", "handwriting": "Zoom sheet Phiếu thực hành vùng B7:H13 rồi xuống B16:H20.", "slideContent": "Hồ sơ giả định: A OCR tại máy, B trợ lý SOP, C cảm biến bảo trì, D mô phỏng số. Không suy ra xếp hạng thị trường.", "lectureScript": "Đây là ma trận minh họa trên sheet Phiếu thực hành. Chúng ta chỉ hỏi phương án nào nên được xác minh trước trong bối cảnh An Bình hiện muốn giảm lỗi mã lô và có đội ngũ vận hành nhỏ. Trước khi đọc thứ tự, kiểm tổng trọng số bằng một trăm phần trăm, kiểm chiều của rủi ro phụ thuộc và nhìn trạng thái nguồn. Khi thiếu một điều kiện, bảng phải cảnh báo, thay vì âm thầm xếp hạng để người học hiểu nhầm là đã đủ hồ sơ đầu tư."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-2", "sceneName": "Tính ví dụ OCR ở máy: 4,35 trên 5", "handwriting": "Viết từng hạng và kết quả, nhấn điểm rủi ro đã đảo chiều.", "slideContent": "A: 5 x 35% + 4 x 30% + 4 x 20% + (6 - 2) x 15% = 4,35.", "lectureScript": "Với OCR xử lý tại máy, chúng ta giả định giá trị vấn đề là năm, khả thi thử là bốn, nguồn lực là bốn và mức phụ thuộc là hai. Điểm có trọng số bằng năm nhân ba mươi lăm phần trăm, cộng bốn nhân ba mươi phần trăm, cộng bốn nhân hai mươi phần trăm, cộng với sáu trừ hai rồi nhân mười lăm phần trăm. Kết quả là bốn phẩy ba lăm trên năm. Nhãn đó chỉ có nghĩa đáng thiết kế phép thử có kiểm soát; chưa xác nhận được hiệu quả kỹ thuật, chi phí sở hữu hoặc quyền sử dụng."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-3", "sceneName": "Ba phương án còn lại và bẫy điểm số", "handwriting": "Hiện bốn dòng kết quả; không biến thứ tự ma trận thành biểu đồ xu hướng thị trường.", "slideContent": "B: 3,65 nhưng CHƯA KIỂM NGUỒN; C: 3,35 nên theo dõi; D: 1,35 và chưa kiểm.", "lectureScript": "Hãy nhìn ba dòng còn lại. Trợ lý AI soạn quy trình có điểm ba phẩy sáu lăm, nhỉnh hơn ngưỡng số học, nhưng nguồn chưa được đối chiếu nên chưa thể thành ứng viên thử nhỏ. Cảm biến bảo trì đạt ba phẩy ba lăm, dưới ngưỡng đề xuất; cách xử lý là theo dõi và tìm thêm dữ liệu về hỏng máy, không tự kết luận giải pháp kém. Mô phỏng số toàn dây chuyền có một phẩy ba lăm trong bối cảnh nguồn lực giả định hiện nay và cũng chưa kiểm nguồn."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thử độ nhạy thay vì tin một thứ hạng", "handwriting": "Thao tác đổi E12:H12 và quan sát ô C12, C17:C20. Hoàn tác về 35-30-20-15.", "slideContent": "Đổi trọng số phải bảo toàn 100%; thử ưu tiên nguồn lực/khả thi rồi so trạng thái.", "lectureScript": "Có một cách đơn giản để kiểm tra độ mong manh của ma trận: thay trọng số trong phạm vi hợp lý nhưng giữ tổng bằng một trăm phần trăm. Nếu một thay đổi nhỏ làm thứ tự đảo ngược, phải ghi rằng kết quả nhạy với giả định. Nhưng thay trọng số không được phép đổi trạng thái chưa kiểm nguồn thành đã kiểm. Excel sẽ cảnh báo khi tổng trọng số lệch; sau khi trình diễn, đưa các giá trị về bộ mặc định."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Thiết kế phép thử nhỏ cho ứng viên phù hợp", "handwriting": "Một trang brief thử OCR trong điều kiện nhãn mờ, nhãn lệch và đổi ca; mục tiêu/ngưỡng chỉ là đề xuất.", "slideContent": "Nhiệm vụ, dữ liệu đầu vào, mẫu tốt/mẫu lỗi, KPI, nguồn lực, ngân sách, rủi ro và cổng dừng.", "lectureScript": "Bản brief phải viết rõ một công đoạn được thử, thời hạn, người vận hành và dữ liệu nhãn có thể dùng hợp pháp. Cần có mẫu tốt và mẫu lỗi từ nhiều ca, bao gồm mã mờ, nhãn lệch và điều kiện ánh sáng khác nhau. Chốt trước cách đếm bỏ sót, loại nhầm, thời gian dừng và người xác nhận kết quả. Cũng cần dự toán chi phí thử, kế hoạch bảo mật, phương án quay lui khi có sự cố. Chỉ sau khi đủ cổng an toàn và quyền dữ liệu, nhóm mới trình đề xuất thử cho cấp có thẩm quyền."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Năm điều kiện phải có người nhận việc", "handwriting": "Điền trạng thái Đã kiểm/Chưa kiểm và Đã giao/Chưa giao tại hàng 25-29.", "slideContent": "1. KPI và nhu cầu; 2. nguồn/mẫu đối chứng; 3. tích hợp; 4. quyền dữ liệu; 5. thiết kế thử và đường lui.", "lectureScript": "Một là nhu cầu và chỉ số nền của doanh nghiệp. Hai là nguồn kỹ thuật, bộ mẫu và cách thử độc lập. Ba là khả năng tích hợp với dây chuyền thực. Bốn là quyền sử dụng dữ liệu và điều khoản nhà cung cấp. Năm là phạm vi thử, người chịu trách nhiệm, chi phí và phương án dừng. Anh chị phải điền cả trạng thái kiểm tra lẫn việc đã giao người phụ trách. Nếu còn một cổng chưa kiểm, bảng báo cần bổ sung chứng cứ, dù OCR có điểm bốn phẩy ba lăm."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Kết bài: quyết định có điều kiện, không dự báo", "handwriting": "Chốt bằng ảnh phiếu thực hành, liên kết tới Bài 33 về lựa chọn bài toán AI dựa trên dữ liệu.", "slideContent": "Đầu ra: nhật ký 2 nguồn; ma trận 4 ứng viên; 5 cổng; 1 brief thử và danh mục theo dõi.", "lectureScript": "Kết thúc Bài 32, anh chị cần có một nhật ký nguồn, một bảng sàng lọc và một đề xuất kiểm chứng nhỏ. Với ví dụ An Bình, OCR là ứng viên đáng thiết kế thử trước, nhưng cổng hồ sơ vẫn chưa đủ để triển khai. Trợ lý AI chưa có nguồn được đối chiếu, còn các lựa chọn khác nên được theo dõi theo nhu cầu. Khi có dữ liệu mới, hãy cập nhật điểm và lưu phiên bản cũ để giải thích vì sao quyết định thay đổi."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('8e4a2cd9-d62f-56c0-b2ae-d36e5ddd55db', '6721da87-6494-5fd4-9cc7-6163a275f01a', 1, 'EL-033-V33.1', 'VIDEO 33.1: TỪ VẤN ĐỀ KINH DOANH ĐẾN GIẢ THUYẾT CẦN AI', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Từ đề nghị AI đến bài toán thực", "handwriting": "Mở bằng câu đề nghị “Lắp AI ngay”, rồi thay bằng sơ đồ quy trình đóng gói An Bình giả định.", "slideContent": "Slide: Bắt đầu từ lỗi, không từ thuật toán. Dòng 1: Vấn đề? Dòng 2: Ai bị ảnh hưởng? Dòng 3: Chỉ số nền?", "lectureScript": "Ở An Bình, quản lý phân xưởng nhận một đề nghị: lắp trí tuệ nhân tạo để giảm lỗi nhãn và mã lô. Nếu chúng ta mở đầu bằng câu hỏi nên mua hệ thống AI nào, rất dễ bỏ qua công đoạn đang gây thiệt hại. Tôi muốn anh chị đi theo trình tự ngược lại. Trước tiên, mô tả một vấn đề có thể quan sát: túi đi qua khâu kiểm mã, một số mã bị nhòe hoặc sai. Tiếp theo, xác định tỷ lệ lỗi lọt và chi phí xử lý lại. Những con số trong bài chỉ là giả định giảng dạy, không phải báo cáo thật của doanh nghiệp."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "AI khác quy tắc ở đâu?", "handwriting": "Vẽ nhánh: nếu điều kiện rõ và ổn định -> thử quy tắc trước; nếu nhiều biến thể -> khảo sát AI.", "slideContent": "Bảng 3 cột: Quy tắc cố định | Tự động hóa thông thường | AI học từ dữ liệu. Ví dụ mã QR kiểm định dạng.", "lectureScript": "Không phải nhiệm vụ nào cũng cần mô hình học máy. Nếu mã lô phải có mười hai ký tự và luôn theo một định dạng, bước kiểm tra chiều dài hoặc cấu trúc có thể dùng quy tắc lập trình. Khi ảnh bị thay đổi bởi ánh sáng, góc chụp và vật liệu, kỹ thuật nhận dạng dựa trên dữ liệu mới có thể đáng thử. Cụm từ có thể đáng thử rất quan trọng: một giải pháp OCR cũng có thể hoạt động tốt mà không cần huấn luyện mô hình riêng. Hãy lập phương án đơn giản nhất làm đối chứng. Chỉ gọi AI là cần thiết khi có lý do kiểm chứng được rằng quy tắc thông thường không đáp ứng đủ mục tiêu."}, {"layout": "L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Viết một câu bài toán đo được", "handwriting": "Gõ câu mẫu từng thành phần, tô vàng ô mẫu số và người xác nhận.", "slideContent": "Mẫu: Tại [công đoạn], giảm [lỗi/độ trễ] từ [nền] xuống [mục tiêu], trên [mẫu], trong [thời gian].", "lectureScript": "Một câu bài toán tốt không chứa lời hứa chung như nâng cao hiệu quả nhờ AI. Chẳng hạn, trong ví dụ An Bình, mục tiêu cần được phê duyệt có thể là giảm tỷ lệ lỗi mã lô lọt qua khâu kiểm sau đóng gói trong bốn tuần thử. Người phụ trách chất lượng phải xác nhận thế nào là lỗi, cách lấy mẫu và tỷ lệ nền trước khi thử. Nếu ta chưa biết tổng số túi được kiểm hoặc chưa thống nhất định nghĩa lỗi, mọi phần trăm sẽ thiếu căn cứ. Nhớ đưa cả mẫu số vào câu; đây là cách để các bên không thay cách đếm giữa lúc thí điểm."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Từ quy trình đến dữ liệu tối thiểu", "handwriting": "Từng bước xuất hiện, đánh dấu nơi thiếu dữ liệu và nơi cần người xác nhận.", "slideContent": "Sơ đồ dòng dữ liệu: phát sinh -> ghi nhận -> làm sạch -> gán nhãn -> kiểm chứng -> ra quyết định.", "lectureScript": "Sau khi có câu bài toán, hãy đi ngược theo đường đi của dữ liệu. Ảnh do camera nào tạo ra, ca nào, điều kiện sáng ra sao? Mã lô chuẩn được lấy ở đâu? Ai quyết định một ảnh là lỗi thật? Nếu các nhãn được ghi bởi hai người nhưng không có cách xử lý khi bất đồng, ta có thể huấn luyện mô hình theo một tiêu chuẩn không nhất quán. Không có bộ dữ liệu chung nào dùng được cho mọi bài toán AI. Chỉ sau khi hiểu quá trình tạo dữ liệu, anh chị mới có thể nói dữ liệu hiện có có đủ phù hợp để bắt đầu hay không."}, {"layout": "L2 + L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Đặt đường cơ sở và chi phí sai", "handwriting": "Hiện hai phân số với cùng tử số nhưng mẫu số khác; khóa nhãn GIẢ ĐỊNH.", "slideContent": "Thẻ KPI: lỗi lọt / tổng kiểm; loại nhầm / mẫu tốt; giờ xử lý lại; chi phí một lỗi.", "lectureScript": "Cùng một hệ thống nhận dạng có thể phát hiện nhiều lỗi hơn nhưng cũng loại nhầm nhiều túi tốt. Vì thế tôi không khuyến nghị dùng tỷ lệ chính xác chung làm chỉ số duy nhất. Với công đoạn kiểm mã, chúng ta cần ít nhất số lỗi lọt, số hàng tốt bị loại và thời gian xử lý lại. Một giải pháp giảm lỗi lọt nhưng khiến nhân viên phải kiểm lại quá nhiều có thể không tạo giá trị ròng. Bên cạnh đó, cần ghi phương án đang dùng: kiểm thủ công, mã vạch hay quy tắc có sẵn. Khi so sánh, cả hai phương án phải xử lý mẫu tương đương. Đây cũng là lý do phải chốt chỉ số nền trước khi xem kết quả trình diễn."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Đầu ra video 1: quyết định câu hỏi", "handwriting": "Gạch chân “giả thuyết cần thử”; chuyển sang bốn tình huống ở video 2.", "slideContent": "Mẫu một trang: vấn đề | chủ quy trình | baseline | phương án không AI | giả thuyết AI | dữ liệu cần.", "lectureScript": "Bài thực hành đầu tiên không yêu cầu anh chị chọn nền tảng hay nhà cung cấp. Hãy hoàn thiện một trang gồm sáu trường: vấn đề đang ảnh hưởng đến ai; chỉ số nền; ai chịu trách nhiệm về quy trình; giải pháp không dùng AI đang có; giả thuyết AI có thể giúp gì; và những dữ liệu nào cần kiểm. Nếu chưa thể viết chỉ số nền, hãy tạm dừng việc chấm công nghệ để bổ sung phép đo. Nếu phương án quy tắc đủ đáp ứng mục tiêu với chi phí thấp, kết luận hợp lý có thể là chưa dùng AI. Đó là cách tránh tiêu tiền để giải một việc mà doanh nghiệp đã có phương án đơn giản hơn."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('eba7b402-b6fd-5e5d-843d-5cd20d9caf11', '6721da87-6494-5fd4-9cc7-6163a275f01a', 2, 'EL-033-V33.2', 'VIDEO 33.2: DỮ LIỆU VÀ SÀNG LỌC BÀI TOÁN AI', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Bốn bài toán, không phải bốn sản phẩm", "handwriting": "Hiện bốn thẻ cạnh cùng câu hỏi “Giải quyết lỗi hoặc chậm trễ nào?”.", "slideContent": "Bốn thẻ: A kiểm mã lô; B dự báo thiếu vật tư; C tra cứu SOP; D dự báo hỏng băng tải.", "lectureScript": "Trong video này, tôi dùng bốn bài toán giả định tại An Bình. A là nhận diện nhãn và mã lô không đạt. B là dự báo nguy cơ thiếu vật tư bao bì theo tuần. C là tìm đúng nội dung trong quy trình thao tác chuẩn, gọi tắt là SOP, để nhân viên tra cứu nhanh. D là dự báo băng tải có thể hỏng trước khi phải dừng máy. Những bài toán này có mẫu dữ liệu, người phụ trách và mức độ rủi ro khác nhau. Đặc biệt, bài toán A từng được dùng ở các bài thí điểm trước với kết quả giả định còn phải khắc phục. Ở đây chúng ta chỉ tập sàng lọc nhu cầu, không tuyên bố đã triển khai thành công."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Đánh giá dữ liệu dùng được", "handwriting": "Tô đậm các tiêu chí “đầy đủ, đúng, liên quan và được phép”.", "slideContent": "Định nghĩa: số bản ghi dùng được / tổng bản ghi được xét. Điều kiện: đúng phiên bản, có nhãn, có quyền.", "lectureScript": "Dữ liệu sẵn có khác dữ liệu có thể dùng. Một nghìn ảnh lưu trên ổ cứng chưa chắc tạo thành một nghìn mẫu huấn luyện hoặc kiểm thử. Trong phiếu, một bản ghi chỉ được tính là dùng được khi có định dạng phù hợp, nhãn đã đối chiếu và quyền sử dụng được xác nhận trong phạm vi công việc. Với dữ liệu dự báo, ta còn cần kiểm tra có đủ các kỳ và các biến thể mùa vụ hay không. Với trợ lý SOP, cần biết phiên bản tài liệu đang hiệu lực. Vì vậy, người phụ trách dữ liệu phải ghi rõ quy tắc loại mẫu và cách xử lý những mẫu có tranh chấp."}, {"layout": "L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Tính 850 chia 1.000", "handwriting": "Tính từng phép chia. Cảnh báo tỷ lệ cao chưa chứng minh dữ liệu đại diện.", "slideContent": "Bảng đếm: A 1.000/850; B 52/31; C 120/110; D 30/12. Đọc: 85%, 59,6%, 91,7%, 40%.", "lectureScript": "Hãy nhìn bốn con số trong phiếu. Bài toán A có một nghìn hồ sơ giả định, trong đó tám trăm năm mươi hồ sơ dùng được. Tỷ lệ sẵn sàng sơ bộ là tám mươi lăm phần trăm. B có ba mươi mốt trên năm mươi hai kỳ, xấp xỉ năm mươi chín phẩy sáu phần trăm. C có một trăm mười trên một trăm hai mươi tài liệu, còn D chỉ có mười hai trên ba mươi sự cố được ghi đủ trường. Mười hai sự cố có thể quá ít để xây mô hình dự báo, và năm mươi hai tuần chưa chắc phản ánh đầy đủ mùa vụ. Tỷ lệ này chỉ dùng để sàng lọc dữ liệu, không chứng minh mô hình sẽ dự báo đúng."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Quyền dữ liệu, nhãn và sai lệch", "handwriting": "Dùng biểu tượng khóa và ba loại ca vận hành; để trạng thái quyền dữ liệu “Chưa kiểm”.", "slideContent": "Ba lớp kiểm: quyền dùng dữ liệu | nhãn có thống nhất | mẫu đại diện cho ca, máy, sản phẩm.", "lectureScript": "Có dữ liệu về kỹ thuật vẫn chưa đủ quyền để đưa dữ liệu vào mô hình. Hình ảnh sản xuất có thể chứa thông tin của khách hàng hoặc công thức sản phẩm. Tài liệu SOP có thể có quy trình nội bộ không được gửi tới dịch vụ bên ngoài. Người quản lý cần xác nhận mục đích sử dụng, ai có quyền truy cập, nơi lưu và cách xóa sau thử. Ngay khi quyền hợp lệ, ta vẫn phải xem dữ liệu có lệch về một máy hoặc một ca không. Nếu chỉ lấy mẫu ca sáng, mô hình có thể không phản ánh ca đêm. Chúng không thay thế được nhau."}, {"layout": "L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Mức cần AI và khả năng kiểm soát", "handwriting": "Cho ví dụ C tra SOP chỉ tra từ khóa; D dự báo hỏng cần nhiều biến cố hiếm.", "slideContent": "Thang 1-5 cho tác động và mức cần AI. Điểm 1: quy tắc đơn giản; điểm 5: nhiều biến thể cần thử nghiệm.", "lectureScript": "Bài toán có giá trị lớn chưa chắc cần AI mạnh. Trong phiếu, tác động kinh doanh được chấm một đến năm dựa trên chi phí vấn đề và ưu tiên quy trình. Mức cần AI cũng từ một đến năm: điểm thấp khi quy tắc đơn giản có thể giải quyết; điểm cao khi nhiều biến thể khiến cách xử lý cố định khó đạt mục tiêu. Ví dụ một hệ thống tìm kiếm theo từ khóa có thể giúp tra cứu SOP trước khi chúng ta cân nhắc trợ lý tạo sinh. Ngược lại, dữ liệu bảo trì còn rất ít thì dù tác động dừng máy cao, chưa nên hứa có mô hình dự báo hỏng đáng tin cậy."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Loại khỏi thử nhỏ không có nghĩa phủ định ý tưởng", "handwriting": "Ba nhãn: ứng viên thử nhỏ; bổ sung dữ liệu; đánh giá cách không AI.", "slideContent": "Ngưỡng minh họa: dữ liệu >= 75%, tác động >= 4, mức cần AI >= 3, điểm >= 4.", "lectureScript": "Chúng ta cần một cách chốt danh sách làm việc. Với bộ ngưỡng học tập, ứng viên thử nhỏ phải đạt tỷ lệ dữ liệu dùng được tối thiểu bảy mươi lăm phần trăm, tác động từ bốn điểm, mức cần AI từ ba điểm và điểm tổng ít nhất bốn. Các ngưỡng này được đặt để luyện thao tác sàng lọc, không phải chuẩn công nghiệp. A tạm qua bộ lọc; D có tác động cao nhưng tỷ lệ hồ sơ dùng được thấp, nên cần bổ sung dữ liệu. B chưa đủ tỷ lệ theo ngưỡng, còn C cần so sánh nghiêm túc với giải pháp tra cứu thông thường. Nó chỉ cho biết việc gì cần làm trước."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('33ff86de-e53d-557b-b1b9-eb66e01e1d6c', '6721da87-6494-5fd4-9cc7-6163a275f01a', 3, 'EL-033-V33.3', 'VIDEO 33.3: MA TRẬN VÀ KẾ HOẠCH THỬ NHỎ CÓ ĐIỀU KIỆN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L3", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đọc ma trận ba thành phần", "handwriting": "Hiện mẫu công thức trong Excel; nhấn điều kiện dữ liệu và thang 1-5.", "slideContent": "Điểm = 45% tác động + 30% (5 x dữ liệu dùng được / tổng) + 25% mức cần AI.", "lectureScript": "Từ cột D và E, Excel tính tỷ lệ hồ sơ dùng được. Tiếp đó, điểm sơ bộ được tính từ ba thành phần cùng quy về thang năm: bốn mươi lăm phần trăm tác động kinh doanh, ba mươi phần trăm mức sẵn sàng dữ liệu và hai mươi lăm phần trăm mức cần AI. Chúng ta phải kiểm tổng trọng số bằng một trăm phần trăm. Cách chấm này là mô hình minh họa do bài học xây dựng, không phải một công thức tiêu chuẩn áp dụng cho mọi doanh nghiệp. Điểm là công cụ tạo thảo luận và phát hiện giả định còn thiếu, không đo xác suất thành công của dự án."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Giải tính điểm bài toán A", "handwriting": "Viết lần lượt 2,25 + 1,275 + 1,00 = 4,525; làm tròn Excel thành 4,53.", "slideContent": "Dòng A: tác động 5; dữ liệu 850/1000; mức cần AI 4. Kết quả 4,53/5.", "lectureScript": "Với A, tác động kinh doanh được giả định là năm điểm. Tỷ lệ hồ sơ dùng được là không phẩy tám mươi lăm, quy về thang năm thành bốn phẩy hai mươi lăm. Mức cần AI là bốn. Lấy năm nhân không phẩy bốn mươi lăm, cộng bốn phẩy hai mươi lăm nhân không phẩy ba mươi, cộng bốn nhân không phẩy hai mươi lăm, ta được bốn phẩy năm hai năm. Excel hiển thị làm tròn thành bốn phẩy năm ba. Nhưng đó chưa phải quyết định mua hay thử. Thử thay trọng số để xem vị trí A thay đổi thế nào."}, {"layout": "L2", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Cổng không được bù bằng điểm", "handwriting": "Tô cam cổng 3 “Chưa kiểm”, dù A đạt 4,53.", "slideContent": "Năm cổng: KPI nền; bộ dữ liệu/nhãn; quyền dữ liệu; đối chứng không AI; brief thử an toàn.", "lectureScript": "Trong phiếu, chúng ta có năm cổng cần đủ hồ sơ trước thử nhỏ. Một là đường cơ sở và chi phí vấn đề; hai là bộ dữ liệu với nhãn được xác nhận; ba là quyền dữ liệu và bảo mật; bốn là phương án không AI để so sánh; năm là brief thử có người duyệt và tiêu chí dừng. Tôi chủ động để cổng quyền dữ liệu ở trạng thái chưa kiểm. Do vậy, dù A là ứng viên có điểm cao, dòng trạng thái tổng vẫn ghi chưa mở thử. Không thể lấy điểm tác động cao để bù cho việc chưa có quyền sử dụng dữ liệu."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thiết kế phép thử đối chứng nhỏ", "handwriting": "Sơ đồ hai luồng: cách hiện tại/không AI và phương án thử AI, cùng mẫu tương đương.", "slideContent": "Brief: phạm vi 2 ca; mẫu nhãn tốt/lỗi; baseline quy tắc; chỉ số lỗi lọt, loại nhầm, giờ xử lý.", "lectureScript": "Một brief thử nhỏ phải trả lời được phương án AI có tốt hơn cách đang làm không. Với A, hãy chọn mẫu có mã đúng, mã mờ, mã sai và điều kiện sáng khác nhau. Bộ mẫu cần được gán nhãn độc lập trước khi xem đầu ra mô hình. Chạy song song phương án kiểm hiện tại hoặc OCR theo quy tắc, với cùng tiêu chuẩn đo. Theo dõi tỷ lệ lỗi lọt, tỷ lệ loại nhầm, thời gian xử lý lại và sự cố tích hợp. Nếu đã dùng mẫu để điều chỉnh mô hình, không dùng lại nguyên mẫu đó để tuyên bố kiểm chứng độc lập. Đây là những điều kiện kỹ thuật có thể kiểm."}, {"layout": "L2 + L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Bộ kiểm độc lập và phiên bản mô hình", "handwriting": "Tách ba khối bộ mẫu; gắn nhãn KHÔNG DÙNG LẠI ĐỂ TỐI ƯU trên khối đánh giá.", "slideContent": "Chia dữ liệu theo mục đích: xây dựng, điều chỉnh, đánh giá độc lập; nhật ký phiên bản và người duyệt nhãn.", "lectureScript": "Điều cuối cần thống nhất về dữ liệu thử là bộ đánh giá độc lập. Nếu một ảnh đã được dùng để chọn ngưỡng hoặc điều chỉnh mô hình, kết quả trên ảnh ấy không còn là phép kiểm độc lập. Hãy lưu một nhóm mẫu riêng, có đủ loại lỗi và điều kiện ca vận hành, chỉ dùng khi đánh giá cuối. Mỗi lượt thử phải ghi phiên bản mô hình, phiên bản nhãn và người phê duyệt. Việc kiểm chứng cần cho phép người khác tái hiện cùng cách đếm trên cùng phạm vi, kể cả khi kết quả thấp hơn kỳ vọng."}, {"layout": "L2", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Kiểm soát rủi ro và điểm dừng", "handwriting": "Hiện cổng ĐƯỢC PHÉP THỬ? rồi mới đưa sang bảng KPI; mũi tên DỪNG khi vi phạm.", "slideContent": "Checklist: không phát tán dữ liệu; người duyệt; chi phí tối đa; KPI tối thiểu; dừng khi vi phạm.", "lectureScript": "Trước khi chạy thử, người chịu trách nhiệm phải xác định nơi dữ liệu được xử lý và lưu, quyền truy cập của nhà cung cấp, cách hủy dữ liệu và nhật ký thay đổi. Bài thử cần trần thời gian, trần ngân sách và một người có thẩm quyền xác nhận kết quả. Nếu có vấn đề an toàn hoặc lộ dữ liệu, phải có khả năng dừng mà không làm gián đoạn sản xuất. Tất cả điều kiện tiếp tục hay dừng phải được thống nhất trước khi thu kết quả để tránh chọn ngưỡng theo kết quả đẹp nhất."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Bài nộp: chọn vấn đề và nêu phần chưa biết", "handwriting": "Đánh dấu các trường chưa có bằng chứng. Chuyển học viên sang bài trắc nghiệm và tự chấm.", "slideContent": "Mẫu bài nộp: một câu vấn đề; data audit; ma trận; đối chứng; năm cổng; brief thử và người chịu trách nhiệm.", "lectureScript": "Kết thúc bài này, tôi đề nghị anh chị nộp một trang thể hiện rõ quyết định ở mức nào. Nêu một vấn đề có chỉ số nền, liệt kê dữ liệu và quyền sử dụng, tính tỷ lệ hồ sơ dùng được, so sánh với giải pháp không AI và chấm theo thang đã ghi. Sau đó, viết điều kiện để một ứng viên được phép bước vào thử nhỏ. Nếu thiếu cổng dữ liệu hoặc chưa đủ mẫu, ghi đúng là cần bổ sung, không đổi thành đã đạt. Nếu giải pháp quy tắc đủ tốt, hãy đề xuất dùng giải pháp ấy trước."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('054d4960-8cee-5fbc-85c9-3ddc72f969e8', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 1, 'EL-034-V1', 'Phần 1: Giới thiệu và Nguyên lý cốt lõi', 240, NULL, NULL, NULL, '[{"layout": "Đồ họa hoạt hình", "popupQuiz": "Q1", "sceneCode": "V1-1", "sceneName": "Mở đầu", "handwriting": "", "slideContent": "Khái niệm và định nghĩa", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('96eb7202-79c5-58d3-9805-53aa92ddac22', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 2, 'EL-034-V2', 'Phần 2: Phương pháp triển khai và Phân tích', 240, NULL, NULL, NULL, '[{"layout": "Slide tương tác", "popupQuiz": "Q2", "sceneCode": "V2-1", "sceneName": "Nội dung chính", "handwriting": "", "slideContent": "Các bước triển khai", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('db122da2-8b64-591b-bec5-099093986003', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 3, 'EL-034-V3', 'Phần 3: Bài học thực tiễn và Hành động', 240, NULL, NULL, NULL, '[{"layout": "Infographic tổng kết", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Tóm tắt", "handwriting": "", "slideContent": "3 điểm cần nhớ và hành động", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('ee0e2d07-4c5f-544c-88ed-66a4fff657d7', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 1, 'EL-035-V35.1', 'VIDEO 35.1: TỪ QUY TRÌNH ĐẾN BẢN ĐỒ NĂNG LỰC CÔNG NGHỆ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Bản đồ không phải danh sách thiết bị", "handwriting": "Cho xuất hiện danh sách máy rời rạc rồi nối chúng thành luồng vận hành.", "slideContent": "Hai hình: Danh mục mua sắm | Bản đồ công đoạn - năng lực - dữ liệu - kết quả.", "lectureScript": "Khi nghe yêu cầu xây dựng bản đồ công nghệ, nhiều doanh nghiệp bắt đầu bằng việc liệt kê máy móc và phần mềm đang sở hữu. Danh sách đó cần thiết nhưng chưa thành bản đồ. Một bản đồ hữu ích phải trả lời công nghệ đang hỗ trợ bước nào của quy trình, năng lực thực hiện hiện nay đến đâu và cần tiến tới mức nào. Trong bài này, chúng ta dùng cơ sở đóng gói cà phê An Bình làm tình huống giả định. Thay vì hỏi mua camera nào, nhóm quản lý sẽ nhìn cả dòng công việc, từ vật tư, đóng gói, kiểm nhãn đến truy vết. Mọi điểm số trong video là ví dụ học tập, không phải đánh giá doanh nghiệp ngoài đời."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Chọn ranh giới bản đồ", "handwriting": "Từng công đoạn hiện lần lượt, tô khung người chịu trách nhiệm và chỉ số đầu ra.", "slideContent": "Bản đồ 4 công đoạn: nhập vật tư -> đóng gói -> kiểm mã lô -> ghi nhận sự cố và truy vết.", "lectureScript": "Trước khi chấm điểm, hãy chốt ranh giới: bản đồ dành cho một dây chuyền, một nhà máy hay toàn doanh nghiệp? Nếu trộn cấp nhà máy với một máy riêng lẻ, điểm sẽ không so sánh được. Ở ví dụ này ta chọn một dây chuyền đóng gói. Đầu vào là vật tư và lệnh sản xuất; đầu ra là túi đạt, mã lô hợp lệ và dữ liệu về sự cố. Mỗi mắt xích có một người xác nhận: kho, sản xuất, chất lượng và bảo trì. Khi ranh giới rõ, chúng ta dễ thấy công nghệ nào là công cụ trực tiếp, công nghệ nào là hạ tầng dữ liệu chung. Đừng quên ghi phiên bản và ngày lập bản đồ để biết khi nào cần cập nhật."}, {"layout": "L2", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Đặt lớp công nghệ lên công đoạn", "handwriting": "Lần lượt nối camera, bảng tính, cảm biến và tài liệu SOP vào công đoạn phù hợp.", "slideContent": "Bảng 4 hàng: công đoạn | công cụ hiện có | KPI nền | chủ quy trình.", "lectureScript": "Lớp thứ hai của bản đồ là công nghệ và dữ liệu hiện có. Ví dụ, công đoạn kiểm nhãn có camera hoặc thao tác kiểm thủ công; kho có bảng theo dõi vật tư; bảo trì có sổ ghi giờ dừng; nhân viên tra cứu quy trình bằng tài liệu. Cần phân biệt có công cụ với sử dụng công cụ có hiệu quả. Một máy được lắp nhưng không xuất được dữ liệu đáng tin có thể không đáp ứng mục tiêu truy vết. Vì vậy, bên cạnh tên công nghệ, hãy ghi KPI và bằng chứng, chẳng hạn tỷ lệ lỗi lọt, tỷ lệ ghi đủ sự cố, hay thời gian tìm được phiên bản SOP đúng. Nếu chưa đo, đánh dấu chưa có số liệu, không tự đặt điểm cao."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Thang năng lực hiện trạng và mục tiêu", "handwriting": "Chiếu hai thanh cùng thang; giải thích đây là quy ước sư phạm, không phải chuẩn quốc gia.", "slideContent": "Thang 1-5: 1 thủ công/thiếu dữ liệu; 2 ghi chép rời; 3 quy trình ổn định; 4 đo và tích hợp; 5 quản trị theo dữ liệu được kiểm.", "lectureScript": "Để so sánh khoảng trống, nhóm phải dùng cùng một thang đo. Trong bài tập, mức một biểu thị hoạt động còn thủ công và thiếu hồ sơ. Mức hai là có ghi nhận nhưng rời rạc. Mức ba có quy trình lặp lại được. Mức bốn có dữ liệu được đo và kết nối với quy trình. Mức năm có khả năng theo dõi và kiểm soát dựa trên dữ liệu đã được xác nhận. Đây là thang quy ước cho lớp, không phải tiêu chuẩn chứng nhận. Trước khi cho điểm, nhóm phải đưa ra ví dụ bằng chứng tương ứng với mỗi mức. Mục tiêu cũng phải có thời hạn và người chịu trách nhiệm, không đơn thuần ghi mức năm cho mọi công đoạn."}, {"layout": "L2 + L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Khoảng trống không đồng nghĩa ưu tiên", "handwriting": "So sánh hai thẻ có cùng khoảng trống nhưng tác động và sẵn sàng khác nhau.", "slideContent": "Công thức: khoảng trống = MAX(mục tiêu - hiện trạng, 0). Minh họa 1 -> 4 = 3.", "lectureScript": "Khoảng trống năng lực là chênh lệch giữa mức mục tiêu và mức hiện tại. Nếu sổ dừng máy mới ở mức một còn mục tiêu là bốn, khoảng trống bằng ba. Nhưng con số ba không tự nói dự án này phải làm trước. Một khoảng trống lớn có thể do dữ liệu chưa có, nhà cung cấp chưa rõ hoặc chi phí quá sức. Ngược lại, một thay đổi nhỏ nhưng xử lý được lỗi gây tổn thất cao có thể rất đáng ưu tiên. Vì thế bản đồ chỉ là bước nhận diện. Sau đó chúng ta phải hỏi tác động kinh doanh và độ sẵn sàng triển khai. Người học cũng cần lưu cách chấm, nguồn bằng chứng và lý do đặt mục tiêu để khi tranh luận có thể đối chiếu."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Sản phẩm của bước lập bản đồ", "handwriting": "Gạch chân ô chưa có chứng cứ; dẫn sang danh mục ở video 2.", "slideContent": "Một trang: 4 công đoạn, công nghệ hiện tại, mức hiện trạng, mức mục tiêu, khoảng trống, phụ thuộc, chủ sở hữu.", "lectureScript": "Sau video một, đầu ra của anh chị là một bản đồ một trang. Mỗi dòng nêu công đoạn, năng lực đang có, mức mục tiêu, khoảng trống, công cụ liên quan và người xác nhận. Bổ sung một dòng phụ thuộc: chẳng hạn dự báo cần dữ liệu đơn hàng đã được ghi đủ, hay truy vết cần mã lô thống nhất. Nếu không tìm được bằng chứng cho một mức hiện trạng, hãy để trạng thái chưa kiểm. Không chỉnh điểm chỉ để hạng mục trông cấp bách hơn. Video tiếp theo sẽ chuyển bản đồ sang danh mục đề xuất, nhưng vẫn giữ mối liên hệ với công đoạn và chỉ số ban đầu. Đây là cách kiểm xem một ý tưởng công nghệ thực sự giải quyết vấn đề gì."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('b3fd4aad-a0d6-5d24-8b92-72244d543016', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 2, 'EL-035-V35.2', 'VIDEO 35.2: DANH MỤC VÀ TRỌNG SỐ ƯU TIÊN', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Từ khoảng trống đến bốn ứng viên", "handwriting": "Hiện 4 ứng viên cùng công đoạn, tách mục tiêu công nghệ với tên sản phẩm.", "slideContent": "Bảng A kiểm nhãn OCR; B dự báo vật tư; C ghi dữ liệu dừng máy; D tra cứu SOP.", "lectureScript": "Ở video hai, chúng ta chuyển bốn khoảng trống thành danh mục có thể so sánh. A là kiểm mã lô bằng camera OCR; B là tăng năng lực cảnh báo thiếu vật tư; C là chuẩn hóa và thu thập dữ liệu dừng máy; D là tra cứu quy trình thao tác chuẩn. Đây là bốn đề xuất giả định của An Bình. Không có nghĩa cả bốn phải mua phần mềm mới. Với C, bước đầu có thể chỉ là chuẩn hóa nhật ký dừng máy. Với D, có thể tổ chức lại tài liệu và phân quyền. Chúng ta chấm nhu cầu và khả năng thực hiện, không chấm độ nổi tiếng của công nghệ. Trước khi xếp hạng, mỗi ứng viên phải có chỉ số mà chủ quy trình sẽ dùng để đo kết quả."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Ba tiêu chí có cùng thang điểm", "handwriting": "Cho ba trọng số lên biểu đồ, nhắc tổng 100% và kiểm thứ tự.", "slideContent": "Tác động kinh doanh 40% | Khoảng trống 35% | Sẵn sàng triển khai 25%.", "lectureScript": "Bộ tiêu chí minh họa gồm tác động kinh doanh, mức khoảng trống năng lực và độ sẵn sàng triển khai. Tác động được chấm từ một đến năm theo mức liên hệ với KPI và tổn thất. Khoảng trống bằng mục tiêu trừ hiện trạng; để đưa lên cùng thang một đến năm, bảng cộng thêm một vào chênh lệch từ không đến bốn. Độ sẵn sàng xét con người, dữ liệu, khả năng phối hợp và nguồn lực, cũng dùng thang một đến năm. Trọng số trong bài là bốn mươi phần trăm, ba mươi lăm phần trăm và hai mươi lăm phần trăm. Đây là lựa chọn để dạy cách tính, không phải bộ tiêu chí chuẩn áp dụng cho mọi doanh nghiệp."}, {"layout": "L2", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Chấm bằng bằng chứng, không cảm giác", "handwriting": "Điểm mờ dần khi chưa có chủ quy trình hoặc KPI; hiện cảnh báo cần xác minh.", "slideContent": "Bảng chấm: tiêu chí | mức 1 | mức 3 | mức 5 | ví dụ bằng chứng.", "lectureScript": "Hai nhóm có thể cho một dự án điểm khác nhau dù dùng cùng công thức. Nguyên nhân thường nằm ở cách hiểu thang chấm. Với tác động, nhóm nên dựa trên dữ liệu lỗi, giờ dừng, chi phí và chỉ số nền, thay vì chỉ nói rất quan trọng. Với độ sẵn sàng, hãy xem năng lực nhân sự, chất lượng dữ liệu, tích hợp kỹ thuật và người chịu trách nhiệm. Đừng cộng điểm của một nhà cung cấp vào điểm nhu cầu doanh nghiệp. Nếu dữ liệu chưa xác minh, hãy ghi giả định và ai có nhiệm vụ kiểm tra. Một bảng điểm không có nguồn, người chấm và thời điểm đánh giá chỉ là ý kiến tạm thời. Nó vẫn hữu ích để đặt câu hỏi, nhưng không đủ làm cơ sở phê duyệt."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Tính thử bốn hạng mục", "handwriting": "Tính điểm trên màn hình và xếp C, A, B, D; không hiển thị như khuyến nghị mua.", "slideContent": "Bảng số: A 2->5, G=3, tác động5, sẵn sàng3; B 2->4, G=2, tác động4, sẵn sàng2; C 1->4, G=3, tác động5, sẵn sàng4; D 3->4, G=1, tác động3, sẵn sàng4.", "lectureScript": "Tôi đọc bảng giả định. A có mức hiện tại hai, mục tiêu năm, khoảng trống ba, tác động năm và sẵn sàng ba. B lần lượt là hai, bốn, hai, bốn và hai. C là một, bốn, ba, năm và bốn. D là ba, bốn, một, ba và bốn. Theo trọng số vừa chọn, bảng Excel sẽ cho C bốn phẩy bốn điểm; A bốn phẩy một lăm; B ba phẩy một lăm; D hai phẩy chín. Điểm cao nhất là ứng viên đáng được kiểm chứng tiếp, không phải công nghệ chắc chắn sinh lợi. Hạng C vốn hướng đến dữ liệu nền, nên bước hợp lý có thể là chuẩn hóa cách ghi dừng máy trước khi mua cảm biến."}, {"layout": "L2 + L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Thấy thứ tự và phụ thuộc", "handwriting": "Nối mũi tên nguồn dữ liệu trước ứng dụng; so với bảng điểm.", "slideContent": "Sơ đồ phụ thuộc: nhật ký dừng máy -> phân tích bảo trì; dữ liệu kho -> dự báo; nhãn kiểm -> OCR.", "lectureScript": "Một danh mục ưu tiên còn cần bản đồ phụ thuộc. Dự báo vật tư cần lịch sử vật tư có định nghĩa và độ phủ đủ. Phân tích bảo trì cần mã sự cố và thời gian dừng đáng tin. OCR kiểm nhãn cần bộ mẫu đã gán nhãn và quy trình xử lý loại nhầm. Nếu phụ thuộc chưa có, dự án ứng dụng có thể phải chờ một hạng mục dữ liệu nền. Vì vậy, thứ tự dựa trên điểm chưa chắc là thứ tự thực thi. Anh chị nên đánh dấu việc nào tạo nền cho việc khác, việc nào cần chủ sở hữu dữ liệu và việc nào đòi hỏi thử nghiệm lại. Không thể gom các điều kiện vào một con số rồi bỏ qua đường thực hiện thực tế."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Từ bảng điểm sang danh mục quyết định", "handwriting": "Chuyển danh sách A-D vào 3 làn công việc theo bằng chứng, không theo quảng cáo.", "slideContent": "Ba nhóm: xác minh ngay | xây nền | theo dõi; dưới mỗi mục ghi KPI và người phụ trách.", "lectureScript": "Cuối video hai, hãy phân loại kết quả thành ba nhóm. Một là ứng viên có điểm sàng lọc cao và có thể lập hồ sơ kiểm chứng. Hai là hạng mục cần xây năng lực trước, thường liên quan dữ liệu hoặc nhân sự. Ba là hạng mục nên theo dõi vì tác động hoặc khoảng trống nhỏ. Trong ví dụ, C là ưu tiên khảo sát quy trình ghi dữ liệu dừng máy; A cần xem lại kết quả thử OCR ở bài trước vì chỉ tiêu phát hiện lỗi chưa đạt. B cần củng cố dữ liệu vật tư; D có thể thử cải tiến tra cứu hiện hữu mà không mặc định cần AI. Danh mục này là đề xuất để tổ chức việc tiếp theo, chưa có quyết định ký hợp đồng hay đầu tư."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('f708c10b-df43-5c5d-8669-0613ae8348a7', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 3, 'EL-035-V35.3', 'VIDEO 35.3: KIỂM ĐỘ NHẠY, PHỤ THUỘC VÀ CỔNG TRIỂN KHAI', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L3", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Mở phiếu Excel và đọc công thức", "handwriting": "Khoanh ô vàng; chỉ vào ô công thức không được nhập đè.", "slideContent": "Phiếu: Hiện trạng D, mục tiêu E, khoảng trống F, tác động G, sẵn sàng H.", "lectureScript": "Cột D là mức năng lực hiện tại, cột E là mức muốn đạt, cột F tự tính khoảng trống. Cột G và H ghi tác động cùng sẵn sàng theo thang năm. Các ô vàng cho phép anh chị thay giả định. Dòng trọng số có ba ô chỉnh sửa; tổng phải bằng một trăm phần trăm. Chỉ nhập các mức từ một đến năm, và trong bài này mục tiêu không nhỏ hơn hiện trạng. Nếu thiếu một dữ liệu bắt buộc, bảng sẽ báo chưa hợp lệ thay vì âm thầm coi ô trống là số không. "}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Giải tay điểm của hạng mục C", "handwriting": "Viết 5x40% + 4x35% + 4x25% = 4,40; gắn điểm chỉ là sàng lọc.", "slideContent": "C: 1 -> 4; gap3 -> 4 điểm; tác động5; sẵn sàng4. Tổng 4,40.", "lectureScript": "Hạng C có năng lực hiện tại một và mục tiêu bốn nên khoảng trống là ba. Để quy đổi theo mô hình bài học, điểm khoảng trống là bốn. Tác động kinh doanh năm và độ sẵn sàng bốn. Ta tính năm nhân không phẩy bốn, cộng bốn nhân không phẩy ba lăm, cộng bốn nhân không phẩy hai lăm, bằng bốn phẩy bốn. Lưu ý: một khoảng trống lớn chỉ làm tăng điểm trong mô hình cụ thể này. Doanh nghiệp có thể chọn trọng số khác hoặc áp đặt trần nguồn lực. "}, {"layout": "L2 + L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Thử độ nhạy của thứ tự ưu tiên", "handwriting": "Hiện thanh trọng số mới và vị trí B-D đảo; yêu cầu học viên giải thích.", "slideContent": "Trọng số thay từ 40/35/25 sang 25/30/45; B: 3,15 -> 2,80; D: 2,90 -> 3,15.", "lectureScript": "Bây giờ giảm tỷ trọng tác động xuống hai mươi lăm phần trăm, khoảng trống còn ba mươi phần trăm và tăng sẵn sàng lên bốn mươi lăm phần trăm. Khi đó B giảm từ ba phẩy một lăm xuống hai phẩy tám, còn D tăng từ hai phẩy chín lên ba phẩy một lăm. Hai hạng mục đảo vị trí dù số liệu gốc không đổi. Điều đó không chứng minh trọng số nào đúng hơn. Nó chỉ chỉ ra quyết định nhạy với ưu tiên chiến lược. Hãy ghi người phê duyệt trọng số, lý do điều chỉnh và những hạng mục đổi thứ tự. "}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thứ tự chấm không phải lịch thực thi", "handwriting": "Dùng hai làn song song: ưu tiên để xác minh và thứ tự có thể triển khai.", "slideContent": "Hai cột: điểm sàng lọc và phụ thuộc tiên quyết; mũi tên từ dữ liệu nền sang ứng dụng.", "lectureScript": "Sau phép thử độ nhạy, ta còn một câu hỏi khác: hạng mục nào có thể làm trước về mặt vận hành? Dữ liệu dừng máy có thể cần được ghi theo mã sự cố thống nhất trước khi phân tích bảo trì. Hạng mục OCR của bài trước còn một chỉ tiêu thí điểm chưa đạt, nên chưa thể coi là sẵn sàng nhân rộng. Do đó thứ tự điểm C, A, B, D không tương đương lịch đặt mua hay lịch lắp đặt. Người lập danh mục phải vẽ thêm sơ đồ phụ thuộc, xác định công việc nền và điểm kiểm tra trước mỗi bước. "}, {"layout": "L2", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Năm cổng không thể bù trừ", "handwriting": "Tô cam cổng về giao diện và quyền dữ liệu đang Chưa kiểm.", "slideContent": "Cổng: chủ quy trình/KPI; hiện trạng có nguồn; phụ thuộc và giao diện; quyền/an toàn; nguồn lực và tiêu chí thử.", "lectureScript": "Bảng điểm hỗ trợ chọn thứ tự làm việc. Còn việc được phép bước sang thử nghiệm phụ thuộc các điều kiện riêng. Trong phiếu có năm cổng: chủ sở hữu và KPI; căn cứ mức năng lực hiện trạng; phụ thuộc dữ liệu và khả năng tích hợp; quyền dữ liệu, an toàn; cuối cùng là nguồn lực, chỉ tiêu và người duyệt phép thử. Tôi cố ý để một cổng ở trạng thái chưa kiểm. Do đó, dù C có điểm cao nhất, trạng thái danh mục vẫn yêu cầu bổ sung hồ sơ. Cổng chưa kiểm không đồng nghĩa ý tưởng xấu; nó có nghĩa chưa có quyền kết luận đủ điều kiện. "}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Lập nhịp triển khai có điểm dừng", "handwriting": "Các bước được vẽ thành bậc; ở mỗi bậc có cổng dừng và người phê duyệt.", "slideContent": "Bảng công việc: xác minh KPI -> chuẩn hóa dữ liệu -> thử giới hạn -> đánh giá -> quyết định.", "lectureScript": "Với C, trước tiên thống nhất mã sự cố, cách ghi giờ dừng và trách nhiệm nhập liệu. Chỉ sau khi mẫu ghi đủ và dữ liệu được phép dùng mới xem xét công cụ thu thập tự động. Với A, đối chiếu lại kết quả OCR chưa đạt ở phép thử trước, kiểm nhãn và loại nhầm trước khi đề xuất thí điểm mới. Với B, cần làm rõ lịch sử kho; với D, rà quy trình tra cứu hiện hữu. Mỗi bước có kết quả bàn giao, người phụ trách, chi phí tối đa và tiêu chí dừng. "}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Bài nộp và quy tắc cập nhật bản đồ", "handwriting": "Khoanh vùng ô còn trống, hiển thị lời mời hoàn thành bài tự luyện và tự chấm.", "slideContent": "Bài nộp: bản đồ có nguồn; bảng điểm; thử trọng số; năm cổng; danh mục việc có chủ và KPI.", "lectureScript": "Sau bài học, anh chị nộp bản đồ công nghệ của một quy trình thực tế hoặc dùng số giả định của An Bình. Bản đồ phải có ranh giới, công đoạn, hiện trạng, mục tiêu, khoảng trống và nguồn xác nhận. Tiếp theo, tính điểm ưu tiên, thử một bộ trọng số khác, chỉ ra ít nhất một phụ thuộc và lập việc tiếp theo cho từng hạng mục. Cuối cùng, đánh dấu năm cổng, ghi người chịu trách nhiệm và các bằng chứng chưa có. Khi quy trình, KPI, nhà cung cấp hoặc dữ liệu thay đổi, bản đồ phải có ngày cập nhật và phiên bản mới. "}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('6b178942-29e9-57fb-a378-8fa757191dc4', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 1, 'EL-036-V36.1', 'VIDEO 36.1: TỪ CHIẾN LƯỢC KINH DOANH ĐẾN DANH MỤC 3 - 5 NĂM', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Vì sao cần lộ trình nhiều năm", "handwriting": "Hiện từng mũi tên; đối chiếu với một danh sách mua sắm không ghi KPI.", "slideContent": "Tiêu đề: Đích kinh doanh -> năng lực cần có -> công việc công nghệ -> bằng chứng -> năm triển khai.", "lectureScript": "Khi doanh nghiệp nói rằng năm tới sẽ đầu tư camera, hai năm nữa triển khai dự báo và năm thứ ba mua thêm cảm biến, đó chưa phải lộ trình đổi mới công nghệ. Một lộ trình có ích phải trả lời được công nghệ phục vụ kết quả kinh doanh nào, công việc nào phải đi trước và điều kiện gì cho phép chi tiền ở từng giai đoạn. Trong bài này, chúng ta xây dựng lộ trình ba năm lõi, có thể mở đến năm thứ tư và năm thứ năm. Tôi dùng tình huống cơ sở đóng gói cà phê An Bình, toàn bộ số liệu là giả định để thực hành. Đích của chúng ta là một bảng có thể điều chỉnh khi dữ liệu và chiến lược thay đổi, không phải một lời hứa sẽ mua đủ thiết bị."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Chọn hai đích kinh doanh có số đo", "handwriting": "Gạch chân KPI và nguồn đường cơ sở; đặt dấu hỏi tại mục thiếu dữ liệu.", "slideContent": "Hai mục tiêu minh họa: giảm lỗi nhãn lọt; giảm giờ dừng và số lần thiếu vật tư. Mỗi mục gắn mẫu số và chủ quy trình.", "lectureScript": "Bước đầu tiên là ghi mục tiêu kinh doanh bằng chỉ số mà người chịu trách nhiệm có thể xác nhận. Chẳng hạn An Bình muốn giảm tỷ lệ lỗi nhãn lọt ra khách hàng, kiểm soát số lần thiếu vật tư làm gián đoạn đóng gói và giảm giờ dừng máy không rõ nguyên nhân. Với từng mục, cần có đường cơ sở, cách đếm và kỳ theo dõi. Lỗi nhãn phải xác định trên số túi hoặc lô được kiểm, còn thiếu vật tư phải thống nhất khi nào được tính là một lần gián đoạn. Nếu chưa có số nền tin cậy, nhiệm vụ năm đầu tiên có thể là chuẩn hóa việc ghi nhận. Chưa đủ dữ liệu thì chưa thể hứa mức cải thiện."}, {"layout": "L2 + L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Nối năng lực công nghệ với mục tiêu", "handwriting": "Nối từng nhu cầu với lớp dữ liệu, người sở hữu và KPI; hiển thị Q1.", "slideContent": "Bản đồ từ Bài 35: mã sự cố -> dữ liệu dừng; mã vật tư -> cảnh báo; dữ liệu nhãn -> kiểm OCR.", "lectureScript": "Từ bản đồ công nghệ ở Bài ba mươi lăm, chúng ta không lấy thứ tự điểm số để chép thẳng thành thứ tự đầu tư. Hạng mục ghi dữ liệu dừng máy có điểm ưu tiên cao, nhưng muốn phân tích nguyên nhân dừng trước hết phải có mã sự cố, thời gian bắt đầu và kết thúc, cùng người xác nhận. Với camera OCR, lần thí điểm minh họa ở Bài hai mươi chín chưa đạt chỉ số phát hiện lỗi. Như vậy, công việc hợp lý là khắc phục, chuẩn hóa mẫu và thử lại trước khi tính đến nhân rộng. Các quan hệ trước sau này phải được ghi thành cột phụ thuộc, chứ không chỉ nói bằng lời."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Phân biệt ba lớp công việc", "handwriting": "Chuyển thẻ dự án sang làn, khoanh thẻ chưa thể mở rộng.", "slideContent": "Ba làn: xây nền dữ liệu; kiểm chứng giải pháp; mở rộng có điều kiện.", "lectureScript": "Tôi chia danh mục thành ba lớp. Lớp thứ nhất là công việc nền: chuẩn hóa mã vật tư, mã sự cố và cách lưu nhãn, mã lô. Lớp thứ hai là kiểm chứng: thử lại một giải pháp sau khi đã sửa vấn đề và đo bằng chỉ số định trước. Lớp cuối cùng là mở rộng vận hành, chỉ khi kết quả thử, quyền sử dụng và an toàn đều được xác minh. Đây là phân loại theo điều kiện, không phải theo độ mới của công nghệ. Nếu ngân sách giảm, doanh nghiệp có thể lùi lớp mở rộng mà vẫn giữ các bước nền cần thiết. Việc giãn tiến độ phải được ghi vào phiên bản mới của lộ trình."}, {"layout": "L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Ví dụ năm 1 trước năm 2", "handwriting": "Dựng thanh thời gian năm 1-5; vẽ P3 -> P4 -> P6 và P2 -> P5.", "slideContent": "Lịch minh họa: năm 1 P1,P2,P3; năm 2 P4; năm 3 P5; năm 4 P6; năm 5 P7.", "lectureScript": "Giả sử An Bình đặt ba việc nền vào năm thứ nhất: chuẩn mã sự cố, chuẩn mã vật tư và chuẩn nhãn, mã lô. Năm hai mới dự kiến thử lại camera OCR. Năm ba mới cân nhắc cảnh báo thiếu vật tư. Mở rộng OCR sang ca khác được đặt ở năm bốn, sau thử lại; còn phân tích dừng máy ở năm năm dựa trên dữ liệu đã tích lũy. Khi nhìn sơ đồ, anh chị hãy thử di chuyển dự án thử OCR về năm một. Nếu điều kiện dữ liệu nền chưa hoàn tất, lịch mới mâu thuẫn với chính giả định đã đặt. Đó là lý do một lộ trình phải kiểm được phụ thuộc."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Chốt sản phẩm video 1", "handwriting": "Đánh dấu 4 trường bắt buộc và chuyển sang bài phân bổ nguồn lực.", "slideContent": "Tờ đầu ra: đích kinh doanh + 7 sáng kiến + KPI + năm dự kiến + điều kiện phụ thuộc.", "lectureScript": "Kết thúc phần này, anh chị chưa cần dự báo chính xác ngân sách đến năm năm. Hãy lập được hồ sơ đầu tiên gồm mục tiêu kinh doanh, ít nhất một KPI nền có cách đo, danh mục các sáng kiến và quan hệ phụ thuộc giữa chúng. Với mỗi sáng kiến, ghi ai chịu trách nhiệm cung cấp bằng chứng. Một năm triển khai trên sơ đồ chỉ là vị trí đề xuất. Sang video thứ hai, chúng ta sẽ kiểm xem những vị trí ấy có nằm trong sức chịu đựng của ngân sách và nhân lực hay không. Nếu không, phải sửa lịch trước khi đưa ra quyết định."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('2f604f18-9933-5db4-b3d3-dd88292e7b0d', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 2, 'EL-036-V36.2', 'VIDEO 36.2: PHÂN BỔ NGÂN SÁCH, NHÂN LỰC VÀ CỔNG QUYẾT ĐỊNH', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Lịch đẹp có thể không đủ nguồn lực", "handwriting": "Tô đỏ năm vượt trần; mọi số là giả định.", "slideContent": "Hai đường: nhu cầu dự kiến và trần nguồn lực theo năm; năm 4 có cảnh báo.", "lectureScript": "Hai dự án cùng triển khai trong một năm có thể tranh nhau ngân sách, nhân sự vận hành và thời gian dừng dây chuyền để lắp đặt. Vì vậy, tôi đề nghị xem từng năm như một giới hạn nguồn lực. Không chỉ hỏi tổng chi phí năm năm là bao nhiêu, mà còn hỏi năm nào phải chi, bộ phận nào chịu tải và nếu dồn nhiều việc cùng lúc thì hoạt động sản xuất bị ảnh hưởng thế nào. Ví dụ của An Bình tính kinh phí ban đầu theo triệu đồng và nỗ lực triển khai theo người-tháng. Đây là các ước lượng học tập; chưa bao gồm toàn bộ chi phí vận hành và rủi ro phát sinh. Khi dùng thật, doanh nghiệp cần làm dự toán riêng theo phạm vi hợp đồng."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Cách đọc hai cột nguồn lực", "handwriting": "Cộng dọc số minh họa, so với trần năm 1: 230 triệu và 8 người-tháng.", "slideContent": "P1: 70 triệu, 3 người-tháng; P2: 65,2; P3:80,2. Năm 1 cộng 215 và 7.", "lectureScript": "Ở năm thứ nhất, P một cần bảy mươi triệu và ba người-tháng, P hai cần sáu mươi lăm triệu và hai người-tháng, P ba cần tám mươi triệu và hai người-tháng. Cộng lại là hai trăm mười lăm triệu và bảy người-tháng. Trong giả định, trần của năm một là hai trăm ba mươi triệu và tám người-tháng, nên kế hoạch không vượt trần tại thời điểm lập. Hãy phân biệt dự toán sáng kiến, quỹ dự phòng, chi phí vận hành và tổng chi phí sở hữu. Những thứ ấy chưa được cộng đầy đủ trong phiếu ngắn này. Phiếu chỉ dùng để phát hiện việc xếp lịch vượt sức chịu tải ban đầu."}, {"layout": "L2 + L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Bài toán năm 4 vượt trần", "handwriting": "Tính chênh lệch -20 triệu và -1 người-tháng; bật Q3.", "slideContent": "P6 năm 4: 280 triệu và 7 người-tháng; trần 260 triệu và 6 người-tháng.", "lectureScript": "Bây giờ xem năm thứ tư. Việc mở rộng OCR được dự kiến hai trăm tám mươi triệu và bảy người-tháng, trong khi trần minh họa chỉ là hai trăm sáu mươi triệu và sáu người-tháng. Như vậy, năm này thiếu hai mươi triệu và thiếu một người-tháng. Bảng phải báo vượt trần, kể cả khi các năm trước còn dư; không thể tự động chuyển ngân sách qua năm nếu chưa có cơ chế cho phép. Có ba lựa chọn cần thẩm định: chia nhỏ phạm vi, đổi thời điểm hoặc xin điều chỉnh trần. Dù chọn cách nào, phần mở rộng vẫn phụ thuộc kết quả thử OCR và cổng an toàn, dữ liệu."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Xem phụ thuộc theo mã dự án", "handwriting": "Kéo P4 về năm 1 để hiện cảnh báo sai thứ tự; sau đó hoàn tác.", "slideContent": "Mũi tên P3 -> P4 -> P6; P2 -> P5; P1 -> P7. Cột năm dự kiến.", "lectureScript": "P bốn thử lại OCR phụ thuộc P ba chuẩn hóa nhãn và mã lô. P sáu mở rộng OCR lại phụ thuộc P bốn. Nếu đặt P bốn cùng năm với P ba, công thức sẽ nhắc rằng thứ tự chưa hợp lệ theo quy tắc thận trọng của bài: công việc tiên quyết phải ở năm trước. Trong doanh nghiệp, một số việc có thể chạy song song theo các mốc nhỏ, nhưng khi ấy phải có kế hoạch mốc và nghiệm thu chi tiết, không được âm thầm bỏ phụ thuộc. Cần kiểm tra cả nội dung điều kiện: P bốn chưa có kết quả thử đạt thì dù đến năm bốn P sáu vẫn chưa được xem là sẵn sàng."}, {"layout": "L2 + L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Cổng theo bằng chứng và người nhận", "handwriting": "Hiện hai màu: Đã kiểm hoặc Chưa kiểm; cổng thứ hai là Chưa kiểm.", "slideContent": "Cổng: người bảo trợ/KPI; quyền dữ liệu và an toàn; ngân sách và mua sắm.", "lectureScript": "Tôi dùng ba cổng cho bản lộ trình cấp danh mục. Cổng thứ nhất xác nhận chủ sở hữu, mục tiêu và KPI. Cổng thứ hai kiểm quyền dữ liệu, an toàn, sở hữu trí tuệ và tiêu chí thử. Cổng thứ ba xem khả năng cấp ngân sách cùng quy trình mua sắm. Đặc biệt, tại An Bình, thử OCR trước đó chưa đạt ngưỡng phát hiện lỗi, nên công việc thử lại phải có bộ mẫu độc lập và quy tắc dừng. Không có tài liệu này, không chuyển P sáu sang triển khai dù sơ đồ có ghi ở năm bốn. Chúng ta không bù cổng bằng ngân sách dư hoặc điểm ưu tiên."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Duy trì một kế hoạch có phiên bản", "handwriting": "Đánh dấu mục chưa đủ và giới thiệu video thực hành Excel.", "slideContent": "Bảng kiểm 6 trường: phiên bản, quyết định, KPI, phụ thuộc, nguồn lực, người duyệt.", "lectureScript": "Hãy lưu lý do, ngày xác nhận, ai đề xuất và ai có quyền duyệt. Nếu năm bốn vượt trần, người lập không sửa dự toán tùy ý chỉ để biểu đồ chuyển sang màu xanh. Họ phải đề xuất giảm phạm vi với sản phẩm bàn giao rõ ràng, hoặc chuyển một phần việc sang kỳ khác rồi tính lại. Với hạng mục dữ liệu, trách nhiệm chuẩn hóa và duy trì hồ sơ cũng cần ngân sách thường xuyên, không chỉ chi phí thiết lập ban đầu. Ở video tiếp theo, chúng ta sẽ thao tác trực tiếp trên phiếu và kiểm ba lỗi phổ biến: sai thứ tự phụ thuộc, vượt trần nguồn lực và thiếu cổng pháp lý, an toàn."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('34b199e2-300c-5a3a-bfad-69cd8937fb12', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 3, 'EL-036-V36.3', 'VIDEO 36.3: LẬP PHIẾU LỘ TRÌNH VÀ QUY TẮC ĐIỀU CHỈNH', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đọc ba vùng của phiếu Excel", "handwriting": "Di con trỏ qua D-I, sau đó E-I ở bảng năm.", "slideContent": "Vùng A: 7 sáng kiến; B: 5 năm phân bổ; C: 3 cổng. Ô vàng nhập; ô xanh công thức.", "lectureScript": "Bây giờ mở sheet PHIẾU THỰC HÀNH. Vùng thứ nhất có bảy sáng kiến, năm triển khai, vốn dự kiến, người-tháng, mã phụ thuộc và trạng thái bằng chứng. Vùng thứ hai cộng nguồn lực theo từng năm, rồi so với trần mà lớp học đã giả định. Vùng cuối ghi ba cổng quản trị. Những ô nền vàng là nơi anh chị được thay số hoặc trạng thái. Ô nền xanh là kết quả công thức, không nhập đè. Mục đích là để phát hiện mâu thuẫn và sửa đề xuất, không phải tìm cách làm mọi ô đều hiện chữ đạt."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Kiểm năm 1 và năm 4 bằng tay", "handwriting": "Dùng con trỏ ở hàng 18 và 21; gạch dưới phần chênh lệch.", "slideContent": "Năm 1: 215/230 triệu, 7/8 người-tháng. Năm 4: 280/260, 7/6.", "lectureScript": "Tôi kiểm lại hai hàng bằng tay. Năm một có ba khoản bảy mươi, sáu mươi lăm và tám mươi triệu, tổng hai trăm mười lăm. Người-tháng là ba cộng hai cộng hai, bằng bảy. Năm bốn chỉ có P sáu nhưng đã cần hai trăm tám mươi triệu và bảy người-tháng. Trần năm này là hai trăm sáu mươi triệu và sáu người-tháng. Cột còn lại hiển thị âm hai mươi triệu và âm một người-tháng, báo vượt trần. Hãy thử tăng trần lên ba trăm triệu và tám người-tháng. Cảnh báo nguồn lực có thể hết, nhưng cổng kiểm chứng OCR vẫn chưa hoàn thành."}, {"layout": "L2 + L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Phân biệt ba năm lõi và hai năm tùy chọn", "handwriting": "Tính tổng năm 1-3 và năm 4-5 riêng; hiển thị Q5.", "slideContent": "Chân dung danh mục: N1-N3 = 535 triệu; N4-N5 = 470 triệu; tổng = 1.005 triệu.", "lectureScript": "Nhìn tổng vốn dự kiến năm một đến năm ba: hai trăm mười lăm, một trăm bốn mươi lăm và một trăm bảy mươi lăm triệu, cộng lại là năm trăm ba mươi lăm triệu. Hai năm mở rộng, năm bốn và năm năm, có thêm hai trăm tám mươi cộng một trăm chín mươi, tức bốn trăm bảy mươi triệu. Kế hoạch ba năm lõi vẫn cần phê duyệt hằng giai đoạn; hai năm sau phụ thuộc hiệu quả thực tế và năng lực tích lũy. Ngân sách minh họa chưa phải tổng chi phí sở hữu, vì chi phí vận hành, dự phòng và thay thế chưa được tính đủ."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Thử sai thứ tự phụ thuộc", "handwriting": "Tô màu mã P3 và năm 1; cho thấy P4 không thể cùng năm theo quy tắc bài.", "slideContent": "Đổi P4 từ năm 2 xuống năm 1 để kích hoạt SAI THỨ TỰ; hoàn tác.", "lectureScript": "P bốn phụ thuộc P ba mà P ba cũng đang ở năm một. Công thức báo sai thứ tự theo quy ước của phiếu, vì chưa dành một năm riêng cho bước tiên quyết. Nếu doanh nghiệp muốn làm cùng năm, họ phải tách thành các mốc nhỏ và chứng minh mốc nghiệm thu đi trước mốc khởi động, chứ không bỏ qua cảnh báo. Tôi trả P bốn về năm hai. Thử tiếp trường hợp thứ hai: để nguyên năm nhưng chuyển trạng thái bằng chứng của P bốn về Chưa kiểm, như dữ liệu mặc định. Lịch có thể đúng về thời gian nhưng vẫn chưa đủ điều kiện để khởi động dự án."}, {"layout": "L2 + L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Tình huống thiếu cổng", "handwriting": "Tách nhãn ĐỦ LỊCH khỏi ĐỦ PHÊ DUYỆT; hiện Q6.", "slideContent": "Cổng 2 chưa kiểm quyền dữ liệu, an toàn và pháp lý. Cảnh báo toàn bảng.", "lectureScript": "Tình huống thứ ba là thiếu cổng. Dù các dòng dự án được xếp đúng thứ tự và nguồn lực nằm trong trần, quyền sử dụng dữ liệu, an toàn thiết bị và trách nhiệm của nhà cung cấp vẫn phải được xác nhận. Với An Bình, cổng thứ hai cố ý để Chưa kiểm. Cần ghi bằng chứng phải có, người nhận việc và thời hạn xử lý. Khi trình lãnh đạo, nên nói: đây là phương án lộ trình để thẩm định, còn các điều kiện chưa hoàn tất. Kết luận có trách nhiệm là chờ xác minh, không tự động nhân rộng công nghệ."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Lập phương án điều chỉnh có trách nhiệm", "handwriting": "So sánh điều kiện, không tự sửa dự toán thành số vừa trần.", "slideContent": "Hai kịch bản: A giữ P6, bổ sung nguồn lực có phê duyệt; B chia P6 thành hai gói có KPI riêng.", "lectureScript": "Hãy viết ít nhất hai phương án điều chỉnh. Một là xin xem xét trần nguồn lực năm bốn, kèm tác động tới dòng tiền và khả năng bố trí người. Hai là chia P sáu thành hai đợt mở rộng có phạm vi, kiểm thử và đầu ra riêng. Phương án chia nhỏ phải có báo giá mới; không thể tùy tiện coi nửa phạm vi sẽ tốn đúng một nửa chi phí. Cả hai phương án đều phải giữ điều kiện P bốn thử OCR đạt trước khi mở rộng. Sau đó xác định mốc rà soát hằng năm, hoặc sớm hơn nếu KPI và nguồn lực thay đổi lớn."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Bài nộp và tiêu chí tự đánh giá", "handwriting": "Gắn hình checklist cuối video; không coi file Excel là hồ sơ đầu tư đã ký.", "slideContent": "Sản phẩm: 7 sáng kiến, 5 năm, 3 cổng, 2 kịch bản, 1 người duyệt; 10 câu và tự chấm.", "lectureScript": "Bài nộp phải cho thấy mục tiêu kinh doanh, bảy sáng kiến hoặc danh mục thay thế tương đương, quan hệ phụ thuộc, nguồn lực theo năm và phần còn thiếu bằng chứng. Hãy thử ít nhất một thay đổi năm triển khai, một thay đổi trần ngân sách, rồi ghi hai cách xử lý xung đột. Làm mười câu trắc nghiệm, ba nhiệm vụ viết và tự chấm bảy tiêu chí. Khi chuyển sang quyết định thực tế, cần thêm dự toán tổng chi phí sở hữu, đánh giá rủi ro, kết quả kiểm chứng và thẩm quyền phê duyệt."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('cdc30995-94a5-5a23-a22e-221ab34438e5', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 1, 'EL-037-V37.1', 'VIDEO 37.1: CHỌN BÀI TOÁN CHO AI TẠO SINH VÀ TRỢ LÝ NỘI BỘ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Bắt đầu từ việc, không bắt đầu từ chatbot", "handwriting": "Hiện lời hỏi quá rộng rồi thu thành công việc có đầu ra đo được; đóng dấu GIẢ ĐỊNH.", "slideContent": "Sơ đồ: nhu cầu quản trị -> nhiệm vụ tri thức -> dữ liệu được phép dùng -> người kiểm -> phép thử.", "lectureScript": "Khi nghe tới trí tuệ nhân tạo tạo sinh, nhiều doanh nghiệp muốn lập ngay một trợ lý trả lời mọi câu hỏi. Cách bắt đầu ấy khó kiểm soát vì chưa ai định nghĩa câu hỏi nào được trả lời, dữ liệu nào được sử dụng và ai chịu trách nhiệm nếu câu trả lời sai. Trong bài này, tôi đề nghị bắt đầu từ một nhiệm vụ nhỏ có người nhận kết quả. Ví dụ tại cơ sở đóng gói cà phê An Bình, nhân viên thường phải tìm quy trình kiểm nhãn, tổng hợp bàn giao ca và tra cứu hướng dẫn xử lý sự cố. Đây là tình huống giả định."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "AI tạo sinh làm gì và không bảo đảm điều gì", "handwriting": "Đặt câu trả lời nghe hợp lý bên cạnh một đoạn nguồn không có căn cứ; đánh dấu cảnh báo.", "slideContent": "Hai cột: tạo văn bản/tóm tắt/hỏi đáp và giới hạn: có thể sai, thiếu, không hiểu quyền nội bộ.", "lectureScript": "AI tạo sinh có thể viết bản nháp, tóm tắt văn bản và diễn đạt một câu trả lời bằng ngôn ngữ dễ đọc. Nhưng việc tạo được câu văn mạch lạc không chứng minh nội dung đúng. Hệ thống có thể ghép thông tin từ các nguồn khác thời điểm, nêu một con số không tồn tại, hoặc giải thích sai quy định vận hành. Vì vậy cần tách ba việc: tìm được hồ sơ có quyền truy cập, tạo câu trả lời có dẫn chiếu và để người có chuyên môn phê duyệt phần cần hành động. Với các thao tác có rủi ro an toàn, điều kiện dừng máy hoặc thay đổi cài đặt thiết bị, trợ lý không tự ra lệnh thực thi. Nội dung được xem là đề xuất cần xác minh."}, {"layout": "L2 + L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Ba tình huống và một thước đo", "handwriting": "Gắn nhãn nhu cầu, loại dữ liệu, tiêu chí đúng và trách nhiệm; bật Q1.", "slideContent": "A: hỏi đáp SOP; B: soạn bàn giao ca; C: soạn thư phản hồi. Mỗi đầu ra có mẫu và người kiểm.", "lectureScript": "Hãy nhìn ba nhiệm vụ có thể đề xuất tại An Bình. Một là trả lời câu hỏi từ quy trình thao tác chuẩn đã ban hành, kèm phiên bản tài liệu. Hai là soạn bản nháp bàn giao ca từ các ghi nhận mà người phụ trách đã kiểm. Ba là chuẩn bị bản nháp giải thích cho khách hàng từ thông tin công bố được phép dùng. Với quy trình sản xuất, câu trả lời sai có thể khiến người dùng làm sai bước kiểm tra. Do đó, chúng ta chọn nhiệm vụ hỏi đáp SOP để thử đầu tiên, trên một bộ tài liệu được phép truy cập và có người đối chiếu."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Trợ lý có nguồn khác lời đáp trống nguồn", "handwriting": "Cho hiện câu “không tìm thấy căn cứ” khi kho nguồn không chứa thông tin.", "slideContent": "Màn hình tách ba bước: nhận câu hỏi -> tìm đoạn tài liệu hợp lệ -> tạo đáp án kèm tên/phiên bản.", "lectureScript": "Một trợ lý tri thức đáng thử phải cho người dùng biết câu trả lời dựa vào đâu. Trong thiết kế minh họa, câu hỏi đi qua bước kiểm quyền, sau đó tìm đoạn văn bản trong kho tài liệu đã duyệt. Hệ thống trả lời bằng nội dung có dẫn tên và phiên bản tài liệu để nhân viên mở ra kiểm tra. Đây là cách tổ chức luồng công việc, không phải cam kết mọi câu trả lời đều đúng. Nếu tài liệu không chứa thông số được hỏi, câu trả lời phù hợp là nói chưa tìm thấy căn cứ và chuyển người có thẩm quyền. Việc từ chối đúng phải được tính như một kết quả đạt trong bộ kiểm thử, thay vì thưởng cho hệ thống vì luôn trả lời."}, {"layout": "L2 + L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Chọn phạm vi thử đủ hẹp", "handwriting": "Khoanh câu ngoài phạm vi; hiện Q2.", "slideContent": "Một sơ đồ phạm vi: 7 câu kiểm, tài liệu SOP đã kiểm, không truy cập dữ liệu cá nhân, không điều khiển máy.", "lectureScript": "Ở lần thử đầu, An Bình giả định chỉ dùng một tập SOP đã được người sở hữu tài liệu xác nhận. Bộ kiểm gồm bảy tình huống: có câu hỏi tìm thấy nguồn, có câu hỏi không có nguồn, có trường hợp dễ nhầm phiên bản và có câu hỏi mà việc suy đoán sẽ gây rủi ro. Hệ thống chưa được kết nối trực tiếp với điều khiển thiết bị. Các tài liệu về nhân sự, hợp đồng hoặc dữ liệu khách hàng nằm ngoài phạm vi cho đến khi có đánh giá quyền riêng. Người thực hiện phải ghi trước cách chấm từng câu. Nếu thay bộ mẫu sau khi thấy kết quả, chúng ta sẽ không còn phép thử khách quan như lúc lập kế hoạch. Phải lưu ngày, phiên bản và người duyệt bộ kiểm."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Brief một trang cho đội thử nghiệm", "handwriting": "Hiện lần lượt sáu ô cần điền; chuyển sang video quản trị dữ liệu.", "slideContent": "Mẫu brief: người dùng, trường hợp sử dụng, nguồn, việc cấm, ngưỡng kiểm, người phê duyệt.", "lectureScript": "Trước khi mời một đơn vị cung cấp trợ lý AI, hãy viết một brief một trang. Nhân viên nào đặt câu hỏi, họ thường tìm thông tin gì, tài liệu gốc được lưu ở đâu, ai có quyền đọc và họ phải làm gì khi không tìm thấy đáp án? Tiếp đó, ghi rõ những việc hệ thống không được làm: không tự sửa SOP, không tự quyết định dừng máy, không xuất dữ liệu ngoài nơi được cho phép. Brief cũng phải xác định một người quản lý chất lượng đầu ra và một đầu mối kỹ thuật xử lý sự cố. Video tiếp theo sẽ đi sâu vào kiểm quyền, chất lượng nguồn và cách nhận diện câu trả lời bịa."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('5017e1b8-0f89-5ba6-84f8-ae5ca5a8199a', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 2, 'EL-037-V37.2', 'VIDEO 37.2: QUẢN TRỊ NGUỒN TRI THỨC, QUYỀN TRUY CẬP VÀ CHẤT LƯỢNG ĐẦU RA', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Kho tri thức phải có chủ và phiên bản", "handwriting": "Tô nhãn hết hiệu lực; câu trả lời không dùng bản cũ khi có bản mới.", "slideContent": "Bảng: SOP-01 phiên bản, ngày hiệu lực, chủ tài liệu, trạng thái áp dụng, nhóm truy cập.", "lectureScript": "Một trợ lý nội bộ chỉ hữu ích khi biết đâu là nguồn được phép trích dẫn. Với mỗi SOP, cần ghi mã tài liệu, phiên bản, ngày hiệu lực, người sở hữu và nhóm nhân viên được xem. Nếu kho chứa cả bản nháp lẫn bản đã ban hành mà không có dấu phân biệt, hệ thống có thể trộn hai quy tắc. Vì vậy, trước khi thử thuật toán, đội triển khai phải làm sạch danh mục và loại các bản hết hiệu lực khỏi phạm vi tra cứu phù hợp. Không nên đặt kỳ vọng AI tự xác định mọi quy định nội bộ là chính xác. Người quản trị tài liệu mới có thẩm quyền xác nhận phiên bản."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Phân quyền không nằm ở lời nhắc", "handwriting": "Minh họa quyền trước tìm kiếm; che các dữ liệu cá nhân.", "slideContent": "Sơ đồ nhân sự: vận hành, QA, CNTT; mỗi nhóm đọc được nguồn khác nhau.", "lectureScript": "Hãy phân biệt câu nhắc với quyền kỹ thuật. Viết rằng “không tiết lộ thông tin mật” trong câu nhắc là chưa đủ để bảo vệ dữ liệu. Đội triển khai phải xác định tài liệu nào được đưa vào môi trường thử, ai có quyền truy cập, dữ liệu có được ghi nhật ký hay chuyển tới bên khác và thời hạn lưu là bao lâu. Chỉ sử dụng những tài liệu đã có cơ sở pháp lý và phê duyệt nội bộ phù hợp. Nếu chưa đánh giá được một luồng dữ liệu, hãy đánh dấu chưa kiểm, không tự coi là được phép."}, {"layout": "L2 + L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Viết yêu cầu có đường kiểm chứng", "handwriting": "Đánh dấu ba điều kiện trên ví dụ; bật Q3.", "slideContent": "Mẫu yêu cầu: chỉ dùng SOP đã duyệt; dẫn mã/phiên bản; thiếu căn cứ thì nói không có.", "lectureScript": "Khi giao việc cho trợ lý, thay vì yêu cầu “hãy trả lời thật chính xác”, chúng ta nêu hành vi có thể kiểm. Chẳng hạn: chỉ sử dụng nội dung SOP đã được cấp quyền; ở mỗi hướng dẫn, ghi mã và phiên bản nguồn; nếu tài liệu không nêu thông số, báo thiếu căn cứ và hướng người dùng đến người phụ trách. Câu nhắc như vậy không bảo đảm hệ thống luôn tuân thủ. Nó chỉ giúp đội kiểm thử có tiêu chí quan sát rõ. Cần thử cả những yêu cầu cố tình thúc hệ thống suy đoán hoặc bỏ qua quy định. Nếu hệ thống trả lời trái nguồn, nhóm phụ trách phải lưu lỗi và có cách chặn xuất bản. Không lấy một ví dụ trả lời đúng làm bằng chứng đủ cho mọi ca vận hành."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Bộ câu thử phải có đáp án kỳ vọng", "handwriting": "Dùng cặp câu dễ và câu không có nguồn; không chỉ lấy câu hệ thống làm tốt.", "slideContent": "Bảng bảy trường hợp: có nguồn/không có; loại trả lời; người duyệt; kết quả 1/0.", "lectureScript": "Bộ thử của chúng ta gồm bảy tình huống giả định. Mỗi tình huống có trạng thái có nguồn hay không có nguồn trong kho được phép dùng. Nếu có nguồn, đầu ra chỉ đạt khi trả lời đúng và dẫn được tài liệu. Nếu không có nguồn, một lời từ chối đúng là kết quả đạt; còn tự chế thông số phải xem là lỗi. Thêm cột kiểm phiên bản, cột người duyệt và kết quả một hoặc không. Điểm được tính theo số câu được xác minh, không tự chấm bằng nhận xét do chính mô hình tạo ra. Những câu chưa kiểm phải để trống kết quả, không biến ô trống thành không điểm rồi làm sai mẫu số. Cách đếm sẽ được thực hành trong video cuối."}, {"layout": "L2 + L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Nhìn lỗi bịa nguồn thay vì chỉ nhìn trung bình", "handwriting": "Hiện chữ BỊA NGUỒN; so sánh với T4 từ chối đúng; bật Q4.", "slideContent": "Tình huống T7: hỏi thông số chưa có tài liệu; trợ lý bịa nguồn; dừng mở thử.", "lectureScript": "Một lỗi cần xử lý riêng là đầu ra bịa nguồn. Giả sử nhân viên hỏi một thông số máy không có trong tài liệu được duyệt, nhưng trợ lý nêu con số và ghi một mã SOP không tồn tại. Cho dù sáu câu còn lại đều đạt, sự kiện này không nên bị làm mờ bởi tỷ lệ trung bình. Trong mẫu bài học, chỉ cần xuất hiện một câu trả lời bịa nguồn thì trạng thái sẽ chuyển sang dừng mở rộng, điều tra nguyên nhân và sửa trước khi thử lại. Ngược lại, câu T bốn biết từ chối vì thiếu nguồn là hành vi cần ghi nhận. Các ngưỡng này là quy tắc đào tạo giả định, không phải tiêu chuẩn pháp lý phổ quát."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Dựng nguyên tắc tiếp tục hay dừng", "handwriting": "Khóa ngưỡng trước khi xem kết quả, chuyển sang phiếu Excel.", "slideContent": "Các cổng: quyền dữ liệu, chủ nguồn, chủ phê duyệt; các ngưỡng đạt mẫu, không bịa.", "lectureScript": "Trước khi xem bảng tính, chúng ta ghi quy tắc quyết định. Trong ví dụ, ít nhất sáu trên bảy câu được kiểm phải đạt, tỷ lệ đạt tối thiểu tám mươi lăm phần trăm, mọi câu không có nguồn phải biết từ chối và số lần bịa nguồn phải bằng không. Ngoài ra, các cổng về nguồn tài liệu, quyền dữ liệu và người duyệt đều phải được xác minh. Những ngưỡng này chỉ dùng cho bài tập; trong dự án thật, phải thiết kế bộ mẫu đủ đại diện và xác lập mức rủi ro chấp nhận được. Nếu thiếu một cổng, chưa mở thử cho người dùng rộng. Nếu phát hiện câu bịa nguồn, dừng triển khai và sửa nguyên nhân trước khi thử lại."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('900815a8-25b9-5d25-991d-a0674b02dd07', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 3, 'EL-037-V37.3', 'VIDEO 37.3: THỰC HÀNH KIỂM THỬ TRỢ LÝ VÀ RA QUYẾT ĐỊNH CÓ KIỂM SOÁT', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Đọc cấu trúc phiếu ba phần", "handwriting": "Di con trỏ qua D-G ô vàng, H-I ô kết quả; không sửa công thức.", "slideContent": "Mở PHIẾU THỰC HÀNH; A: 7 mẫu, B: chỉ số; C: cổng bắt buộc.", "lectureScript": "Bây giờ mở sheet PHIẾU THỰC HÀNH. Vùng A gồm bảy tình huống từ T một tới T bảy. Mỗi hàng ghi câu hỏi và kết quả cần kiểm. Cột D nói có nguồn trong kho được phép dùng hay không. Cột E ghi loại phản hồi của trợ lý. Cột F kiểm phiên bản nguồn, cột G là kết luận của người duyệt; đây đều là ô vàng có thể thay theo tình huống thực tế. Hai cột H và I tự tính kết quả và hành động tiếp theo. Vùng B tổng hợp chỉ tiêu, vùng C là các cổng quyết định."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Kiểm đúng cả câu có và không có nguồn", "handwriting": "Đổi T4 sang Đúng + dẫn khi không có nguồn để thấy bị chấm 0.", "slideContent": "T1,T2,T5,T6 trả lời đúng có dẫn; T4 từ chối đúng; T3 và T7 sai.", "lectureScript": "Theo dữ liệu mẫu, T một, T hai, T năm và T sáu có nguồn, trả lời đúng và có dẫn chiếu. T bốn không có nguồn, trợ lý từ chối phù hợp, nên cũng được một điểm. T ba thiếu căn cứ trong câu trả lời; T bảy lại tự bịa mã tài liệu. Anh chị hãy thử đổi T bốn thành loại “đúng có dẫn” dù nguồn đã ghi không có. Bảng phải trả về không điểm, vì không thể có dẫn chứng hợp lệ từ một nguồn không tồn tại trong kho đã kiểm."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-3", "sceneName": "Tính tỷ lệ và ngưỡng tiếp tục", "handwriting": "Hiện phép chia 5/7, so với ngưỡng; đánh dấu không đạt.", "slideContent": "Màn hình: đã kiểm 7, đạt 5, tỷ lệ 71,4%, ngưỡng 85%; từ chối đúng 1/2.", "lectureScript": "Ở vùng chỉ số, số mẫu có kết quả là bảy, số mẫu đạt là năm. Tỷ lệ đạt bằng năm chia bảy, xấp xỉ bảy mươi mốt phẩy bốn phần trăm, thấp hơn ngưỡng giả định tám mươi lăm phần trăm. Riêng nhóm câu hỏi không có nguồn, chỉ một trong hai câu được từ chối đúng, tức năm mươi phần trăm. Không được lấy số câu trả lời nghe trôi chảy làm mẫu số thay cho số câu đã được người duyệt đánh giá. Nếu một hàng còn “chưa kiểm”, công thức phải báo chưa đủ bộ mẫu thay vì tự quy hàng đó là đáp án sai."}, {"layout": "L3", "popupQuiz": "Q5", "sceneCode": "V3-4", "sceneName": "Xử lý câu bịa nguồn và cập nhật", "handwriting": "Thử đổi T7 thành Từ chối đúng và người duyệt Đạt để xem tỷ lệ đổi; sau đó hoàn tác.", "slideContent": "T7 Bịa nguồn -> chỉ số bịa = 1; đặt điều kiện bằng 0; Q5.", "lectureScript": "Cột lỗi nghiêm trọng đang ghi một lần bịa nguồn, trong khi ngưỡng của bài là không. Vì thế quyết định trước hết phải là chặn mở rộng và rà soát nguồn, câu nhắc, bộ lọc cùng nhật ký. Anh chị có thể mô phỏng một lần sửa: đổi loại phản hồi của T bảy thành từ chối đúng và kết luận người duyệt thành đạt. Khi đó, điểm đạt tăng, tỷ lệ từ chối câu thiếu nguồn được cải thiện. Nhưng con số mới chỉ chứng minh các ô bài tập đã thay; ngoài thực tế phải chạy lại hệ thống trên câu hỏi độc lập và có biên bản xác nhận."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-5", "sceneName": "Ba cổng không cộng vào điểm nội dung", "handwriting": "Đổi D28 từ Chưa kiểm sang Đã kiểm, xem kết quả vẫn bị chặn khi có bịa.", "slideContent": "Ba cổng: chủ tài liệu, phân quyền dữ liệu, phê duyệt vận hành; D28 mặc định Chưa kiểm.", "lectureScript": "Vùng C có ba cổng: nguồn SOP phải có người chịu trách nhiệm, quyền sử dụng và lưu trữ dữ liệu phải được kiểm, và đầu ra có người phê duyệt. Trong tình huống, cổng quyền dữ liệu vẫn là chưa kiểm. Bởi vậy ngay cả khi giả lập sửa đủ bảy câu, bảng cũng không tự cho phép mở rộng nếu cổng này chưa hoàn tất. Trong dự án thật, trạng thái chỉ được đổi khi đã có tài liệu phê duyệt và người có thẩm quyền xác nhận. Hãy giữ ranh giới giữa một bài tập có điểm và một quyết định triển khai thực tế."}, {"layout": "L2 + L3", "popupQuiz": "Q6", "sceneCode": "V3-6", "sceneName": "Đề xuất sửa và phép thử lại", "handwriting": "Vẽ 4 bước và Q6 ở cuối cảnh.", "slideContent": "Hành động: sửa nguồn và quyền, tạo câu không nguồn mới, kiểm lại T3/T7, phê duyệt theo cấp.", "lectureScript": "Thứ nhất, xác minh vì sao T ba thiếu dẫn chiếu: lỗi tìm kiếm, phiên bản tài liệu hay cách tổng hợp câu trả lời. Thứ hai, điều tra câu T bảy bịa mã nguồn và bổ sung bộ kiểm câu hỏi nằm ngoài tài liệu. Thứ ba, hoàn thiện cổng quyền dữ liệu, nhật ký truy cập và giới hạn người dùng thử. Cuối cùng, khóa một bộ câu mới, không trùng hoàn toàn bộ đã dùng để sửa, rồi mời người sở hữu SOP đánh giá lại. Nếu các điều kiện đạt, chỉ đề xuất một thử nghiệm giới hạn có giám sát; chưa tự động đưa trợ lý vào toàn bộ hoạt động quản trị."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Sản phẩm nộp và tự chấm", "handwriting": "Trỏ lần lượt 8 sheet và nhắc 10 trắc nghiệm, 3 bài viết, 7 tiêu chí tự chấm.", "slideContent": "Checklist: brief, 7 mẫu, 4 chỉ số, 3 cổng, 2 lỗi cần sửa, người duyệt.", "lectureScript": "Sản phẩm cuối bài gồm brief nhiệm vụ, danh mục nguồn có phiên bản, một bộ câu thử có cả trường hợp không có nguồn, bảng đối chiếu với người duyệt và danh sách hành động khắc phục. Trong file, anh chị hãy làm mười câu trắc nghiệm tự chấm, ba nhiệm vụ viết và bảy tiêu chí tự đánh giá. Đừng chỉ báo tỷ lệ đạt chung; phải nêu riêng lỗi bịa nguồn và việc từ chối đúng khi thiếu căn cứ. Nội dung của trợ lý là đề xuất hỗ trợ con người, không thay quy trình quản lý chất lượng hay quyền quyết định của doanh nghiệp."}]', '2026-11-10 03:39:59.831852+00');
