INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('fa3153af-ebf9-5883-9816-0e254526598f', '45adeb6d-9960-5956-b29c-defd86eba6dc', 1, 'EL-048-V48.1', 'VIDEO 48.1: TỪ KẾT QUẢ NGHIÊN CỨU ĐẾN ĐỀ XUẤT GIÁ TRỊ CÓ KHÁCH HÀNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Mở bài: nghiên cứu chưa phải hàng bán", "handwriting": "Lộ trình: chứng minh nhu cầu -> giá trị -> demo -> bước tiếp; chưa có doanh thu.", "slideContent": "Hai cột: KẾT QUẢ NGHIÊN CỨU và GIẢI PHÁP KHÁCH MUA; câu hỏi: khách hàng giải quyết được việc gì?", "lectureScript": "Một nhóm nghiên cứu có thể làm ra nguyên mẫu chạy tốt trong phòng thử nghiệm nhưng vẫn chưa có sản phẩm để doanh nghiệp quyết định mua. Vấn đề không nằm ở số slide giới thiệu, mà ở chỗ khách hàng cần xử lý việc gì, cần bằng chứng nào, ai chịu trách nhiệm thử và ai có quyền ra quyết định. Trong bài này, chúng ta theo dõi nhóm Sao Mai với một bộ cảm biến rung và phần mềm ghi tín hiệu. Tên nhóm, sản phẩm và mọi con số đều là giả định. Mục tiêu cuối cùng là tạo một phiên trình diễn cho khách hàng có thể kiểm chứng, cùng một danh sách việc phải làm sau buổi gặp."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Bắt đầu từ vấn đề khách hàng", "handwriting": "Hiện ba câu: sự cố nào, lặp bao lâu, hậu quả vận hành gì; không vẽ AI dự báo.", "slideContent": "Quy trình đóng gói: băng tải rung, giờ dừng máy, người ghi nhận; đánh dấu dữ kiện cần hỏi.", "lectureScript": "Hãy hình dung cơ sở đóng gói cà phê An Bình thường xuyên phải dừng băng tải nhưng chưa có nhật ký tín hiệu đủ chi tiết để đối chiếu nguyên nhân. Nhóm Sao Mai muốn giới thiệu cảm biến rung. Nếu mở đầu bằng độ nhạy của cảm biến và sơ đồ kết nối, người quản lý nhà máy có thể vẫn chưa thấy lý do trao đổi tiếp. Cách đặt vấn đề tốt hơn là hỏi số lần dừng, thời gian mất, dữ liệu hiện có và điều kiện lắp đặt. Những câu hỏi ấy cần người vận hành xác nhận. Không có đường cơ sở, một đoạn đồ thị đẹp chưa chứng minh được máy chạy tốt hơn."}, {"layout": "L2 + L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Viết đề xuất giá trị có giới hạn", "handwriting": "Dùng bút chuyển câu “giảm 30% hỏng máy” thành một giả thuyết cần kiểm.", "slideContent": "Cấu trúc: khách hàng - công việc - kết quả quan sát - bằng chứng - giới hạn.", "lectureScript": "Đề xuất giá trị không nhất thiết là lời hứa giảm một tỷ lệ hỏng máy. Với trường hợp này, có thể viết: bộ cảm biến giúp ghi lại tín hiệu rung tại vị trí đã thống nhất để đội bảo trì so sánh với thời điểm dừng băng tải. Giá trị cần kiểm là khả năng thu được dữ liệu có ích cho chẩn đoán, chứ chưa phải giảm sự cố hay tiết kiệm chi phí. Nếu muốn tuyên bố giảm thời gian dừng, phải có thiết kế đo trước và sau với điều kiện đủ so sánh. Một bản chào có giới hạn sẽ đáng tin hơn lời khẳng định mà nhóm nghiên cứu chưa thể chứng minh."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Bốn mức độ dễ bị nhầm", "handwriting": "Mũi tên tiến độ có cổng xác minh; không thể hiện là đã qua mọi giai đoạn.", "slideContent": "Thẻ: nghiên cứu - mẫu trình diễn - PoC - thí điểm; dưới mỗi thẻ ghi câu hỏi cần trả lời.", "lectureScript": "Kết quả nghiên cứu cho biết một nguyên lý có cơ sở hoặc một thuật toán chạy được trong điều kiện nhất định. Mẫu trình diễn giúp khách hàng nhìn thấy một chức năng cụ thể. PoC kiểm tra giả thuyết kỹ thuật trong phạm vi hẹp; thí điểm xem công nghệ vận hành thế nào tại môi trường thật qua nhiều ca hoặc nhiều tuần. Mỗi bước có bằng chứng khác nhau. Một video ghi hình buổi demo không thay thế dữ liệu của PoC, và PoC đạt cũng không tự tạo ra hợp đồng bán hàng. Khi giới thiệu, hãy ghi rõ nhóm đang ở bước nào, những phép thử nào đã làm và điều kiện nào vẫn chưa kiểm."}, {"layout": "L2 + L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Chọn nhóm khách hàng phù hợp", "handwriting": "Cho thấy khác nhau giữa người dùng, người duyệt kỹ thuật và người mua; bật Q2.", "slideContent": "Ba chân dung: bảo trì đóng gói; bảo trì máy quay; kho lạnh cần nhiệt độ; không phải ai cũng phù hợp.", "lectureScript": "Không phải khách hàng có nhà máy đều là khách hàng của cảm biến rung. Với băng tải hoặc trục quay, câu hỏi về tín hiệu rung có thể phù hợp. Với kho lạnh chỉ muốn đo nhiệt độ hàng hóa, nhóm cần kiểm lại nhu cầu trước khi giới thiệu. Trong mỗi doanh nghiệp, người thao tác và người quyết định mua thường không phải một người. Đội bảo trì có thể đánh giá dữ liệu, IT cần kiểm truy cập, còn bộ phận mua sắm xem điều kiện hợp đồng. Vì vậy, một đầu mối tỏ ra thích công nghệ mới chỉ là tín hiệu ban đầu. Chúng ta phải tìm được vấn đề cụ thể và người có quyền xác nhận bước tiếp."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Giao bài: brief trình diễn một trang", "handwriting": "Dừng ở sáu ô mẫu, chuyển sang video trình diễn.", "slideContent": "Biểu mẫu 1 trang: đối tượng, vấn đề, chỉ tiêu, dữ liệu, giới hạn, người phê duyệt.", "lectureScript": "Trước khi đặt lịch trình diễn, hãy viết brief một trang gồm sáu nội dung. Đầu tiên là khách hàng và công đoạn mà họ muốn cải thiện. Tiếp đến là chỉ tiêu có thể đo, chẳng hạn tỷ lệ ghi nhận được sự kiện dừng đã được người vận hành đánh dấu. Ghi thiết bị và dữ liệu cần cung cấp, bối cảnh nơi đặt cảm biến, giới hạn mà buổi demo không trả lời được. Cuối cùng là người kiểm kết quả và người quyết định cho thử tiếp. Nếu chưa trả lời được ba mục cuối, đừng dùng buổi gặp để thay cho việc khảo sát. Video sau chúng ta sẽ biến brief thành kịch bản chứng minh."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('5fb4475b-4c2f-5436-9fbe-46757059b7dd', '45adeb6d-9960-5956-b29c-defd86eba6dc', 2, 'EL-048-V48.2', 'VIDEO 48.2: THIẾT KẾ TRÌNH DIỄN CÔNG NGHỆ CÓ BẰNG CHỨNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Demo là phép kiểm, không phải buổi giới thiệu", "handwriting": "Tách phần giới thiệu 5 phút khỏi phần quan sát và hỏi đáp.", "slideContent": "Mục tiêu trước/sau: thấy dữ liệu rung, đồng bộ thời điểm dừng, ghi nhật ký.", "lectureScript": "Một buổi trình diễn hiệu quả cho khách hàng doanh nghiệp phải để khách hàng tự trả lời một câu hỏi kỹ thuật. Đó không phải là việc người bán nói hết tính năng trong ba mươi phút. Với bộ cảm biến Sao Mai, mục tiêu mẫu có thể là chứng minh thiết bị ghi được chuỗi tín hiệu rung, hiển thị mốc thời gian và xuất dữ liệu để đội bảo trì đối chiếu. Đây chỉ là kết quả cần kiểm, chưa phải kết quả đã đạt. Buổi trình diễn nên ngắn, có người vận hành của khách hàng tham gia, có tiêu chí lập trước, và có biên bản ghi cả điều chưa thành công."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Thiết kế phép thử và đối chứng", "handwriting": "Zoom vào đồng hồ và mã sự kiện; đánh dấu sai lệch thời gian cần làm rõ.", "slideContent": "Ba bước: tín hiệu vào - nhật ký tham chiếu - kết quả đối chiếu; trường ngày/giờ/đơn vị.", "lectureScript": "Hãy thống nhất một phép thử dễ quan sát. Người vận hành tạo một số sự kiện dừng giả lập đã được cho phép, lưu thời điểm trong nhật ký tham chiếu, rồi so với dữ liệu cảm biến. Hai nguồn phải cùng mốc thời gian, cùng thiết bị và cùng đơn vị. Nếu giờ của thiết bị lệch so với nhật ký, phải ghi rõ trước khi tính kết quả. Đừng chọn trước những đoạn tín hiệu đẹp nhất để trình diễn. Nếu một thao tác có rủi ro an toàn, dùng dữ liệu mô phỏng hoặc môi trường thử được phê duyệt thay vì cố tạo sự cố ngay trên dây chuyền đang sản xuất."}, {"layout": "L2 + L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Chốt tiêu chí chấp nhận trước demo", "handwriting": "Đánh dấu tiêu chí trước khi bật video demo; bật Q3.", "slideContent": "Mẫu: nhận đủ sự kiện thử, xuất log, độ trễ, phương pháp đối chiếu, người kiểm.", "lectureScript": "Giả sử khách hàng đặt tiêu chí thử là phát hiện và ghi nhận đúng ít nhất chín trong mười sự kiện đã gắn nhãn. Ngưỡng chín trên mười chỉ để luyện tập, không đại diện cho yêu cầu kỹ thuật của ngành nào. Nhóm phải nói rõ thế nào là đúng, ai tạo nhật ký tham chiếu, xử lý mẫu hỏng ra sao và có kiểm tra trường hợp hệ thống báo nhầm hay không. Tính cả số lần phát hiện sai mới giúp diễn giải công bằng. Tiêu chí được thống nhất trước khi chạy thử; đổi ngưỡng sau khi thấy kết quả sẽ làm mất ý nghĩa của phép kiểm."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Trình diễn trung thực khi kết quả chưa đạt", "handwriting": "Trình bày cả chỉ số bỏ sót và báo nhầm, ghi dữ liệu minh họa.", "slideContent": "Bảng thử giả định: 10 sự kiện, 8 phát hiện đúng, 2 bỏ sót, 1 báo nhầm.", "lectureScript": "Trong ví dụ giả định, mười sự kiện đã được đánh dấu, hệ thống ghi đúng tám và bỏ sót hai; đồng thời có một cảnh báo không trùng sự kiện tham chiếu. Nếu tiêu chí là ít nhất chín trên mười, kết quả này chưa đạt. Không được biến số tám thành chín bằng cách loại một mẫu khó mà không giải thích. Nhóm nghiên cứu nên hỏi khách điều kiện hiện trường, xem lại vị trí cảm biến và cách đồng bộ thời gian, rồi hẹn thử lại bằng bộ mẫu thống nhất. Một demo thất bại ở tiêu chí cụ thể vẫn có giá trị vì nó chỉ ra điều phải sửa trước khi mời khách hàng bỏ nguồn lực vào thí điểm."}, {"layout": "L2 + L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Dữ liệu, quyền công nghệ và an toàn", "handwriting": "Cho ô quyền công nghệ Chưa kiểm; bật Q4; không dùng mã nguồn thật.", "slideContent": "Ba cổng: quyền trình diễn, quyền dữ liệu khách, quy trình an toàn tại nơi lắp.", "lectureScript": "Một bản trình diễn đẹp không cho phép nhóm bỏ qua quyền sở hữu trí tuệ. Cần kiểm ai có quyền khai thác kết quả nghiên cứu, phạm vi được giới thiệu, dữ liệu nào thuộc khách hàng và ai có quyền nhận bản xuất. Trường hợp có nhiều đơn vị tham gia nghiên cứu, quyền công bố và thương mại hóa có thể không thuộc riêng người thuyết trình. Nếu cần bí mật kỹ thuật, hãy dùng phiên bản demo có kiểm soát thay vì gửi toàn bộ hồ sơ hoặc mã nguồn. Bên cạnh đó, không lắp thử thiết bị vào máy đang chạy nếu chưa có người có thẩm quyền phê duyệt điều kiện an toàn."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Biên bản demo và đề nghị bước kế", "handwriting": "Hiện 2 cột: sự kiện đã đo và phát biểu cần xác minh; sang video 3.", "slideContent": "Biên bản: mục tiêu, dữ liệu, kết quả, giới hạn, người duyệt, việc kế, hạn.", "lectureScript": "Cuối phiên, hãy dành vài phút cho biên bản. Ghi điều kiện thử, bộ dữ liệu, kết quả theo từng tiêu chí, những lỗi phát hiện và mức độ chấp nhận của khách hàng. Tách hai câu: khách thấy chức năng có ích và khách cam kết chi tiền. Câu thứ hai chỉ có giá trị khi đi kèm thẩm quyền, điều khoản và tài liệu thích hợp. Nếu buổi demo mở ra khả năng thử tiếp, hãy đề nghị một cuộc thẩm định phạm vi, người kiểm và chi phí thử nghiệm; không ghi vào báo cáo là đã bán được hàng. Ở video cuối, chúng ta lập phễu theo dõi sáu đầu mối mà không phóng đại tín hiệu."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('899353dc-7e93-5de1-bb47-f81502c19e2a', '45adeb6d-9960-5956-b29c-defd86eba6dc', 3, 'EL-048-V48.3', 'VIDEO 48.3: ĐỌC PHỄU KHÁCH HÀNG VÀ QUYẾT ĐỊNH BƯỚC THƯƠNG MẠI HÓA', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L3", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Mở phiếu phễu khách hàng", "handwriting": "Quét các ô vàng D-G và ô trạng thái H, I là bước tiếp.", "slideContent": "Sheet PHIẾU THỰC HÀNH: A 6 đầu mối, B chỉ số, C ba cổng.", "lectureScript": "Mở sheet PHIẾU THỰC HÀNH. Phần A là sáu đầu mối khách hàng hoàn toàn giả định, mỗi đầu mối có một vấn đề vận hành. Cột D kiểm việc khách đã xác nhận nhu cầu hay chưa. Cột E hỏi hai bên đã chốt tiêu chí trình diễn chưa. Cột F là kết quả demo theo tiêu chí; cột G kiểm có người ra quyết định tham gia không. Cột H là trạng thái suy ra từ bốn thông tin ấy. Hãy sửa dữ liệu tại ô vàng và để nguyên các ô có công thức. Chưa tính doanh thu."}, {"layout": "L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Đọc sáu trường hợp như một phễu", "handwriting": "Hiện COUNTA/COUNTIFS, giữ chung mẫu số và tránh gọi là doanh số.", "slideContent": "Bảng: sáu đầu mối, bốn nhu cầu xác nhận, bốn demo có tiêu chí, ba demo đạt, hai ứng viên.", "lectureScript": "Với bộ dữ liệu mẫu, có sáu đầu mối, bốn trường hợp đã xác nhận nhu cầu, bốn phiên có tiêu chí trình diễn và ba phiên ghi kết quả đạt. Chỉ hai đầu mối vừa có nhu cầu, vừa có tiêu chí, demo đạt và có người quyết định tham gia. Họ là ứng viên cho bước thẩm định tiếp, chưa phải khách hàng đã mua. Nếu dùng tỷ lệ hai trên sáu, bạn phải nói rõ đó là tỷ lệ ứng viên trong danh sách nhỏ này, không phải tỷ lệ chuyển đổi thị trường. "}, {"layout": "L2 + L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Tại sao điểm số chưa đủ bước thương mại", "handwriting": "Bật Q5; chuyển trạng thái quyền từ Chưa kiểm sang Đã kiểm, chỉ sau bằng chứng.", "slideContent": "Hai người được đánh dấu ứng viên, ba cổng độc lập ở D27-D29.", "lectureScript": "Giả sử An Bình và một xưởng cơ khí có kết quả demo đạt. Bảng vẫn chưa cho phép mời thử vì cổng quyền khai thác kết quả nghiên cứu chưa được xác minh. Chúng ta cũng chưa chốt người có quyền duyệt đề nghị thương mại và điều khoản thử. Tính đủ điều kiện là hai tầng: tín hiệu nhu cầu và bằng chứng kỹ thuật ở phần A, rồi các điều kiện pháp lý, dữ liệu và thẩm quyền ở phần C. Không có cách cộng điểm khách hàng để bù cho quyền sử dụng công nghệ chưa rõ. Đổi trạng thái phải kèm hồ sơ thật."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Phân biệt đề nghị thử, báo giá và hợp đồng", "handwriting": "Đánh dấu các yếu tố phải thẩm định: phạm vi, quyền, trách nhiệm, bảo mật, chi phí.", "slideContent": "Bậc 1: yêu cầu thử; bậc 2: điều kiện thử; bậc 3: đề xuất giá; bậc 4: ký kết.", "lectureScript": "Sau khi có ứng viên, bước hợp lý có thể là gửi đề nghị thẩm định hoặc PoC có giới hạn. Đề nghị này nêu câu hỏi cần trả lời, thời gian, dữ liệu và người chấp thuận. Báo giá là một tài liệu khác; nó phải dựa trên phạm vi cung cấp, bảo hành, hỗ trợ và điều kiện sử dụng đã làm rõ. Hợp đồng còn cần kiểm quyền sở hữu trí tuệ, trách nhiệm nghiệm thu, giới hạn dữ liệu và thẩm quyền ký. Các điều kiện này phải thương thảo riêng; bài sau sẽ đi sâu về hợp đồng và định giá."}, {"layout": "L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Thử độ nhạy bằng thay trạng thái", "handwriting": "Ghi trước/sau số ứng viên và kết luận; bật Q6.", "slideContent": "Thử ba thao tác: sửa demo K4 Chưa đạt thành Đạt; gỡ người quyết định K6; hoàn tất cổng.", "lectureScript": "Bây giờ hãy thử ba thao tác. Trước hết đổi kết quả K4 từ Chưa đạt sang Đạt và xem trạng thái có chuyển hay không. Tiếp đến đổi cột người quyết định của K6 sang Chưa; số ứng viên sẽ giảm, dù demo vẫn đạt. Cuối cùng thử hoàn tất cả ba cổng ở phần C và xem thông báo thay đổi từ còn điều kiện sang danh sách thẩm định. Chọn trạng thái chỉ mô phỏng; không tạo ra bằng chứng ngoài đời."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Lập danh sách hành động theo chủ và hạn", "handwriting": "Điền ai làm, tài liệu gì, hạn nào và tiêu chí hoàn thành.", "slideContent": "Kế hoạch: xác minh quyền nghiên cứu, thử lại tín hiệu, thống nhất bộ mẫu, xin chấp thuận thử.", "lectureScript": "Một danh sách cơ hội có ích phải đi kèm hành động. Với K1, nhóm phụ trách cần xin xác nhận quyền triển khai thử và thỏa thuận bộ mẫu do khách kiểm. Với K4, trước tiên cần khắc phục lỗi trình diễn, không gửi một đề nghị mua sắm. Với K3, hãy quay lại tìm hiểu nhu cầu trước khi đặt cảm biến. Mỗi công việc phải có người chịu trách nhiệm, hạn và bằng chứng kết thúc; nếu không, sau buổi demo tất cả dễ trở lại trạng thái “đang trao đổi”. Chuyển các việc còn mở vào kế hoạch theo dõi."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Nộp bộ hồ sơ và tự chấm", "handwriting": "Hiện đường đến BÀI TẬP TỰ LUYỆN, TỰ CHẤM, HỎI ĐÁP.", "slideContent": "Checklist: brief, kịch bản demo, kết quả, phễu sáu đầu mối, ba cổng, kế hoạch tiếp.", "lectureScript": "Để kết thúc, bạn nộp một bộ hồ sơ gọn: brief đề xuất giá trị cho khách hàng, kịch bản trình diễn có tiêu chí đo, biên bản cho biết điều đạt và chưa đạt, bảng theo dõi sáu đầu mối và danh sách việc tiếp theo. Đặc biệt hãy chỉ rõ còn thiếu quyền khai thác nào, dữ liệu nào chưa được phép dùng và ai có thẩm quyền chấp nhận thử tiếp. Làm mười câu trắc nghiệm, ba câu viết và tự chấm theo bảy tiêu chí. Chỉ khi bằng chứng và điều kiện được giải quyết, nhóm mới có cơ sở đề xuất bước thương mại tiếp. Đừng đổi sự quan tâm trong buổi gặp thành một khoản doanh thu tưởng tượng."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('084f818a-9dc2-5812-8d5f-deb3fe8830c2', '641a0564-4c0a-553d-b485-2857b82f7131', 1, 'EL-049-V49.1', 'VIDEO 49.1: XÁC ĐỊNH ĐỐI TƯỢNG, PHẠM VI QUYỀN VÀ CHỦ THỂ HỢP ĐỒNG', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-1", "sceneName": "Từ buổi demo đến câu hỏi về quyền", "handwriting": "Cho hai ô tách nhau, nối bằng cổng hồ sơ, không dùng biểu tượng hợp đồng đã ký.", "slideContent": "Hai ô: ĐÃ DEMO và QUYỀN SỬ DỤNG; nêu bên có quyền, tài sản và công việc sau demo.", "lectureScript": "Ở bài trước, nhóm nghiên cứu Sao Mai đã trình diễn cảm biến rung cho một số doanh nghiệp. Một bản demo có khách quan tâm vẫn chưa cho biết bên nghiên cứu có quyền chuyển giao những gì, và doanh nghiệp mua chính xác quyền nào. Hôm nay chúng ta dùng tình huống giả định: An Bình muốn triển khai bộ cảm biến, phần mềm đọc tín hiệu và tài liệu kỹ thuật. Trước khi nói về giá, hai bên phải trả lời ai có quyền quyết định, sản phẩm công nghệ gồm những thành phần nào và kết quả nghiệm thu được xác nhận bằng cách nào. Hợp đồng không thể sửa được một quyền mà bên chuyển giao vốn không sở hữu."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-2", "sceneName": "Tách đối tượng chuyển giao thành từng thành phần", "handwriting": "Mỗi thẻ nối với hồ sơ nguồn gốc, phiên bản và điều kiện cung cấp.", "slideContent": "Năm thẻ: cấu hình cảm biến, phần mềm, mã nguồn, hướng dẫn vận hành, bí quyết hiệu chuẩn.", "lectureScript": "Hãy liệt kê bộ giải pháp Sao Mai thành những phần có thể kiểm đếm. Phần cứng cảm biến cần số lượng và cấu hình. Phần mềm cần phiên bản, điều kiện sử dụng và quyền cập nhật. Mã nguồn có thể không nằm trong phạm vi cấp phép, còn bí quyết hiệu chuẩn cần cách đào tạo, hồ sơ kiểm tra và giới hạn tiết lộ. Tài liệu hướng dẫn cũng là hạng mục bàn giao chứ không phải một lời hứa mơ hồ. Nếu chỉ ghi chuyển giao công nghệ cảm biến rung, người mua có thể kỳ vọng toàn bộ mã nguồn trong khi bên cung cấp chỉ dự định trao quyền vận hành phần mềm. Sai lệch này phải được giải quyết ở bước mô tả đối tượng."}, {"layout": "L2 + L3", "popupQuiz": "Q1", "sceneCode": "V1-3", "sceneName": "Cấp phép khác với chuyển nhượng", "handwriting": "Gạch chân các câu hỏi: ai sở hữu, ai được dùng, có chuyển cho bên thứ ba không.", "slideContent": "Bảng so sánh: cấp quyền sử dụng, chuyển nhượng quyền, chuyển giao bí quyết; ô phạm vi và chủ thể.", "lectureScript": "Trong cấp phép, bên nhận thường được sử dụng đối tượng theo phạm vi thỏa thuận; việc cấp phép không mặc nhiên làm chủ sở hữu quyền thay đổi. Chuyển nhượng quyền là một giao dịch khác, cần xác định đối tượng có thể chuyển nhượng và chủ thể có quyền định đoạt. Với bí quyết, điều người mua nhận còn phụ thuộc cách cung cấp, đào tạo và bảo mật. Đối với Sao Mai, hãy hỏi quyền dùng phần mềm chỉ trong một nhà máy hay nhiều cơ sở, có quyền sửa không, có được cho đơn vị tích hợp khác truy cập không và quyền sử dụng kéo dài bao lâu. Các câu trả lời này ảnh hưởng trực tiếp đến cả giá và rủi ro."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V1-4", "sceneName": "Phạm vi quyền phải có biên giới rõ", "handwriting": "Hiện ví dụ chỉ áp dụng tại một dây chuyền của An Bình, không tự bao gồm doanh nghiệp khác.", "slideContent": "Ma trận: lãnh thổ, ngành, thời hạn, số cơ sở, độc quyền, quyền cấp lại, dữ liệu.", "lectureScript": "Hai bên có thể đồng ý một giấy phép sử dụng nhưng bất đồng về phạm vi. Ví dụ An Bình muốn triển khai trên một dây chuyền đóng gói trong ba năm; sau đó mới xem xét mở rộng. Khi ấy phải nêu rõ phạm vi sử dụng, số điểm cài đặt, thời hạn, cập nhật phiên bản và cách xử lý khi hết hạn. Điều khoản độc quyền có thể làm thay đổi khả năng Sao Mai phục vụ khách khác, nên không nên đưa vào chỉ vì một bên yêu cầu. Dữ liệu rung do hệ thống thu thập cũng cần quy định ai kiểm soát, ai được xem và khi chấm dứt hợp đồng thì sao. Không nội dung nào nên suy ra từ một câu nói trong cuộc gặp."}, {"layout": "L2 + L3", "popupQuiz": "Q2", "sceneCode": "V1-5", "sceneName": "Kiểm tra ai thực sự có quyền ký", "handwriting": "Đặt cổng kiểm chứng hồ sơ trước cột Chữ ký; hiển thị Q2.", "slideContent": "Sơ đồ nhóm nghiên cứu, tổ chức chủ quản, đồng sở hữu, người được ủy quyền.", "lectureScript": "Người trình diễn giỏi nhất không nhất thiết là người có quyền ký. Kết quả nghiên cứu có thể hình thành từ đề tài dùng nguồn lực của tổ chức, từ hợp đồng với đối tác hoặc từ đóng góp của nhiều tác giả. Với mỗi thành phần, cần kiểm tài liệu thể hiện quyền sở hữu, quyền khai thác và người được ủy quyền. Tôi không dùng một quy tắc sở hữu duy nhất cho mọi kết quả, vì nguồn hình thành và loại quyền có thể khác nhau. Nếu Sao Mai chưa có hồ sơ quyền đối với phần mềm và dữ liệu hiệu chuẩn, An Bình không nên thay việc xác minh đó bằng một cam kết miệng. Hãy đưa trạng thái vào danh sách điều kiện trước ký."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V1-6", "sceneName": "Đầu ra video một: khung đối tượng và quyền", "handwriting": "Chụp mẫu có dòng chưa xác minh, không hiển thị dấu đóng hoàn thành.", "slideContent": "Mẫu term sheet bốn dòng: đối tượng, chủ thể, phạm vi, ngoại lệ.", "lectureScript": "Sau video này, bạn cần viết bốn dòng đầu của bản điều khoản sơ bộ. Dòng thứ nhất nêu rõ thành phần công nghệ và phiên bản. Dòng thứ hai ghi bên dự kiến có quyền chuyển giao, kèm tài liệu phải kiểm. Dòng thứ ba xác định An Bình được sử dụng ở đâu, trong bao lâu và cho mục đích gì. Dòng thứ tư liệt kê quyền không tự động bao gồm, chẳng hạn mã nguồn, quyền sửa phần mềm hoặc quyền cấp phép lại. Những chỗ chưa có chứng cứ hãy ghi chưa kiểm. Đây là bản thảo để đàm phán, không phải hợp đồng hoàn chỉnh hay xác nhận rằng Sao Mai đã có mọi quyền cần thiết."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('dd7b04c6-eb54-5d95-8aaa-d8060b455828', '641a0564-4c0a-553d-b485-2857b82f7131', 2, 'EL-049-V49.2', 'VIDEO 49.2: ĐIỀU KHOẢN BÀN GIAO, NGHIỆM THU, HỖ TRỢ VÀ CẤU TRÚC GIÁ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-1", "sceneName": "Điều khoản kỹ thuật phải kiểm được", "handwriting": "Vẽ đường đi từ bàn giao đến nghiệm thu, mỗi đoạn có hồ sơ minh chứng.", "slideContent": "Bàn giao, lắp đặt, chạy thử, nghiệm thu, hỗ trợ, đào tạo thành các ô hành động.", "lectureScript": "Một hợp đồng chỉ ghi bên cung cấp sẽ bàn giao giải pháp hoàn chỉnh thì chưa đủ cho đội vận hành. An Bình cần biết ngày giao thiết bị, phiên bản phần mềm, quyền truy cập tài liệu, điều kiện lắp đặt và người xác nhận kết quả. Với cảm biến rung, tiêu chí nghiệm thu có thể là thu thập đúng tín hiệu từ vị trí đã chọn và xuất được nhật ký có dấu thời gian để so sánh với sự kiện dừng băng tải. Không nên ghi chắc chắn giảm bao nhiêu sự cố khi chưa có thử nghiệm đủ sức chứng minh. Điều khoản kỹ thuật nên gắn công việc được giao, tiêu chí đo và cách xử lý khi không đạt."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-2", "sceneName": "Nghiệm thu phải gắn người và phiên bản", "handwriting": "Đánh dấu khác biệt giữa kiểm giao đủ hàng và kiểm hiệu năng.", "slideContent": "Biên bản mẫu: cấu hình, bộ mẫu, ngưỡng, lỗi, thời gian thử, người ký xác nhận.", "lectureScript": "Hãy tách nghiệm thu bàn giao khỏi nghiệm thu tính năng. Kiểm giao đủ có thể dựa vào số lượng cảm biến, tài khoản phần mềm và tài liệu. Kiểm tính năng đòi dữ liệu thử, cách đo và ngưỡng được hai bên thống nhất trước. Nếu dùng mười sự kiện dừng đã được xác nhận mà hệ thống chỉ ghi đúng tám, kết luận phải đối chiếu với ngưỡng đã chốt, không sửa ngưỡng sau khi nhìn kết quả. Biên bản cần ghi cả lỗi bỏ sót và điều kiện đo. Khi thử lại, phiên bản phần mềm và dữ liệu mẫu phải được lưu. Cơ chế nghiệm thu giúp hai bên biết lúc nào đủ căn cứ thanh toán từng đợt."}, {"layout": "L2 + L3", "popupQuiz": "Q3", "sceneCode": "V2-3", "sceneName": "Hỗ trợ, bảo mật và rủi ro sau bàn giao", "handwriting": "Bật ba cột trách nhiệm của bên giao, bên nhận và việc cần thỏa thuận.", "slideContent": "Bảng trách nhiệm: đào tạo, cập nhật, sao lưu, phân quyền, an toàn, thay nhà cung cấp.", "lectureScript": "Sau nghiệm thu, công nghệ vẫn cần người vận hành, bảo trì và hỗ trợ. Hợp đồng nên xác định mức hỗ trợ, thời gian phản hồi, trách nhiệm khi lỗi xuất phát từ thiết bị hay từ mạng nội bộ. Với phần mềm, cần thỏa thuận cập nhật, lưu trữ dữ liệu, phân quyền và cách hoàn trả hoặc xóa dữ liệu khi chấm dứt. Nếu Sao Mai là bên duy nhất biết hiệu chuẩn cảm biến, An Bình phải cân nhắc yêu cầu đào tạo, tài liệu và phương án chuyển giao cho nhân sự kế nhiệm. Những nghĩa vụ này có chi phí và ảnh hưởng đến giá. Mỗi nghĩa vụ nên có hồ sơ kiểm, không chỉ có một đoạn mô tả thiện chí."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V2-4", "sceneName": "Cấu trúc giá phải đi cùng quyền và trách nhiệm", "handwriting": "Chiếu bảng giải thích mức phí giả định, không trình bày đây là báo giá thị trường.", "slideContent": "Ba lựa chọn: trả một lần, phí theo kỳ, phí theo sử dụng; sơ đồ mốc và quyền.", "lectureScript": "Giá công nghệ có thể được thương lượng bằng khoản trả ban đầu, khoản trả định kỳ hoặc một phần theo mức sử dụng hay doanh thu đã được định nghĩa. Nhưng các cách thu tiền không giống nhau về rủi ro. Trả trước nhiều làm người nhận cần quan tâm hơn đến điều kiện nghiệm thu. Phí biến đổi làm hai bên cần thống nhất cách xác định cơ sở tính phí, quyền kiểm tra số liệu và thời điểm đối soát. Với tình huống giả định, Sao Mai đề nghị phí quyền sử dụng ban đầu một trăm năm mươi triệu đồng và các khoản phí từng năm. Đây không phải giá chuẩn cho cảm biến rung. Một mức phí chỉ có ý nghĩa khi gắn với phạm vi quyền, nhiệm vụ hỗ trợ và lợi ích dự kiến."}, {"layout": "L2 + L3", "popupQuiz": "Q4", "sceneCode": "V2-5", "sceneName": "Ba cách tiếp cận định giá không cho một đáp án chắc chắn", "handwriting": "Dùng ba kính nhìn khác nhau; không tự suy ra giá từ chi phí nghiên cứu.", "slideContent": "So sánh chi phí, giao dịch tương tự và thu nhập; ghi dữ liệu cần có và giới hạn.", "lectureScript": "Có thể bắt đầu định giá từ chi phí tái tạo hoặc thay thế giải pháp, từ giao dịch có thể so sánh, hoặc từ thu nhập tăng thêm mà công nghệ có thể tạo ra. Mỗi cách đòi dữ liệu riêng. Chi phí làm ra nguyên mẫu không tự xác định mức khách hàng sẵn lòng trả. Một giao dịch khác cũng khó so sánh nếu quyền độc quyền, lãnh thổ hoặc nghĩa vụ hỗ trợ khác nhau. Với cách tiếp cận thu nhập, phải ước tính tiền vào, tiền ra, thời điểm xảy ra và mức rủi ro. Chúng ta dùng bảng năm năm để học phép tính, không gọi kết quả đó là giá trị pháp lý hay giá thị trường của công nghệ."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V2-6", "sceneName": "Gắn điều khoản với điều kiện thanh toán", "handwriting": "Kéo dấu nối từ mốc thanh toán đến biên bản nghiệm thu; kết phần hai.", "slideContent": "Term sheet đủ tám ô: quyền, bàn giao, nghiệm thu, hỗ trợ, bảo mật, giá, mốc trả, kiểm chứng.", "lectureScript": "Khi soạn term sheet, hãy nối các khoản thanh toán với công việc kiểm được. Ví dụ chỉ giải ngân một phần sau khi bàn giao tài liệu và hoàn thành huấn luyện, phần khác sau nghiệm thu tại vị trí lắp đặt đã thống nhất. Ghi cách khắc phục nếu thử không đạt, quyền xem dữ liệu để đối soát phí biến đổi và người có thẩm quyền ký xác nhận. Cần rà điều kiện an toàn, bảo mật và trách nhiệm khi chấm dứt. Một bảng điều khoản có thể giúp hai bên đàm phán rõ hơn, nhưng vẫn cần người có chuyên môn pháp lý rà soát hợp đồng và thủ tục pháp luật áp dụng trước khi ký."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('b6cb7206-5d3e-5fe8-851a-678e152f2f9f', '641a0564-4c0a-553d-b485-2857b82f7131', 3, 'EL-049-V49.3', 'VIDEO 49.3: TÍNH NPV, ĐÀM PHÁN GIÁ VÀ CHẶN KÝ KHI THIẾU HỒ SƠ', 240, NULL, NULL, NULL, '[{"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Vì sao phải chiết khấu dòng tiền", "handwriting": "Làm nổi số tiền gắn thời điểm, không gọi doanh thu là tiền thuần.", "slideContent": "Trục năm 0-5: phí trước, lợi ích sau; NPV là tổng giá trị hiện tại tiền thuần.", "lectureScript": "Bây giờ chuyển sang bài tính. Nếu An Bình trả khoản phí ban đầu hôm nay còn lợi ích đến trong năm năm sau, ta không thể cộng tiền năm thứ năm như tiền hiện tại mà không xét thời gian. Giá trị hiện tại ròng, gọi là NPV, quy đổi từng dòng tiền thuần về thời điểm đầu. Dòng tiền thuần bằng lợi ích tiền tăng thêm trừ chi phí vận hành bổ sung và phí chuyển giao trong cùng kỳ. Mô hình minh họa giả định các khoản trong năm xảy ra ở cuối năm, không xét thuế, lạm phát hay giá trị còn lại. Bạn cần giữ cùng một cơ sở tính khi so sánh phương án."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-2", "sceneName": "Lập dòng tiền trước khi xem NPV", "handwriting": "Đếm rõ năm 0: -180; năm 1: 78; năm 2: 90, tất cả giả định.", "slideContent": "Bảng 0-5 năm: lợi ích, chi phí ứng dụng, phí chuyển giao, tiền thuần, tiền quy đổi.", "lectureScript": "Ở năm không, giả định An Bình trả một trăm năm mươi triệu phí ban đầu và ba mươi triệu chi phí tích hợp, nên tiền thuần là âm một trăm tám mươi triệu. Năm một, giả định lợi ích tăng thêm một trăm mười lăm triệu, chi phí ứng dụng hai mươi lăm triệu và phí trả Sao Mai mười hai triệu, còn bảy mươi tám triệu. Các năm tiếp theo cho tiền thuần lần lượt là chín mươi, chín mươi bốn, chín mươi ba và tám mươi tám triệu đồng. Đây là những giả định để luyện cách đọc, không phải dự báo được phê duyệt. Mỗi khoản tiền cần có chủ dữ liệu và căn cứ trước khi dùng trong đàm phán."}, {"layout": "L2 + L3", "popupQuiz": "Q5", "sceneCode": "V3-3", "sceneName": "Đọc kết quả NPV và đổi giả định", "handwriting": "Minh họa đổi 12% sang 20% bằng một ô; không vẽ phân phối xác suất.", "slideContent": "Ô tỷ lệ chiết khấu 12%; NPV; kịch bản 20%; nhắc ngưỡng bằng không.", "lectureScript": "Với tỷ lệ chiết khấu giả định mười hai phần trăm, bảng cho NPV dương khoảng một trăm ba mươi bảy triệu đồng. Nếu tăng tỷ lệ lên hai mươi phần trăm, cùng các dòng tiền ấy, NPV giảm còn khoảng tám mươi hai triệu. Tính nhạy này cho biết kết quả phụ thuộc giả định rủi ro và thời gian. NPV dương chỉ có nghĩa dòng tiền của bên nhận trong mô hình vượt mức chiết khấu đặt ra; nó không chứng minh bên chuyển giao sở hữu đủ quyền, không xác nhận hiệu năng kỹ thuật và cũng không phải giá công nghệ duy nhất. Vì vậy, chúng ta đọc số cùng điều kiện hình thành nó."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-4", "sceneName": "Tính trần phí ban đầu có điều kiện", "handwriting": "Đặt trần và phí đề nghị cạnh nhau, ghi giả định giữ nguyên tất cả khoản khác.", "slideContent": "Dòng trần phí ở KPI P5: PV dòng tương lai trừ chi phí năm 0 không phải phí.", "lectureScript": "Một phép tính thương lượng là giữ nguyên lợi ích, chi phí và phí thường niên, rồi tìm mức phí ban đầu khiến NPV của bên nhận vừa bằng không. Bảng giả định cho trần khoảng hai trăm tám mươi bảy triệu, cao hơn mức đề nghị một trăm năm mươi triệu. Chênh lệch không có nghĩa nên trả thêm ngay. Rủi ro kỹ thuật, độ tin cậy của lợi ích, điều khoản độc quyền và giải pháp thay thế đều có thể khiến mức giá được chấp nhận thấp hơn."}, {"layout": "L2 + L3", "popupQuiz": "Q6", "sceneCode": "V3-5", "sceneName": "Ba cổng không được bù bằng NPV", "handwriting": "Hiện kết luận CHƯA ĐỦ CỔNG - CHƯA KÝ dù NPV dương.", "slideContent": "Ba cổng: quyền khai thác, hồ sơ nghiệm thu, thẩm quyền/pháp lý; hai cổng Chưa kiểm.", "lectureScript": "Ba cổng ở cuối phiếu gồm hồ sơ quyền chuyển giao, hồ sơ nghiệm thu kỹ thuật và thẩm quyền ký kèm rà soát pháp lý. Mặc định hai cổng chưa xác minh. Vì vậy, dù NPV dương, Excel vẫn báo chưa đủ cổng, chưa ký. Bảng tính không thay việc kiểm quyền hoặc thủ tục luật định. Ngay khi cả ba cổng đạt, trạng thái cũng chỉ là đủ điều kiện đưa sang thẩm định, không tự phê duyệt hợp đồng."}, {"layout": "L2 + L3", "popupQuiz": "", "sceneCode": "V3-6", "sceneName": "Kiểm độ nhạy và rủi ro thanh toán", "handwriting": "Lập danh sách việc chưa đóng theo người kiểm: tài chính, kỹ thuật, pháp chế.", "slideContent": "Ba câu kiểm: lợi ích giảm, phí tăng, nghiệm thu chậm; bảng người chịu trách nhiệm.", "lectureScript": "Thử độ nhạy không chỉ bằng tỷ lệ chiết khấu. Hãy giảm lợi ích từng năm hoặc tăng chi phí hỗ trợ rồi đọc NPV. Phí trả trước nghiệm thu còn tạo rủi ro thu hồi. Mỗi kịch bản cần ghi điều đã thay và ai xác minh. Nếu thiết bị chưa dùng được sau đào tạo, hoặc chưa rõ quyền đối với dữ liệu, dòng tiền mô hình không đủ làm căn cứ ký. Danh sách giả định lớn phải đi kèm bản thảo giá."}, {"layout": "L1 -> L2", "popupQuiz": "", "sceneCode": "V3-7", "sceneName": "Đầu ra cuối: term sheet và quyết định có điều kiện", "handwriting": "Kết tại cổng kiểm với chữ THẨM ĐỊNH, không ghi ĐÃ KÝ.", "slideContent": "Hai trang: term sheet chưa ký và bảng dòng tiền, có người nhận việc, hạn xác minh.", "lectureScript": "Kết thúc bài, bạn phải nộp hai phần. Phần một là term sheet tóm tắt đối tượng, phạm vi quyền, tiêu chí bàn giao nghiệm thu, đào tạo, bảo mật, cấu trúc phí và trách nhiệm khi chấm dứt. Phần hai là bảng tiền năm không đến năm năm, tỷ lệ chiết khấu, NPV và ít nhất một lần thử độ nhạy. Cuối phiếu phải có danh sách việc chưa xong: ai kiểm hồ sơ quyền, ai chốt mẫu nghiệm thu và ai rà thẩm quyền ký. Mục tiêu không phải hoàn tất hợp đồng trong lớp học, mà là biết chính xác còn thiếu điều gì trước khi cân nhắc ký kết."}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('b3f5877b-4c77-531d-8894-8aa0d1adda79', '4136304a-a901-53c0-a081-b528490e14dd', 1, 'EL-050-V1', 'Phần 1: Giới thiệu và Nguyên lý cốt lõi', 240, NULL, NULL, NULL, '[{"layout": "Đồ họa hoạt hình", "popupQuiz": "Q1", "sceneCode": "V1-1", "sceneName": "Mở đầu", "handwriting": "", "slideContent": "Khái niệm và định nghĩa", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('a9eb2c69-2cbc-59bf-b34e-b23d090a6655', '4136304a-a901-53c0-a081-b528490e14dd', 2, 'EL-050-V2', 'Phần 2: Phương pháp triển khai và Phân tích', 240, NULL, NULL, NULL, '[{"layout": "Slide tương tác", "popupQuiz": "Q2", "sceneCode": "V2-1", "sceneName": "Nội dung chính", "handwriting": "", "slideContent": "Các bước triển khai", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_micro_videos (id, material_id, video_order, video_code, title, duration_seconds, video_storage_key, video_file_name, thumbnail_url, call_sheet_json, created_at) VALUES ('22f1bb70-5775-5748-b838-46b343b33bca', '4136304a-a901-53c0-a081-b528490e14dd', 3, 'EL-050-V3', 'Phần 3: Bài học thực tiễn và Hành động', 240, NULL, NULL, NULL, '[{"layout": "Infographic tổng kết", "popupQuiz": "", "sceneCode": "V3-1", "sceneName": "Tóm tắt", "handwriting": "", "slideContent": "3 điểm cần nhớ và hành động", "lectureScript": "Lời giảng minh họa"}]', '2026-11-10 03:39:59.831852+00');
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9341bb4a-e551-41bc-a491-2e239ae45b6b', 'a580ccfe-dd70-54dd-b23e-38908d52df62', '50fb1f30-cbed-5ea7-8426-4d195721296e', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Công nghệ và đổi mới công nghệ: doanh nghiệp thực sự cần hiểu gì?'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('79c5f354-d454-425e-8f9e-6452d2c9c2c3', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 'd3aab42f-2809-52cb-bed3-86c544d1317e', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('28f363a3-fb04-4fbd-bcd7-7c9411e283bb', '19e00f35-65ac-5dc5-977e-99da22e4f37f', '4b2cbc63-234e-520b-a607-ddfb5b99fe24', 'Q1', 160, 'V1-3', 'Yếu tố nào là chỉ số kết quả, không phải giải pháp?', 'Mua phần mềm lập lịch', 'Lắp thêm màn hình trong xưởng', 'Tỷ lệ đơn giao đúng hẹn', 'Tổ chức lớp hướng dẫn phần mềm', 'C', 'Tỷ lệ giao đúng hẹn đo kết quả. Ba phương án còn lại mô tả hoạt động hoặc giải pháp, chưa chứng minh hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1a8436bc-d047-4741-8580-15641e853a09', '19e00f35-65ac-5dc5-977e-99da22e4f37f', '4b2cbc63-234e-520b-a607-ddfb5b99fe24', 'Q2', 225, 'V1-4', 'Nếu chưa có số liệu giao đúng hẹn đáng tin cậy, bạn nên làm gì?', 'Tự chọn tỷ lệ dự kiến', 'Dùng tỷ lệ của doanh nghiệp khác', 'Coi mọi đơn đều đúng hẹn', 'Định nghĩa chỉ số và lập kế hoạch thu thập dữ liệu', 'D', 'Cần cùng định nghĩa tử số, mẫu số, kỳ đo và nguồn dữ liệu. Các lựa chọn còn lại làm sai lệch đường cơ sở.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('ce4a0d48-aa1f-427d-8a54-47e944e59d5e', '19e00f35-65ac-5dc5-977e-99da22e4f37f', '91219b65-2a21-5608-9b51-67c35691bdfe', 'Q3', 150, 'V2-3', 'Dấu hiệu đơn hàng dồn trước đóng gói chứng minh được điều gì?', 'Đã chắc chắn máy đóng gói hỏng', 'Có vị trí cần khảo sát tiếp', 'Phải mua ngay máy mới', 'Bộ phận giao hàng làm sai', 'B', 'Tồn đọng giúp xác định nơi cần khảo sát, chưa chứng minh nguyên nhân. Các phương án khác nhảy thẳng sang kết luận.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('bf2b19ae-9876-4b3f-8f4b-baa93a663f59', '19e00f35-65ac-5dc5-977e-99da22e4f37f', '91219b65-2a21-5608-9b51-67c35691bdfe', 'Q4', 215, 'V2-4', 'Thông tin nào là ghi nhận có thể đối chiếu chứng từ?', 'Nhân viên thiếu trách nhiệm', 'Công nghệ hiện tại quá lạc hậu', 'Lịch sản xuất của đơn A được đổi hai lần trong nhật ký', 'Máy mới chắc chắn giải quyết được giao trễ', 'C', 'Nhật ký thay đổi là dấu vết có thể kiểm chứng. Các lựa chọn khác là phán đoán hoặc khẳng định nhân quả chưa có bằng chứng.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('f78091c4-1b17-47fb-80be-a3c6e2af893d', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 'da0e5c58-4832-556a-873b-e6612affcadd', 'Q5', 195, 'V3-4', 'Mô tả nào là bài toán công nghệ rõ hơn?', 'Cần một hệ thống ERP hiện đại', 'Cần chuyển đổi số toàn diện', 'Phải tăng số lượng phần mềm', 'Bộ phận kế hoạch cần ghi nhận thay đổi lịch và đo tỷ lệ đơn hoàn tất đúng kế hoạch', 'D', 'Phương án D nêu người dùng, thao tác và kết quả đo. Các phương án còn lại chỉ gọi tên giải pháp hoặc khẩu hiệu.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('3294e9ea-4e76-4618-85b9-c83a316ae64a', '19e00f35-65ac-5dc5-977e-99da22e4f37f', 'da0e5c58-4832-556a-873b-e6612affcadd', 'Q6', 255, 'V3-5', 'Một giải pháp có tác động kỳ vọng cao nhưng chưa có bằng chứng và không rõ dữ liệu đầu vào nên làm gì?', 'Phê duyệt ngay vì tác động cao', 'Đánh dấu cần kiểm chứng và thử quy mô nhỏ', 'Loại bỏ mọi phương án khác', 'Chấm điểm khả thi tối đa', 'B', 'Cần giảm bất định trước khi đầu tư lớn. Các phương án khác bỏ qua rủi ro và giả định chưa kiểm chứng.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8190f820-a9d2-4ae8-9091-222ea0e5330f', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 'bfbf8810-7ff1-5086-a671-a62a8d11fdfe', 'Q1', 171, 'V1-3', 'Dấu hiệu nào thuộc điểm nghẽn chất lượng cần kiểm tra?', 'Giá vật liệu tăng', 'Gói phải hàn lại nhiều lần', 'Khách hỏi báo giá mới', 'Bán hàng mở thêm kênh', 'B', 'B là dấu hiệu làm lại do chất lượng. A là biến động chi phí, C là yêu cầu thị trường và D là thay đổi kênh bán; các yếu tố này không trực tiếp mô tả lỗi chất lượng.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8a7f76f1-ce25-4794-8e2e-6e4bf9b65b63', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 'bfbf8810-7ff1-5086-a671-a62a8d11fdfe', 'Q2', 230, 'V1-4', 'Khi có nhiều đơn giao chậm, phát biểu nào đúng nhất?', 'Máy đóng gói chắc chắn hỏng', 'Bộ phận bán hàng chắc chắn sai', 'Đã xác định nguyên nhân gốc', 'Đây là triệu chứng; cần đối chiếu từng bước và dấu thời gian', 'D', 'D giữ nguyên trạng thái bằng chứng. A, B và C đều khẳng định nguyên nhân khi chưa đối chiếu hồ sơ hoặc quan sát quy trình.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8c3550f5-d79a-4978-bf38-14dc8767c04f', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', '99336dee-cff9-59f8-aa11-3d570fd133c2', 'Q3', 170, 'V2-3', 'Trong dây chuyền nối tiếp giả định có năng lực 120, 80 và 100 gói/giờ, bước nào giới hạn đầu ra ổn định nếu cùng điều kiện và không có gián đoạn?', 'Công đoạn 120 gói/giờ', 'Công đoạn 100 gói/giờ', 'Công đoạn 80 gói/giờ', 'Cả ba công đoạn như nhau', 'C', 'C đúng vì năng lực chuỗi nối tiếp bị giới hạn bởi công đoạn nhỏ nhất khi cùng đơn vị, cùng điều kiện. A, B và D bỏ qua giới hạn này; kết quả thực tế còn có thể thấp hơn.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('89e8921b-efdd-4ed8-b55f-42d88e9e064b', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', '99336dee-cff9-59f8-aa11-3d570fd133c2', 'Q4', 233, 'V2-4', 'Chỉ số nào đo được mức độ đạt chất lượng ngay lần kiểm tra đầu?', 'Số gói đạt lần đầu / số gói kiểm tra lần đầu', 'Số lượt sửa máy / tổng giờ làm', 'Số phản hồi khách / số nhân viên', 'Tổng gói bao gồm cả lượt làm lại / giờ', 'A', 'A đo tỷ lệ đạt lần đầu nếu định nghĩa mẫu số nhất quán. B đo bảo trì, C là tỷ lệ không phù hợp về thị trường, còn D dễ đếm trùng và không đo tỷ lệ đạt lần đầu.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('c40f55b4-eb41-440e-8e36-fb7a8e7da177', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 'b83bcf1a-0377-56d8-9132-1e5508c94ada', 'Q5', 201, 'V3-4', 'Một vấn đề được dự đoán ảnh hưởng lớn nhưng chưa có dữ liệu tin cậy. Bước ưu tiên là gì?', 'Đặt mua máy mới ngay', 'Cho điểm tác động cao nhất', 'Chọn theo đề xuất của nhà cung cấp', 'Ưu tiên đo và xác minh giả thuyết trong phạm vi kiểm soát', 'D', 'D phù hợp nguyên tắc ra quyết định theo bằng chứng. A, B, C đặt lựa chọn công nghệ trước việc xác minh tác động và tính khả thi.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('765ebe6e-c029-45e5-81c5-66d376c570ac', 'fe8c162f-af5c-5798-9eff-5184fcd588fe', 'b83bcf1a-0377-56d8-9132-1e5508c94ada', 'Q6', 255, 'V3-5', 'Đơn có đổi nhãn sát giờ thường giao trễ hơn trong mẫu khảo sát. Kết luận nào chặt chẽ nhất?', 'Đổi nhãn là nguyên nhân duy nhất', 'Có mối liên hệ cần kiểm tra thêm yếu tố gây nhiễu', 'Phải cấm mọi yêu cầu đổi nhãn', 'Không cần xem thông tin công đoạn khác', 'B', 'B phân biệt liên hệ thống kê với quan hệ nhân quả. A, C, D là suy diễn vượt quá chứng cứ ban đầu và không xét loại đơn hay quy mô.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9796ba12-b4e9-458f-ba7e-93217c196d6d', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', '0ff9e47a-f201-520b-a46a-6f4efea45d3e', 'Q1', 171, 'V1-3', 'Trong tình huống giả định, 18 túi hở mép trên 200 túi kiểm tra lần đầu. Tỷ lệ lỗi trong mẫu là bao nhiêu?', '18%', '9%', '0,9%', 'Không thể tính vì thiếu tên máy', 'B', 'B đúng vì 18 chia 200 bằng 0,09, tức 9%. A và C sai phép chia; D sai vì tính tỷ lệ mẫu không cần tên thiết bị.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0567ebd5-7b6b-442b-a576-89191fba4692', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', '0ff9e47a-f201-520b-a46a-6f4efea45d3e', 'Q2', 228, 'V1-4', 'Nhận định nào mới là giả thuyết cần kiểm tra?', 'Phiếu QC ghi 18 túi hở mép', 'Nhật ký có mã lô màng mới', 'Lô màng mới gây ra lỗi hở mép', 'QC kiểm tra lần đầu 200 túi', 'C', 'C khẳng định quan hệ nhân quả chưa được thử. A, B, D là thông tin có thể đối chiếu hồ sơ khi hồ sơ đáng tin cậy.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1916bc7f-54f7-4e6b-b643-3cb4a85f2214', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 'ac0b34f8-b15a-528b-a6da-f5d0906399d0', 'Q3', 172, 'V2-3', 'Khi chưa đo nhiệt thực tế hay kiểm tra sổ bảo trì, chuỗi "đầu đo lệch -> thiếu hiệu chuẩn" nên được gọi là gì?', 'Nguyên nhân gốc đã chắc chắn', 'Giả thuyết kèm phép đo cần xác minh', 'Sai phạm của người vận hành', 'Lý do phải thay máy ngay', 'B', 'B đúng vì chuỗi 5 Why chỉ là giả thuyết cho tới khi từng mắt xích có chứng cứ. A, C và D suy diễn vượt dữ kiện.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8f7a3408-ff95-4073-a2a3-5cb0ecad91db', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 'ac0b34f8-b15a-528b-a6da-f5d0906399d0', 'Q4', 236, 'V2-4', 'Giả thuyết "lô màng B gây lỗi nhiều hơn" có thể bị yếu đi nếu dữ liệu nào xuất hiện?', 'Không có số túi đã dùng mỗi lô', 'Hai lô cho tỷ lệ lỗi tương đương trong nhiều lượt thử có điều kiện phù hợp', 'Máy có nhãn hiệu quen thuộc', 'Nhiều người đồng ý với giả thuyết', 'B', 'B là dữ kiện có thể bác bỏ hoặc làm suy yếu giả thuyết. A cho thấy thiếu dữ liệu, còn C và D không phải phép thử nguyên nhân.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('2a66f82e-00c9-4945-8bc8-649ef0d9dac5', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 'd59da99a-afca-5a21-a363-d6fc8b08172b', 'Q5', 196, 'V3-4', 'Dữ liệu minh họa lô A lỗi 4/100, lô B lỗi 14/100 nhưng nhiệt thực tế cũng thay đổi. Kết luận nào phù hợp?', 'Đã chứng minh chỉ do màng B', 'Phải mua máy mới', 'Chênh lệch 10 điểm phần trăm, cần kiểm tra yếu tố nhiệt gây nhiễu', 'Không có chênh lệch giữa hai lô', 'C', 'C đúng: 14% trừ 4% là 10 điểm phần trăm, nhưng chưa tách ảnh hưởng của màng và nhiệt. A, B thiếu bằng chứng; D sai số liệu.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('f8e35936-6c64-4ae5-83c1-7b067a35c7bf', '9cb95dd9-c6be-55d5-b21d-410fa5c8ffa4', 'd59da99a-afca-5a21-a363-d6fc8b08172b', 'Q6', 301, 'V3-6', 'Khi kết quả thử không nhất quán và chưa kiểm soát đủ điều kiện, bước nào hợp lý?', 'Ghi một nguyên nhân gốc tùy ý', 'Dừng toàn bộ đánh giá vĩnh viễn', 'Mua thiết bị theo báo giá thấp nhất', 'Bổ sung phép đo, sửa thiết kế thử rồi quyết định', 'D', 'D phù hợp vì dữ liệu không nhất quán không cho phép chốt nguyên nhân hoặc đầu tư. A, B, C không giải quyết thiếu chứng cứ.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('e49cb203-de74-48c8-8114-baa036d0fa80', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', '7c75faeb-1f48-536e-a041-5e3f6ec7f67e', 'Q1', 173, 'V1-3', 'Muốn kiểm kê hiện trạng không bỏ sót luồng thông tin, nên bắt đầu bằng việc nào?', 'Chọn ngay máy đắt nhất', 'Theo đơn hàng qua từng bước và ghi đầu vào, đầu ra, người phụ trách', 'Chỉ hỏi nhân viên có muốn dùng phần mềm không', 'Liệt kê tuổi thiết bị mà không xem quy trình', 'B', 'B phù hợp vì quy trình cho thấy vai trò của cả năm lớp. A, C, D bỏ qua mối liên hệ giữa công việc và công nghệ.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('17078e25-6308-4c36-90f2-c93287d27372', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', '7c75faeb-1f48-536e-a041-5e3f6ec7f67e', 'Q2', 234, 'V1-4', 'Không tìm thấy sổ bảo trì của MH-01 thì ghi nhận chính xác nhất là gì?', 'Máy chắc chắn chưa bảo trì', 'Máy bắt buộc phải thay', 'Thiếu hồ sơ để kiểm chứng lịch bảo trì', 'Máy không còn giá trị sử dụng', 'C', 'C là trạng thái chứng cứ. A, B, D suy diễn tình trạng kỹ thuật từ việc thiếu tài liệu.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('01490606-a40d-42a7-af23-64ad85ea7c26', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', '830fa855-f343-5907-8051-8b671f6b5808', 'Q3', 173, 'V2-3', 'Một ca có 420 phút dự kiến chạy và 42 phút dừng; kết quả nào đúng?', 'Tỷ lệ thời gian chạy 90%; chưa đủ để tính OEE', 'OEE chắc chắn bằng 90%', 'Tỷ lệ lỗi bằng 10%', 'Không thể tính thời gian chạy', 'A', '378/420 = 90% thời gian chạy trong kế hoạch; OEE cần thêm dữ liệu tốc độ và chất lượng. B, C, D không đúng.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1d9d896d-3e76-4b2a-80ee-3b537d32c9ac', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', '830fa855-f343-5907-8051-8b671f6b5808', 'Q4', 233, 'V2-4', 'Trong 40 bản ghi, có 4 mã lô khác nhau giữa hai hệ thống. Điều nào kết luận được ngay?', 'Phải mua ERP', 'Nhân viên nhập tay là nguyên nhân đã chứng minh', 'Không có vấn đề gì', 'Tỷ lệ sai khác trong mẫu là 10%, cần kiểm tra luồng dữ liệu', 'D', 'D đúng vì 4/40 = 10%; tỷ lệ quan sát chưa chỉ ra nguyên nhân. A, B suy luận quá mức; C phủ nhận dữ kiện.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fe63328a-fa5d-4989-a12e-86a4ca71f117', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', '7d3a78bf-fbdc-5665-a955-907115845ee3', 'Q5', 148, 'V3-3', 'Tiêu chí nào phù hợp để xếp ưu tiên kiểm chứng khoảng trống?', 'Giá thiết bị mới cao nhất', 'Ảnh hưởng, độ tin cậy bằng chứng và khả năng kiểm tra', 'Tên công nghệ nghe hiện đại', 'Số nhà cung cấp gửi báo giá', 'B', 'B gắn ưu tiên với quyết định và điều kiện kiểm tra. Các phương án khác không đánh giá đúng hiện trạng.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('3b2e5d1a-ccd3-4bca-a1a9-8f77ea81ffd0', 'fb4d9fac-4641-5217-b8ca-8f841c96bf1f', '7d3a78bf-fbdc-5665-a955-907115845ee3', 'Q6', 198, 'V3-4', 'Khi chưa có log dừng đủ và chưa kiểm tra cảm biến, hành động nào phù hợp?', 'Công bố máy hàn hỏng', 'Thay toàn bộ thiết bị', 'Bổ sung dữ liệu, đối chiếu thiết bị và quy trình rồi mới đánh giá phương án', 'Xóa những chỉ số chưa đạt', 'C', 'C giữ nguyên tắc phân biệt dữ kiện với giả thuyết; A, B, D loại bỏ bước xác minh cần thiết.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('3f2f8c44-3e68-4025-a938-a6b384d91c58', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', '0be83abb-d9a1-5311-9129-e7ee66118167', 'Q1', 169, 'V1-3', 'Phát biểu nào mô tả đúng năng lực hấp thụ công nghệ của doanh nghiệp?', 'Đủ tiền mua máy mới', 'Nhận biết, tiếp thu, tích hợp và vận dụng tri thức công nghệ vào công việc', 'Công nghệ có TRL cao', 'Có nhà cung cấp nổi tiếng', 'B', 'B nêu năng lực của tổ chức; A là nguồn vốn, C là đặc tính của giải pháp, D chỉ là thông tin nhà cung cấp.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('534d0d30-fe74-41ed-8165-8d77346134f6', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', '0be83abb-d9a1-5311-9129-e7ee66118167', 'Q2', 228, 'V1-4', 'Nhóm thông tin nào cần rà soát để tiếp nhận hệ thống cảnh báo?', 'Chỉ chi phí mua thiết bị', 'Chỉ thương hiệu và cấu hình', 'Chỉ số nhân viên trong doanh nghiệp', 'Con người, quy trình, dữ liệu, hạ tầng và quản trị', 'D', 'D xét cả chu trình sử dụng. A, B, C bỏ sót điều kiện triển khai, vận hành và duy trì.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('99e7f328-c0aa-4460-993b-4a055315cb09', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 'bdbf821d-b966-5d8a-a92a-ca3f59dc6ece', 'Q3', 169, 'V2-3', '14 trên 20 phiếu QC điền đủ trường bắt buộc cho biết điều gì?', '70% phiếu đầy đủ trong mẫu đã kiểm tra', '70% sản phẩm đạt chất lượng', '70% năng lực hấp thụ của doanh nghiệp', 'Hệ thống cảnh báo sẽ giảm 30% lỗi', 'A', '14/20 = 70% độ đầy đủ trong mẫu; không phải tỷ lệ sản phẩm đạt hay hiệu quả của công nghệ.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0dea9fbc-6bf6-4608-a65e-9048b6d4ae43', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 'bdbf821d-b966-5d8a-a92a-ca3f59dc6ece', 'Q4', 226, 'V2-4', 'Điểm thực hành 5/10 từ năm nhóm cho phép kết luận chắc chắn điều gì?', 'Doanh nghiệp cần mua ngay công nghệ', 'Dự án có 50% xác suất thành công', 'Có các khoảng trống cần kiểm chứng, không thay thế điều kiện bắt buộc', 'Bất kỳ điều kiện an toàn nào cũng có thể bù bằng điểm khác', 'C', 'C đọc điểm đúng giới hạn; thang tự luyện không đo xác suất thành công, không thay thế kiểm tra an toàn.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fc9cef75-0549-4f59-8372-b94541463a10', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', '97675fbd-0a06-5c34-8614-7d6153b9badd', 'Q5', 142, 'V3-3', 'Phương án thử nghiệm nào phù hợp với hệ thống cảnh báo nhiệt?', 'Tự thay ngưỡng máy đang chạy để tạo lỗi', 'Thử có phê duyệt, điều kiện an toàn, dữ liệu nền và tiêu chí dừng', 'Bỏ qua SOP vì chỉ thử nhỏ', 'Đánh giá bằng cảm nhận một người', 'B', 'B có điều kiện kiểm soát và chứng cứ; A nguy hiểm, C và D thiếu căn cứ.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('f3976001-9603-48df-b2d8-699dced52d05', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', '97675fbd-0a06-5c34-8614-7d6153b9badd', 'Q6', 190, 'V3-4', 'Khi thử phát hiện thiếu bản ghi và lỗi có thể sửa, cần làm gì?', 'Mặc định triển khai toàn nhà máy', 'Công bố thành công dù chưa đủ dữ liệu', 'Bỏ qua vì nhà cung cấp đã cam kết', 'Điều chỉnh nguyên nhân đã phát hiện và kiểm tra lại theo tiêu chí đã duyệt', 'D', 'D giữ được tính kiểm chứng; A, B, C bỏ qua khoảng trống cần xử lý.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('5999c1a3-5c3a-41f6-9582-e88d01f84f06', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', '49704ea1-e919-5074-940f-456eb0a32487', 'Q1', 167, 'V1-3', 'Trong các lựa chọn dưới đây, đâu là một câu chức năng đúng nghĩa, thay vì chỉ nêu tên giải pháp hoặc mô tả mong muốn chung chung?', 'Cần một phần mềm quản lý sản xuất.', 'Cần ứng dụng trí tuệ nhân tạo', 'Trưởng ca có thể kiểm tra trạng thái phê duyệt bản vẽ trước khi phát hành lệnh in.', 'Hệ thống cần có giao diện hiện đại, dễ sử dụng.', 'C', 'Điểm khác biệt của phương án C là yêu cầu đã được mô tả thông qua một hoạt động nghiệp vụ cụ thể: ai thực hiện, cần kiểm tra thông tin gì và tại thời điểm nào.
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('3e8aa4fa-3310-46db-ae27-78082ae28ab9', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', '49704ea1-e919-5074-940f-456eb0a32487', 'Q2', 233, 'V1-4', 'Khi tiếp nhận yêu cầu “Hệ thống phải dễ sử dụng”, cách diễn đạt nào giúp chuyển mong muốn này thành một yêu cầu cụ thể, có thể quan sát và kiểm chứng trong thực tế?', 'Hệ thống phải có giao diện rất dễ sử dụng.', 'Người dùng mới thực hiện được tác vụ tìm đúng bản vẽ cho một lệnh in sau buổi hướng dẫn; mức đạt được xác nhận qua thử nghiệm.', 'Hệ thống phải có giao diện đẹp và trực quan.', 'Hệ thống phải dễ sử dụng tương tự các ứng dụng phổ biến hiện nay.', 'B', 'Phương án B xác định được người dùng, tác vụ và cách thử nghiệm. Mức “dễ sử dụng” cần được kiểm chứng trên người dùng thật; không áp đặt thời gian thao tác tùy tiện khi chưa có dữ liệu.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('b58a44e5-a34f-4bae-97db-0135ff54d8f8', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 'ae6e30df-a922-5447-a95d-37785fe1414d', 'Q3', 161, 'V2-3', 'Khi phỏng vấn người trực tiếp thực hiện công việc để tìm hiểu quy trình hiện tại, câu hỏi nào nên được ưu tiên đặt ra trước tiên?', 'Anh/chị cần phần mềm gì để hỗ trợ công việc?', 'Anh/chị mong muốn công việc được quản lý tốt hơn như thế nào?', 'Lần gần nhất công việc này phát sinh là khi nào và đã diễn ra qua những bước nào?', 'Anh/chị có hài lòng với cách thực hiện công việc hiện nay không?', 'C', 'Khi khảo sát người dùng, điều quan trọng trước tiên là tìm hiểu cách công việc thực sự đang diễn ra, thay vì vội vàng hỏi họ muốn sử dụng giải pháp nào.
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('76aec5b0-e102-457f-8f7b-01ff0dcee025', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 'ae6e30df-a922-5447-a95d-37785fe1414d', 'Q4', 242, 'V2-4', 'Trong quá trình khảo sát thực tế, ghi nhận nào dưới đây phản ánh một hiện trạng có thể quan sát và kiểm chứng trực tiếp, thay vì là nhận định hoặc suy đoán về con người?', 'Công nhân không quan tâm đến chất lượng công việc.', 'Hai tệp có tên gần giống nhau được lưu trong cùng một thư mục.', 'Công nhân thường quên đọc tin nhắn.', 'Trưởng ca chưa được đào tạo đầy đủ.', 'B', 'Phương án B mô tả một hiện trạng cụ thể, có thể kiểm tra trực tiếp trên hệ thống hoặc tại nơi lưu trữ dữ liệu. Đây là thông tin có căn cứ để ghi nhận và tiếp tục phân tích.
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('e31e18fb-9332-4646-93b9-a1d57dc99384', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 'c9674177-b17e-5f0b-8777-3ef422e10388', 'Q5', 210, 'V3-4', 'Trong danh sách yêu cầu có nội dung “Tích hợp với phần mềm kế toán đang sử dụng”, nhưng hiện chưa xác định được định dạng dữ liệu và điều kiện kết nối giữa hai hệ thống. Trong trường hợp này, nên xử lý yêu cầu như thế nào?', 'Gắn nhãn B (bắt buộc)', 'Gắn nhãn N (nên có)', 'Đánh dấu chưa xác định và đưa vào danh sách cần kiểm tra, làm rõ.', 'Loại bỏ yêu cầu khỏi bản mô tả.', 'C', 'Việc xác định một yêu cầu là bắt buộc hay nên có cần dựa trên mức độ cần thiết đối với hoạt động nghiệp vụ và những căn cứ đã được xác minh.
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('e19fcd4b-34fc-4df8-94d3-f794e1298c62', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 'c9674177-b17e-5f0b-8777-3ef422e10388', 'Q6', 266, 'V3-5', 'Dòng mô tả “Cần hệ thống quản trị tổng thể” chưa đáp ứng tiêu chí nào trong bộ ba câu hỏi dùng để kiểm tra chất lượng của một yêu cầu?', 'Ai thực hiện, thực hiện công việc gì và ở bước nào?', 'Nếu bỏ tên công nghệ hoặc giải pháp, nội dung yêu cầu còn diễn đạt được ý nghĩa cụ thể không?', 'Có tình huống thực tế để xác định yêu cầu đã được đáp ứng hay chưa?', 'Cả ba tiêu chí trên.', 'D', 'Cụm từ “Cần hệ thống quản trị tổng thể” mới chỉ thể hiện một mong muốn ở mức khái quát, chưa đủ thông tin để xác định yêu cầu nghiệp vụ cụ thể.
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('b39137d8-3759-4647-84bf-92fdd1b9e7ed', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 'e2c3a5d9-a543-5ede-b7cd-dce6c3051796', 'Q1', 172, 'V1-3', 'Tử số phù hợp của KPI tỷ lệ túi hở mép hàn là gì?', 'Số phút máy hoạt động', 'Số túi được xác nhận hở mép trong phạm vi kiểm', 'Tổng số túi sản xuất ở mọi công đoạn', 'Số cảm biến vừa lắp', 'B', 'B đúng. A là thời gian, C chỉ có thể là mẫu số nếu phù hợp quy tắc kiểm, D đo đầu tư chứ không đo lỗi.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('43ad2201-b51b-4f5c-a353-dea73f594345', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 'e2c3a5d9-a543-5ede-b7cd-dce6c3051796', 'Q2', 292, 'V1-5', 'Vì sao không chỉ dùng số túi lỗi để so sánh giữa các tuần?', 'Vì số túi kiểm có thể thay đổi', 'Vì mọi tuần luôn có cùng sản lượng', 'Vì không cần kiểm chất lượng', 'Vì phải dùng tên nhà cung cấp', 'A', 'A đúng: số lỗi tuyệt đối thiếu mẫu số. B không được giả định; C, D không liên quan phép so sánh.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('2ca4310c-6445-419d-8d3e-3de927928a0c', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 'c567b325-0b82-5dca-82cc-a54d36820793', 'Q3', 178, 'V2-3', 'Nếu 240 túi hở mép trong 8.000 túi kiểm, tỷ lệ lỗi nền bằng bao nhiêu?', '0,3%', '30%', '3,0%', '12%', 'C', 'C đúng: 240 chia 8.000 bằng 0,03, nhân 100 thành 3,0%.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('b40fe658-ba9c-4027-b6ea-c32115cdbf2e', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 'c567b325-0b82-5dca-82cc-a54d36820793', 'Q4', 241, 'V2-4', 'Tuần 4 có tỷ lệ lỗi 3,6%, nhóm dự án nên làm gì?', 'Loại tuần 4 ngay để chỉ số đẹp hơn', 'Khẳng định chắc chắn máy bị hỏng', 'Chỉ lấy tuần 3 làm mức nền', 'Đối chiếu dữ liệu, điều kiện đo và nhật ký trước khi kết luận', 'D', 'D giữ lại bằng chứng và kiểm tra khác biệt. A thiên lệch, B suy diễn nguyên nhân, C chọn mẫu có lợi.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7578e248-5833-4d8c-9e86-5cdadbb96656', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', '998b7112-d6e7-53e0-8955-ec5046ab0527', 'Q5', 136, 'V3-3', 'Điều kiện nào cần có khi so KPI trước và sau dự án?', 'Càng nhiều thay đổi đồng thời càng dễ kết luận', 'Cùng quy tắc đếm, phạm vi tương đương và ghi yếu tố thay đổi', 'Đổi mẫu số nhưng vẫn xem tỷ lệ như nhau', 'Bỏ chỉ số thời gian dừng máy', 'B', 'B đúng. Thay đổi cách đếm hoặc điều kiện không ghi nhận làm suy yếu so sánh; KPI hỗ trợ giúp phát hiện đánh đổi.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('55c3fe5c-beb2-45a3-b910-a7bfbcfabfc7', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', '998b7112-d6e7-53e0-8955-ec5046ab0527', 'Q6', 178, 'V3-4', 'Sau thử quan sát tỷ lệ 2,0% so với nền 3,0%, câu nào đúng?', 'Giảm quan sát 1 điểm phần trăm, chưa chứng minh nguyên nhân do công nghệ', 'Công nghệ chắc chắn giảm đúng 33,3% lỗi', 'Tỷ lệ giảm tuyệt đối là 33,3 điểm phần trăm', 'Không cần xem điều kiện trước và sau', 'A', 'A đúng. 33,3% là mức giảm tương đối, không chứng minh quan hệ nhân quả nếu chưa kiểm soát yếu tố khác.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('04f69fb1-0587-4203-8069-f4d5f1e47b4c', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', '2b294f46-6308-576e-acd0-553cb3389bbe', 'Q1', 151, 'V1-3', 'Hai bộ phận nêu “giảm tìm hồ sơ lô” và “truy xuất chứng từ lô nhanh hơn”. Cách làm đúng trước khi chấm là gì?', 'Chấm hai nhu cầu độc lập ngay', 'Gộp luôn dù chưa kiểm phạm vi', 'Đối chiếu phạm vi, KPI rồi gộp nếu thực sự trùng', 'Chọn nhu cầu do cấp quản lý đề xuất', 'C', 'C đúng. A có thể đếm trùng, B gộp thiếu kiểm chứng, D không đánh giá nội dung.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('18983931-113e-4f18-8db1-f50540a42ff5', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', '2b294f46-6308-576e-acd0-553cb3389bbe', 'Q2', 266, 'V1-5', 'Một nhu cầu tác động rất cao nhưng chưa xác minh an toàn và quyền sử dụng dữ liệu. Nên xử lý thế nào?', 'Phê duyệt vì điểm tác động cao', 'Đánh dấu chờ xác minh điều kiện, chưa phê duyệt thử', 'Cộng thêm điểm khả thi', 'Bỏ hẳn đánh giá tác động', 'B', 'B đúng. Cổng an toàn, tuân thủ và dữ liệu tách khỏi điểm có trọng số.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('3e388254-63de-459d-947d-c80e22359e0b', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 'b7cccc6b-fa62-5557-808c-454da3646509', 'Q3', 170, 'V2-3', 'Dấu hiệu nào phù hợp nhất để cho điểm khả thi cao?', 'Báo giá quảng cáo rẻ', 'Thiết bị có giao diện hiện đại', 'Nhiều doanh nghiệp khác mua', 'Dữ liệu, đội ngũ, nguồn lực và phạm vi thử được xác minh sẵn sàng', 'D', 'D đúng; tính khả thi là năng lực triển khai trong điều kiện doanh nghiệp, không là quảng cáo.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('da76c0cf-154a-410f-9c6c-0f2f444ffaae', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 'b7cccc6b-fa62-5557-808c-454da3646509', 'Q4', 231, 'V2-4', 'Tác động = 5, khả thi = 4; trọng số tương ứng 60% và 40%. Điểm tổng là bao nhiêu?', '4,6/5', '4,4/5', '9,0/5', '92% xác suất thành công', 'A', 'A đúng: 5x0,6 + 4x0,4 = 4,6. Không diễn giải thành xác suất thành công.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('cbdbcbba-8025-418c-857c-b8751e0e60cd', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 'dcdac1cd-7fb0-5351-b3fb-d40f476849be', 'Q5', 127, 'V3-3', 'Khi đổi trọng số từ 60/40 sang 40/60, A và B đảo vị trí. Kết luận nào hợp lý?', 'Công thức tính sai', 'B chắc chắn luôn tốt hơn A', 'Thứ hạng nhạy với trọng số; cần kiểm tra chiến lược và chứng cứ', 'Bỏ tất cả tiêu chí khả thi', 'C', 'C đúng. Thứ hạng thay đổi theo ưu tiên chiến lược là tín hiệu cần thẩm định thêm.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('43000fe2-88a1-4e92-ab29-ce5049bec01d', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 'dcdac1cd-7fb0-5351-b3fb-d40f476849be', 'Q6', 228, 'V3-5', 'Nhu cầu truy vết lô có điểm cao nhưng mã lô chưa chuẩn hóa. Hành động trước mắt phù hợp nhất?', 'Ký mua hệ thống ngay', 'Đổi điểm để nhu cầu đứng cuối', 'Bỏ mục tiêu truy vết', 'Ưu tiên chuẩn hóa mã lô, làm sạch dữ liệu rồi đánh giá lại thử nghiệm', 'D', 'D đúng. Điều kiện nền chưa đạt thì cần một việc chuẩn bị, không phê duyệt đầu tư chỉ dựa vào điểm.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7f3852be-79ca-4ec4-bcfb-6037edb8ca1a', '3a6158cd-409e-53b6-b657-95bfc28329ba', '61c60907-ff56-5e3b-af65-9adc59909623', 'Q1', 145, 'V1-3', 'Kiểm tra 8.000 túi, phát hiện 240 túi hở mép hàn. Kết luận nào chính xác nhất?', '3% toàn bộ sản phẩm nhà máy chắc chắn bị lỗi', '3% trong mẫu đã kiểm; cần xem cách lấy mẫu trước khi suy rộng', '240% sản phẩm bị lỗi', 'Không thể tính tỷ lệ lỗi từ dữ liệu này', 'B', 'B đúng: 240/8.000 = 3% trên số túi kiểm, không mặc nhiên đại diện cho toàn bộ sản lượng.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('ab0ddfcd-81ce-4bb8-bbd0-b3b082f8ed07', '3a6158cd-409e-53b6-b657-95bfc28329ba', '61c60907-ff56-5e3b-af65-9adc59909623', 'Q2', 254, 'V1-5', 'Dữ liệu ca chạy chưa xác minh nhưng bộ phận kỹ thuật nghi ngờ nhiệt độ hàn. Nên ghi thế nào?', 'Nguyên nhân gốc đã chứng minh', 'Mua cụm hàn mới ngay', 'Không cần ghi lại giả thuyết', 'Giả thuyết cần kiểm bằng dữ liệu nhiệt độ, lô vật liệu và lỗi theo ca', 'D', 'D đúng. Giả thuyết không phải kết luận; cần thu dữ liệu, giữ rõ tình trạng chưa xác minh.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8c544013-0835-45da-8d78-f351d9c5c535', '3a6158cd-409e-53b6-b657-95bfc28329ba', '7e5d8c8a-e6ea-5060-a23b-08a36d85ab7d', 'Q3', 158, 'V2-3', 'Chưa khảo sát khả năng tích hợp với phần mềm cũ. Nhãn thích hợp trên phiếu là gì?', 'B, bắt buộc ngay', 'N, chắc chắn nên có', '?, cần xác minh trước khi phân loại', 'Bỏ khỏi phiếu hoàn toàn', 'C', 'C đúng. Nhãn ? yêu cầu có người xác nhận và kế hoạch kiểm chứng, tránh đưa ra tiêu chí sai.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a894e266-8d53-4388-8936-f5cbc1e36fac', '3a6158cd-409e-53b6-b657-95bfc28329ba', '7e5d8c8a-e6ea-5060-a23b-08a36d85ab7d', 'Q4', 216, 'V2-4', 'Đâu là tiêu chí thử nghiệm có thể đánh giá hơn câu “thiết bị vận hành ổn định”?', 'Tỷ lệ lỗi <=2% theo cùng cách lấy mẫu, có điều kiện thử và giám sát an toàn', 'Thiết bị có giao diện đẹp', 'Nhà cung cấp cam kết sẽ tốt hơn', 'Máy có giá đắt nhất', 'A', 'A đúng, nhưng trước thử phải thống nhất phạm vi, mẫu, thời lượng và cách đo; vẫn cần kiểm soát yếu tố khác.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8457715b-a2b4-4a31-9be8-dd1fbe709231', '3a6158cd-409e-53b6-b657-95bfc28329ba', '451a46de-f163-58fb-ac4c-d77bf9ca2274', 'Q5', 130, 'V3-3', 'Câu hỏi nào phù hợp nhất khi bắt đầu trao đổi với chuyên gia?', 'Bên anh có máy đời mới nhất không?', 'Làm sao mua ngay thiết bị đang quảng cáo?', 'Anh có thể báo giá dù chưa rõ phạm vi?', 'Cần thêm bằng chứng nào để kiểm chứng nguyên nhân và đề xuất phương án thử phù hợp?', 'D', 'D đúng: yêu cầu chuyên gia làm rõ cách kiểm chứng và phương án, không buộc chọn sẵn công nghệ.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('cfaef486-d462-44d7-bc6b-dabce7566d49', '3a6158cd-409e-53b6-b657-95bfc28329ba', '451a46de-f163-58fb-ac4c-d77bf9ca2274', 'Q6', 228, 'V3-5', 'Sau thử, tỷ lệ lỗi giảm. Kết luận nào có căn cứ nhất?', 'Giải pháp chắc chắn gây ra toàn bộ mức giảm', 'Có cải thiện quan sát; phải kiểm cách lấy mẫu và các yếu tố thay đổi trước khi quy kết nguyên nhân', 'Dự án chắc chắn sinh lời', 'Không cần giám sát thêm', 'B', 'B đúng. So sánh trước-sau cần giữ định nghĩa và xét các yếu tố gây nhiễu; rủi ro an toàn phải được giám sát.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('d11848fe-1d4b-44ea-9dee-647e9aeab838', 'f9d455c5-f10f-57da-8dba-e0e566a16173', '4a7440e0-6d3a-502d-a129-0241d2d4be8c', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Hệ sinh thái cung – cầu công nghệ: doanh nghiệp có thể tìm công nghệ ở đâu?'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('c3f09eb0-c397-4fb9-94dc-6bf76eb43db0', 'f9d455c5-f10f-57da-8dba-e0e566a16173', '18fda756-5c9d-536e-9e15-a578a248891b', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('90032e1a-0351-47a4-bcff-c0bd356a03c3', '3115a810-8fd8-5c58-b491-e8cd3f554dd0', '615a724d-6995-5083-b845-53e9557ed860', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Các con đường tiếp cận công nghệ: mua, thuê, licensing, chuyển giao và hợp tác R&D'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('01530845-9b05-422a-9c76-56bd2f67d29b', '3115a810-8fd8-5c58-b491-e8cd3f554dd0', 'a9bd98b4-5847-5900-9cfa-d51d816ec4d3', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a96b9c0f-7f94-4c01-bb42-1fcda7d1124d', '1c72af3d-190b-5477-a4fe-559cb0698ecf', 'd05350da-a792-5caa-8e84-2eadb9d2b063', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Tìm kiếm công nghệ hiệu quả bằng từ khóa, chức năng, ngành và bài toán ứng dụng'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('ca88c464-7fab-4b8a-8a55-a92aba5c718e', '1c72af3d-190b-5477-a4fe-559cb0698ecf', 'd354a006-b1de-507f-ac19-e33d85b69b18', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0ea52197-8464-49c1-82b0-1fa6ea687ee9', 'b077eeb8-a125-5b14-b57e-adb919073e53', 'ece42f32-ce6b-54c4-9ac2-d9c6a3bce505', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Khai thác cơ sở dữ liệu công nghệ, sáng chế và nguồn thông tin công khai'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('d8bbe1b5-5877-4b21-8224-699b4b82dd5f', 'b077eeb8-a125-5b14-b57e-adb919073e53', 'afe69f46-f8b6-5cd0-bf6d-c5e9e34389a1', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('79346e2a-ef7e-418c-a320-92e74ae69e04', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 'a3197e63-1c53-578d-8d08-7e5866c64a04', 'Q1', 2, 'V1-3', 'Dòng “camera công nghiệp” trong hồ sơ có tự chứng minh thiết bị phát hiện được mã lô sai không?', 'Có, vì tên camera đã nói rõ chức năng', 'Có, nếu hãng sản xuất nổi tiếng', 'Không; cần mô tả đầu vào, quy tắc phát hiện và đầu ra', 'Có, vì máy có thể kết nối mạng', 'C', 'C đúng. Tên thiết bị chưa thay thế cho tài liệu chức năng và phép thử trên mã lô thật.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('21b49ac1-1b5c-4896-b410-374776c6b9f7', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 'a3197e63-1c53-578d-8d08-7e5866c64a04', 'Q2', 4, 'V1-5', 'Nhà cung cấp ghi “99% chính xác” nhưng không nêu mẫu số. Doanh nghiệp nên làm gì?', 'Coi 99% là tỷ lệ phát hiện lỗi', 'Yêu cầu định nghĩa, mẫu thử và tách bỏ lọt/loại nhầm', 'Mặc định đạt nghiệm thu', 'Lấy 99% trừ tỷ lệ lỗi hiện tại', 'B', 'B đúng. Phải biết đối tượng đo và cách phân loại trước khi diễn giải con số công bố.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('6bcd3724-d402-470f-85f0-dee7750c9ec9', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', '83872c06-db46-5675-a8ee-b9241eb2dbc0', 'Q3', 2, 'V2-3', 'Thiết bị có cổng Ethernet. Có thể kết luận sẽ tích hợp ngay với hệ thống hiện tại không?', 'Có, vì Ethernet luôn tương thích phần mềm', 'Có, nếu cắm dây kết nối', 'Không cần kiểm vì chỉ kiểm tra ảnh', 'Chưa; phải xác minh giao thức, dữ liệu, độ trễ và phân quyền', 'D', 'D đúng. Cổng kết nối chỉ là một điều kiện; khả năng tích hợp phải được kiểm thực tế.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('126fe1b0-9865-49a9-995c-e2cd4b8fce2d', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', '83872c06-db46-5675-a8ee-b9241eb2dbc0', 'Q4', 4, 'V2-5', 'Bằng chứng nào phù hợp nhất để đánh giá camera trên dây chuyền An Bình?', 'Biên bản thử với mẫu, điều kiện, kết quả và người xác nhận rõ ràng', 'Ảnh quảng cáo của nhà cung cấp', 'Lời giới thiệu rằng thiết bị rất ổn định', 'Video demo không ghi cỡ mẫu', 'A', 'A đúng. Bằng chứng đo có phương pháp và bối cảnh rõ giúp kiểm tra tính phù hợp.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('41c0bbef-4708-4228-8120-396c234d44dc', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', '8a8dcd00-f79f-5a13-9ed1-9640234ce9f9', 'Q5', 2, 'V3-3', 'Trong 100 gói lỗi camera phát hiện 96; trong 400 gói tốt camera loại nhầm 12. Kết luận nào đúng?', 'Tỷ lệ phát hiện lỗi 96%, loại nhầm 12%', 'Tỷ lệ phát hiện 96%, loại nhầm 3%', 'Độ đúng chung chắc chắn 99%', 'Tỷ lệ bỏ lọt lỗi là 12%', 'B', 'B đúng. Phát hiện lỗi 96/100 = 96%; loại nhầm 12/400 = 3%. Mỗi tỷ lệ có mẫu số riêng.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('f0902528-ec91-4d44-b1c5-b75aa1579279', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', '8a8dcd00-f79f-5a13-9ed1-9640234ce9f9', 'Q6', 3, 'V3-5', 'Tỷ lệ phát hiện đạt 96% so với yêu cầu 98%; loại nhầm 3% so với mức tối đa 1%. Nên làm gì?', 'Chấp nhận vì quảng cáo ghi 99%', 'Kết luận mọi camera đều không phù hợp', 'Ghi chưa đạt phép thử, yêu cầu điều chỉnh và xác minh các điều kiện còn thiếu', 'Bỏ qua các chỉ số vì năng suất danh định cao', 'C', 'C đúng. Hai chỉ tiêu thử chưa đạt; các tiêu chí chưa thử phải ghi chưa xác minh, không thay thế bằng suy đoán.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0774285f-2ab3-496e-8b25-7913cc87efe2', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', '8e5b7b68-add2-5fc3-99dc-40d026a744a5', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''TRL 1–9: đánh giá mức độ sẵn sàng công nghệ'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('b124509d-f697-46a7-b3de-807eaef72b5d', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 'c60ba7fb-44d6-5bed-a14f-143c7e70c329', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('69a3e89e-6033-4694-b839-100ba7cc3231', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', '9120d213-56a9-5115-886d-325d7bf60cd1', 'Q1', 2, 'V1-3', 'Tài liệu nào cho phép truy xuất kết quả phép thử tốt hơn?', 'Ảnh quảng cáo ghi 99% nhưng không ghi đơn vị thử', 'Báo cáo có ngày thử, cấu hình, bộ mẫu, log và người xác nhận', 'Lời giới thiệu “đã áp dụng ở nhiều nơi”', 'Video demo không có mã phiên bản', 'B', 'B đúng. Cấu hình, thời điểm, bộ mẫu, dữ liệu gốc và người xác nhận cho phép kiểm tra lại.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('47da18e7-8bdd-49d7-ba29-e55582ee5f08', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', '9120d213-56a9-5115-886d-325d7bf60cd1', 'Q2', 4, 'V1-5', 'Camera chỉ được thử trên gói mã in rõ, bao bì phẳng. Nên kết luận gì?', 'Đã chứng minh hiệu năng trên mọi loại bao bì', 'Chắc chắn không hoạt động với bao bì bóng', 'Có bằng chứng ở điều kiện đã thử; phải bổ sung mẫu đại diện điều kiện thật', 'Có thể suy ra tỷ lệ lỗi sản xuất của nhà máy', 'C', 'C đúng. Mẫu dễ có thể bỏ qua biến thiên của sản xuất và không cho phép suy rộng.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('befd1daf-884a-4746-86ea-560e8a21342a', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', '17ac8dee-51c4-5d64-8567-61a79259be3a', 'Q3', 2, 'V2-3', 'TP=96, FN=4, FP=12, TN=388. Tỷ lệ phát hiện lỗi và loại nhầm là bao nhiêu?', '96% và 12%', '96,8% và 3%', '96% và 3%', '99% và 4%', 'C', 'C đúng: phát hiện = 96/(96+4)=96%; loại nhầm = 12/(12+388)=3%.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('b665c05a-aec1-468c-b941-895f40222c59', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', '17ac8dee-51c4-5d64-8567-61a79259be3a', 'Q4', 4, 'V2-5', 'Cách nào giúp kiểm tra tính lặp lại và giảm sai lệch do hiệu chỉnh?', 'Dùng lại đúng bộ mẫu đã chỉnh máy để báo cáo cuối', 'Giữ cả lỗi bị bỏ sót ngoài dữ liệu', 'Để nhà cung cấp tự bỏ các mẫu gây khó', 'Khóa cấu hình, dùng bộ mẫu mới có nhãn chuẩn và lưu toàn bộ log', 'D', 'D đúng. Mẫu đánh giá tách biệt và nhật ký đầy đủ làm kết quả dễ kiểm chứng hơn.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a9839c32-2d87-4973-888d-7407c27d6ad9', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', '5e26cc6f-66eb-59ea-b930-136136a37ad4', 'Q5', 2, 'V3-3', 'Không có thông tin ai gán nhãn chuẩn cho bộ mẫu. Cách ghi trạng thái nào đúng?', 'Chưa xác minh và yêu cầu phương pháp gán nhãn', 'Không đạt mọi tiêu chí kỹ thuật', 'Đã đạt vì bảng có số liệu', 'Có thể bỏ qua vì đã tính tỷ lệ đúng', 'A', 'A đúng. Thiếu dữ liệu về nhãn chuẩn làm giảm khả năng tin cậy, nhưng chưa chứng minh thiết bị không đạt.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fb52d27a-84c8-4b1f-a642-a4809c072ae2', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', '5e26cc6f-66eb-59ea-b930-136136a37ad4', 'Q6', 4, 'V3-5', 'Chỉ số tính được 96% phát hiện, 3% loại nhầm; ngưỡng ví dụ là >=98% và <=1%. Nên làm gì?', 'Phê duyệt mua vì video demo đẹp', 'Ghi chưa đạt theo số đo minh họa, đồng thời kiểm nguồn mẫu và thử lại có kiểm soát', 'Kết luận mọi công nghệ camera đều không phù hợp', 'Xóa những dòng log không đạt để tăng tỷ lệ', 'B', 'B đúng. Hai số đo chưa đạt ngưỡng nội bộ giả định; phải kiểm chứng độ tin cậy và thiết kế phép thử tiếp.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1f8cd08b-1c04-48be-9a68-06f3a565b648', '355ab944-8895-5f38-b87f-89e187038e44', 'cbf80674-d93d-5d2a-9ab2-30ae4911669b', 'Q1', 2, 'V1-3', 'Thông tin nào không được suy ra chỉ từ một đơn sáng chế đã công bố?', 'Có một hồ sơ cần tra cứu', 'Đã có bằng độc quyền còn hiệu lực đối với nội dung đang xem', 'Có số công bố để đối chiếu', 'Cần kiểm chủ thể và lãnh thổ', 'B', 'B đúng. Đơn công bố không tự đồng nghĩa đã có văn bằng còn hiệu lực hoặc đúng phạm vi.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8ffe2703-03d2-4785-98ff-f4b795b12533', '355ab944-8895-5f38-b87f-89e187038e44', 'cbf80674-d93d-5d2a-9ab2-30ae4911669b', 'Q2', 4, 'V1-5', 'An Bình định gửi ảnh lỗi cho nhà cung cấp. Cần làm rõ trước điều gì?', 'Chỉ hỏi dung lượng tệp', 'Mặc định nhà cung cấp được dùng lại ảnh cho mọi khách hàng', 'Mục đích dùng, ai truy cập, thời hạn lưu và có được sử dụng lại hay không', 'Cứ trả tiền mua máy thì mọi ảnh tự động công khai', 'C', 'C đúng. Phải xác định giới hạn sử dụng và bảo mật dữ liệu, không tự suy quyền.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('544d0505-64ef-43ae-85f8-42ca82aaa516', '355ab944-8895-5f38-b87f-89e187038e44', '6fbc144f-76bd-5268-8dba-df9e2207ab48', 'Q3', 2, 'V2-3', 'Không tìm thấy kết quả trong một lần tra cứu sáng chế. Kết luận nào phù hợp?', 'Đã chắc chắn không xâm phạm quyền của bên nào', 'Không cần xem thị trường khác', 'Nhà cung cấp chắc chắn có quyền cấp phép', 'Chưa đủ căn cứ; cần kiểm phạm vi tìm kiếm và thẩm định khi có rủi ro', 'D', 'D đúng. Tra cứu sơ bộ có giới hạn và không thay kết luận tự do khai thác.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('84e69d92-5c79-4836-bc5c-cc9acd4dc435', '355ab944-8895-5f38-b87f-89e187038e44', '6fbc144f-76bd-5268-8dba-df9e2207ab48', 'Q4', 4, 'V2-5', 'Điều khoản nào cần được ghi rõ khi bên mua cung cấp ảnh để hiệu chỉnh mô hình?', 'Quyền sử dụng ảnh và kết quả, mục đích, truy cập, lưu giữ, xóa hoặc bàn giao', 'Mọi ảnh mặc nhiên chuyển quyền hoàn toàn cho bên bán', 'Bên bán tự quyết định mọi cách dùng không cần thỏa thuận', 'Chỉ cần ghi số ảnh', 'A', 'A đúng. Cần ghi rõ điều kiện vận hành dữ liệu và kết quả giữa các bên.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('4cbe066a-bb25-40bd-9872-ce0a3e1bfcf1', '355ab944-8895-5f38-b87f-89e187038e44', 'b7263826-4835-5832-a750-771e74728aa7', 'Q5', 2, 'V3-3', 'Nội dung nào kiểm chứng được trong hồ sơ tiếp nhận công nghệ?', 'Cam kết máy sẽ không bao giờ có rủi ro', 'Mô tả đúng phiên bản, địa điểm dùng, thời hạn, quyền bảo trì và cách xử lý khi chấm dứt', 'Chỉ ghi thương hiệu sản phẩm', 'Chỉ ghi giá mua mà không ghi quyền phần mềm', 'B', 'B đúng. Quyền sử dụng và nghĩa vụ bàn giao cần gắn với hành vi thực tế.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('e1faddb0-74ee-4cd4-8e31-840249326680', '355ab944-8895-5f38-b87f-89e187038e44', 'b7263826-4835-5832-a750-771e74728aa7', 'Q6', 4, 'V3-6', 'Khi chuỗi quyền cấp phép không rõ và dự án cần triển khai trên nhiều địa điểm, nên làm gì?', 'Coi như đã có quyền vì đã nhận thiết bị', 'Tự kết luận mọi quyền đều vô hiệu', 'Tạm ghi chưa xác minh và chuyển hồ sơ cho người có chuyên môn trước khi cam kết', 'Xóa điều khoản chưa rõ', 'C', 'C đúng. Bảng kiểm hỗ trợ sàng lọc, không thay việc thẩm định pháp lý.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8f7c5f7b-e413-4720-888e-b4817bee5604', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 'ce98fe1c-dfd4-5990-9a56-81449c582634', 'Q1', 2, 'V1-3', 'Khi lập tập ứng viên, cách làm nào tạo lựa chọn có ý nghĩa?', 'Thu thập sáu brochure của cùng một hệ thống và xem như sáu cơ chế khác nhau', 'Liệt kê các kiến trúc giải quyết khác nhau, ghi nguồn và loại bản trùng', 'Chỉ chọn giải pháp được quảng cáo nhiều nhất', 'Chỉ hỏi một đại lý vì tiết kiệm thời gian', 'B', 'B đúng. Mục tiêu ban đầu là tìm những cách giải quyết khác biệt, không phải đếm tài liệu quảng cáo.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('effbfabb-7ce3-483a-a717-dd0ec7d07c77', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', '54d94eec-ee34-5a53-b110-d8bf911c4d14', 'Q3', 163, 'V2-3', 'Cột rủi ro phụ thuộc chấm 5 là phụ thuộc cao. Khi tính điểm thuận lợi cần làm gì?', 'Nhân thẳng với trọng số', 'Bỏ cả cột', 'Dùng điểm bằng 5 cộng 1', 'Đảo thành 6 trừ điểm rủi ro', 'D', 'Phải đảo chiều để rủi ro phụ thuộc cao không được thưởng điểm.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('034a5557-00f3-4f3e-bfbd-d87a27f8691d', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 'ce98fe1c-dfd4-5990-9a56-81449c582634', 'Q2', 4, 'V1-5', 'Khi nhà cung cấp tuyên bố tốc độ 55 túi/phút nhưng chưa thử tại dây chuyền, nên ghi gì?', 'Đã đáp ứng vì trùng chỉ tiêu mong muốn', 'Loại ngay dù chưa kiểm điều kiện thử', 'Ghi tuyên bố và yêu cầu thử ở điều kiện phù hợp', 'Đổi yêu cầu xuống thấp hơn tuyên bố', 'C', 'C đúng. Tốc độ công bố và kết quả kiểm tại hiện trường là hai mức bằng chứng khác nhau.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0e5f97ca-8cc1-4d39-8073-5a8df1a6569c', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 'f2372605-e168-5eb6-9195-5af05c232793', 'Q3', 2, 'V2-3', 'Vì sao cân trọng lượng không nằm trong shortlist kiểm nhãn và mã lô?', 'Không trực tiếp phát hiện hai lỗi bắt buộc của bài toán', 'Vì cân luôn đắt hơn camera', 'Vì công nghệ cân không còn được dùng', 'Vì mọi cân đều thiếu an toàn', 'A', 'A đúng. Loại theo sự không khớp chức năng, không phủ định giá trị của cân cho nhu cầu khác.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('4372580b-7bbe-4dd7-b131-571e6c684e47', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 'f2372605-e168-5eb6-9195-5af05c232793', 'Q4', 4, 'V2-5', 'Phương án đầu đọc Data Matrix chưa biết phù hợp định dạng mã in. Cách ghi nào đúng?', 'Chắc chắn đạt vì có đầu đọc', 'Chắc chắn thất bại trong mọi dây chuyền', 'Đã mua nên không cần thử', 'Giữ có điều kiện hoặc chờ xác minh; kiểm mẫu mã và thay đổi quy trình', 'D', 'D đúng. Chưa có dữ kiện định dạng thì chưa thể khẳng định đã đáp ứng.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a0db231d-ff9e-4338-9e2a-1220645759cf', '4b69b3b6-aecf-5796-ade2-13adad1e5419', '3949d8dc-e99c-59b6-8ae4-e8da82e227af', 'Q5', 2, 'V3-3', 'Yêu cầu quan trọng nhất để so sánh bốn phương án trong thử nghiệm là gì?', 'Mỗi nhà cung cấp tự chọn loại mẫu dễ nhất', 'Cùng định nghĩa lỗi, mẫu được gắn nhãn chuẩn và điều kiện thử được ghi trước', 'Chỉ so sánh bảng giá', 'Đếm số lời nhận xét tích cực trên mạng', 'B', 'B đúng. Bộ quy tắc thử và nhãn chuẩn giúp so sánh kết quả, không thay thẩm định đầy đủ.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('d3db5d25-ccba-4063-a809-1c1ade6d1735', '4b69b3b6-aecf-5796-ade2-13adad1e5419', '3949d8dc-e99c-59b6-8ae4-e8da82e227af', 'Q6', 4, 'V3-5', 'Sau thử nghiệm, chỉ còn hai phương án đáp ứng cửa bắt buộc. Nên làm gì?', 'Đưa lại một phương án không đáp ứng để đủ ba', 'Giữ nguyên bốn phương án dù đã có bằng chứng loại', 'Ghi nhận hai phương án, mở rộng tìm kiếm và giữ điều kiện bắt buộc', 'Bỏ qua kết quả thử vì shortlist đã phê duyệt', 'C', 'C đúng. Số lượng 3-5 là mục tiêu quản lý; không được làm sai lệch điều kiện bắt buộc.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0d947923-a868-4396-b17f-f524737106bf', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 'fa82b636-ccd6-59c8-9c5a-5bf577b7f9ec', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Thực hành khai thác nền tảng: tìm – lọc – lưu – so sánh – kết nối'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7fc69b5e-19d8-4a60-bd3a-15ca0adbf0be', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 'c9bb977e-f788-5ad9-a408-c7f8cbf5f7f5', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9082e63b-ab6b-4985-b58c-780499e95e3d', '60488501-198f-51f9-b9a3-e9d658985077', '495d554b-7338-5fcd-957b-f20486a319f6', 'Q1', 2, 'V1-3', 'Một hệ thống AI công bố 140 túi/phút. Nhận định nào đúng nhất?', 'Chắc chắn phù hợp hơn mọi hệ thống chậm', 'Phải thử trên túi thật và xét khả năng tích hợp', 'Có thể bỏ qua yêu cầu nhịp 55 túi/phút', 'Đủ căn cứ mua ngay', 'B', 'Thông số công bố là đầu mối khảo sát, không thay bằng chứng hoạt động trong điều kiện doanh nghiệp.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('550b3990-fe58-4b4a-b80d-bdf1663f9f2d', '60488501-198f-51f9-b9a3-e9d658985077', '495d554b-7338-5fcd-957b-f20486a319f6', 'Q2', 4, 'V1-5', 'Một phương án không kiểm được mã lô nhưng có chi phí rất thấp. Cách xử lý?', 'Cộng thêm điểm giá để giữ', 'Chọn vì ít phải đào tạo', 'Loại sơ bộ cho nhiệm vụ kiểm mã lô', 'Xem như đạt vì có camera', 'C', 'Không thể lấy ưu điểm về chi phí bù cho chức năng bắt buộc không đáp ứng.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7d445e04-dd5f-4b13-abf1-fc195ba604a2', '60488501-198f-51f9-b9a3-e9d658985077', '2ed0cc21-6a75-5d49-9502-63999a3fad38', 'Q3', 2, 'V2-3', 'B đầu tư 420 triệu, vận hành 100 triệu/năm. Chi phí sơ bộ sau ba năm là bao nhiêu?', '520 triệu', '720 triệu', '1.200 triệu', '420 triệu', 'B', '420 + 3 x 100 = 720 triệu đồng; chưa gồm tích hợp một lần, dừng máy và chiết khấu.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fae2459c-876e-4ef0-bf4b-774e82a7a777', '60488501-198f-51f9-b9a3-e9d658985077', '2ed0cc21-6a75-5d49-9502-63999a3fad38', 'Q4', 4, 'V2-5', 'Tài liệu nào giúp đánh giá rủi ro triển khai hệ thống tự động trên dây chuyền đang chạy?', 'Bản quảng cáo nhiều tính năng', 'Số lượt xem video demo', 'Chỉ bảng giá thiết bị', 'Sơ đồ kết nối, an toàn, đào tạo và bảo trì', 'D', 'Tích hợp và năng lực vận hành quyết định khả năng khai thác thiết bị thực tế.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0fe38d90-62c0-4e46-840c-852e1a0d12d4', '60488501-198f-51f9-b9a3-e9d658985077', 'a33e2e9b-0d04-5e77-a093-93b88c2580e2', 'Q5', 2, 'V3-3', 'B đạt 4,00 và C đạt 3,05 trên thang minh họa. Có thể kết luận gì?', 'B nên được ưu tiên kiểm chứng theo giả định hiện tại', 'B chắc chắn cho lợi nhuận cao nhất', 'C vi phạm pháp luật', 'A được giữ vì điểm 3,60', 'A', 'Điểm giúp thứ tự kiểm chứng theo giả định; các cổng bắt buộc và phép thử vẫn cần thực hiện.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('c5b69362-d88b-4294-b503-25af8da6e1e8', '60488501-198f-51f9-b9a3-e9d658985077', 'a33e2e9b-0d04-5e77-a093-93b88c2580e2', 'Q6', 4, 'V3-5', 'Bộ thử nào phù hợp để so hai hệ thống đọc nhãn và mã lô?', 'Mỗi nhà cung cấp chọn túi dễ nhất', 'Chỉ xem video demo', 'Dùng mẫu đại diện, nhãn chuẩn và cùng tiêu chí đo', 'Dùng nhịp tối đa trên brochure', 'C', 'Phải kiểm nhịp hữu ích, phát hiện lỗi, loại nhầm, dừng máy và điều kiện vận hành trên cùng căn cứ.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('4f1e33ae-3b1b-41cc-bad8-05873bf8ce0c', '05cd1d76-9728-5680-8053-975784ac47d1', '415b0e9e-b613-5b75-820d-bfac26ae7146', 'Q1', 2, 'V1-3', 'A đo 35 túi/phút, dưới nhịp 55 đã chốt. Làm gì trước khi chấm ma trận?', 'Cộng thêm điểm chi phí cho A', 'Cho A đạt vì công nghệ đơn giản', 'Đánh dấu A không đạt cổng nhịp', 'Cho điểm 5 về hỗ trợ', 'C', 'Một điều kiện bắt buộc đã kiểm mà không đạt thì không được bù bằng điểm ở tiêu chí khác.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7a87a4a3-9439-4cbf-9589-b4d116057234', '05cd1d76-9728-5680-8053-975784ac47d1', '415b0e9e-b613-5b75-820d-bfac26ae7146', 'Q2', 4, 'V1-5', 'Phát biểu nào tạo ra tiêu chí công nghệ có thể đánh giá nhất?', 'Máy phải rất thông minh', 'Độ chính xác càng cao càng tốt', 'Giao diện đẹp và hiện đại', 'Tỷ lệ phát hiện lỗi theo mẫu, điều kiện và nhãn chuẩn chốt trước', 'D', 'Cần đơn vị, định nghĩa phép đo, điều kiện, mẫu và người xác nhận.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('03d2c1fb-0203-4273-8670-3880de5bc903', '05cd1d76-9728-5680-8053-975784ac47d1', '123e3321-1b23-53e2-b710-f5ac29f64bec', 'Q3', 2, 'V2-3', 'Bốn trọng số 35%, 25%, 20%, 20% dùng để tính ma trận. Tổng là bao nhiêu?', '80%', '100%', '95%', '105%', 'B', 'Tổng trọng số cần bằng 100% để điểm có trọng số đúng thang.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('d31c8705-f9e6-46fc-966d-3b6f78cf5b2c', '641a0564-4c0a-553d-b485-2857b82f7131', '084f818a-9dc2-5812-8d5f-deb3fe8830c2', 'Q7', 90, 'V1-3', '', '', '', '', '', 'A', 'Đáp án đúng là phương án A.', 7);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('c4a24295-0302-41ae-b6bf-cda5696dfef1', '05cd1d76-9728-5680-8053-975784ac47d1', '123e3321-1b23-53e2-b710-f5ac29f64bec', 'Q4', 4, 'V2-5', 'B được 4,00 nhưng nhịp mới là công bố. Kết luận phù hợp nhất?', 'Mua B ngay vì đứng đầu', 'B chắc chắn đạt nghiệm thu', 'B được ưu tiên kiểm chứng, chưa được phê duyệt đầu tư', 'B không cần đánh giá an toàn', 'C', 'Thứ hạng dựa trên điểm giả định; trạng thái bằng chứng của cổng vẫn chưa xác minh.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('27a83702-1f8f-4588-a4b8-167c1c2ff124', '05cd1d76-9728-5680-8053-975784ac47d1', '9b0a9546-5c85-53e2-9b74-5c30bdbd67af', 'Q5', 2, 'V3-3', 'Điểm 5 về tích hợp chỉ dựa vào brochure. Cách xử lý đúng?', 'Giữ điểm 5 vì tài liệu đẹp', 'Ghi thiếu bằng chứng, yêu cầu thử tích hợp hoặc thẩm định', 'Tự sửa mọi điểm thành 1', 'Loại mọi hệ thống có phần mềm', 'B', 'Mô tả mức điểm và bằng chứng cần nhất quán; không gán kết luận chắc chắn khi chưa thử.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a4956440-45ea-4089-9d59-23e2f3251052', '05cd1d76-9728-5680-8053-975784ac47d1', '9b0a9546-5c85-53e2-9b74-5c30bdbd67af', 'Q6', 4, 'V3-5', 'Muốn so ba hệ thống kiểm mã lô, phương án thử nào tốt nhất?', 'Mỗi bên dùng mẫu dễ nhất', 'Chỉ so tốc độ brochure', 'Đổi tiêu chí sau khi biết kết quả', 'Dùng mẫu đại diện, nhãn chuẩn và tiêu chí đo thống nhất', 'D', 'Cùng cách đếm, điều kiện thử và ngưỡng chấp nhận để kết quả có thể so sánh.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fa9b4a5d-2ae9-4069-91ad-494cb354cd6c', '3bee64ab-aa58-568d-9644-4fcc98021485', '6331708a-175f-592d-a1b0-8ed3003238bf', 'Q1', 2, 'V1-3', 'Máy 420, tích hợp 35, đào tạo 15, dừng lắp 10 (triệu). CAPEX của dự án là?', '420', '450', '480', '520', 'C', 'CAPEX gồm mọi khoản phải chi ban đầu để đưa giải pháp vào sử dụng, không chỉ giá máy.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9c932260-8585-4d84-b74e-6beaa3884beb', '3bee64ab-aa58-568d-9644-4fcc98021485', '6331708a-175f-592d-a1b0-8ed3003238bf', 'Q2', 4, 'V1-5', 'Đào tạo đã nằm trong hợp đồng trọn gói. Khi lập CAPEX nên?', 'Vẫn cộng một lần nữa', 'Kiểm tra phạm vi và bỏ khoản trùng', 'Chuyển thành lợi ích', 'Bỏ hết chi phí đào tạo', 'B', 'Cùng một khoản đã bao gồm trong báo giá không được tính hai lần.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('cc6199d2-fbcc-4353-ba20-b8bc6b5a97af', '3bee64ab-aa58-568d-9644-4fcc98021485', '93a1ccf8-8317-562a-8451-d26034c6ca6e', 'Q3', 2, 'V2-3', 'CAPEX 480, OPEX 100 triệu/năm, kỳ 3 năm, giá trị còn lại 0. TCO là?', '580 triệu', '680 triệu', '780 triệu', '1.080 triệu', 'C', 'TCO đơn giản = 480 + 100 × 3 = 780 triệu đồng.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('37efdf31-792b-46f5-b92a-e41a9f12252e', '3bee64ab-aa58-568d-9644-4fcc98021485', '93a1ccf8-8317-562a-8451-d26034c6ca6e', 'Q4', 4, 'V2-5', 'TCO trả lời tốt nhất câu hỏi nào?', 'Bao lâu thu hồi vốn', 'Doanh nghiệp sẽ chi bao nhiêu trong kỳ theo phạm vi', 'Dòng tiền thuần bằng bao nhiêu', 'NPV dự án là bao nhiêu', 'B', 'TCO là tổng chi phí theo kỳ; chưa bao gồm kết luận về lợi ích thu hồi vốn.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0b7a6288-98d5-4761-b40e-ffe0ac239778', '3bee64ab-aa58-568d-9644-4fcc98021485', 'db571fb0-50fa-57ad-9cf6-e2ddd64c8521', 'Q5', 2, 'V3-3', 'CAPEX 480, tiết kiệm gộp 300, OPEX tăng thêm 100 triệu/năm. Hoàn vốn đơn giản?', '1,60 năm', '2,40 năm', '3,00 năm', '4,80 năm', 'B', 'Dòng tiền thuần tăng thêm là 300 - 100 = 200; hoàn vốn = 480/200 = 2,40 năm.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('6d22a2c2-b2f2-4599-bad9-6e172f6597ee', '3bee64ab-aa58-568d-9644-4fcc98021485', 'db571fb0-50fa-57ad-9cf6-e2ddd64c8521', 'Q6', 5, 'V3-6', 'Tiết kiệm giảm 20%, hoàn vốn thành 3,43 năm, quá kỳ xét 3 năm. Nên kết luận gì?', 'Vẫn chắc chắn đầu tư', 'Thay số trong báo cáo cho đẹp', 'Bỏ phép thử và mua ngay', 'Ghi rủi ro, xác minh dòng tiền, thẩm định tiếp', 'D', 'Kịch bản xấu có thể vượt kỳ, cần kiểm chứng lợi ích và đánh giá sâu hơn.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('6116849e-8831-4b4b-ab5d-671f38c202ae', '2a6a2b77-bc16-5807-897f-9ea287a133ec', '5b117b6a-38a6-5a90-b7c4-650cb5785988', 'Q1', 2, 'V1-3', 'Để so điện khi số lượng sản phẩm đạt khác nhau, chỉ số nào phù hợp nhất?', 'Điện tổng của tháng', 'kWh trên túi đạt', 'Công suất ghi trên vỏ máy', 'Giá mua máy', 'B', 'Điện chia cho số sản phẩm đạt trong cùng ranh giới, có thể quy về 1.000 túi.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9936b0b7-20b8-4e2a-9d45-bc858a414745', '2a6a2b77-bc16-5807-897f-9ea287a133ec', '5b117b6a-38a6-5a90-b7c4-650cb5785988', 'Q2', 4, 'V1-5', 'Rác bao bì A là 80 kg cho 10.000 túi đạt. Rác trên 1.000 túi đạt là?', '0,8 kg', '5 kg', '8 kg', '80 kg', 'C', '80/10.000 × 1.000 = 8 kg/1.000 túi đạt.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('35db8d93-e825-41bf-8198-176adfec6a06', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 'bab2cf5b-a7b9-524a-8468-5ad8877d2b9a', 'Q3', 2, 'V2-3', 'Cường độ điện B 92 và A 100 kWh/1.000 túi. B thay đổi bao nhiêu?', 'Giảm 8%', 'Tăng 8%', 'Giảm 92%', 'Không thay đổi', 'A', '(92 - 100)/100 = -8%, chỉ so cùng phạm vi và đơn vị chức năng.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('967891bb-8e9d-4126-96fa-00115cccf2bf', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 'bab2cf5b-a7b9-524a-8468-5ad8877d2b9a', 'Q4', 4, 'V2-5', 'Dùng hệ số 0,60 kg CO₂e/kWh do bài học tự đặt, kết luận đúng là?', 'Đã kiểm kê vòng đời', 'Đây là hệ số lưới điện chính thức', 'Có thể tuyên bố trung hòa carbon', 'Chỉ là phép tính minh họa từ điện', 'D', 'Hệ số giả định không phải hệ số báo cáo chính thức; chỉ số không gồm các nguồn phát thải khác.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('c5676290-d25c-4f0c-ae55-7128dfb13038', '2a6a2b77-bc16-5807-897f-9ea287a133ec', '6cf8a023-31a1-51ce-8851-5e980532763c', 'Q5', 2, 'V3-3', 'C so với A: điện/túi tăng 15%, rác/túi giảm 56,25%. Nên diễn giải?', 'C chắc chắn xanh nhất', 'C chắc chắn kém nhất', 'Có đánh đổi, cần thêm điều kiện và bằng chứng', 'C và A tương đương', 'C', 'Hai chỉ số đi ngược chiều, không thể kết luận tổng tác động chỉ từ đây.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('6fb7a904-bdb3-49cb-b818-4e93a30b5556', '2a6a2b77-bc16-5807-897f-9ea287a133ec', '6cf8a023-31a1-51ce-8851-5e980532763c', 'Q6', 4, 'V3-6', 'Số liệu mới là giả định, chưa thử trên dây chuyền. Bước phù hợp nhất?', 'Phê duyệt mua ngay B', 'Thử cùng điều kiện, xác minh an toàn và nguồn số', 'Bỏ dữ liệu rác để chỉ xét điện', 'Tuyên bố chứng nhận bền vững', 'B', 'Cần thí điểm có mẫu số, điều kiện đo, nguồn dữ liệu, người phụ trách và các cổng bắt buộc.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('f7b9ab74-7fc6-473d-81f4-187dad6a1608', '0c0953ac-233f-5928-8c22-045b5eea81b2', '083fdd19-19f9-5db1-8ab6-0f5dd26f97eb', 'Q1', 170, 'V1-3', 'Nếu nhật ký kiểm tra chỉ có thể đọc trên máy chủ của một nhà cung cấp, đây là nguy cơ nào cần rà soát ưu tiên?', 'Phụ thuộc công nghệ và khả năng chuyển dữ liệu', 'Chỉ thiếu công suất thiết bị', 'Chỉ thay đổi màu bao bì', 'Không có rủi ro vì phần mềm đang chạy', 'A', 'Không xuất và chuyển được dữ liệu làm tăng chi phí hoặc trở ngại khi đổi đối tác; đồng thời có thể liên quan quyền dữ liệu.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('f4caee2e-7636-4711-a63a-68ad15ddd07c', '0c0953ac-233f-5928-8c22-045b5eea81b2', '083fdd19-19f9-5db1-8ab6-0f5dd26f97eb', 'Q2', 287, 'V1-5', 'Một hãng công bố phần mềm được phép sử dụng nhưng chưa cung cấp tài liệu giấy phép. Nên ghi gì?', 'Đã có vì hãng nói như vậy', 'Chưa xác minh và yêu cầu giấy phép phù hợp', 'Rủi ro bằng không', 'Đã đủ điều kiện ký', 'B', 'Lời giới thiệu không thay hồ sơ quyền có thể kiểm tra; điều kiện bắt buộc phải được xác minh.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1988df7b-1b9c-410c-91ca-a6d026943c0a', '0c0953ac-233f-5928-8c22-045b5eea81b2', '7ab21d70-64a6-593c-8399-25eb093562c7', 'Q3', 165, 'V2-3', 'Khi chấm P = 4, I = 4 cho rủi ro R1, cách hiểu đúng của điểm 16 là gì?', 'Xác suất sự cố bằng 16%', 'Thiệt hại cố định 16 triệu đồng', 'Mức sàng lọc cao theo thang minh họa', 'Đã chứng minh sự cố sẽ xảy ra', 'C', 'Điểm P x I giúp sắp thứ tự kiểm tra; thang thứ bậc không phải xác suất hoặc tiền thiệt hại.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('44264a5f-625b-4a61-bc8e-d3dba9929fc8', '0c0953ac-233f-5928-8c22-045b5eea81b2', '7ab21d70-64a6-593c-8399-25eb093562c7', 'Q4', 284, 'V2-5', 'Giả sử rủi ro quyền phần mềm có điểm trung bình nhưng chưa có hồ sơ quyền. Cách xử lý phù hợp?', 'Bù bằng điểm chức năng tốt', 'Chốt mua vì điểm chưa cao', 'Bỏ qua và bàn sau hợp đồng', 'Chưa chốt, yêu cầu thẩm định quyền', 'D', 'Thiếu bằng chứng ở cổng bắt buộc không được bù bằng tổng điểm rủi ro thấp.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('578bc4ce-ea26-4b7e-b5af-f155a5cdab0c', '0c0953ac-233f-5928-8c22-045b5eea81b2', 'ed0324ec-cea2-5af7-bcea-e7cabdbfe634', 'Q5', 148, 'V3-3', 'Biện pháp nào tạo bằng chứng tốt nhất để kiểm rủi ro dữ liệu R2?', 'Thử mẫu đủ ca và loại túi, nhãn chuẩn độc lập, lưu kết quả', 'Chọn những ảnh đẹp nhất', 'Tin hoàn toàn báo cáo do hãng chọn mẫu', 'Bỏ dữ liệu ca tối', 'A', 'Bộ mẫu đại diện, nhãn độc lập và nhật ký cho phép kiểm chứng bỏ sót và loại nhầm trong điều kiện dự kiến.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('2d912765-dc86-4bf8-b17b-8982a22b00c4', '0c0953ac-233f-5928-8c22-045b5eea81b2', 'ed0324ec-cea2-5af7-bcea-e7cabdbfe634', 'Q6', 288, 'V3-6', 'Sau khi lập biện pháp giảm rủi ro, khi nào nên giảm điểm P hoặc I?', 'Ngay khi ghi biện pháp vào Excel', 'Khi đã thực hiện, có chứng cứ thử lại và được xác nhận', 'Khi nhà cung cấp đồng ý miệng', 'Khi cần làm điểm bảng đẹp hơn', 'B', 'Điểm sau kiểm soát chỉ có căn cứ khi biện pháp đã được triển khai và kiểm chứng hiệu lực.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9c830db2-08c9-4a0d-9a3a-87861b1a5cd9', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', '0553384a-230a-51e6-8577-d59cff39f363', 'Q1', 172, 'V1-3', 'An Bình muốn thiết kế phép thử độc lập cho OCR. Đầu mối ưu tiên là ai?', 'Đơn vị bán hàng chỉ gửi catalogue', 'Chuyên gia thị giác có phương pháp thử và công bố lợi ích', 'Nhà vận chuyển bao bì', 'Đơn vị chỉ làm quảng cáo', 'B', 'Nhiệm vụ đánh giá độc lập cần năng lực thiết kế thử và minh bạch lợi ích.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a38ffbf9-aa94-4c75-82ad-ec5905c33c75', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', '0553384a-230a-51e6-8577-d59cff39f363', 'Q2', 287, 'V1-5', 'Một đối tác được giới thiệu tại hội thảo. Việc nào cần làm tiếp?', 'Tin ngay vì có diễn giả', 'Chọn vì trang web đẹp', 'Đối chiếu dự án, vai trò thực hiện và người tham chiếu', 'Chỉ yêu cầu bảng giá', 'C', 'Hội thảo là nguồn tìm đầu mối, chưa chứng minh năng lực với điều kiện An Bình.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0b0b9188-5916-494d-8d6f-8541b0d9e91b', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', '9971d7b8-88ac-5771-8733-89a109dce846', 'Q3', 168, 'V2-3', 'Đơn vị I1 đạt 5,0 điểm nhưng hồ sơ tham chiếu chưa xác minh. Cách xử lý?', 'Giữ trạng thái chờ xác minh', 'Tự động mời chuyên sâu vì điểm cao', 'Giảm điểm về 0 để loại', 'Coi như đã đủ năng lực', 'A', 'Điểm sơ bộ không thay cổng bằng chứng; cần tài liệu và người xác nhận.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('2fa3fb20-787f-4900-9e17-4821316f6c32', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', '9971d7b8-88ac-5771-8733-89a109dce846', 'Q4', 226, 'V2-4', 'Người đánh giá nhận hoa hồng của nhà cung cấp. Điều gì phù hợp?', 'Bỏ qua nếu người đó có bằng cấp', 'Yêu cầu minh bạch, đánh giá và quản lý xung đột', 'Tự động coi báo cáo độc lập', 'Giấu quan hệ để làm việc nhanh', 'B', 'Quan hệ tài chính có thể ảnh hưởng tính độc lập của ý kiến và phải được xử lý.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('66d78e69-8c01-4f19-a439-bafdaa0185ab', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 'e6cd24b4-778e-59d7-a997-915ff14a6fab', 'Q5', 122, 'V3-3', 'Câu hỏi nào giúp kiểm chứng lời quảng cáo “OCR chính xác 99%”?', 'Anh có tự tin không?', 'Công nghệ có hiện đại nhất không?', 'Thiết bị có nhiều tính năng không?', 'Tỷ lệ đo trên mẫu nào, ai gán nhãn chuẩn và điều kiện thử ra sao?', 'D', 'Cần mẫu, nhãn chuẩn, điều kiện thử và cách định nghĩa chỉ số.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('605211ef-0202-4f25-a497-347bf0356c68', 'd5e05c2f-1581-55da-8663-ed6be4535ad5', 'e6cd24b4-778e-59d7-a997-915ff14a6fab', 'Q6', 257, 'V3-6', 'Sau buổi trao đổi, bên cung cấp đã gửi brochure nhưng chưa có log thử. Ghi gì?', 'Đã xác minh đầy đủ', 'Tự động phê duyệt', 'Đã nhận brochure; log thử còn thiếu và có người theo dõi', 'Không cần theo dõi', 'C', 'Nhận tài liệu quảng cáo khác với xác minh hiệu quả trong điều kiện thực tế.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fcde0ce6-20b6-483d-a677-f0a5b6bee2b8', 'ff65e401-5641-52eb-92a0-b93256b41783', '1921e2df-4b73-5b40-8eea-ddee25b36f5e', 'Q1', 160, 'V1-3', 'Ai nên xác nhận định nghĩa lỗi nhãn và mẫu kiểm của An Bình?', 'Bộ phận chất lượng có dữ liệu và thẩm quyền', 'Nhà cung cấp chỉ có catalogue', 'Người ghi hình cuộc họp', 'Khách tham dự không biết dây chuyền', 'A', 'QC xác nhận dữ liệu và nhãn lỗi thuộc nghiệp vụ doanh nghiệp; nhà cung cấp cần đưa chứng cứ của mình.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0981412a-1711-4dbe-b7c8-4bc14a65e42b', 'ff65e401-5641-52eb-92a0-b93256b41783', '1921e2df-4b73-5b40-8eea-ddee25b36f5e', 'Q2', 264, 'V1-5', 'Mục tiêu phù hợp của buổi kết nối 45 phút là gì?', 'Ký hợp đồng ngay', 'Chọn hãng nổi tiếng nhất', 'Xác định bằng chứng cần nhận và người theo dõi', 'Công bố máy chắc chắn đạt 99%', 'C', 'Kết nối sơ bộ tạo các câu hỏi có đầu ra, chưa thay thẩm định công nghệ và quy trình mua sắm.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('d9a1013e-2ba7-46e0-bd2f-cad30e0fba48', 'ff65e401-5641-52eb-92a0-b93256b41783', '4305db71-69dd-555b-bdc7-95c46cb091b5', 'Q3', 152, 'V2-3', 'Nhà cung cấp nói OCR đúng 99%. Cần hỏi gì trước?', 'Logo sản phẩm', 'Mẫu, nhãn chuẩn, điều kiện và các loại sai lỗi', 'Số lượt xem quảng cáo', 'Màu thiết bị', 'B', 'Phải kiểm định nghĩa chỉ số, mẫu thử và điều kiện vận hành để hiểu giá trị của tuyên bố.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('57a4960a-4db0-4cfb-9405-866644d514af', 'ff65e401-5641-52eb-92a0-b93256b41783', '4305db71-69dd-555b-bdc7-95c46cb091b5', 'Q4', 205, 'V2-4', 'Nhà cung cấp nói 140 túi/phút nhưng vận hành lo đổi mã nhiều. Điều phối viên nên làm gì?', 'Tuyên bố bên bán sai', 'Chốt thông số công bố làm KPI', 'Bỏ câu hỏi vì mất thời gian', 'Ghi điều kiện khác nhau và đề xuất phép thử trên dây chuyền', 'D', 'Cần tách tốc độ công bố khỏi năng suất đạt và yêu cầu phép thử trong điều kiện thực tế.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('f54bcd7f-25b1-4776-9180-ac993978d76c', 'ff65e401-5641-52eb-92a0-b93256b41783', 'f93ffd0a-45d1-5fa8-9095-50eba41ae27b', 'Q5', 129, 'V3-3', 'Đã nhận brochure nhưng chưa có bản ghi thử OCR. Trạng thái nào đúng?', 'Đã xác minh hiệu quả', 'Cần bổ sung bằng chứng thử', 'Đã nghiệm thu', 'Đã có quyết định đầu tư', 'B', 'Brochure có thể giúp tìm hiểu giải pháp nhưng chưa thay nhật ký và kết quả thử có truy vết.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('581fca32-9344-4876-aad6-3e26f4bd60ca', 'ff65e401-5641-52eb-92a0-b93256b41783', 'f93ffd0a-45d1-5fa8-9095-50eba41ae27b', 'Q6', 272, 'V3-6', 'Cuộc họp vượt giờ và còn đầu việc chưa giao. Kết luận phù hợp?', 'Ghi việc chưa đóng, phân công bổ sung và chưa chuyển quyết định đầu tư', 'Coi như hoàn thành vì đã họp', 'Mua ngay để kịp tiến độ', 'Xóa câu hỏi chưa được trả lời', 'A', 'Thiếu chứng cứ hoặc chủ việc phải được theo dõi riêng, không biến thành phê duyệt mua sắm.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0d29d6c9-3cea-4ce2-911c-545ade91ed0a', '9234a8e5-99d4-5ea0-808d-2d2889672b51', '6572848d-6f87-552e-b95e-b1222a2f164b', 'Q1', 165, 'V1-3', 'PoC trước đầu tư lớn nên trả lời câu hỏi nào?', 'Hợp đồng đã đủ điều kiện thanh toán chưa?', 'Chức năng cốt lõi có đạt ngưỡng trên mẫu và điều kiện đã định không?', 'Nhà cung cấp có logo đẹp không?', 'Có cần bỏ qua việc kiểm nhãn chuẩn không?', 'B', 'PoC kiểm giả thuyết khả thi trong phạm vi hẹp; khác nghiệm thu và vận hành diện rộng.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7b34325d-d288-4eb2-9728-40e4912e7fd9', '9234a8e5-99d4-5ea0-808d-2d2889672b51', '6572848d-6f87-552e-b95e-b1222a2f164b', 'Q2', 273, 'V1-5', 'Tỷ lệ loại nhầm phải lấy mẫu số nào?', 'Tổng số mẫu có lỗi', 'Tổng ảnh chưa gán nhãn', 'Tổng số mẫu thực sự tốt', 'Tổng chi phí PoC', 'C', 'Tỷ lệ loại nhầm bằng FP chia FP cộng TN, tức nhóm thực sự tốt.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7c7bfbb0-3e73-43e5-a0ff-8a119dd6a920', '9234a8e5-99d4-5ea0-808d-2d2889672b51', '301d75a1-06d9-521f-9a50-aa09b3c4894e', 'Q3', 154, 'V2-3', 'TP = 96 và FN = 4. Tỷ lệ phát hiện lỗi là bao nhiêu?', '96%', '4%', '92%', '99%', 'A', '96/(96+4)=96%; đạt ngưỡng 95% của ví dụ nhưng chưa đủ để duyệt đầu tư.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('4149cefe-5d71-4721-8752-37ba2ca4e436', '9234a8e5-99d4-5ea0-808d-2d2889672b51', '301d75a1-06d9-521f-9a50-aa09b3c4894e', 'Q4', 209, 'V2-4', 'FP = 16 và TN = 384. Tỷ lệ loại nhầm là bao nhiêu?', '16%', '96%', '3%', '4%', 'D', '16/(16+384)=4%, vượt giới hạn 3% của bài tập.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('dd5c5b0f-896b-422b-99fd-9f1da89be4ee', '9234a8e5-99d4-5ea0-808d-2d2889672b51', '9726996e-aec5-5ae9-95dd-9f6d5ee337d8', 'Q5', 125, 'V3-3', 'Phát hiện 96% và loại nhầm 4%, với ngưỡng ít nhất 95% và tối đa 3%. Kết luận nào đúng?', 'Đã đạt cả hai', 'Chưa đạt toàn bộ; cần điều chỉnh và thử lại', 'Có thể mua ngay vì phát hiện tốt', 'Tỷ lệ loại nhầm không cần xem', 'B', 'Một chỉ tiêu đạt không bù cho chỉ tiêu khác không đạt; còn các cổng bắt buộc phải kiểm riêng.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('75960773-9e78-48b3-a428-2e25bd393e69', '9234a8e5-99d4-5ea0-808d-2d2889672b51', '9726996e-aec5-5ae9-95dd-9f6d5ee337d8', 'Q6', 283, 'V3-6', 'Nếu PoC độc lập đạt cả hai chỉ số và đủ cổng, bước tiếp theo hợp lý là gì?', 'Phê duyệt mua ngay', 'Tuyên bố phù hợp mọi nhà máy', 'Đề xuất thí điểm vận hành có kiểm soát và thẩm định tiếp', 'Không cần phân tích chi phí', 'C', 'PoC thành công trong phạm vi hẹp mới là cơ sở xem xét bước thí điểm, chưa thay quyết định đầu tư.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('903d8896-1f77-4858-9265-ca22092cdd88', '9234a8e5-99d4-5ea0-808d-2d2889672b51', '6572848d-6f87-552e-b95e-b1222a2f164b', 'Q7', 90, 'V1-3', '', '', '', '', '', 'A', 'Đáp án đúng là phương án A.', 7);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('6facbca8-fc49-43e3-a1ac-e51f5af61349', 'f18c0159-faed-555c-9ff4-5e727391c028', '6d332125-8ba0-56a2-bfdf-e03a018f13cd', 'Q1', 176, 'V1-3', 'Trong thí điểm, tỷ lệ phát hiện lỗi dùng mẫu số nào?', 'TP + FP', 'TP + FN', 'FP + TN', 'Tổng giờ chạy', 'B', 'Mẫu lỗi thật gồm cả phát hiện đúng TP và bỏ sót FN.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a92008ed-e742-4813-ae89-c4b8c8fc5a50', 'f18c0159-faed-555c-9ff4-5e727391c028', '6d332125-8ba0-56a2-bfdf-e03a018f13cd', 'Q2', 286, 'V1-5', 'Nếu chưa được duyệt an toàn cho cơ cấu loại, cần làm gì?', 'Tạm dừng phần thử liên quan', 'Lấy trung bình các KPI để cho qua', 'Đổi ngưỡng tốc độ', 'Bỏ cổng an toàn khỏi biên bản', 'A', 'Cổng an toàn không được bù bằng KPI đạt.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('38a75ade-410d-4629-9842-a6f2c6ba7f38', 'f18c0159-faed-555c-9ff4-5e727391c028', '9efcd7e5-9d8a-591b-b0b4-998ef7ac2e55', 'Q3', 153, 'V2-3', 'TP gộp 188, FN gộp 12. Phát hiện lỗi bằng bao nhiêu?', '95%', '96%', '94%', '98%', 'C', '188/(188+12)=94%; không đạt ngưỡng giả định 95%.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('e179d828-7022-4439-a631-52fdec8e2806', 'f18c0159-faed-555c-9ff4-5e727391c028', '9efcd7e5-9d8a-591b-b0b4-998ef7ac2e55', 'Q4', 265, 'V2-5', '160 giờ kế hoạch, dừng 6,7 giờ. Tỷ lệ sẵn sàng khoảng bao nhiêu?', '94,00%', '95,81%', '96,70%', '6,70%', 'B', '(160-6,7)/160=95,8125%. Nêu rõ giờ dừng thuộc phạm vi đo.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('26bd3b0d-854f-4525-8074-c0879a7f2007', 'f18c0159-faed-555c-9ff4-5e727391c028', '3a25ea6d-830c-5306-9c9f-c03a5a9a3920', 'Q5', 103, 'V3-2', 'Ba KPI đạt nhưng phát hiện lỗi gộp 94% dưới ngưỡng 95%. Kết luận đúng?', 'Nhân rộng ngay', 'Dừng vĩnh viễn không cần xét', 'Bỏ KPI phát hiện vì có ba KPI khác đạt', 'Điều chỉnh và thử lại theo kế hoạch', 'D', 'Tất cả điều kiện chỉ tiêu phải được xét riêng; tránh bù trừ.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7750bb95-1342-414a-bc03-48c876330948', 'f18c0159-faed-555c-9ff4-5e727391c028', '3a25ea6d-830c-5306-9c9f-c03a5a9a3920', 'Q6', 290, 'V3-6', 'Khi thí điểm đủ cổng và đạt mọi KPI, hành động phù hợp nhất là?', 'Chuyển sang thẩm định và đề xuất tiếp tục có điều kiện', 'Tự phê duyệt mua thiết bị', 'Bỏ thẩm định chi phí và hợp đồng', 'Khẳng định dùng được mọi nhà máy', 'A', 'Đạt trong phạm vi pilot chưa là phê duyệt đầu tư lớn.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fa31f896-4a2f-424f-9599-869f2055246f', 'f18c0159-faed-555c-9ff4-5e727391c028', '6d332125-8ba0-56a2-bfdf-e03a018f13cd', 'Q7', 90, 'V1-3', '', '', '', '', '', 'A', 'Đáp án đúng là phương án A.', 7);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('2cf2c052-5255-41be-90c7-10ce33e7ccb7', '4d0e297e-d66a-5abb-b635-d0810e720e7f', '571a872e-15ca-5b6a-ab0a-2d7c961aa739', 'Q1', 174, 'V1-3', 'Bằng chứng nào tốt nhất cho thấy có thể tiếp nhận cấu hình OCR?', 'Biên bản ghi “đã bàn giao” nhưng không có tệp', 'Tệp cấu hình đúng phiên bản, mở thử được và có người nhận', 'Chỉ có ảnh chụp máy', 'Tin nhắn nói nhà cung cấp sẽ gửi sau', 'B', 'Hồ sơ cần có phiên bản, bản bàn giao và phép thử có thể kiểm chứng.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1a509b15-26d4-4145-88b1-dfe0af7de058', '4d0e297e-d66a-5abb-b635-d0810e720e7f', '571a872e-15ca-5b6a-ab0a-2d7c961aa739', 'Q2', 286, 'V1-5', 'Nếu chưa có phép thử khôi phục dữ liệu, người học nên chọn gì?', 'Tạm dừng phần triển khai liên quan và xác minh', 'Bỏ qua vì đào tạo đã đủ', 'Đổi ngưỡng đào tạo cho dễ đạt', 'Tự đánh dấu đã kiểm để hoàn thành bài', 'A', 'Cổng khôi phục không thể bù bằng tỷ lệ học viên đạt.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('d75777c0-668a-4f36-bdfd-7406ab0eed43', '4d0e297e-d66a-5abb-b635-d0810e720e7f', '3de074fd-dd95-5b7b-a554-16c344f57153', 'Q3', 167, 'V2-3', 'Đã học 15 người trong 16 người phải có. Bao phủ đào tạo là bao nhiêu?', '95,00%', '81,25%', '93,75%', '86,67%', 'C', '15/16=93,75%; mẫu số là số người cần đào tạo.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('20c1b97d-a36b-4426-82fd-b18671ddb2ee', '4d0e297e-d66a-5abb-b635-d0810e720e7f', '3de074fd-dd95-5b7b-a554-16c344f57153', 'Q4', 281, 'V2-5', 'Đã học 15, đạt thao tác 13, yêu cầu 16 người. Chỉ tiêu sẵn sàng năng lực của bài là?', '13/15', '15/13', '16/13', '13/16', 'D', 'Bài này xét tỷ lệ nhân sự cần có đã đạt thao tác, bằng 13/16.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1453e780-9bee-4fcf-a83b-c0d780ece848', '4d0e297e-d66a-5abb-b635-d0810e720e7f', '0463cca6-78fe-5b57-a8c0-5176779bd869', 'Q5', 92, 'V3-2', 'Các cổng đủ nhưng hai tỷ lệ đào tạo dưới ngưỡng. Kết luận nào đúng?', 'Bổ sung đào tạo, chưa nhân rộng', 'Nhân rộng vì đã nghiệm thu thiết bị', 'Bỏ qua kiểm tra thao tác', 'Đếm lại số người theo cách có lợi', 'A', 'Nghiệm thu công nghệ không thay thế năng lực vận hành.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8fc5c219-0ded-4798-99f2-8ff5ab5fc63d', '4d0e297e-d66a-5abb-b635-d0810e720e7f', '0463cca6-78fe-5b57-a8c0-5176779bd869', 'Q6', 280, 'V3-6', 'Sau khi được duyệt mở rộng một ca, bước nào vẫn bắt buộc?', 'Bỏ nhật ký vì đã được duyệt', 'Theo dõi KPI, sự cố, đào tạo bổ sung và đường quay lui', 'Cho mọi ca dùng ngay', 'Ngừng lưu phiên bản phần mềm', 'B', 'Mỗi giai đoạn phải theo dõi chất lượng, sự cố, nguồn lực và quy tắc dừng.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a86dabf2-9ae0-4759-be98-91d0ddad70e8', '4d0e297e-d66a-5abb-b635-d0810e720e7f', '571a872e-15ca-5b6a-ab0a-2d7c961aa739', 'Q7', 90, 'V1-3', '', '', '', '', '', 'A', 'Đáp án đúng là phương án A.', 7);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0ecaac5a-3b3c-4376-a38a-5bcb88791acf', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', '2763b367-0ef5-59e3-a700-ae2125658f43', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Bản đồ công nghệ mới: những xu hướng đang thay đổi doanh nghiệp và sản xuất'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('636196f2-d320-4219-8b6d-1c50479627e8', '84f227ba-8772-58f7-bbc5-621fcdd8b0e7', '05d08086-e37b-5d97-b5e7-be14ec90c6bb', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('5781f0ca-274a-4aa0-b324-b8352c48db1d', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', '54d94eec-ee34-5a53-b110-d8bf911c4d14', 'Q1', 168, 'V1-3', 'Một video trình diễn từ nhà cung cấp chưa nêu số mẫu. Cần làm gì trước khi dùng làm chứng cứ?', 'Coi số người xem là độ tin cậy', 'Ghi nguồn, phương pháp, phạm vi và yêu cầu dữ liệu kiểm chứng', 'Tự thêm mẫu số', 'Xếp công nghệ vào nhóm đã chứng minh', 'B', 'Trình diễn giúp nêu câu hỏi nhưng không đủ cho kết luận hiệu năng khi thiếu mẫu số và điều kiện thử.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9fb699d8-c280-430c-b428-2e71e1a2d49c', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', '54d94eec-ee34-5a53-b110-d8bf911c4d14', 'Q2', 282, 'V1-5', 'Tại sao 98 mẫu nhận đúng không đủ để kết luận chính xác 98%?', 'Vì OCR luôn sai', 'Vì chỉ đo trên máy tính', 'Vì không biết tổng mẫu và cách chọn mẫu', 'Vì phải dùng 100 video', 'C', 'Cần mẫu số, thành phần mẫu và quy trình đo; 98 mẫu đúng chưa cho biết tỷ lệ.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7c00a934-1b62-4dda-8486-7a219f6105f6', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', '54d94eec-ee34-5a53-b110-d8bf911c4d14', 'Q4', 268, 'V2-5', 'Ứng viên có 3,65 điểm nhưng nguồn chưa đối chiếu. Trạng thái đúng là?', 'Giữ ở nhóm chưa kiểm nguồn', 'Được phê duyệt mua', 'Thử ngay không cần bảo mật', 'Tự sửa trạng thái nguồn', 'A', 'Điểm cao không bù thiếu xác minh nguồn và các cổng khác.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9c777295-438e-4b30-ac0b-0eac2dff07a8', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', '54d94eec-ee34-5a53-b110-d8bf911c4d14', 'Q5', 94, 'V3-2', 'Điểm minh họa OCR 5,4,4,2 với trọng số 35%,30%,20%,15% là bao nhiêu?', '3,35', '4,35', '4,85', '5,15', 'B', '5x0,35 + 4x0,30 + 4x0,20 + (6-2)x0,15 = 4,35.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8c656653-7aab-452e-a7dc-35ca95c4ea4a', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', '54d94eec-ee34-5a53-b110-d8bf911c4d14', 'Q6', 276, 'V3-6', 'OCR đạt điểm cao nhưng một cổng về quyền dữ liệu chưa kiểm. Kết luận nào đúng?', 'Mua ngay để không lỡ cơ hội', 'Bỏ qua cổng vì điểm cao', 'Tiếp tục xác minh, chưa triển khai thử', 'Đổi thang điểm để thành đạt', 'C', 'Cổng dữ liệu, an toàn và trách nhiệm phải được kiểm bằng chứng riêng trước bước triển khai.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('21a39f35-ba7b-404c-b4ad-3a3aef82d9df', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', '54d94eec-ee34-5a53-b110-d8bf911c4d14', 'Q7', 90, 'V1-3', '', '', '', '', '', 'A', 'Đáp án đúng là phương án A.', 7);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a50211e1-ec37-4acb-96e5-bd0487deb681', '6721da87-6494-5fd4-9cc7-6163a275f01a', '8e4a2cd9-d62f-56c0-b2ae-d36e5ddd55db', 'Q1', 156, 'V1-3', 'Khi bắt đầu xem xét AI, việc nào phải làm trước?', 'Chọn nền tảng AI đang được giới thiệu nhiều', 'Chốt vấn đề, KPI nền và người xác nhận', 'Mua camera để có dữ liệu', 'Ước lượng phần trăm tiết kiệm từ quảng cáo', 'B', 'Mục tiêu vận hành phải có mẫu số, đường cơ sở và chủ quy trình; công cụ là bước sau.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('736f4ea6-30f0-4087-bfcd-8345b9db2809', '6721da87-6494-5fd4-9cc7-6163a275f01a', '8e4a2cd9-d62f-56c0-b2ae-d36e5ddd55db', 'Q2', 264, 'V1-5', 'Hệ thống mới giảm lỗi lọt nhưng loại nhầm nhiều mẫu tốt. Nên đánh giá thế nào?', 'Chỉ báo cáo số lỗi phát hiện thêm', 'Chỉ dùng độ chính xác chung', 'Xem cả lỗi lọt, loại nhầm và chi phí xử lý lại', 'Kết luận có AI là tốt hơn', 'C', 'Lỗi lọt và loại nhầm gây chi phí khác nhau; cần đo cùng bộ mẫu với phương án hiện tại.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0df757a3-a7bd-448a-9a3f-9c3347fc5d1e', '6721da87-6494-5fd4-9cc7-6163a275f01a', '8e4a2cd9-d62f-56c0-b2ae-d36e5ddd55db', 'Q3', 164, 'V2-3', 'Trong 1.000 hồ sơ, 850 hồ sơ dùng được. Tỷ lệ dữ liệu dùng được là bao nhiêu?', '15%', '75%', '85%', '95%', 'C', '850 chia 1.000 bằng 0,85; tỷ lệ này chưa chứng minh mẫu đại diện hoặc mô hình sẽ tốt.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('cef9da47-265f-44dc-a932-ba60a8c277a9', '6721da87-6494-5fd4-9cc7-6163a275f01a', '8e4a2cd9-d62f-56c0-b2ae-d36e5ddd55db', 'Q4', 267, 'V2-5', 'Dữ liệu kỹ thuật có sẵn nhưng chưa xác minh quyền đưa lên dịch vụ AI. Cách xử lý đúng?', 'Tải ngay vì là dữ liệu kỹ thuật', 'Ẩn tên file là đủ', 'Tăng điểm sẵn sàng dữ liệu', 'Chưa đưa lên dịch vụ; xác nhận quyền và phạm vi xử lý', 'D', 'Quyền xử lý và bảo mật là cổng riêng, không thể bù bằng dữ liệu có vẻ đầy đủ.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('13833fa7-f54e-48f3-93f0-261514551580', '6721da87-6494-5fd4-9cc7-6163a275f01a', '8e4a2cd9-d62f-56c0-b2ae-d36e5ddd55db', 'Q5', 147, 'V3-3', 'A có 4,53/5 nhưng cổng quyền dữ liệu vẫn “Chưa kiểm”. Kết luận nào đúng?', 'Chưa mở thử; bổ sung bằng chứng về quyền dữ liệu', 'Được mua vì đứng đầu', 'Tự sửa cổng thành Đã kiểm', 'Bỏ đối chứng không AI', 'A', 'Điểm sàng lọc chỉ xếp thứ tự công việc. Cổng bắt buộc phải có hồ sơ, người duyệt riêng.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('0db72a8f-b951-4070-948b-a16beaa9290f', '6721da87-6494-5fd4-9cc7-6163a275f01a', '8e4a2cd9-d62f-56c0-b2ae-d36e5ddd55db', 'Q6', 247, 'V3-5', 'Nhóm dùng chính dữ liệu đã tinh chỉnh mô hình để tuyên bố hiệu năng. Lỗi chính là gì?', 'Tốn nhiều máy tính', 'Thiếu bộ đánh giá độc lập, dễ đánh giá quá cao', 'Có quá nhiều KPI', 'Chọn công nghệ quá sớm', 'B', 'Bộ kiểm chứng phải độc lập và có quy tắc gán nhãn thống nhất; không tự kiểm bằng mẫu đã tối ưu.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('bce2e8ba-e149-4c10-a5c6-b097553d3aea', 'e12f1618-2bc3-522e-80ad-727bfc35311a', '054d4960-8cee-5fbc-85c9-3ddc72f969e8', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Nhà máy thông minh: lộ trình từ số hóa đến sản xuất thông minh'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('cd10c16a-ca8a-4fb6-b692-657574af860e', 'e12f1618-2bc3-522e-80ad-727bfc35311a', '96eb7202-79c5-58d3-9805-53aa92ddac22', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('4a16b091-5f49-430a-a8fb-dea13c66938f', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 'ee0e2d07-4c5f-544c-88ed-66a4fff657d7', 'Q1', 170, 'V1-3', 'Thông tin nào biến danh sách máy thành bản đồ công nghệ theo quy trình?', 'Chỉ cần tên và giá mua', 'Công đoạn, năng lực, KPI, người phụ trách và liên kết', 'Tên phần mềm đang nổi', 'Số lượng nhà cung cấp', 'B', 'Bản đồ phải cho thấy công nghệ phục vụ hoạt động nào và bằng chứng kết quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('6952f0af-61ed-443b-bc1d-2bacac209e77', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 'ee0e2d07-4c5f-544c-88ed-66a4fff657d7', 'Q2', 283, 'V1-5', 'Hiện trạng mức 1, mục tiêu mức 4. Khoảng trống là bao nhiêu và có tự đủ để ưu tiên đầu tư?', '3 và chưa đủ để phê duyệt', '4 và chắc chắn mua', '5 vì thang tối đa là 5', '1 vì hiện trạng thấp', 'A', 'Khoảng trống là 4 - 1 = 3; còn cần tác động, khả năng triển khai, nguồn lực và cổng.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('d4d36dec-92cd-4c39-af36-c68b57c5eecf', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 'ee0e2d07-4c5f-544c-88ed-66a4fff657d7', 'Q3', 173, 'V2-3', 'Hai người chấm độ sẵn sàng khác nhau. Bước cần làm để bảng điểm kiểm chứng được?', 'Lấy điểm cao hơn', 'Giữ nguyên vì điểm là ý kiến', 'Thống nhất mô tả thang, nguồn minh chứng và người chấm', 'Xóa tiêu chí độ sẵn sàng', 'C', 'Thang, bằng chứng, người duyệt và thời điểm phải được ghi cùng điểm.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('073778f4-e6a3-42b6-a6bf-a55f010c8ea8', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 'ee0e2d07-4c5f-544c-88ed-66a4fff657d7', 'Q4', 284, 'V2-5', 'Một ứng dụng phụ thuộc nhật ký dừng máy còn thiếu. Điều này tác động thế nào đến danh mục?', 'Không liên quan vì điểm cao', 'Tự phê duyệt chi phí', 'Bỏ qua bước dữ liệu nền', 'Có thể phải thực hiện công việc dữ liệu nền trước ứng dụng', 'D', 'Thứ tự thực hiện phải xét phụ thuộc, không chỉ điểm xếp hạng.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('326a4e2e-0517-4cfb-8d9a-011e054077d4', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 'ee0e2d07-4c5f-544c-88ed-66a4fff657d7', 'Q5', 135, 'V3-3', 'Hạng mục C có tác động 5, khoảng trống 3 và sẵn sàng 4. Điểm 40/35/25 là?', '3,40', '4,40', '4,75', '5,00', 'B', '5x0,40 + (1+3)x0,35 + 4x0,25 = 4,40.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('3f40c71d-a45c-4c36-9088-dd8a505c9821', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 'ee0e2d07-4c5f-544c-88ed-66a4fff657d7', 'Q6', 234, 'V3-5', 'C có điểm 4,40 nhưng một cổng quyền dữ liệu vẫn Chưa kiểm. Kết luận đúng?', 'Phê duyệt mua ngay', 'Bù cổng bằng điểm cao', 'Tiếp tục sàng lọc nhưng chưa mở triển khai khi thiếu cổng', 'Sửa cổng thành Đã kiểm', 'C', 'Điểm ưu tiên là phép sàng lọc; quyền dữ liệu, an toàn và nguồn lực phải được xác minh riêng.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('4b7c322b-c530-40ee-a918-08df2bc5e56a', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', '6b178942-29e9-57fb-a378-8fa757191dc4', 'Q1', 174, 'V1-3', 'Trước khi lập dự án phân tích dừng máy, cần ưu tiên việc nào?', 'Mua ngay mô hình dự báo', 'Chuẩn hóa mã sự cố và nhật ký dừng máy', 'Chuyển phần mềm mà không kiểm dữ liệu', 'Lấy điểm ưu tiên làm bằng chứng', 'B', 'Phân tích dừng máy phụ thuộc bản ghi có định nghĩa, đủ kỳ và người sở hữu.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fff8cc07-d492-4d00-ab19-5df1be40bda4', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', '6b178942-29e9-57fb-a378-8fa757191dc4', 'Q2', 283, 'V1-5', 'P4 thử lại OCR phụ thuộc P3 chuẩn dữ liệu nhãn. Lịch nào phù hợp quy tắc trong phiếu?', 'Cả hai đều năm 1', 'P4 năm 1, P3 năm 2', 'P3 năm 1, P4 năm 2', 'Không cần ghi phụ thuộc', 'C', 'Quy ước bài yêu cầu năm của công việc tiên quyết nhỏ hơn năm của việc phụ thuộc.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('cef1d38e-1d66-4f76-ba5c-fba84b2e5f26', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', '6b178942-29e9-57fb-a378-8fa757191dc4', 'Q3', 164, 'V2-3', 'Năm 4 cần 280 triệu và 7 người-tháng; trần 260 và 6. Kết luận?', 'Vượt 20 triệu và 1 người-tháng', 'Còn dư 20 triệu', 'Không vượt vì tổng năm 5 đủ', 'Chỉ thiếu vốn, không thiếu người', 'A', 'Phải kiểm đồng thời hai trần theo từng năm; chênh lệch là 260 - 280 và 6 - 7.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('bb06bfa5-cd2d-4886-98d4-a53e1c89a5ad', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', '6b178942-29e9-57fb-a378-8fa757191dc4', 'Q4', 271, 'V2-5', 'P6 nhân rộng OCR sau P4 thử lại, nhưng P4 chưa có bằng chứng đạt. Nên làm gì?', 'Bỏ qua kết quả thử', 'Ghi nhân rộng là đã duyệt', 'Đổi trạng thái để bảng đẹp', 'Giữ P6 có điều kiện; xác minh P4 trước', 'D', 'Lịch theo năm không bù được kết quả thử chưa đạt và cổng an toàn, pháp lý.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('9afa53c7-84b1-42fc-a622-6857ac9ea626', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', '6b178942-29e9-57fb-a378-8fa757191dc4', 'Q5', 145, 'V3-3', 'Theo số giả định, ngân sách lõi ba năm 1-3 là bao nhiêu?', '470 triệu đồng', '535 triệu đồng', '1.005 triệu đồng', '215 triệu đồng', 'B', '215 + 145 + 175 = 535 triệu; 470 triệu của năm 4-5 chỉ là phần mở rộng.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('20276d32-711f-4271-9aec-3ffdec2b9182', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', '6b178942-29e9-57fb-a378-8fa757191dc4', 'Q6', 245, 'V3-5', 'Nếu đủ tiền nhưng cổng dữ liệu và an toàn vẫn Chưa kiểm, kết luận nào đúng?', 'Tự động mua sắm', 'Bù cổng bằng điểm ưu tiên', 'Chưa phê duyệt; hoàn thành chứng cứ cổng', 'Bỏ cổng vì có ngân sách', 'C', 'Nguồn lực đạt trần không đồng nghĩa điều kiện triển khai được xác minh.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('855bfd4a-de5e-44e7-9587-30c0cee0c479', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 'cdc30995-94a5-5a23-a22e-221ab34438e5', 'Q1', 163, 'V1-3', 'Doanh nghiệp chưa có nhiệm vụ cụ thể. Bước đầu nào hợp lý?', 'Mua chatbot đa năng trước', 'Chọn nhiệm vụ có đầu ra, nguồn và người duyệt', 'Giao AI tự quyết định vận hành', 'Đưa tất cả dữ liệu nội bộ vào công cụ', 'B', 'Một trường hợp sử dụng có thể kiểm chứng phải đi trước quyết định chọn công cụ.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('3799a03c-9f39-41e1-894b-3bbe89cfc8ca', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 'cdc30995-94a5-5a23-a22e-221ab34438e5', 'Q2', 283, 'V1-5', 'Khi tài liệu được phép dùng không có thông số được hỏi, phản hồi nào có thể đạt?', 'Nêu số ước đoán như sự thật', 'Trích một SOP bất kỳ', 'Nói chưa có căn cứ và chuyển đầu mối phụ trách', 'Tạo mã tài liệu mới', 'C', 'Từ chối đúng là kết quả đạt khi dữ liệu không chứa câu trả lời.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('55a5d706-3dde-4161-bd41-44bebd375e60', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 'cdc30995-94a5-5a23-a22e-221ab34438e5', 'Q3', 164, 'V2-3', 'Vì sao ghi “không tiết lộ dữ liệu” vào prompt vẫn chưa đủ?', 'Phải kiểm soát quyền và luồng dữ liệu bằng cơ chế riêng', 'Prompt luôn vô hiệu', 'Mọi tài liệu đều là dữ liệu công khai', 'Đúng câu nhắc là có quyền pháp lý', 'A', 'Câu nhắc không thể thay phân quyền kỹ thuật, chính sách lưu trữ và phê duyệt.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('7f962e3b-7729-4c09-9a6d-488e51f77612', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 'cdc30995-94a5-5a23-a22e-221ab34438e5', 'Q4', 278, 'V2-5', 'Một trợ lý bịa mã SOP dù tỷ lệ đáp án đúng cao. Nên xử lý thế nào?', 'Bỏ qua vì trung bình cao', 'Cộng điểm để bù', 'Đưa lên toàn doanh nghiệp', 'Dừng mở rộng, điều tra lỗi và thử lại', 'D', 'Lỗi bịa nguồn thuộc điều kiện chặn riêng; không bù bằng điểm trung bình.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('32023ed8-7b2c-43ce-b82f-e5de238af927', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 'cdc30995-94a5-5a23-a22e-221ab34438e5', 'Q5', 190, 'V3-4', 'Dữ liệu mẫu có 5/7 đạt, 1 bịa nguồn và 1/2 từ chối đúng. Kết luận?', 'Đủ triển khai ngay', 'Không mở rộng, sửa lỗi và kiểm lại', 'Chỉ cần đổi ngưỡng', 'Ghi hai câu chưa đạt là đúng', 'B', 'Chưa đạt 85% và còn bịa nguồn; phải dừng mở rộng và khắc phục.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('07b3bc2a-4830-4ebb-b47c-78dcd4254773', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 'cdc30995-94a5-5a23-a22e-221ab34438e5', 'Q6', 291, 'V3-6', 'Sau khi các chỉ số đạt, nhưng cổng quyền dữ liệu còn Chưa kiểm, được làm gì?', 'Coi cổng đã xong', 'Để trợ lý tự phê duyệt', 'Bổ sung bằng chứng, trình phê duyệt thử giới hạn', 'Đưa dữ liệu khách hàng vào thử', 'C', 'Chỉ số và cổng quyền truy cập là điều kiện độc lập, không tự động phê duyệt triển khai.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('edfaa5b9-7f60-494b-8c63-52b68b4ac1ee', '78d888e3-1f17-553b-b60b-8bdeefcb1799', '2b74b83f-983a-53ec-afd9-6d2a1ea75f15', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''AI thị giác máy cho kiểm tra chất lượng và giám sát sản xuất'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
