INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('a64127d4-9d91-4cd8-a88d-ace924c9f1d2', '05ff18a7-62d7-5367-bcac-cb27c6a826cd', '1d9affd2-67f1-515c-af69-27cf9426e4ec', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('bfcffb99-ad55-44a9-b217-3fc296d03512', '45adeb6d-9960-5956-b29c-defd86eba6dc', 'fa3153af-ebf9-5883-9816-0e254526598f', 'Q1', 160, 'V1-3', 'Câu nào mô tả giá trị của nguyên mẫu đúng mức bằng chứng?', 'Cam kết giảm 30% sự cố dù chưa thử', 'Bảo đảm khách hàng sẽ mua sau demo', 'Ghi tín hiệu rung để đối chiếu sự kiện dừng; tác động còn phải kiểm', 'Tự động thay người quản lý bảo trì', 'C', 'Diễn đạt đúng việc có thể trình diễn và giới hạn chưa chứng minh được hiệu quả kinh tế.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('2c6363c9-a44a-4556-8460-c77d709bde10', '45adeb6d-9960-5956-b29c-defd86eba6dc', 'fa3153af-ebf9-5883-9816-0e254526598f', 'Q2', 269, 'V1-5', 'Một kỹ sư nói “công nghệ này thú vị”. Doanh nghiệp đã xác nhận điều gì?', 'Đã có đơn đặt hàng', 'Mới có tín hiệu quan tâm, còn cần kiểm nhu cầu và người quyết định', 'Đã chấp thuận thử hiện trường', 'Đã chứng minh thời gian dừng giảm', 'B', 'Quan tâm chưa bằng nhu cầu đã xác nhận, chưa xác lập thẩm quyền hay cam kết mua.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('09649019-a809-4163-bf18-1e0a89aaf9c3', '45adeb6d-9960-5956-b29c-defd86eba6dc', 'fa3153af-ebf9-5883-9816-0e254526598f', 'Q3', 154, 'V2-3', 'Vì sao phải chốt tiêu chí và mẫu đối chiếu trước khi chạy demo?', 'Để kết quả đẹp hơn', 'Để bỏ mẫu khó sau thử', 'Để bảo đảm khách hàng đồng ý mua', 'Để tránh đổi chuẩn theo kết quả và có phép kiểm có thể lặp', 'D', 'Khóa phép đo trước giúp đối chiếu công bằng kể cả khi demo không đạt.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1119b2f4-ee38-466a-ab01-4a262882032e', '45adeb6d-9960-5956-b29c-defd86eba6dc', 'fa3153af-ebf9-5883-9816-0e254526598f', 'Q4', 262, 'V2-5', 'Demo đạt kỹ thuật nhưng chưa rõ quyền khai thác nghiên cứu. Nhóm nên làm gì?', 'Kiểm quyền, phạm vi công bố và phê duyệt trước khi mở thử', 'Gửi mã nguồn toàn bộ để khách yên tâm', 'Coi việc khách khen là bằng chứng quyền công nghệ', 'Bỏ quy trình an toàn vì chỉ thử nhỏ', 'A', 'Kết quả kỹ thuật không thay bằng chứng quyền sở hữu và điều kiện an toàn.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('046f376a-80d3-4ebd-8d0a-9c1d7e18f1e5', '45adeb6d-9960-5956-b29c-defd86eba6dc', 'fa3153af-ebf9-5883-9816-0e254526598f', 'Q5', 139, 'V3-3', 'Hai đầu mối đạt tiêu chí demo và có người ra quyết định, nhưng cổng quyền chưa kiểm. Hành động nào phù hợp?', 'Ghi nhận hai hợp đồng đã chốt', 'Công bố hai doanh thu dự báo chắc chắn', 'Giữ ở danh sách thẩm định và làm rõ cổng trước khi mời thử', 'Tự chuyển trạng thái cổng sang Đã kiểm', 'C', 'Ứng viên đủ tín hiệu chưa phải khách mua và không thể bỏ cổng quyền.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('bc7207ff-ca42-4137-bdcb-1e802bb7cd64', '45adeb6d-9960-5956-b29c-defd86eba6dc', 'fa3153af-ebf9-5883-9816-0e254526598f', 'Q6', 227, 'V3-5', 'K6 có demo đạt nhưng thiếu người quyết định. K6 được xử lý thế nào?', 'Vẫn coi là đơn mua', 'Tìm người có quyền xác nhận bước tiếp và cập nhật phễu', 'Tăng điểm demo để bù thiếu thẩm quyền', 'Xóa khỏi danh sách vĩnh viễn', 'B', 'Người quyết định là điều kiện cần cho bước thương mại, không bù bằng kết quả trình diễn.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('8c979aa1-dded-4640-9ac8-a82726b1cef3', '45adeb6d-9960-5956-b29c-defd86eba6dc', 'fa3153af-ebf9-5883-9816-0e254526598f', 'Q7', 90, 'V1-3', '', '', '', '', '', 'A', 'Đáp án đúng là phương án A.', 7);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('2f142565-dd4c-4cc5-9b57-29adda9de422', '641a0564-4c0a-553d-b485-2857b82f7131', '084f818a-9dc2-5812-8d5f-deb3fe8830c2', 'Q1', 168, 'V1-3', 'Trường hợp cấp quyền sử dụng phần mềm, nhận định nào đúng hơn?', 'Bên nhận luôn trở thành chủ sở hữu mã nguồn', 'Không cần xác định thời hạn và số cơ sở', 'Quyền sử dụng theo phạm vi thỏa thuận, không mặc nhiên chuyển quyền sở hữu', 'Bên nhận mặc nhiên được cấp phép lại cho mọi đối tác', 'C', 'Cấp phép khác chuyển nhượng; cần xác minh đối tượng và phạm vi quyền cụ thể.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('1f3716ce-097a-4f9e-a279-ddeaa1c7e464', '641a0564-4c0a-553d-b485-2857b82f7131', '084f818a-9dc2-5812-8d5f-deb3fe8830c2', 'Q2', 283, 'V1-5', 'Người làm demo nói được toàn quyền chuyển giao nhưng thiếu hồ sơ quyền. Phải làm gì?', 'Cho ký vì người nói là tác giả', 'Kiểm chủ thể quyền và ủy quyền trước khi cam kết', 'Chỉ kiểm giá bán', 'Yêu cầu bỏ tất cả điều khoản bảo mật', 'B', 'Thuyết trình không đồng nghĩa có quyền định đoạt mọi thành phần công nghệ.', 2);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('c135e7e7-8e42-43c6-a5a8-65f9d3f39a7e', '641a0564-4c0a-553d-b485-2857b82f7131', '084f818a-9dc2-5812-8d5f-deb3fe8830c2', 'Q3', 166, 'V2-3', 'Điều khoản nghiệm thu có giá trị kiểm chứng cần yếu tố nào?', 'Chỉ nói sản phẩm hiện đại', 'Để nhà cung cấp tự chọn mẫu đẹp', 'Chỉ ghi đã giao thiết bị', 'Cấu hình, mẫu đối chiếu, ngưỡng, lỗi và người xác nhận', 'D', 'Nghiệm thu chức năng cần bằng chứng và quy tắc đo thống nhất trước khi thử.', 3);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('273c0bca-7b49-46e0-af6e-6d90faaaf40a', '641a0564-4c0a-553d-b485-2857b82f7131', '084f818a-9dc2-5812-8d5f-deb3fe8830c2', 'Q4', 283, 'V2-5', 'Phí tính theo doanh thu/sử dụng cần thỏa thuận thêm điều gì?', 'Định nghĩa cơ sở tính phí, kỳ đối soát và quyền kiểm tra', 'Để mỗi bên tự tính theo ý mình', 'Không cần dữ liệu kiểm toán', 'Coi mức phí là giá trị sở hữu trí tuệ được chứng nhận', 'A', 'Định nghĩa cơ sở và cơ chế đối soát giảm tranh chấp về tiền phải trả.', 4);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('4c6bd7de-ec7f-4437-86a5-68a80e5c0dbc', '641a0564-4c0a-553d-b485-2857b82f7131', '084f818a-9dc2-5812-8d5f-deb3fe8830c2', 'Q5', 161, 'V3-3', 'NPV dương 137 triệu đồng theo mô hình giả định cho phép kết luận nào?', 'Đã xác nhận quyền sở hữu', 'Hợp đồng chắc chắn nên ký', 'Dòng tiền giả định có NPV dương, nhưng phải kiểm bằng chứng và cổng pháp lý', 'Giá công nghệ chính xác là 137 triệu', 'C', 'NPV là kết quả giả định về phía người nhận, không thay giá giao dịch hay thẩm định quyền.', 5);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('5dccb494-fbbb-42a5-aea5-bb9520fb4d62', '641a0564-4c0a-553d-b485-2857b82f7131', '084f818a-9dc2-5812-8d5f-deb3fe8830c2', 'Q6', 242, 'V3-5', 'NPV dương nhưng hai trong ba cổng chưa kiểm. Bước tiếp phù hợp?', 'Ký ngay trước khi đối tác đổi giá', 'Hoàn tất bằng chứng quyền, nghiệm thu, thẩm quyền trước thẩm định hợp đồng', 'Tự sửa ô cổng thành Đã kiểm', 'Xóa chi phí tích hợp để NPV đẹp hơn', 'B', 'Cổng bắt buộc không thể được bù bằng dự báo dòng tiền.', 6);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('c445b9b5-8db9-485e-893c-512dcc87ed36', '4136304a-a901-53c0-a081-b528490e14dd', 'b3f5877b-4c77-531d-8894-8aa0d1adda79', 'Q1', 120, 'V1-1', 'Mục tiêu cốt lõi của nội dung ''Nguồn vốn và chính sách hỗ trợ đổi mới công nghệ'' là gì?', 'Chỉ mua thiết bị công nghệ hiện đại nhất', 'Giải quyết đúng bài toán và tạo ra giá trị đo lường được', 'Thực hiện theo phong trào không cần dữ liệu', 'Giao toàn bộ trách nhiệm cho nhà cung cấp bên ngoài', 'B', 'Đổi mới công nghệ phải gắn kết chặt chẽ với mục tiêu kinh doanh và đo lường được hiệu quả.', 1);
INSERT INTO lms.learning_in_video_quizzes (id, material_id, micro_video_id, quiz_code, trigger_seconds, after_scene, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, display_order) VALUES ('fdf3f5e8-d962-4c7d-a753-29d71c39a592', '4136304a-a901-53c0-a081-b528490e14dd', 'a9eb2c69-2cbc-59bf-b34e-b23d090a6655', 'Q2', 150, 'V2-1', 'Khi đánh giá và lựa chọn phương án công nghệ, nguyên tắc nào quan trọng nhất?', 'Chọn phương án có chi phí cao nhất', 'Đánh giá dựa trên bằng chứng, tính khả thi và năng lực hấp thụ thực tế', 'Bỏ qua yếu tố dữ liệu và con người', 'Áp dụng ngay quy mô toàn diện mà không cần thử nghiệm PoC', 'B', 'Đánh giá khách quan dựa trên bằng chứng và sự sẵn sàng của doanh nghiệp giúp giảm thiểu rủi ro đầu tư.', 2);
