INSERT INTO lms.learning_practice_rubrics (id, material_id, criterion_number, criterion_name, description_score_0, description_score_1, description_score_2, weight_multiplier) VALUES ('e3020571-7abb-4b3d-922b-2b9ecdda8054', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 1, 'Mục tiêu rõ ràng, định lượng và gắn với bài toán doanh nghiệp', 'Chưa nêu rõ mục tiêu', 'Mục tiêu còn chung chung', 'Mục tiêu cụ thể, có số liệu và người chịu trách nhiệm', 1);
INSERT INTO lms.learning_practice_rubrics (id, material_id, criterion_number, criterion_name, description_score_0, description_score_1, description_score_2, weight_multiplier) VALUES ('9358bb77-90c6-4bac-88e9-541d2d77828b', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 2, 'Chỉ số KPI và kế hoạch thu thập dữ liệu đường cơ sở', 'Không có KPI', 'Có KPI nhưng thiếu cách đo', 'Đầy đủ công thức, nguồn dữ liệu và kỳ đo', 1);
INSERT INTO lms.learning_practice_rubrics (id, material_id, criterion_number, criterion_name, description_score_0, description_score_1, description_score_2, weight_multiplier) VALUES ('aada4d7e-72f5-446f-9930-90d70a8ae0ef', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 3, 'Phân tích điểm nghẽn và nguyên nhân gốc rễ', 'Không phân tích nguyên nhân', 'Mới nêu triệu chứng', 'Tách bạch triệu chứng và nguyên nhân có bằng chứng', 1);
INSERT INTO lms.learning_practice_rubrics (id, material_id, criterion_number, criterion_name, description_score_0, description_score_1, description_score_2, weight_multiplier) VALUES ('cea915a2-2ea9-4cd1-b719-c3e94e82ea89', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 4, 'So sánh tối thiểu 2-3 phương án can thiệp', 'Chỉ nêu duy nhất một phương án', 'Có so sánh nhưng thiếu tiêu chí', 'So sánh đa chiều: tác động, khả thi, chi phí, rủi ro', 1);
INSERT INTO lms.learning_practice_rubrics (id, material_id, criterion_number, criterion_name, description_score_0, description_score_1, description_score_2, weight_multiplier) VALUES ('1aa0c81d-b839-4079-9ab6-57b30990005a', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 5, 'Đánh giá năng lực hấp thụ và độ sẵn sàng công nghệ', 'Không đánh giá năng lực', 'Đánh giá cảm tính', 'Đánh giá đủ 4 trụ cột: nhân lực, tài chính, hạ tầng, quản trị', 1);
