INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2ed60c33-84f1-4dbc-bd66-a9b9e830ad90', '01940001-0000-7000-8000-000000000001', 1, 'Quyền sở hữu công nghiệp đối với sáng chế được xác lập trên cơ sở nào?', 'Quyết định cấp văn bằng bảo hộ của cơ quan nhà nước có thẩm quyền', 'Sử dụng công khai lần đầu tiên tại hội chợ triển lãm', 'Tự động phát sinh kể từ khi sáng chế được tạo ra', 'Hợp đồng chuyển nhượng quyền sử dụng với đối tác', 'A', 'Theo Luật SHTT, quyền sở hữu công nghiệp đối với sáng chế chỉ được xác lập trên cơ sở quyết định cấp Văn bằng bảo hộ của Cục SHTT.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('415ce664-a7c7-4bfd-b7bf-496ea106bb97', '01940001-0000-7000-8000-000000000001', 2, 'Thời hạn bảo hộ Bằng độc quyền sáng chế tại Việt Nam là bao nhiêu năm tính từ ngày nộp đơn?', '10 năm', '15 năm', '20 năm (không được gia hạn)', 'Vĩnh viễn', 'C', 'Bằng độc quyền sáng chế có hiệu lực 20 năm tính từ ngày nộp đơn hợp lệ và không được gia hạn.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ec0c09b1-3ca6-455b-8dfe-76a7829ca6dc', '01940001-0000-7000-8000-000000000001', 3, 'Điều kiện nào sau đây KHÔNG phải là tiêu chuẩn bảo hộ sáng chế?', 'Có tính mới trên phạm vi toàn thế giới', 'Có trình độ sáng tạo', 'Có khả năng áp dụng công nghiệp', 'Có giá thành sản xuất rẻ hơn sản phẩm cùng loại', 'D', 'Tiêu chuẩn bảo hộ sáng chế gồm 3 điều kiện: Tính mới, Trình độ sáng tạo và Khả năng áp dụng công nghiệp. Giá thành rẻ không phải điều kiện bảo hộ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a01dc69c-d3ce-47a2-b699-3b9ddf05ce01', '01940001-0000-7000-8000-000000000002', 1, 'Phương pháp nào thường được ưu tiên khi định giá công nghệ đã tạo ra doanh thu ổn định trên thị trường?', 'Phương pháp chiết khấu dòng tiền (DCF - Thu nhập)', 'Phương pháp chi phí tái tạo', 'Phương pháp chi phí thay thế', 'Phương pháp giá trị thanh lý', 'A', 'Phương pháp thu nhập (DCF) phản ánh chính xác nhất tiềm năng kinh tế và dòng tiền tương lai của công nghệ đã đi vào khai thác.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8b7aa67e-baae-430c-848d-af5bb6a050f7', '01940001-0000-7000-8000-000000000002', 2, 'Yếu tố TRL (Technology Readiness Level) ảnh hưởng thế nào đến tỷ suất chiết khấu trong định giá công nghệ?', 'TRL càng cao thì rủi ro càng thấp, tỷ suất chiết khấu càng giảm', 'TRL không ảnh hưởng đến tỷ suất chiết khấu', 'TRL càng cao thì tỷ suất chiết khấu càng tăng', 'Chỉ áp dụng với công nghệ TRL 1-3', 'A', 'Mức độ sẵn sàng công nghệ (TRL) cao chứng minh công nghệ đã qua thử nghiệm thực tế, rủi ro thương mại hóa thấp dẫn đến tỷ suất chiết khấu rủi ro thấp hơn.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('4662b6b4-3875-44b8-91ed-3e9e6582f873', '01940001-0000-7000-8000-000000000003', 1, 'Hợp đồng Li-xăng độc quyền (Exclusive License) trao quyền gì cho bên nhận li-xăng?', 'Được độc quyền sử dụng sáng chế trong phạm vi lãnh thổ đã thỏa thuận, bên giao li-xăng không được cấp cho bên thứ ba và không được tự sử dụng', 'Được quyền chuyển nhượng vĩnh viễn quyền sở hữu sáng chế', 'Chỉ được sử dụng nội bộ không được bán sản phẩm ra thị trường', 'Bên giao li-xăng vẫn có quyền cấp li-xăng cho doanh nghiệp khác', 'A', 'Li-xăng độc quyền loại trừ quyền sử dụng của cả bên thứ ba lẫn chính chủ sở hữu trong phạm vi lãnh thổ và thời hạn thỏa thuận.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('044ce34d-97c0-4fc7-8af9-b8aa2e115cc7', '01940001-0000-7000-8000-000000000003', 2, 'Cơ chế thù lao Running Royalty trong hợp đồng chuyển giao thường được tính trên cơ sở nào?', 'Tỷ lệ phần trăm trên doanh thu thuần hoặc lợi nhuận gộp từ sản phẩm áp dụng công nghệ', 'Khoản tiền cố định trả một lần duy nhất', 'Số lượng bằng sáng chế đối tác sở hữu', 'Số giờ chuyên gia tư vấn trực tiếp', 'A', 'Running Royalty tính theo % doanh thu thuần hoặc sản lượng sản phẩm thực tế bán ra.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('5012653e-c500-411b-9807-2c3b440af7fc', '01940001-0000-7000-8000-000000000004', 1, 'Hợp đồng chuyển giao công nghệ bắt buộc phải lập thành văn bản không?', 'Bắt buộc phải lập thành văn bản hoặc hình thức tương đương', 'Có thể thỏa thuận bằng lời nói nếu giá trị dưới 100 triệu', 'Chỉ cần thỏa thuận qua email', 'Không bắt buộc hình thức', 'A', 'Luật CGCN quy định hợp đồng chuyển giao công nghệ bắt buộc phải lập thành văn bản.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('3714c245-f485-410a-8fd8-c2eef15686ff', '01940001-0000-7000-8000-000000000006', 1, 'Mã nguồn thuật toán AI chưa đăng ký bằng sáng chế có thể được bảo vệ dưới hình thức nào?', 'Bí mật kinh doanh (Trade Secret) và Quyền tác giả đối với phần mềm máy tính', 'Bằng độc quyền sáng chế tự động', 'Nhãn hiệu chứng nhận', 'Chỉ dẫn địa lý', 'A', 'Mã nguồn phần mềm và thuật toán được bảo hộ tự động dưới dạng Quyền tác giả và có thể bảo vệ qua Bí mật kinh doanh nếu giữ kín.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('50c3054b-93b5-4fd9-bfac-28a401750027', '01940001-0000-7000-8000-000000000006', 2, 'Phương pháp Berkus trong định giá startup giai đoạn sớm tập trung vào yếu tố nào?', 'Đánh giá định lượng dựa trên 5 yếu tố giảm thiểu rủi ro của mô hình kinh doanh và đội ngũ', 'Doanh thu thuần 5 năm gần nhất', 'Chi phí máy móc thiết bị nhà xưởng', 'Tài sản thế chấp ngân hàng', 'A', 'Phương pháp Berkus gán giá trị cho 5 yếu tố rủi ro của startup: Ý tưởng cơ bản, Nguyên mẫu sản phẩm, Đội ngũ quản lý, Mối quan hệ chiến lược, Triển vọng bán hàng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('68212a78-1fd2-421f-9b1b-56b3b2aaafea', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 3, '64 túi lỗi trong 2.000 túi kiểm bằng?', '0,32%', '32%', '3,2%', '6,4%', 'C', 'C đúng vì 64/2.000 x100 = 3,2%; các phương án khác sai phép chia.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('96b6d048-461a-4405-9e98-a4db131967f9', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 1, 'Câu hỏi ôn tập 1: Nhận định nào sau đây là chuẩn xác nhất đối với ''Công nghệ và đổi mới công nghệ: doanh nghiệp thực sự cần hiểu gì?''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('bf86befd-1a58-41da-adee-c54db56736d6', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 2, 'Câu hỏi ôn tập 2: Nhận định nào sau đây là chuẩn xác nhất đối với ''Công nghệ và đổi mới công nghệ: doanh nghiệp thực sự cần hiểu gì?''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ae3fc957-6fad-4db2-a9e1-efa090e0ebf9', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 6, '12 gói đạt bị loại nhầm trong 400 gói đạt tương đương?', '12%', '0,3%', '3%', '4%', 'C', 'C đúng. 12/400=0,03, tương đương 3% số mẫu tốt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0f0e8bbc-67e9-457f-af5b-fe95aed06f93', 'a580ccfe-dd70-54dd-b23e-38908d52df62', 3, 'Câu hỏi ôn tập 3: Nhận định nào sau đây là chuẩn xác nhất đối với ''Công nghệ và đổi mới công nghệ: doanh nghiệp thực sự cần hiểu gì?''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
