INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('bef867a2-f4fc-4cc8-9862-c5f1d5a6c058', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 8, 'Bằng chứng nào tốt cho kết quả đào tạo?', 'Số email gửi', 'Ảnh chụp buổi họp', 'Danh sách nhân viên đã nhận thông báo', 'Bài thực hành xử lý tình huống có người xác nhận', 'D', 'Đáp án đúng là D. Nội dung được giải thích trong Tóm tắt kiến thức cốt lõi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('5c226903-94e4-4a8c-a710-09acb7e78281', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 9, 'Một phép thử tiếp nhận cần có gì?', 'Mục tiêu, phạm vi, dữ liệu nền, người duyệt, điều kiện an toàn và dừng', 'Tăng ngưỡng thiết bị tùy ý', 'Chỉ kết luận của bên bán', 'Không cần nhật ký', 'A', 'Đáp án đúng là A. Nội dung được giải thích trong Tóm tắt kiến thức cốt lõi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('101a60c0-4624-4b86-8e2c-32e05c3f79a9', 'e9b85f94-bc5d-5994-a12e-ceca16a9cc9f', 10, 'Sau khi thử có sai lệch dữ liệu có thể sửa, lựa chọn phù hợp là gì?', 'Bỏ qua và nhân rộng ngay', 'Điều chỉnh rồi kiểm tra lại theo tiêu chí đã phê duyệt', 'Coi dự án chắc chắn thất bại', 'Xóa bản ghi sai', 'B', 'Đáp án đúng là B. Nội dung được giải thích trong Tóm tắt kiến thức cốt lõi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('84156b42-d016-42bc-9b92-c156f3b5ad83', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 1, 'Mục đích chính của bản mô tả nhu cầu công nghệ ở giai đoạn đầu là gì?', 'Thay thế hồ sơ mời thầu trong quá trình lựa chọn nhà cung cấp.', 'Chỉ dùng để liệt kê các công nghệ hiện đang bán trên thị trường.', 'Làm rõ vấn đề nghiệp vụ, chức năng, điều kiện và cách kiểm chứng để trao đổi với các bên liên quan.', 'Chốt trước tên sản phẩm và giá dự kiến để không thay đổi phương án.', 'C', 'Tài liệu này làm rõ nhu cầu và phép kiểm chứng ở giai đoạn đầu; không thay thế thiết kế chi tiết hoặc hồ sơ đấu thầu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('47124b40-42ea-4c16-9641-7ec0c82ce251', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 2, 'Đâu là cách diễn đạt một yêu cầu chức năng cụ thể, thay vì chỉ nêu tên giải pháp hoặc định hướng công nghệ?', 'Doanh nghiệp cần mua phần mềm quản lý kho.', 'Doanh nghiệp cần một ứng dụng trên thiết bị di động.', 'Hệ thống cần được xây dựng trên nền tảng công nghệ đời mới.', 'Thủ kho có thể xem được số lượng tồn kho hiện tại tại thời điểm lập phiếu xuất.', 'D', 'Phương án D nói rõ thủ kho cần làm gì tại bước lập phiếu xuất. Các phương án còn lại mới gọi tên giải pháp.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('9ac7203c-2afa-431d-a264-354847d1e2ef', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 3, 'Với yêu cầu “Hệ thống phải hoạt động ổn định”, cách xử lý nào phù hợp khi lập bản mô tả nhu cầu?', 'Bổ sung từ “rất” để nhấn mạnh mức độ quan trọng của yêu cầu.', 'Giữ nguyên cách diễn đạt vì đây là yêu cầu phổ biến và dễ hiểu.', 'Chuyển yêu cầu thành tình huống hoặc tiêu chí có thể kiểm tra; nếu chưa đủ dữ liệu để xác định ngưỡng đánh giá, ghi nhận là nội dung cần kiểm chứng.', 'Loại bỏ yêu cầu khỏi bản mô tả vì chưa thể định lượng.', 'C', 'Cần diễn đạt bằng trường hợp kiểm tra và thống nhất tiêu chí; thông tin chưa đủ phải đánh dấu để khảo sát.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('5352c3ef-caf9-4212-8aa7-38e0741f18ac', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 4, 'Khi phỏng vấn người trực tiếp thực hiện công việc, câu hỏi nào nên được ưu tiên sử dụng để tìm hiểu quy trình thực tế?', 'Anh/chị muốn cài phần mềm nào để hỗ trợ công việc?', 'Anh/chị mong muốn việc quản lý công việc được cải thiện như thế nào?', 'Anh/chị có hài lòng với cách thực hiện công việc hiện nay không?', 'Lần gần nhất việc này xảy ra là khi nào, ở bước nào?', 'D', 'Hỏi về lần xảy ra gần nhất và công đoạn cụ thể giúp thu được sự việc có thể đối chiếu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('df38f80c-f0bd-4e18-9d44-3fb7d481bbdc', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 5, 'Trong các ghi nhận dưới đây, nội dung nào là nhận định mang tính phỏng đoán, chưa phải dữ kiện quan sát được?', 'Hai tệp có tên gần giống nhau được lưu trong cùng một thư mục.', 'Công nhân không quan tâm đến chất lượng công việc.', 'Phiếu in lại có ghi rõ lý do liên quan đến sai phiên bản.', 'Nhóm sản xuất báo rằng có hai lần bàn giao bản vẽ qua thư điện tử trong cùng một ngày.', 'B', 'Nhận xét thái độ “không quan tâm” là suy đoán, còn những phương án khác mô tả thông tin kiểm tra được.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e87616e6-fd62-432a-8f95-47125f55ac83', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 6, 'Khi chưa có số liệu về tỷ lệ phải in lại, doanh nghiệp nên xử lý nội dung mục tiêu này như thế nào?', 'Tự đặt ra mức giảm dựa trên kinh nghiệm cá nhân.', 'Tham khảo tỷ lệ của một doanh nghiệp khác để làm căn cứ.', 'Ghi nhận đây là dữ liệu cần thu thập, chẳng hạn thông qua việc thống kê các phiếu in lại.', 'Để trống mục tiêu và không tiếp tục xem xét.', 'C', 'Chưa có dữ liệu thì cần thiết kế cách thu thập, không đặt tỷ lệ hay mượn số liệu từ nơi khác.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c5a25d22-2058-401f-8187-e6f4a06e20cc', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 7, 'Trong danh sách chức năng, nhãn “?” được sử dụng trong trường hợp nào?', 'Chức năng đã được xác định là bắt buộc.', 'Chức năng đã được xem xét và loại khỏi phạm vi.', 'Chức năng được đánh giá là không quan trọng.', 'Chức năng hoặc điều kiện thực hiện chưa được làm rõ, cần tiếp tục kiểm tra.', 'D', 'Nhãn ? nghĩa là thông tin còn thiếu hoặc chưa đủ căn cứ để phân loại yêu cầu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c135767b-5968-40d3-bd0b-cc87b87c0033', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 8, 'Sai sót nào trong quá trình xây dựng bản mô tả nhu cầu dễ khiến phạm vi dự án mở rộng thiếu kiểm soát và gây khó khăn khi so sánh các phương án?', 'Không xác định người có trách nhiệm nghiệm thu kết quả.', 'Không đưa ra tình huống hoặc tác vụ cụ thể để kiểm tra.', 'Không nêu tên nhà cung cấp', 'Liệt kê mọi tính năng mong muốn mà không phân biệt bắt buộc và nên có', 'D', 'Tất cả tính năng có mức ưu tiên ngang nhau dễ gây phình phạm vi và khó so sánh phương án.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a46ace21-1ec0-4577-8edd-17dfe2ab3da1', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 9, 'Khi chưa xác định được một số điều kiện triển khai, chẳng hạn quyền truy cập của người dùng, cách xử lý nào phù hợp nhất?', 'Tự đưa ra giả định dựa trên kinh nghiệm cá nhân.', 'Đánh dấu là nội dung cần kiểm tra và tiếp tục làm rõ với các bên liên quan.', 'Bỏ qua nội dung này vì chưa ảnh hưởng đến việc mô tả chức năng.', 'Để nhà cung cấp tự quyết định mà không cần thống nhất trước.', 'B', 'Điều kiện chưa xác định phải ghi nhận và phân công kiểm tra, không tự suy đoán.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('72b14f66-52f7-4387-b223-265665e12260', '860c9b04-cf13-57ea-ab94-0d1b3b246f83', 10, 'Sau khi hoàn thành bản mô tả nhu cầu công nghệ, kết quả nào dưới đây có thể được xem là một hướng xử lý phù hợp?', 'Doanh nghiệp nhất thiết phải đầu tư và triển khai phần mềm.', 'Doanh nghiệp phải lựa chọn ngay một nhà cung cấp cụ thể.', 'Sau khi đánh giá các phương án, doanh nghiệp có thể lựa chọn điều chỉnh quy trình hiện tại, bổ sung công cụ số hoặc triển khai giải pháp công nghệ phù hợp.', 'Doanh nghiệp loại bỏ vấn đề đã xác định vì đã hoàn thành bản mô tả nhu cầu.', 'C', 'Bản mô tả giúp so sánh nhiều cách xử lý, kể cả thay đổi quy trình mà chưa phải mua công nghệ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7eb96800-e9c2-48cc-b687-f2370bf7dc43', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 1, 'KPI nào phù hợp nhất để đo lỗi hở mép hàn?', 'Số cảm biến được lắp', 'Tỷ lệ túi hở mép trong số túi kiểm theo quy tắc xác định', 'Số giờ họp dự án', 'Số bài giới thiệu công nghệ', 'B', 'B đo đúng kết quả bằng tỷ lệ túi lỗi trên tổng túi kiểm; A, C, D chỉ đo hoạt động hoặc đầu tư.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('5add4fb9-5616-44e7-9780-ceee4efa2ccd', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 2, 'Tỷ lệ lỗi tính bằng công thức nào?', 'Túi lỗi/túi kiểm x100', 'Túi kiểm/túi lỗi x100', 'Số lỗi x số ca', 'Túi lỗi + túi kiểm', 'A', 'A đúng công thức tỷ lệ; B đảo tử mẫu, C và D không cho tỷ lệ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e533df50-7c52-4f4e-9b84-e2c7e21c8da3', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 4, 'Điều nào cần có trong phiếu định nghĩa KPI?', 'Chỉ tên chỉ số', 'Chỉ người phụ trách', 'Chỉ tên máy', 'Tử số, mẫu số, phạm vi, nguồn, chu kỳ và người xác nhận', 'D', 'D gồm đủ điều kiện để người khác tính và kiểm lại; ba phương án khác quá thiếu thông tin.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('bd23fff0-ba1b-43eb-aecd-40516248c845', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 5, 'Đường cơ sở được xác định vào lúc nào?', 'Từ dữ liệu trước thay đổi trong kỳ và quy tắc đã xác định', 'Sau khi thấy kết quả tốt nhất', 'Bất kỳ lúc nào bằng dự đoán', 'Chỉ sau khi nhà cung cấp đồng ý', 'A', 'A dùng dữ liệu trước can thiệp theo định nghĩa nhất quán; B, C, D là cách chọn số thiếu căn cứ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('90298025-c640-4360-abca-662ce306599f', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 6, 'Tổng 240 lỗi trên 8.000 túi kiểm bằng?', '0,03%', '30%', '3,0%', '8,0%', 'C', 'C đúng: 240/8.000 x100 = 3,0%; các tỷ lệ khác sai.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('cd120e0e-b283-465a-b6ac-31bfa61759a1', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 7, 'Tuần 4 có 3,6% lỗi; cách xử lý phù hợp?', 'Xóa tuần để đẹp báo cáo', 'Kiểm tra nhật ký và tính so sánh trước khi loại hay kết luận', 'Khẳng định nguyên nhân do cảm biến', 'Thay mẫu số tuần 4 bằng mẫu số tuần 1', 'B', 'B đúng: kiểm nhật ký trước; A, C chọn số có lợi, D thay đổi mẫu số không hợp lệ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('922a76a0-4c39-497e-99ca-20973b32ec8a', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 8, 'Từ 3,0% xuống 2,0% là giảm tuyệt đối bao nhiêu?', '33,3 điểm phần trăm', '3 điểm phần trăm', '2 điểm phần trăm', '1 điểm phần trăm', 'D', 'D đúng: 3,0 - 2,0 = 1,0 điểm phần trăm, không phải giảm 33,3 điểm phần trăm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('93322598-84e7-47d1-ba1c-0e11229d6792', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 9, 'Mức giảm tương đối từ 3,0% xuống 2,0% xấp xỉ?', '33,3%', '1%', '50%', '66,7%', 'A', 'A đúng: (3-2)/3 x100 = 33,3% tương đối; các phương án khác nhầm cách tính.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('09049e71-d3ec-49b2-8a04-ca143b1c6fe5', 'e12535ad-5dc3-567d-92e6-963fbdd62da7', 10, 'Kết quả sau thử 80/4.000=2,0% cho biết gì?', 'Chắc chắn do công nghệ', 'Không cần kiểm soát điều kiện đo', 'Đã quan sát tỷ lệ 2,0% trong phạm vi kiểm, cần đánh giá yếu tố khác trước khi gán nguyên nhân', 'Lỗi đã hoàn toàn biến mất', 'C', 'C là mức quan sát trong mẫu, không đủ khẳng định nguyên nhân do công nghệ; A, B, D sai.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('463ff9d9-d2c3-4362-b406-c79962305eb7', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 1, 'Danh mục ưu tiên trước khi chấm nên gồm gì?', 'Tên nhà cung cấp', 'Nhu cầu đã mô tả phạm vi, KPI và bằng chứng', 'Danh sách công nghệ đắt nhất', 'Chỉ mong muốn lãnh đạo', 'B', 'B đúng: so nhu cầu có định nghĩa và bằng chứng. A/C/D bỏ qua vấn đề nghiệp vụ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('594535ff-abe9-43df-8e0c-e902bbb20347', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 2, 'Hai đề xuất có vẻ trùng nhau, bước đầu là gì?', 'Đối chiếu phạm vi, chỉ số và người sử dụng', 'Cộng hai điểm cho đề xuất của trưởng phòng', 'Xóa một đề xuất bất kỳ', 'Cứ chấm hai dòng riêng', 'A', 'A đúng: cần kiểm trước khi gộp để tránh đếm trùng hoặc bỏ mất phạm vi khác nhau.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('41788cc8-f24b-4561-95b2-c56dad3f86b1', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 3, 'Đâu là bằng chứng phù hợp nhất khi chấm tác động?', 'Ảnh chụp thiết bị mới', 'Nhận xét cảm tính của nhà cung cấp', 'Tỷ lệ lỗi nền, phạm vi ảnh hưởng và hậu quả đã xác minh', 'Số lượt truy cập quảng cáo', 'C', 'C đúng: tác động gắn hậu quả nghiệp vụ và KPI, không gắn độ mới của thiết bị.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('686a8d8a-219e-41d0-a64d-bfebcf1c7975', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 4, 'Tính khả thi nên dựa trên yếu tố nào?', 'Tên công nghệ', 'Độ nổi tiếng trên thị trường', 'Màu sắc giao diện', 'Dữ liệu, nhân lực, ngân sách, hạ tầng và khả năng thử', 'D', 'D đúng: khả thi đo điều kiện thực hiện và duy trì kết quả.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e5064d41-86f1-412b-b8c4-8dc3ac60c00f', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 5, 'Trọng số nào hợp lệ cho mô hình chỉ gồm tác động và khả thi?', '60% + 40%', '70% + 40%', '30% + 30%', '80% + 30%', 'A', 'A đúng: tổng trọng số phải bằng 100%; các lựa chọn khác không bằng 100%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('412594c1-7e55-4028-9dbc-ce2649fa3d26', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 6, 'Tác động 5, khả thi 4, trọng số 60/40: điểm là?', '5,4', '4,4', '4,6', '92%', 'C', 'C đúng: 5×0,6+4×0,4=4,6 trên thang 5; không phải xác suất.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d5e29dda-0e96-45aa-8f28-17c93f9d23e8', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 7, 'B có tác động 4 và khả thi 5. Với trọng số 60/40, B đạt?', '4,8', '4,4', '4,0', '5,0', 'B', 'B đúng: 4×0,6+5×0,4=4,4.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('468235c8-b371-4894-8f03-099d6553bcda', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 8, 'Điều kiện an toàn chưa xác minh nhưng điểm cao, cần?', 'Cho qua vì tác động lớn', 'Tăng điểm khả thi', 'Đưa vào thử luôn', 'Giữ trạng thái chờ xác minh, không duyệt triển khai', 'D', 'D đúng: điều kiện bắt buộc tách khỏi điểm có trọng số.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0e0c28e0-17e9-4cca-8253-1a9c70cdc0a1', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 9, 'Khi đổi trọng số 40/60, điểm A/B lần lượt là?', '4,4 và 4,6', '4,6 và 4,4', '5,0 và 5,0', '3,0 và 2,0', 'A', 'A đúng: A=5×0,4+4×0,6=4,4; B=4×0,4+5×0,6=4,6.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c60a8e93-21ba-42d4-b528-057f0001ade3', 'f2043dbe-5a67-5b02-a78c-4f8c211fa339', 10, 'Nhu cầu điểm cao nhưng chưa chuẩn hóa dữ liệu nên làm gì?', 'Ký hợp đồng sớm', 'Gán dữ liệu thiếu bằng số giả định', 'Ưu tiên công việc chuẩn bị, xác minh rồi đánh giá lại', 'Loại vĩnh viễn', 'C', 'C đúng: chuyển vào nhóm chuẩn bị với đầu việc và người phụ trách rõ ràng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('146909de-c3de-45ab-a7ed-81caaa308d1c', '3a6158cd-409e-53b6-b657-95bfc28329ba', 1, 'Mục tiêu của Bài 10 là đầu ra nào?', 'Chọn hãng máy ngay', 'Chốt giá mua thiết bị', 'Phiếu nhu cầu để trao đổi và kiểm chứng phương án', 'Ký hợp đồng chuyển giao', 'C', 'C đúng. Bài này dừng ở hồ sơ kết nối và bước xác minh, không thay quyết định đầu tư.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('fc779d77-f469-4104-9a38-83ab36f6802e', '3a6158cd-409e-53b6-b657-95bfc28329ba', 2, '240 túi lỗi trên 8.000 túi đã kiểm tương đương?', '3% mẫu đã kiểm', '30% tổng sản lượng', '3% mọi túi sản xuất chắc chắn', '0,3% mẫu đã kiểm', 'A', 'A đúng: 240/8.000=0,03 = 3%. Chưa biết mẫu có đại diện cho tổng sản lượng không.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('219bcfe0-8272-4822-88fc-c97eaa63eb61', '3a6158cd-409e-53b6-b657-95bfc28329ba', 3, 'Điều nào là giả thuyết chưa chứng minh?', 'Có 240 lỗi trong mẫu', 'Nhiệt độ hàn biến động gây ra mọi lỗi', 'Đã kiểm 8.000 túi', 'Tỷ lệ lỗi mẫu là 3%', 'B', 'B đúng: phải kiểm nhật ký nhiệt độ, vật liệu, ca và các yếu tố khác.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6b61adb6-b9c8-4de9-862e-f00c4e2336b0', '3a6158cd-409e-53b6-b657-95bfc28329ba', 4, 'Cách diễn đạt nhu cầu nào đúng hơn?', 'Mua máy hiện đại nhất', 'Mua gói cảm biến có sẵn', 'Mua thiết bị do bạn giới thiệu', 'Kiểm soát các yếu tố làm hở mép hàn để giảm tỷ lệ lỗi', 'D', 'D đúng. Mô tả kết quả trước, chưa đóng khung giải pháp.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('47de38bc-8a0f-4cfc-807c-e3423c5453d2', '3a6158cd-409e-53b6-b657-95bfc28329ba', 5, 'Khi thiếu bằng chứng về tích hợp phần mềm, ghi nhãn nào?', '? và người phụ trách xác minh', 'B ngay', 'N chắc chắn', 'Xóa yêu cầu', 'A', 'A đúng. Dấu ? nêu rõ thông tin còn thiếu và cách xác minh.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('78ff55c1-8dea-406e-b75d-cc7388c97303', '3a6158cd-409e-53b6-b657-95bfc28329ba', 6, 'Giảm 3% xuống 2% là thay đổi nào?', 'Giảm một phần trăm tương đối', 'Giảm một điểm phần trăm; tương đối khoảng 33,3%', 'Tăng một điểm phần trăm', 'Không thay đổi', 'B', 'B đúng: giảm 1 điểm phần trăm; tỷ lệ giảm tương đối 1/3 ≈33,3% với mẫu so sánh tương đương.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('49546fc8-68eb-4442-8ad3-5694e39e2d82', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 3, 'Cần 16 người, 15 người đã học. Bao phủ đào tạo bằng?', '86,67%', '81,25%', '93,75%', '95%', 'C', '15/16=93,75%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('f4914bcd-078f-4f30-adfa-2bd63b17bbfc', '3a6158cd-409e-53b6-b657-95bfc28329ba', 7, 'Tiêu chí nghiệm thu cần thêm thông tin gì ngoài ngưỡng 2%?', 'Màu sơn máy', 'Hãng cung cấp nổi tiếng', 'Quy tắc mẫu, thời gian, người đo và chỉ số an toàn', 'Slogan quảng cáo', 'C', 'C đúng. Ngưỡng đứng riêng không đủ để thiết kế phép thử có thể so sánh.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('15ab93f7-7551-4e87-a5d6-a4fffb40ff1b', '3a6158cd-409e-53b6-b657-95bfc28329ba', 8, 'Dữ liệu mật của khách hàng có nên gửi trong buổi kết nối đầu?', 'Gửi đầy đủ để thuyết phục', 'Chuyển qua tài khoản cá nhân', 'Chỉ gửi khi đối tác thúc giục', 'Chỉ chia sẻ phần được phê duyệt với điều kiện phù hợp', 'D', 'D đúng. Quyền chia sẻ và trách nhiệm sử dụng phải được xác định trước.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6011bab3-3793-4525-aeeb-2084bb013b99', '3a6158cd-409e-53b6-b657-95bfc28329ba', 9, 'Chuyên gia đề xuất mua cụm hàn mới. Hành động hợp lý nhất?', 'Kiểm giả thuyết, dữ liệu và khả năng thử các phương án trước', 'Ký mua ngay', 'Loại bỏ mọi giải pháp khác', 'Thay mục tiêu cho khớp lời chào', 'A', 'A đúng. Đề xuất cần bằng chứng và phép thử, không tự động trở thành lựa chọn cuối.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('03cfbe29-95fc-42e1-992b-c9a51923af48', '3a6158cd-409e-53b6-b657-95bfc28329ba', 10, 'Sau thử tỷ lệ lỗi thấp hơn, nên kết luận thế nào?', 'Đã chứng minh nhân quả hoàn toàn', 'Quan sát cải thiện; kiểm soát yếu tố gây nhiễu và điều kiện đo trước khi quy kết', 'Chắc chắn hoàn vốn', 'Không cần giám sát chất lượng', 'B', 'B đúng. Chênh lệch trước-sau không tự chứng minh nguyên nhân; phải kiểm vật liệu, ca, mẫu và an toàn.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('afae4780-011d-4e29-bda9-1fc29069af60', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 1, 'Câu hỏi ôn tập 1: Nhận định nào sau đây là chuẩn xác nhất đối với ''Hệ sinh thái cung – cầu công nghệ: doanh nghiệp có thể tìm công nghệ ở đâu?''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ead243d2-5b02-4627-9c9e-61d96c77642c', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 2, 'Câu hỏi ôn tập 2: Nhận định nào sau đây là chuẩn xác nhất đối với ''Hệ sinh thái cung – cầu công nghệ: doanh nghiệp có thể tìm công nghệ ở đâu?''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7e035ab1-41a9-4eaf-bd93-56546fadeecf', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 3, 'Câu hỏi ôn tập 3: Nhận định nào sau đây là chuẩn xác nhất đối với ''Hệ sinh thái cung – cầu công nghệ: doanh nghiệp có thể tìm công nghệ ở đâu?''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('50e5a671-4d5b-4dee-a95d-aaa481e83315', 'f9d455c5-f10f-57da-8dba-e0e566a16173', 4, 'Câu hỏi ôn tập 4: Nhận định nào sau đây là chuẩn xác nhất đối với ''Hệ sinh thái cung – cầu công nghệ: doanh nghiệp có thể tìm công nghệ ở đâu?''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
