INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('f559549c-a32a-4e41-9586-9f44a6138498', 'b077eeb8-a125-5b14-b57e-adb919073e53', 10, 'Câu hỏi ôn tập 10: Nhận định nào sau đây là chuẩn xác nhất đối với ''Khai thác cơ sở dữ liệu công nghệ, sáng chế và nguồn thông tin công khai''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('bbd95382-bcda-4a8a-b3ba-69abb57536c9', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 1, 'Khi đọc hồ sơ camera, điểm khởi đầu phù hợp là gì?', 'Giá niêm yết', 'Hãng có nhiều quảng cáo', 'Chức năng cần đạt trong quy trình', 'Màu vỏ thiết bị', 'C', 'C đúng: cần đối chiếu công việc với chức năng và đầu ra đã mô tả.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('93a3b720-28fd-414f-88e7-e16712c15cd1', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 2, 'Thông số “tối đa 120 gói/phút” cho phép khẳng định điều gì?', 'Đạt 120 ở mọi điều kiện', 'Đó là giá trị công bố; cần biết điều kiện đo', 'Đã có dư công suất 45 gói/phút thực tế', 'Không cần thử tại dây chuyền', 'B', 'B đúng. Điều kiện thử, bao bì và dừng máy có thể làm thay đổi năng suất thực tế.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('55a706e9-b541-438d-8803-be14059f94f2', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 3, 'Khi hồ sơ ghi 99% chính xác nhưng không định nghĩa, bước tiếp theo là gì?', 'Coi là 99% phát hiện lỗi', 'Coi là 99% không bỏ lọt', 'Chấp nhận ngay', 'Yêu cầu công thức, mẫu, cách kiểm và kết quả từng loại lỗi', 'D', 'D đúng. Không thể suy một chỉ số chưa định nghĩa thành chỉ tiêu nghiệm thu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('5d7e3222-4a76-4b93-97b3-1ea2de8e3327', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 4, 'Đâu là điều kiện tích hợp cần kiểm chứng?', 'Giao thức tín hiệu, độ trễ, phân quyền và xử lý khi mất kết nối', 'Máy có màu tương đồng băng tải', 'Tờ rơi có chữ Ethernet', 'Nhà cung cấp dùng biểu tượng internet', 'A', 'A đúng. Cổng vật lý không thay thế kiểm thử giao tiếp và dữ liệu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0e386cb8-e3fe-4eb1-990d-8a41f1dd5461', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 5, '96 phát hiện đúng trên 100 mẫu lỗi cho tỷ lệ nào?', '96% phát hiện lỗi', '96% loại nhầm', '4% đúng chung', '99% độ chính xác', 'A', 'A đúng. Mẫu số của tỷ lệ phát hiện là toàn bộ mẫu thực sự lỗi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6ca481bb-3c6d-4e2e-b237-190eef1d6e89', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 9, 'Khi hai chỉ tiêu thử chưa đạt, còn tốc độ chưa thử, kết luận hợp lý là?', 'Chỉ tiêu thử chưa đạt; tốc độ chưa xác minh', 'Công nghệ được chấp nhận vì có tốc độ danh định cao', 'Mọi công nghệ camera đều không dùng được', 'Mặc nhiên tốc độ đã đạt', 'A', 'A đúng. Phải tách chưa đạt với chưa có bằng chứng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('1a490094-b932-4566-8a6a-80078ef9d81f', '0b029b20-faeb-5fa0-b982-3bb2cd8f9e7f', 10, 'Điều kiện tiên quyết để thử hệ thống trên dây chuyền là gì?', 'Được phép tự thay đổi bộ điều khiển', 'Nhà cung cấp cam kết miệng', 'Thống nhất phép thử và có phê duyệt an toàn, trách nhiệm người vận hành', 'Đợi đến lúc nghiệm thu mới xác định mẫu', 'C', 'C đúng. Cần phương án thử, điều kiện dừng và phê duyệt phù hợp trước khi triển khai.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('96f779db-4c2a-435f-92d9-b62d4514ae1e', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 1, 'Câu hỏi ôn tập 1: Nhận định nào sau đây là chuẩn xác nhất đối với ''TRL 1–9: đánh giá mức độ sẵn sàng công nghệ''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
