INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c9b9bbbc-0c54-4f9e-aa43-78b482f86239', 'bad7abb8-61c1-55e8-b195-1d7ff15633d4', 10, 'Câu hỏi ôn tập 10: Nhận định nào sau đây là chuẩn xác nhất đối với ''TRL 1–9: đánh giá mức độ sẵn sàng công nghệ''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c80c38d6-5f6e-48c2-bb2f-4d8fb858cd3d', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 1, 'Khẳng định 99% chính xác không ghi điều kiện thử nên được coi là gì?', 'Kết quả nghiệm thu chắc chắn', 'Một tuyên bố cần làm rõ định nghĩa và bằng chứng', 'Bằng chứng thử độc lập', 'Căn cứ dự toán sản lượng ngay', 'B', 'B đúng. Chưa biết chỉ số, mẫu số, mẫu và điều kiện thì chưa thể nghiệm thu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b8428e71-b3e9-49d4-997f-85674d411cdb', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 2, 'Thông tin nào giúp xác định báo cáo có đúng cấu hình đang đánh giá?', 'Mã phiên bản thiết bị, phần mềm và ngày thử', 'Màu của slide giới thiệu', 'Tên miền của logo nhà cung cấp', 'Số trang brochure', 'A', 'A đúng. Kết quả của cấu hình khác không tự xác nhận cấu hình hiện tại.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('05f81ece-2572-455f-af22-53733071e44b', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 3, 'Tại sao cần giữ log từng mẫu bên cạnh bảng tổng hợp?', 'Để làm file lớn hơn', 'Để dùng lại mọi thông tin cá nhân', 'Để kiểm tra đếm, mẫu bị loại và trường hợp máy sai', 'Để thay chuẩn gán nhãn', 'C', 'C đúng. Log giúp truy xuất sai số, loại trừ và điều kiện tương ứng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('464bebc1-7250-4b84-aa49-e6041190bdd6', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 4, 'Điều nào cho thấy nguy cơ sai lệch khi đánh giá?', 'Thử trên ca khác nhau', 'Thử với bao bì khó', 'Có log đầy đủ', 'Chỉ lấy mẫu đã dùng để hiệu chỉnh hệ thống', 'D', 'D đúng. Mẫu quen thuộc có thể làm kết quả lạc quan hơn trên mẫu mới.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0b60ba36-0a2e-421c-b723-d811adf18f53', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 5, 'TP=96, FN=4. Phát hiện lỗi bằng bao nhiêu?', '96%', '4%', '96,8%', '24%', 'A', 'A đúng. Mẫu số là TP+FN=100 mẫu thực sự lỗi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8489a0d3-5e08-40df-9523-d42111b7c2f9', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 6, 'FP=12, TN=388. Tỷ lệ loại nhầm bằng bao nhiêu?', '12%', '0,3%', '3%', '4%', 'C', 'C đúng. 12/(12+388)=3% mẫu thực sự tốt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8a0eb11f-6f68-4102-bb07-416e79134e8c', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 7, '100 mẫu lỗi trong tổng 500 mẫu thử có nghĩa gì?', 'Nhà máy chắc chắn có 20% sản phẩm lỗi', 'Thiết kế bộ thử có 20% mẫu lỗi, không suy ra tỷ lệ lỗi sản xuất', 'Camera bỏ lọt 20% mẫu lỗi', 'Tỷ lệ phát hiện chắc chắn bằng 80%', 'B', 'B đúng. Cơ cấu bộ mẫu thử không nhất thiết đại diện cho sản xuất.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ef6faa5d-e571-40da-afee-a704052b7a3c', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 8, 'Khi không biết ai gán nhãn chuẩn, trạng thái phù hợp là gì?', 'Đã đạt', 'Không đạt mọi điều kiện', 'Đủ bằng chứng', 'Chưa xác minh; cần bổ sung quy trình và người xác nhận', 'D', 'D đúng. Thiếu bằng chứng phải ghi thiếu thay vì đưa ra kết luận kỹ thuật cuối cùng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e35e2f6f-ddae-4cfe-ba0b-3d05e19fce59', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 9, 'Theo ngưỡng ví dụ phát hiện >=98%, loại nhầm <=1%, phép đo 96%/3% là gì?', 'Chưa đạt cả hai chỉ tiêu trong phép thử minh họa', 'Đạt cả hai tiêu chí', 'Đạt vì đúng chung 96,8%', 'Không cần kiểm tính đại diện', 'A', 'A đúng. Hai số đo nằm ngoài ngưỡng minh họa; chất lượng dữ liệu vẫn phải kiểm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a9bb98bc-340f-4140-bafd-69ce215c908f', 'd23af58f-738b-5f58-b6f5-6ec6202780f2', 10, 'Yêu cầu thử lại nào có thể kiểm tra được?', 'Xin nhà cung cấp đảm bảo 100% không bao giờ lỗi', 'Chỉ xin thêm video quảng cáo', 'Chốt bộ mẫu, ngưỡng, điều kiện, log, người gán nhãn và cách dừng an toàn', 'Yêu cầu mua máy trước rồi đánh giá sau', 'C', 'C đúng. Tiêu chí và phương pháp chốt trước làm kết quả có thể đối chiếu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0775a655-2245-489b-886d-d0cfbc5676c8', '355ab944-8895-5f38-b87f-89e187038e44', 1, 'Mua thiết bị camera có tự động được sao chép phần mềm sang dây chuyền khác không?', 'Có, vì máy đã được thanh toán', 'Phải xem quyền sử dụng và điều khoản áp dụng', 'Có, nếu dùng cùng thương hiệu', 'Luôn luôn bị cấm bất kể thỏa thuận', 'B', 'B đúng. Quyền đối với máy và phạm vi cấp phép phần mềm cần kiểm riêng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('dc056031-0297-46e3-b634-baad79d69dbe', '355ab944-8895-5f38-b87f-89e187038e44', 2, 'Khi nhà cung cấp nêu một đơn sáng chế, cần kiểm trước điều gì?', 'Màu của bằng chứng', 'Số trang trong brochure', 'Tình trạng đơn/văn bằng, chủ thể, phạm vi và lãnh thổ', 'Số lượt xem quảng cáo', 'C', 'C đúng. Đơn và văn bằng đã cấp có trạng thái pháp lý khác nhau.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7f65a141-2338-4ba1-92c8-95628cb27d8c', '355ab944-8895-5f38-b87f-89e187038e44', 3, 'Đối với phần mềm nhúng, hạng mục nào phải được ghi trong phạm vi sử dụng?', 'Số điểm cài, thời hạn, tích hợp và quyền bảo trì', 'Màu máy và vị trí logo', 'Giờ ăn trưa của bên cung cấp', 'Chỉ giá mua thiết bị', 'A', 'A đúng. Phạm vi sử dụng nên bám các hành vi vận hành thực tế.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a38728e9-951f-4e86-b77c-159a94f02288', '355ab944-8895-5f38-b87f-89e187038e44', 4, 'Khi chuyển ảnh lỗi sản phẩm cho nhà cung cấp, bước nào phù hợp?', 'Tự cho phép bên bán bán lại ảnh', 'Công khai ảnh chưa sàng lọc', 'Bỏ qua mục đích và lưu giữ', 'Thỏa thuận mục đích, truy cập, giữ, dùng lại và xử lý khi kết thúc', 'D', 'D đúng. Quyền dùng ảnh và quản trị dữ liệu phải làm rõ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('82e8386a-dcab-4dc9-8d93-9c430f4bb2be', '355ab944-8895-5f38-b87f-89e187038e44', 5, 'Không tìm thấy sáng chế trong một lần tra cứu nghĩa là gì?', 'Tất cả quyền của bên thứ ba đã hết', 'Chưa đủ căn cứ kết luận không xâm phạm; cần kiểm thêm', 'Thiết bị chắc chắn không có tính mới', 'Nhà cung cấp không sở hữu máy', 'B', 'B đúng. Giới hạn tra cứu không thể thay thẩm định FTO.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a76dcdbe-951e-497e-9a7a-0b1e9b343a7c', '355ab944-8895-5f38-b87f-89e187038e44', 6, 'Phần mềm chứa thư viện nguồn mở thì nên làm gì?', 'Giả định không có điều kiện', 'Xóa tên thư viện khỏi hồ sơ', 'Yêu cầu danh mục phiên bản và kiểm điều kiện giấy phép tương ứng', 'Cấm mọi cách dùng thư viện', 'C', 'C đúng. Nghĩa vụ phụ thuộc từng giấy phép và cách phân phối, sử dụng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('98b8604b-56ab-4142-8596-7e9eeab3c056', '355ab944-8895-5f38-b87f-89e187038e44', 7, 'Bên cung cấp chưa chứng minh quyền cấp phép. Trạng thái ghi nhận phù hợp?', 'Chưa xác minh; yêu cầu chuỗi quyền hoặc chứng từ ủy quyền', 'Đã hợp pháp vì có báo giá', 'Đã vi phạm trong mọi trường hợp', 'Đã có quyền khai thác toàn cầu', 'A', 'A đúng. Thiếu chứng cứ khác với kết luận vi phạm đã được xác lập.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8c32d006-0696-446f-96b9-c859200f24f8', '355ab944-8895-5f38-b87f-89e187038e44', 8, 'Phiếu ghi 6 hạng mục, có tài liệu 2, chưa xác minh 4, vướng mắc 0. Tỷ lệ có tài liệu là bao nhiêu?', '66,7%, chứng minh giao dịch an toàn', '33,3% và đó là tỷ lệ an toàn pháp lý', '100% vì chưa có khiếu nại', '33,3%, chỉ đo mức đủ tài liệu để rà soát', 'D', 'D đúng. 2/6=33,3%. Chỉ số quản lý hồ sơ không phải tỷ lệ an toàn pháp lý.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7bcfd60c-6e07-4b02-a81c-2020a84ab7b1', '355ab944-8895-5f38-b87f-89e187038e44', 9, 'Nếu giấy phép cho một địa điểm nhưng kế hoạch cần hai, cách xử lý?', 'Tự mở rộng vì không thay phần mềm', 'Xác định chênh lệch và đàm phán phạm vi/điều kiện bổ sung', 'Bỏ qua vì máy là tài sản của doanh nghiệp', 'Ngưng mọi hoạt động tìm kiếm công nghệ', 'B', 'B đúng. Phải khớp quyền được cấp với phạm vi triển khai dự kiến.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b32ed56a-c44b-4b9a-ad56-360ba68b3a75', '355ab944-8895-5f38-b87f-89e187038e44', 10, 'Khi quyền liên quan nhiều chủ thể và có rủi ro xuyên biên giới, doanh nghiệp nên?', 'Chỉ xem báo giá', 'Để kế toán tự phê duyệt quyền', 'Chuyển thẩm định pháp lý cùng hồ sơ thành phần và hành vi dự kiến', 'Ghi “sạch pháp lý” vì nhà cung cấp có thương hiệu', 'C', 'C đúng. Bảng rà soát sơ bộ không thay đánh giá pháp lý chuyên sâu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('785854f5-6b0e-4aa4-b8a9-f69c10b819b6', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 1, 'Danh sách ngắn 3-5 giải pháp dùng để làm gì?', 'Chốt ngay nhà cung cấp', 'Chọn nhóm phương án đáng kiểm chứng và trao đổi sâu', 'Thay hồ sơ thử nghiệm và nghiệm thu', 'Chỉ để xếp hạng thương hiệu', 'B', 'B đúng. Đây là đầu ra sàng lọc, chưa phải quyết định đầu tư.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e966ccc9-d32e-4574-822d-b6f705288751', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 2, 'Vì sao không nên đếm ba brochure từ ba đại lý là ba giải pháp khác nhau?', 'Vì có thể cùng một kiến trúc và cùng một công nghệ nền', 'Vì mọi đại lý đều không đáng tin', 'Vì mọi giải pháp cần đúng ba nguồn', 'Vì không được đọc brochure', 'A', 'A đúng. Cần phân biệt số nguồn tài liệu với số cách giải quyết khác biệt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('58a6f358-a2aa-4b5d-9a7f-33e049a2a50d', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 3, 'Tiêu chí nào là điều kiện bắt buộc trong bài toán An Bình?', 'Màu sắc đẹp của camera', 'Có càng nhiều chức năng càng tốt', 'Phải phát hiện nhãn và đối chiếu mã lô cho từng túi', 'Có logo nổi tiếng', 'C', 'C đúng. Hai chức năng này gắn trực tiếp với lỗi cần xử lý.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7d9ffa94-7641-40da-a5a7-097c4576be3b', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 4, 'Bộ cân trọng lượng có đáp ứng nhiệm vụ kiểm đúng mã lô không?', 'Có, vì cân phát hiện mọi lỗi', 'Có, nếu giá thấp', 'Có, nếu thay máy cân mới', 'Không trực tiếp; cần công nghệ đọc/đối chiếu mã', 'D', 'D đúng. Cân có thể giải quyết bài toán khối lượng, không kiểm nội dung mã lô.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c0542aec-4a69-47d1-bc3b-3a8cf6f2839e', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 5, 'Tốc độ công bố trên brochure nên được ghi thế nào?', 'Là kết quả thử nghiệm chính thức tại An Bình', 'Là tuyên bố cần kiểm trong điều kiện vận hành thực tế', 'Là bảo đảm tuyệt đối cho mọi sản phẩm', 'Là căn cứ bỏ yêu cầu thí điểm', 'B', 'B đúng. Mức bằng chứng phụ thuộc điều kiện và nguồn kiểm chứng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('637d5cb7-463c-4749-a87b-2d7bae284603', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 6, 'Với phương án đọc Data Matrix khi mã in đang là chuỗi chữ, bước phù hợp?', 'Kiểm định dạng và khả năng đổi quy trình in; chưa tự coi là đáp ứng', 'Coi như chắc chắn đáp ứng vì cùng gọi là mã lô', 'Loại mọi công nghệ đầu đọc trong mọi trường hợp', 'Để nhà cung cấp quyết định định dạng mà không hỏi doanh nghiệp', 'A', 'A đúng. Phù hợp phụ thuộc định dạng mã và điều kiện thay đổi quy trình.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0e29e25b-66e5-4c49-bc22-788a47b03453', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 7, 'Một phương án thiếu chức năng bắt buộc nhưng chi phí thấp. Nên làm gì?', 'Chấm giá cao để bù chức năng thiếu', 'Chấp nhận nếu nhà bán bảo hành', 'Sàng lọc ra cho bài toán hiện tại; không bù trừ bằng điểm', 'Giấu thiếu sót khỏi bảng', 'C', 'C đúng. Điều kiện bắt buộc là cửa loại trừ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6bc527d7-b5ca-458a-91b7-ea8496dfe202', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 8, 'Trong sáu phương án giả định, A-D được giữ, E-F bị loại. Tỷ lệ giữ là bao nhiêu?', '4/6 = 66,7%', '2/6 = 33,3%', '4/5 = 80%', '6/6 = 100%', 'A', 'A đúng. Tỷ lệ là chỉ số tiến độ sàng lọc, không đo xác suất thành công công nghệ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2a29caf7-2ffc-4c37-8eb5-0543a0f321e7', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 9, 'Để so sánh kết quả thử giữa các nhà cung cấp, nên thực hiện điều gì?', 'Để mỗi bên chọn bộ mẫu thuận lợi nhất', 'Đánh giá theo độ dài video quảng cáo', 'Chỉ đánh giá một ngày có ít lỗi', 'Dùng cùng định nghĩa lỗi, nhãn chuẩn và điều kiện thử đã thống nhất', 'D', 'D đúng. Cần điều kiện thử có thể so sánh và ghi nhận khác biệt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('75b9f131-e799-4dc4-9de1-9dc488a432ef', '4b69b3b6-aecf-5796-ade2-13adad1e5419', 10, 'Kết quả thử khiến shortlist còn hai phương án. Cách xử lý?', 'Đưa lại phương án không đạt để đủ ba', 'Ghi nhận thực trạng, mở rộng tìm kiếm, giữ nguyên điều kiện bắt buộc', 'Gán lại trạng thái cho các phương án bị loại', 'Chọn ngay phương án có giá thấp nhất', 'B', 'B đúng. Số lượng mong muốn không được ép sai kết luận sàng lọc.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8d74882f-ea5d-4ad3-a1a5-745e8b73960b', '6fb1f56d-a3e8-5fdb-98f5-55b31283e301', 1, 'Câu hỏi ôn tập 1: Nhận định nào sau đây là chuẩn xác nhất đối với ''Thực hành khai thác nền tảng: tìm – lọc – lưu – so sánh – kết nối''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
