INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('1242b814-bb64-4be5-a0c5-dd9c63fbb2ec', '60488501-198f-51f9-b9a3-e9d658985077', 1, 'Ý nghĩa đúng của “công nghệ phù hợp nhất” là gì?', 'Công nghệ có giá mua cao nhất', 'Công nghệ có nhiều tính năng nhất', 'Công nghệ đáp ứng nhiệm vụ trong ràng buộc của doanh nghiệp', 'Công nghệ quảng cáo mới nhất', 'C', 'Phù hợp phụ thuộc nhiệm vụ, điều kiện vận hành, tổ chức và chi phí.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('54a953fa-30ce-45de-95c8-3678da304b7c', '60488501-198f-51f9-b9a3-e9d658985077', 2, 'Tốc độ 140 túi/phút trong brochure có nghĩa gì?', 'Đủ bằng chứng đạt 140 ở mọi nhà máy', 'Là tuyên bố cần kiểm trong điều kiện áp dụng', 'Chắc chắn không thể dùng ở An Bình', 'Đã phản ánh tỷ lệ loại nhầm thực tế', 'B', 'Thông số công bố chưa thay thế phép thử tại hiện trường.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('1748973b-ad84-4ca1-b120-1189250d7025', '60488501-198f-51f9-b9a3-e9d658985077', 3, 'Nhiệm vụ bắt buộc của An Bình trong bài là gì?', 'Phát hiện nhãn và đối chiếu mã lô từng túi', 'Chỉ cân khối lượng sản phẩm', 'Thay toàn bộ phần mềm kế toán', 'Phải lắp robot AI', 'A', 'Chức năng kiểm nhãn và đúng mã lô được xác định từ bài toán.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('3ecdf409-6c4d-4dd3-9b0d-e7c5a2902571', '60488501-198f-51f9-b9a3-e9d658985077', 4, 'A chỉ xử lý 35 túi/phút trong khi yêu cầu 55. Cách kết luận?', 'Tự cộng điểm giá để bù', 'Chọn A ngay vì rẻ', 'Ghi A chắc chắn đạt nếu thêm nhân viên', 'A không đáp ứng cổng nhịp nếu 35 là số đo tại điều kiện cần', 'D', 'Nhịp là điều kiện bắt buộc khi kiểm toàn bộ sản phẩm ở đỉnh nhu cầu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d962ac74-3fdf-4678-9920-b6ed74ed0f34', '60488501-198f-51f9-b9a3-e9d658985077', 5, 'Chi phí sơ bộ 3 năm của B: vốn 420, vận hành 100 triệu/năm?', '420 triệu', '720 triệu', '300 triệu', '1.020 triệu', 'B', '420 + 3 x 100 = 720 triệu, chưa tính những khoản còn thiếu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2c87902a-b7cc-4783-ab33-b25a5ec21a2f', '60488501-198f-51f9-b9a3-e9d658985077', 6, 'Khoản nào có thể khiến giá mua không phản ánh chi phí vòng đời?', 'Chỉ màu sơn thiết bị', 'Chỉ số model', 'Dừng máy, tích hợp, đào tạo, bảo trì', 'Tên thương hiệu', 'C', 'Các khoản này cần ước tính và đưa vào thẩm định.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('3bf5714e-e47d-4bc4-a0de-f40a99cecbcb', '60488501-198f-51f9-b9a3-e9d658985077', 7, 'Vì sao năng lực vận hành là tiêu chí chọn công nghệ?', 'Vì phải có người hiệu chỉnh, xử lý cảnh báo và duy trì hệ thống', 'Vì thiết bị tự động không bao giờ cần bảo trì', 'Vì chỉ công nghệ mới nhất đòi dữ liệu', 'Vì người dùng không liên quan kết quả', 'A', 'Thiếu năng lực hấp thụ làm tăng rủi ro dừng máy và phụ thuộc.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a7665305-ec67-4702-841f-72198574213a', '60488501-198f-51f9-b9a3-e9d658985077', 8, 'Tổng trọng số bốn tiêu chí 40%, 25%, 20%, 15% là bao nhiêu?', '80%', '85%', '95%', '100%', 'D', 'Trọng số phải cộng đủ 100% để có điểm bình quân có trọng số.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('88ef46e6-6014-49b7-a583-6502a0c4b5e3', '60488501-198f-51f9-b9a3-e9d658985077', 9, 'B được 4 điểm ở cả bốn tiêu chí, tổng điểm là?', '4,00', '3,05', '3,60', '5,00', 'A', '4 x (0,40+0,25+0,20+0,15) = 4,00.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a8656c0c-6b53-480d-b7e1-e6ff6456c2da', '60488501-198f-51f9-b9a3-e9d658985077', 10, 'Sau khi B được xếp ưu tiên kiểm chứng, bước phù hợp tiếp theo?', 'Mua ngay vì điểm cao', 'Thử cùng tiêu chí, đo dữ liệu rồi mới xem xét đầu tư', 'Bỏ kiểm tra an toàn', 'Chuyển thông số quảng cáo thành biên bản nghiệm thu', 'B', 'Điểm xếp hạng không thay kiểm thử và quy trình phê duyệt đầu tư.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('57851153-30f3-49b6-bc3b-8bec1bea8f6c', '05cd1d76-9728-5680-8053-975784ac47d1', 1, 'Đặt tiêu chí để so sánh công nghệ nên bắt đầu từ đâu?', 'Tính năng quảng cáo', 'Mức giá cao nhất', 'Bài toán và yêu cầu có thể kiểm', 'Thương hiệu phổ biến', 'C', 'Bộ tiêu chí phải suy ra từ nhu cầu và ràng buộc thực tế.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('45921ad7-4883-4d61-8387-77be6da54731', '05cd1d76-9728-5680-8053-975784ac47d1', 2, 'Điều kiện nào cần đặt vào cổng bắt buộc?', 'Màu sắc vỏ máy', 'Khả năng đọc đúng mã lô theo yêu cầu', 'Mẫu brochure', 'Số lượt xem video', 'B', 'Chức năng phải có không thể được bù bằng điểm giá hay trải nghiệm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('9161ec69-808b-402c-8939-874864d86a53', '05cd1d76-9728-5680-8053-975784ac47d1', 3, 'A đã đo 35 túi/phút, yêu cầu 55. Cách xử lý?', 'A không đạt cổng nhịp', 'Cho A thêm 2 điểm chi phí', 'Chỉ đổi trọng số cho A thắng', 'Bỏ qua nhịp', 'A', 'Khi ngưỡng thực sự bắt buộc và đo tin cậy, A không đạt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c5fcd7aa-4931-4133-b064-8fa9ad36cdfb', '05cd1d76-9728-5680-8053-975784ac47d1', 4, 'Một tiêu chí tốt cần gì?', 'Từ ngữ chung như rất tốt', 'Điểm do nhà cung cấp tự chấm', 'Chỉ có đơn vị phần trăm', 'Định nghĩa, cách đo, điều kiện và nguồn', 'D', 'Không có quy tắc đo thì các đánh giá không tương đương.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('fe45593c-f514-43ef-b6d2-ccbe701dea4f', '05cd1d76-9728-5680-8053-975784ac47d1', 5, 'Tổng trọng số 35/25/20/20 bằng bao nhiêu?', '90%', '100%', '95%', '105%', 'B', 'Tổng là một trăm phần trăm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('fe40df57-adb9-47c3-a4c3-5ef4d773a314', '05cd1d76-9728-5680-8053-975784ac47d1', 6, 'B đạt điểm 4 ở cả bốn tiêu chí. Điểm tổng?', '3,50', '3,85', '4,00', '5,00', 'C', 'Bằng 4 nhân tổng trọng số, tức 4,00.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('575f44a1-20a1-42c2-bf2a-7a5e5e06d917', '05cd1d76-9728-5680-8053-975784ac47d1', 7, 'B có điểm cao nhất nhưng cổng nhịp chưa kiểm tại nhà máy. Kết luận?', 'Mua ngay', 'B chắc chắn phù hợp', 'Không cần đo thêm', 'Ưu tiên thử, chưa phê duyệt', 'D', 'Điểm giả định không chuyển tuyên bố thành bằng chứng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e307122a-974c-4d25-9455-171f5283daa4', '05cd1d76-9728-5680-8053-975784ac47d1', 8, 'Hai tiêu chí là giá mua và vốn đầu tư ban đầu giống nhau. Rủi ro?', 'Đếm đôi cùng yếu tố chi phí', 'Không còn cần chấm tích hợp', 'Trọng số luôn bằng 100%', 'Tăng tính chính xác của điểm', 'A', 'Hai tiêu chí trùng có thể làm chi phí bị tính trọng số nhiều lần.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('32184b98-0288-45a4-bd54-ac734c072703', '05cd1d76-9728-5680-8053-975784ac47d1', 9, 'Đổi trọng số có lý do để xem thứ hạng thay đổi gọi là gì?', 'Đánh giá nhân sự', 'Phân tích độ nhạy', 'Nghiệm thu máy', 'Tính thuế', 'B', 'Cần ghi rõ kịch bản và giả định thay đổi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('f69f40f8-6743-4780-b940-6a3a4b14e9a8', '05cd1d76-9728-5680-8053-975784ac47d1', 10, 'Bước phù hợp trước khi đề xuất đầu tư là gì?', 'Chốt thiết bị ngay theo điểm', 'Xóa nhãn chưa xác minh', 'Thử trên mẫu đại diện và cập nhật điểm, cổng', 'Lấy riêng số liệu nhà cung cấp', 'C', 'Cần bằng chứng thử, điều kiện an toàn, nguồn lực và chi phí thẩm định.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('fa3691f6-3089-4186-88fc-b5997c6bfc04', '3bee64ab-aa58-568d-9644-4fcc98021485', 1, 'CAPEX trong bài là gì?', 'Chi phí chi ban đầu để đưa hệ thống vào sử dụng', 'Chỉ tiền điện từng tháng', 'Chỉ lương nhân viên hiện hữu', 'Doanh thu hằng năm', 'A', 'Tổng vốn đầu tư ban đầu phải bao gồm hạng mục thực chi, không chỉ giá máy.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('41e8a129-5e5e-4204-9073-201158145f57', '3bee64ab-aa58-568d-9644-4fcc98021485', 2, 'Khoản nào thuộc OPEX lặp lại?', 'Giá mua máy mới', 'Dừng máy khi lắp đặt', 'Phí giấy phép phần mềm hằng năm', 'Tư vấn thiết kế ban đầu', 'C', 'Phí giấy phép trả theo năm là chi vận hành lặp lại.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b9a6090b-286f-4bf4-9bac-8f303b075e8c', '3bee64ab-aa58-568d-9644-4fcc98021485', 3, 'Máy 420, tích hợp 35, đào tạo 15, dừng lắp 10. CAPEX bằng?', '420', '465', '480', '520', 'C', '420+35+15+10=480 triệu đồng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('16736cdb-26da-4bfc-bffa-16fad42b45c7', '3bee64ab-aa58-568d-9644-4fcc98021485', 4, 'OPEX 100 triệu/năm trong ba năm là?', '100 triệu', '200 triệu', '300 triệu', '480 triệu', 'C', 'Cần quy về cùng kỳ: 100×3=300 triệu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6a846f09-acb9-4821-9755-76afe5a71ae5', '3bee64ab-aa58-568d-9644-4fcc98021485', 5, 'CAPEX 480, OPEX 100/năm, 3 năm, thu hồi 0. TCO?', '580', '680', '780', '900', 'C', 'TCO giản lược bằng 480+300=780 triệu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('cc80de9f-89bd-44a5-a944-fc82a12d089a', '3bee64ab-aa58-568d-9644-4fcc98021485', 6, 'Nếu chưa có bằng chứng giá trị bán lại máy thì nên?', 'Tự cộng mức bán lại ước đoán cao', 'Ghi 0 hoặc ghi chưa xác minh, tránh khấu trừ tùy tiện', 'Bỏ CAPEX', 'Cộng vào OPEX', 'B', 'Giá trị còn lại cần có căn cứ để không làm thấp TCO.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('edde6334-706d-41b6-bf7e-e3ed4fa75bf3', '3bee64ab-aa58-568d-9644-4fcc98021485', 7, 'Tiết kiệm gộp 300 và OPEX mới 100/năm. Dòng tiền thuần tăng thêm?', '400', '300', '200', '100', 'C', '300 trừ 100 bằng 200 triệu/năm nếu không trùng khoản tiết kiệm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a1fbae8c-b2d3-4566-a150-15ab6307c7f7', '3bee64ab-aa58-568d-9644-4fcc98021485', 8, 'Vốn ban đầu 480, dòng tiền thuần 200/năm. Hoàn vốn đơn giản?', '1,6 năm', '2,4 năm', '3,0 năm', '4,8 năm', 'B', '480/200=2,4 năm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('84cc4f59-359c-4ebe-8c82-a442d29b40d2', '3bee64ab-aa58-568d-9644-4fcc98021485', 9, 'Tiết kiệm gộp giảm 20% còn 240, OPEX 100. Hoàn vốn xấp xỉ?', '1,6 năm', '2,4 năm', '3,43 năm', '5,0 năm', 'C', 'Dòng tiền thuần 140, nên 480/140≈3,43 năm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7ca8f460-6b4c-4f66-9095-e6d826949d12', '3bee64ab-aa58-568d-9644-4fcc98021485', 10, 'Khi nào nên bổ sung NPV/IRR?', 'Khi cần thẩm định sâu có giá trị thời gian của tiền', 'Khi muốn bỏ qua dòng tiền', 'Để thay dữ liệu bằng cảm tính', 'Khi muốn coi TCO là lợi nhuận', 'A', 'Hoàn vốn đơn giản bỏ qua giá trị thời gian của tiền và các dòng tiền sau thu hồi vốn.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7dd98411-ba76-4186-aaf2-b02ee053280e', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 1, 'Đơn vị chức năng nào hợp lý để so điện của hai công nghệ đóng gói?', 'Số túi đạt', 'Tuổi máy', 'Giá mua thiết bị', 'Diện tích văn phòng', 'A', 'Nên quy về một đầu ra hữu ích với phạm vi tương đương.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('fc65c8db-6bba-4835-93ea-4b1016f3ee23', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 2, 'Nếu chỉ có tổng kWh tháng nhưng sản lượng hai kỳ khác nhau, cần làm gì?', 'Chọn tháng có điện thấp', 'Tính trên mỗi túi đạt và kiểm tra điều kiện', 'Gọi máy điện thấp hơn là xanh', 'Bỏ số liệu sản lượng', 'B', 'Tổng điện một mình không tách hiệu quả ra khỏi quy mô hoạt động.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c6df8cd2-3d17-4252-9958-23071d06fd66', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 3, 'A 1.000 kWh và 10.000 túi đạt. Điện trên 1.000 túi là?', '10 kWh', '92 kWh', '100 kWh', '1.000 kWh', 'C', '1.000/10.000 × 1.000 = 100 kWh/1.000 túi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8f527e22-3d94-43a7-8974-0a3b8618fed2', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 4, 'B 920 kWh và 10.000 túi đạt. Điện/túi B so A 1.000 kWh thay đổi?', 'Giảm 8%', 'Tăng 8%', 'Giảm 80%', 'Tăng 20%', 'A', '(920 - 1.000)/1.000 = -8%, với cùng 10.000 túi đạt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('81e8c568-2f9f-480e-b321-1c2d2149779c', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 5, 'Rác A 80 kg cho 10.000 túi. Chỉ số trên 1.000 túi là?', '0,8 kg', '8 kg', '80 kg', '800 kg', 'B', '80/10.000 × 1.000 = 8 kg.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b80d8fdc-26a2-4f9a-9a5a-39b2161fa898', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 6, 'Hệ số 0,60 kg CO₂e/kWh trong phiếu là gì?', 'Hệ số lưới điện được chứng nhận', 'Hệ số chính thức bắt buộc dùng', 'Hệ số từ hóa đơn điện', 'Số giả định để luyện phép tính', 'D', 'Không dùng số minh họa làm hệ số phát thải chính thức.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('4f37a829-05df-4229-a8fe-a13ec88c53b9', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 7, 'Điện B 920 kWh, hệ số giả định 0,60. CO₂e từ điện bằng?', '552 kg CO₂e', '920 kg CO₂e', '1.533 kg CO₂e', '0,60 kg CO₂e', 'A', '920 × 0,60 = 552 kg CO₂e theo giả định, chưa gồm vòng đời.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('176b5a56-6818-41fa-912b-0465ba234526', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 8, 'C tăng điện 15% nhưng giảm rác 56,25%. Kết luận đúng?', 'C chắc chắn tốt hơn B', 'Có đánh đổi cần xác minh', 'C không gây phát thải', 'C chắc chắn không đạt', 'B', 'Hai chỉ số đo các tác động khác nhau, chưa đủ quyết định.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2c0ff1d1-25e1-486d-b5d0-c6a2be5bdd23', '2a6a2b77-bc16-5807-897f-9ea287a133ec', 9, 'Điều nào phải kiểm tra ngoài điện và rác?', 'Chỉ màu sắc thiết bị', 'Chỉ nhãn hiệu', 'An toàn vận hành, tiếng ồn và xử lý cuối vòng đời', 'Chỉ hình dáng máy', 'C', 'Sản xuất bền vững còn xét an toàn và các tác động không đo trong bảng.', false);
