INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('9a5b9bda-b6e3-4c33-a9ed-3af27e0babc3', 'ff65e401-5641-52eb-92a0-b93256b41783', 6, 'Chênh lệch một phần họp được tính thế nào?', 'Phút dự kiến trừ phút thực tế', 'Phút thực tế cộng phút dự kiến', 'Phút thực tế trừ phút dự kiến', 'Luôn bằng không', 'C', 'Dấu dương chỉ phần kéo dài so với kế hoạch.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('822d342a-bd8e-4d21-8366-4cb2d4637a8c', 'ff65e401-5641-52eb-92a0-b93256b41783', 8, 'Có brochure nhưng chưa có nhật ký thử nên ghi trạng thái nào?', 'Đã nghiệm thu', 'Đã được chứng minh', 'Không cần thêm gì', 'Cần bổ sung bằng chứng', 'D', 'Brochure chưa có điều kiện thử, số mẫu và dữ liệu kết quả gốc.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('46fc1170-4f0e-407c-9ba5-a3dbb2549faa', 'ff65e401-5641-52eb-92a0-b93256b41783', 9, 'Nhân sự nào nên kiểm điều kiện quyền lưu trữ ảnh thử?', 'Người thiết kế slide', 'CNTT và đầu mối pháp lý hoặc dữ liệu có trách nhiệm', 'Người xem quảng cáo', 'Bên cung tự quyết cho doanh nghiệp', 'B', 'Cần xác định phạm vi truy cập, quyền sử dụng và chính sách lưu giữ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('f874946b-519f-4646-9592-ef2310259703', 'ff65e401-5641-52eb-92a0-b93256b41783', 10, 'Sau khi đánh dấu đủ tất cả trạng thái biên bản có được mua luôn không?', 'Có, vì Excel hiện đạt', 'Có, vì cuộc họp đủ 45 phút', 'Không; còn thẩm định kỹ thuật, quyền, chi phí và quy trình mua sắm', 'Có, nếu bên bán đồng ý', 'C', 'Đủ nhật ký phiên kết nối không đồng nghĩa đã kiểm chứng công nghệ hoặc đủ thẩm quyền mua.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e88a7274-492d-43a9-ad84-a2103651bd88', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 1, 'Kết quả cần có trước khi bắt đầu PoC là gì?', 'Hợp đồng mua máy đã ký', 'Giả thuyết, mẫu, ngưỡng và cổng bắt buộc đã xác định', 'Ảnh quảng cáo sản phẩm', 'Ước tính doanh thu không có nguồn', 'B', 'Phải định nghĩa câu hỏi kiểm chứng, dữ liệu và điều kiện dừng trước khi chạy.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2bc376d9-c674-45e5-ba79-986214a39fc5', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 2, 'PoC khác thí điểm vận hành ở điểm nào?', 'PoC kiểm chức năng phạm vi hẹp; thí điểm kiểm vận hành thực', 'PoC luôn dài hơn thí điểm', 'PoC đã là nghiệm thu cuối', 'PoC không cần dữ liệu', 'A', 'PoC chỉ giải quyết một giả thuyết hẹp, thí điểm xem xét thêm tích hợp và vận hành.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('876cc4d5-fcf1-41e7-98d5-19fe1718bac4', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 3, 'TP = 96, FN = 4. Mẫu số của tỷ lệ phát hiện là bao nhiêu?', '96', '500', '100', '400', 'C', 'TP+FN=100 mẫu có lỗi.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e7255650-9e2a-4ec5-8e7c-478efbc82c22', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 4, 'TP 96, FN 4, FP 16, TN 384. Tỷ lệ phát hiện là?', '4%', '80%', '99%', '96%', 'D', '96/(96+4)=96%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7d74243b-66c5-4f96-9225-0a5679cc6f6d', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 5, 'FP = 16, TN = 384. Tỷ lệ loại nhầm là?', '4%', '16%', '96%', '3%', 'A', '16/(16+384)=4%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b16ad131-68d3-4d78-b597-1b4aea8617b6', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 6, 'Tỷ lệ chính xác chung trên 500 mẫu trong ví dụ là?', '95%', '96%', '92%', '4%', 'B', '(TP+TN)/500=(96+384)/500=96%; không được dùng một mình.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('740b0112-3563-4ac1-8683-c1da0db1c9e5', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 7, 'Với trần ngân sách 20 triệu và chi phí 18 triệu, phần còn là?', '38 triệu', '-2 triệu', '2 triệu', '0 triệu', 'C', '20-18=2 triệu đồng; đây không phải TCO.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6d278316-e409-48a4-a3d4-70c0c578fa63', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 8, 'Sau điều chỉnh, FP 12 và TN 388. Tỷ lệ loại nhầm mới là?', '12%', '4%', '5%', '3%', 'D', '12/400=3%, nhưng phải đo trên phép thử mới độc lập, không sửa kết quả cũ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0d9e7ce0-1400-40cc-83ee-0f40e012474d', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 9, 'Khi chưa có quyền dùng ảnh thử, bước nào đúng?', 'Dừng phần dùng ảnh cho đến khi được phép', 'Cứ thử để giữ tiến độ', 'Ẩn nguồn ảnh khỏi báo cáo', 'Chỉ hỏi người bán', 'A', 'Quyền sử dụng dữ liệu là điều kiện bắt buộc, không thể thay bằng điểm số.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a866994b-fc1f-49e9-8609-65bfd7c9261c', '9234a8e5-99d4-5ea0-808d-2d2889672b51', 10, 'Khi PoC đạt cả hai ngưỡng thì nên làm gì?', 'Ký mua toàn bộ thiết bị ngay', 'Đề xuất pilot có kiểm soát và thẩm định tiếp', 'Bỏ kiểm an toàn', 'Gọi kết quả là đúng mọi dây chuyền', 'B', 'PoC đạt trong phạm vi hẹp chưa chứng minh hiệu quả khi mở rộng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('78050d89-18e6-47b0-9f5c-8cd832e7a6ec', 'f18c0159-faed-555c-9ff4-5e727391c028', 1, 'Khác biệt trọng tâm của thí điểm so với PoC là gì?', 'Thí điểm đánh giá vận hành trong phạm vi có kiểm soát', 'Thí điểm chỉ kiểm logo sản phẩm', 'Thí điểm thay nghiệm thu pháp lý', 'Thí điểm không cần người vận hành', 'A', 'PoC kiểm giả thuyết chức năng; pilot cần đo tác động trong điều kiện vận hành.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d11aa529-d762-411f-a02b-50e183c711e3', 'f18c0159-faed-555c-9ff4-5e727391c028', 2, 'Một chỉ số cần chốt khi nào để tránh chỉnh ngưỡng theo kết quả?', 'Sau khi xem tuần cuối', 'Trước khi bắt đầu lấy dữ liệu thí điểm', 'Chỉ sau khi nhà cung cấp đề nghị', 'Khi đã ký mua thiết bị', 'B', 'Chốt ngưỡng, đơn vị và mẫu số trước thử nghiệm; thay đổi sau phải có phê duyệt và lưu vết.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('9fdfb87c-338a-4836-85ca-c0d8206447ba', 'f18c0159-faed-555c-9ff4-5e727391c028', 3, 'TP=188, FN=12. Tỷ lệ phát hiện lỗi gộp là?', '88%', '95%', '94%', '98%', 'C', '188/200=94%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('80bd3421-ed90-49c9-9d21-e01e5fe28b1b', 'f18c0159-faed-555c-9ff4-5e727391c028', 4, 'FP=49, TN=1751. Tỷ lệ loại nhầm là?', '49%', '0,27%', '4,90%', '2,72%', 'D', '49/1800=2,7222%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('1c9a5a79-254b-4962-8770-99148354b84e', 'f18c0159-faed-555c-9ff4-5e727391c028', 5, '160 giờ dự kiến và 6,7 giờ dừng. Tỷ lệ sẵn sàng là?', '95,81%', '93,30%', '96,70%', '6,7%', 'A', '(160-6,7)/160=95,8125%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('613e6ff4-c0aa-4576-a593-ace64d1cdbcc', 'f18c0159-faed-555c-9ff4-5e727391c028', 6, 'Bốn cửa sổ cùng độ dài có tốc độ 42,45,47,48 túi/phút. Bình quân là?', '46,5', '45,5', '42,0', '48,0', 'B', '(42+45+47+48)/4=45,5 túi/phút.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('3fad8485-d8ce-437d-b756-963a06b427da', 'f18c0159-faed-555c-9ff4-5e727391c028', 7, 'Vì sao không lấy bình quân bốn tỷ lệ phát hiện mỗi tuần tùy tiện?', 'Vì tỷ lệ luôn trên 100%', 'Vì Excel không hỗ trợ bình quân', 'Vì mẫu số mỗi tuần có thể khác nhau', 'Vì chỉ số này không cần thiết', 'C', 'Cộng số đếm TP và FN theo cùng định nghĩa trước khi tính tỷ lệ gộp.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('4d17bc7e-33b3-4d27-92ec-a47cb714ba90', 'f18c0159-faed-555c-9ff4-5e727391c028', 8, 'Nếu thiếu phê duyệt an toàn nhưng tất cả KPI đạt, kết luận nào phù hợp?', 'Cho phép mở rộng', 'Chỉ công bố kết quả đẹp', 'Tự đổi điều kiện cổng', 'Tạm dừng phần thử liên quan đến khi kiểm xong', 'D', 'Điều kiện bắt buộc không có cơ chế bù trừ bằng kết quả KPI.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d3b1fe76-7b06-4391-a6f2-049ecfa0b5b0', 'f18c0159-faed-555c-9ff4-5e727391c028', 9, 'Nếu tăng FN trong bảng giả lập, điều gì xảy ra khi TP giữ nguyên?', 'Tỷ lệ phát hiện giảm', 'Tỷ lệ phát hiện tăng', 'Tỷ lệ loại nhầm bằng không', 'Giờ vận hành tăng', 'A', 'TP/(TP+FN) giảm khi mẫu số tăng do FN tăng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e0f5a105-3a70-4a1b-843e-34e5318def2e', 'f18c0159-faed-555c-9ff4-5e727391c028', 10, 'Thí điểm đạt đủ cổng và KPI cho phép kết luận nào?', 'Đã đủ điều kiện mua mọi thiết bị', 'Có thể đề xuất thẩm định tiếp tục, chưa tự duyệt đầu tư', 'Không cần đánh giá nhà cung cấp nữa', 'Kết quả áp dụng mọi ca sản xuất', 'B', 'Quyết định đầu tư còn cần thẩm định kinh tế, rủi ro, quyền và điều kiện nhân rộng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('be9931bd-86bb-46e5-b580-c31d110158ef', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 1, 'Khi Bài 29 còn thiếu KPI, Bài 30 có được mặc nhiên coi đã phê duyệt nhân rộng?', 'Không, cần xử lý và kiểm chứng lại với quyết định riêng', 'Có, vì đã sang bài tiếp theo', 'Có, nếu nhà cung cấp đồng ý miệng', 'Có, nếu số người đã học đủ', 'A', 'Bài 30 là tình huống giả định có bước kiểm chứng và phê duyệt riêng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('42d1e916-b374-4074-9a49-ed759db2c510', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 2, 'Tài liệu nào cần có phiên bản và kiểm thử truy cập được trong bàn giao?', 'Chỉ slide quảng cáo', 'SOP và cấu hình/phục hồi hệ thống', 'Chỉ hóa đơn mua hàng', 'Chỉ hình ảnh buổi đào tạo', 'B', 'SOP, cấu hình và cách phục hồi phải thực thi được khi nhà cung cấp vắng mặt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c93e1ca5-7fa6-4b1d-8572-6875326eb827', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 4, '13 người đạt thao tác trên 16 người cần có. Tỷ lệ năng lực bằng?', '90%', '86,67%', '93,75%', '81,25%', 'D', '13/16=81,25%; không dùng 13/15 vì đang đo năng lực của toàn bộ vị trí cần có.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('1ae87e25-acc8-4c93-b4a9-d4ad07203cb6', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 5, 'Ai xác nhận nhãn chuẩn và kết quả QC khi bàn giao?', 'Người/đơn vị QC được phân công', 'Chỉ người bán thiết bị', 'Bất cứ ai nhìn qua ảnh', 'Tự động lấy điểm đào tạo', 'A', 'Nhãn chuẩn cần người có trách nhiệm và bằng chứng truy xuất.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('f92d453a-e71b-49d4-8bcb-2b35b9f6f724', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 6, 'Nếu một người đã dự lớp nhưng không xử lý được mã in mờ, nên làm gì?', 'Tính là đạt vì đã ký tên', 'Kèm cặp và kiểm tra thực hành lại', 'Giảm ngưỡng xuống không cần kiểm', 'Cho bỏ cảnh báo vĩnh viễn', 'B', 'Điểm danh không chứng minh năng lực thực hiện thao tác.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8db40e6c-0998-4102-b50b-393c7ae4f842', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 7, 'Vì sao phải có tuyến quay lui về kiểm thủ công?', 'Để không cần QC', 'Để che lỗi thiết bị', 'Để duy trì kiểm soát khi có sự cố hoặc vượt ngưỡng dừng', 'Để thay bằng chứng nghiệm thu', 'C', 'Quy trình quay lui phải được duyệt, tập dượt và ghi rõ người quyết định.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6cdca51f-6031-428a-8a0d-49c8aabe9122', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 8, 'Một cổng quyền sử dụng dữ liệu chưa kiểm dù đào tạo đạt 100%, kết luận đúng là?', 'Nhân rộng ngay', 'Tự bỏ cổng', 'Đổi tên cổng', 'Tạm dừng bước liên quan đến khi xác minh', 'D', 'Cổng dữ liệu không bù được bằng điểm đào tạo.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('43d100c0-46e0-45d5-a7b8-cf0f41c9afb3', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 9, 'Vì sao tỷ lệ đạt thao tác 13/15 không thay 13/16 trong bài?', 'Vì hai tỷ lệ trả lời hai câu hỏi khác nhau', 'Vì 13/15 bằng 0', 'Vì Excel không tính được', 'Vì người chưa học luôn được coi đạt', 'A', '13/15 đánh giá người tham gia lớp; 13/16 đánh giá đủ người cho vị trí bắt buộc.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('0d6e8e64-0f61-4d3a-80b5-657a086b12dd', '4d0e297e-d66a-5abb-b635-d0810e720e7f', 10, 'Đủ cổng và đủ tỷ lệ đào tạo cho phép kết luận nào?', 'Mở toàn nhà máy ngay', 'Đề xuất mở rộng theo giai đoạn để người có thẩm quyền xét duyệt', 'Bỏ theo dõi QC', 'Xóa nhật ký thí điểm', 'B', 'Kết quả nội bộ trên phiếu không tự phê duyệt nhân rộng.', false);
