INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8068d0c1-9e37-450b-be01-8b229447b0f2', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 1, 'Đâu là bước đầu khi thấy một tuyên bố công nghệ rất hấp dẫn?', 'Ghi lại nguồn, phạm vi và khẳng định cần kiểm', 'Đặt mua bản dùng thử trả phí ngay', 'Coi số lượt xem là hiệu suất', 'Tăng điểm phù hợp lên 5', 'A', 'Tuyên bố cần được truy về nguồn và điều kiện áp dụng trước khi ra quyết định.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a8d0d363-bc7e-4528-83b2-5588703c5a5c', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 2, 'Một trình diễn đúng 98 hình nhưng không có tổng số hình. Kết luận nào hợp lệ?', 'Độ chính xác 98%', 'Chưa đủ thông tin để tính tỷ lệ chính xác', 'Độ chính xác luôn dưới 50%', 'Công nghệ bị loại vĩnh viễn', 'B', 'Thiếu mẫu số và điều kiện chọn mẫu nên không có tỷ lệ có căn cứ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2b81f4b6-762a-4462-bf51-7a5ae11f7a90', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 3, 'Ba tầng cần tách khi đọc xu hướng là gì?', 'Giá, thương hiệu, bảo hành', 'Thiết bị, phần mềm, đào tạo', 'Tín hiệu, giả thuyết, quyết định', 'Tin, quảng cáo, doanh số', 'C', 'Phân tầng giúp không biến thông tin thành quyết định đầu tư một cách trực tiếp.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d1527cc5-b298-411c-a572-41f0dd4bfab6', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 4, 'Trọng số bốn tiêu chí là 35%, 30%, 20%, 25%. Bước phù hợp là?', 'Giữ nguyên vì tổng không ảnh hưởng', 'Tự bỏ cột phụ thuộc', 'Lấy điểm trung bình cộng', 'Sửa trọng số để tổng đúng 100% trước khi xếp điểm', 'D', 'Tổng hiện bằng 110%, nên cần rà lại tỷ trọng và lý do chọn tỷ trọng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('f733cf5d-abee-497e-a1e9-e8572a5a9f4e', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 5, 'Với rủi ro phụ thuộc được chấm 5 là cao, điểm thuận lợi để tính trọng số là?', '1', '5', '6', '0', 'A', 'Đảo chiều bằng 6-5=1.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('465dd5f2-b48e-40fb-8141-047d3cc4856a', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 6, 'Điểm 3,65 nhưng nguồn chưa kiểm có thể kết luận gì?', 'Sẵn sàng ký hợp đồng', 'Chưa đủ cổng, tiếp tục xác minh nguồn', 'Bảo đảm tiết kiệm chi phí', 'Bắt buộc bỏ phương án', 'B', 'Điểm không thay thế bằng chứng, hợp đồng và các điều kiện bắt buộc.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('47975bb8-bbcd-4544-95ab-04f743c2bce7', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 7, 'Sử dụng số lượt xuất hiện trên truyền thông làm chỉ số nào là sai?', 'Mức độ được nhắc đến', 'Nhu cầu tìm hiểu thêm', 'ROI của dự án tại An Bình', 'Tín hiệu đáng kiểm tra', 'C', 'Tần suất truyền thông không cho biết dòng tiền tăng thêm của doanh nghiệp.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8384d578-75cc-41a2-832b-d3b8b934faee', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 8, 'OCR minh họa 5,4,4,2 với trọng số 35/30/20/15 có điểm bao nhiêu?', '3,35', '3,65', '4,00', '4,35', 'D', 'Tính có đảo chiều cột phụ thuộc cho ra 4,35.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('282e74a3-175d-4852-b0f1-14219033ae79', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 9, 'Sau khi tăng trọng số nguồn lực, thứ tự thay đổi mạnh. Điều này phản ánh?', 'Kết quả nhạy với giả định, cần giải thích', 'Số liệu ban đầu đã chắc chắn sai', 'Công nghệ thay đổi ngay lập tức', 'Quy định bắt buộc phải mua phương án đứng đầu', 'A', 'Độ nhạy của thứ tự là thông tin về mô hình chấm, không là bằng chứng hiệu năng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('08ebedfe-19e6-4f1b-9bcd-d612d68c5dae', '77feaa2a-a749-5a86-be4b-c699c1ee15cf', 10, 'Một brief thử nhỏ cần gồm nội dung nào?', 'Tên công nghệ thịnh hành và logo', 'Phạm vi, mẫu, KPI, người xác nhận, an toàn và điều kiện dừng', 'Chỉ chi phí phần cứng', 'Chỉ bảng xếp hạng điểm', 'B', 'Phép thử cần khả năng đo được và kiểm soát rủi ro.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('beefa053-a042-41cb-b87b-b21ab385e392', '6721da87-6494-5fd4-9cc7-6163a275f01a', 1, 'Khi có đề nghị đưa AI vào nhà máy, bước đầu thích hợp là?', 'Chốt vấn đề và KPI nền', 'Chọn tên mô hình', 'Ký gói dịch vụ', 'Bỏ phương án đang dùng', 'A', 'Giải đúng vấn đề cần đường cơ sở và người xác nhận.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ad898f42-3ece-44c4-b788-a0f5ad157372', '6721da87-6494-5fd4-9cc7-6163a275f01a', 2, 'Kiểm tra định dạng mã cố định theo 12 ký tự nên bắt đầu bằng?', 'Mô hình tạo sinh', 'Quy tắc rõ ràng để đối chứng', 'Dự báo bảo trì', 'Mua GPU', 'B', 'Một điều kiện kiểm dễ diễn đạt không tự động cần AI.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('600bceef-6858-4dcb-a8bf-5706eb27d831', '6721da87-6494-5fd4-9cc7-6163a275f01a', 3, 'Có 850 hồ sơ dùng được từ 1.000 hồ sơ. Tỷ lệ là?', '15%', '70%', '85%', '95%', 'C', 'Tính 850/1.000 = 85%. Còn cần kiểm chất lượng và đại diện.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('30a0e7b2-e971-4f71-aa03-08cbbab84f6d', '6721da87-6494-5fd4-9cc7-6163a275f01a', 4, 'Tài liệu SOP có dữ liệu nội bộ, chưa rõ quyền đưa lên dịch vụ AI. Hành động đúng?', 'Tải thử ít trang', 'Thay tên file', 'Tăng điểm tác động', 'Chưa gửi, kiểm quyền dữ liệu trước', 'D', 'Quyền dữ liệu là điều kiện bắt buộc.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('75a8c8d6-5151-4d9b-8d44-c0bdfa07a82c', '6721da87-6494-5fd4-9cc7-6163a275f01a', 5, 'Một AI kiểm nhãn phát hiện thêm lỗi nhưng loại nhầm hàng tốt tăng. Cần?', 'Đo lỗi lọt, loại nhầm, chi phí xử lý trên cùng mẫu', 'Chỉ báo cáo tỷ lệ đúng chung', 'Bỏ mẫu tốt', 'Mua ngay', 'A', 'Tối ưu một chỉ số có thể gây hại cho vận hành.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b7a1c40f-333d-4986-bc17-950b5487be7d', '6721da87-6494-5fd4-9cc7-6163a275f01a', 6, 'B có 31 kỳ dùng được trong 52 kỳ; kết luận phù hợp là?', 'Dữ liệu luôn đủ dự báo', 'Tỷ lệ 59,6%, cần xét độ phủ và bổ sung', 'Mô hình chắc chắn sai', 'Không cần gán nhãn', 'B', 'Tỷ lệ và độ phủ theo mùa cần được phân tích riêng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e18d95a1-0209-43a6-ac44-d07994036084', '6721da87-6494-5fd4-9cc7-6163a275f01a', 7, 'D có tác động 5 nhưng 12/30 hồ sơ dùng được. Theo ngưỡng dữ liệu 75%, nên?', 'Ưu tiên mua', 'Tăng điểm cần AI', 'Bổ sung dữ liệu, chưa đủ bộ lọc thử', 'Dùng 12 hồ sơ để chứng minh chính xác', 'C', '40% thấp hơn ngưỡng giả định, chưa có cơ sở thử nhỏ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('cf6c78a6-a43b-4875-b942-9b135f3e643f', '6721da87-6494-5fd4-9cc7-6163a275f01a', 8, 'Điểm A với tác động 5, dữ liệu 85%, cần AI 4; trọng số 45/30/25 là?', '3,25', '4,00', '4,25', '4,53', 'D', '5x0,45 + (5x0,85)x0,30 + 4x0,25 = 4,525; Excel làm tròn 4,53.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('26fd5511-6ad5-4ccc-bcbc-b41231f1345e', '6721da87-6494-5fd4-9cc7-6163a275f01a', 9, 'Trong bài, cổng quyền dữ liệu đang Chưa kiểm. Ý nghĩa?', 'Dừng việc đề xuất thử thực tế cho tới khi có bằng chứng', 'Điểm số có thể bù', 'Bỏ cổng vì ít dữ liệu', 'Mô hình đạt yêu cầu', 'A', 'Kiểm cổng độc lập với điểm ma trận.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('31dd3f6a-3848-4748-b9d4-f7f9f35e09c5', '6721da87-6494-5fd4-9cc7-6163a275f01a', 10, 'Thiết kế bộ đánh giá AI cần tránh điều gì?', 'Mẫu lỗi và mẫu tốt', 'Dùng lại đúng mẫu tinh chỉnh để tuyên bố hiệu năng độc lập', 'Cùng mẫu cho đối chứng', 'Nhật ký phiên bản', 'B', 'Mẫu đánh giá phải độc lập với mẫu dùng tối ưu mô hình.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('009abcfa-3de7-4827-886e-e53076960fed', 'e12f1618-2bc3-522e-80ad-727bfc35311a', 1, 'Câu hỏi ôn tập 1: Nhận định nào sau đây là chuẩn xác nhất đối với ''Nhà máy thông minh: lộ trình từ số hóa đến sản xuất thông minh''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
