INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e9017086-5b9d-4857-8ee4-ac36b5d8363c', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 2, 'Khi xây bản đồ cho một dây chuyền, bước cần làm đầu tiên là?', 'Mua cảm biến', 'Chốt ranh giới, công đoạn và chủ sở hữu', 'Chấm điểm nhà cung cấp', 'Đặt mục tiêu mức 5 cho mọi việc', 'B', 'Nếu chưa chốt phạm vi, điểm các hạng mục thiếu khả năng so sánh.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('9e3b0e26-9d14-4aab-8354-cdfe8c3b74cd', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 3, 'Hiện trạng mức 1, mục tiêu mức 4, khoảng trống bằng?', '1', '4', '3', '5', 'C', 'Trong bài, MAX(4-1,0)=3.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b1cbee1d-9ccc-431c-b71b-f072152a0b2e', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 4, 'Khoảng trống lớn có tự làm một công nghệ thành ưu tiên đầu tư?', 'Luôn có', 'Có nếu quảng cáo tốt', 'Có nếu hiện trạng thấp', 'Không; còn xét tác động, sẵn sàng, phụ thuộc và cổng', 'D', 'Khoảng trống chỉ là một thành phần của đánh giá.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('71c641bf-8185-451f-a17c-c5f1db05b21a', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 5, 'C có tác động 5, gap 3, sẵn sàng 4, trọng số 40/35/25. Điểm?', '4,40', '3,40', '4,00', '5,00', 'A', '5x0,40+(1+3)x0,35+4x0,25=4,40.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('28605270-323b-49ea-a06e-7341a56dd72a', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 6, 'Vì sao phải ghi nguồn và thời điểm chấm mức hiện trạng?', 'Để tăng điểm', 'Để có thể kiểm chứng và cập nhật khi điều kiện đổi', 'Để bỏ KPI', 'Để coi điểm là số đo khách quan', 'B', 'Điểm sàng lọc không tự chứng minh dữ liệu ban đầu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('37be6a5a-9485-45b4-b530-9a37733c356e', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 7, 'B cần lịch sử vật tư đầy đủ nhưng dữ liệu chưa có. Nên?', 'Mua hệ thống dự báo ngay', 'Bỏ luôn hoạt động kho', 'Đưa việc chuẩn hóa dữ liệu nền vào danh mục trước', 'Tự tăng điểm sẵn sàng', 'C', 'Một hạng mục phụ thuộc chỉ khả thi khi điều kiện đầu vào được xử lý.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('f262bead-0aad-4375-b6cc-7d7a766aeab9', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 8, 'Trọng số 25/30/45 làm B=2,80 và D=3,15. Hiện tượng này cho thấy?', 'D chắc chắn sinh lời', 'B có dữ liệu sai', 'Phải luôn ưu tiên D', 'Thứ tự nhạy với trọng số; cần giải thích giả định', 'D', 'Đảo thứ tự không xác nhận trọng số nào là đúng; cần người duyệt và mục tiêu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ffc83664-0dae-403d-aa69-6c2ca8f8a2ed', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 9, 'Điểm C cao nhưng cổng quyền dữ liệu Chưa kiểm. Kết luận nào phù hợp?', 'Chưa mở triển khai; bổ sung bằng chứng cổng', 'Có thể bỏ cổng', 'Tự phê duyệt mua', 'Điểm cao đủ thay thẩm định', 'A', 'Cổng bắt buộc không được bù trừ bằng điểm ưu tiên.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('a19fe525-0cf2-412a-a740-19f239ac03a2', 'd477e3e0-2326-5301-a830-9ecc7d59e5c6', 10, 'Khi nào nên cập nhật bản đồ công nghệ?', 'Không bao giờ', 'Khi KPI, quy trình, dữ liệu hoặc điều kiện triển khai thay đổi', 'Chỉ khi có quảng cáo mới', 'Chỉ cuối 5 năm', 'B', 'Bản đồ là hồ sơ có phiên bản, chủ cập nhật và nguồn chứng cứ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e1d0068e-cd22-43ad-948e-4a8e6a47429a', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 1, 'Điểm khởi đầu của lộ trình đổi mới công nghệ là gì?', 'Mục tiêu kinh doanh và KPI có đường cơ sở', 'Danh mục phần mềm đang nổi', 'Bảng giá nhà cung cấp', 'Ngày triển lãm công nghệ', 'A', 'Mục tiêu, KPI và chủ sở hữu quyết định bài toán nào cần công nghệ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d13da165-023c-4496-b3c9-fa721a82c597', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 2, 'Việc P4 thử lại OCR phải đặt sau P3 vì?', 'P3 có giá mua thấp', 'P3 chuẩn hóa nhãn, mã lô và bộ mẫu làm đầu vào', 'P4 luôn cần đúng 2 năm', 'P3 có điểm ưu tiên cao hơn', 'B', 'Phụ thuộc là yêu cầu đầu vào cần hoàn thành và có bằng chứng, không phải giá.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7b2f4da4-9934-4ba6-9856-07b574d8328b', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 3, 'Năm 1 có 70, 65, 80 triệu. Tổng vốn là?', '200', '230', '215', '245', 'C', '70+65+80 = 215 triệu đồng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c9a5c2ef-0b5f-4903-9043-a123f87a0c0c', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 4, '7 người-tháng có thể được hiểu đúng là?', 'Bắt buộc 7 người toàn thời gian cả năm', 'Chỉ cần một quản lý ký duyệt', 'Số giờ máy chạy', 'Tổng nỗ lực nhân sự quy đổi, cần kiểm lịch thực tế', 'D', 'Người-tháng là đơn vị khối lượng công việc, không phải số người hiện diện.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('e04f2064-8aa6-4729-baac-726ab6b2149d', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 5, 'Năm 4 cần 280 triệu, trần 260 triệu. Khoản chênh là?', 'Thiếu 20 triệu', 'Dư 20 triệu', 'Dư 540 triệu', 'Không có chênh', 'A', 'Trần 260 trừ nhu cầu 280 bằng âm 20 triệu.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d082d809-01b9-44c3-b3ba-919a6dee375e', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 6, 'Tổng ba năm lõi là 215 + 145 + 175 triệu, bằng?', '470', '535', '1.005', '360', 'B', 'Phần năm 4-5 chưa cộng vào tổng ba năm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b90190a4-b717-4def-8762-39b219235057', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 7, 'Nếu P4 có năm triển khai bằng P3, theo quy tắc trong phiếu thì?', 'Đã hợp lệ', 'Tự chuyển P3 sang năm khác', 'Báo sai thứ tự phụ thuộc', 'Bỏ dòng P3', 'C', 'Phiếu yêu cầu năm tiên quyết nhỏ hơn năm dự án phụ thuộc.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('d1d1bc62-25a5-4673-9398-e5c884750cfd', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 8, 'Vì sao không thể gọi tổng vốn 1.005 triệu là TCO?', 'Vì đã có 5 năm', 'Vì quá nhỏ', 'Vì bảng thiếu chữ ký', 'Vì chưa cộng đủ vận hành, duy trì, thay thế và các chi phí liên quan', 'D', 'TCO bao quát chi phí vòng đời, không chỉ dự toán vốn theo năm.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8d9e83e7-131f-4100-99df-de732a214e54', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 9, 'Đề xuất P6 mở rộng OCR có đủ vốn nhưng P4 chưa đạt thử. Nên?', 'Giữ trạng thái chờ xác minh và không mở rộng', 'Phê duyệt ngay', 'Xóa cổng kiểm', 'Tăng điểm ưu tiên', 'A', 'Cổng thử nghiệm không thể bị bù bằng khả năng cấp ngân sách.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b9d6a825-a926-43b8-ba9f-a9aca930622d', '19d71e0c-bbd1-5d32-844e-751cef6e3bdb', 10, 'Khi trần ngân sách năm 4 thay đổi, người quản lý cần?', 'Tự đổi số liệu để đủ', 'Lưu phiên bản, nêu lý do, tính lại nguồn lực và xin quyết định', 'Không thay gì dù phạm vi đổi', 'Giả định chi phí bằng một nửa khi chia gói', 'B', 'Mọi thay đổi lịch và vốn phải có giả định, nguồn và người phê duyệt rõ ràng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ef38c7c5-62ae-4562-9453-138cd728e759', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 1, 'Vì sao nên chọn nhiệm vụ trước khi chọn công cụ AI?', 'Để xác định đầu ra, dữ liệu và cách kiểm chứng', 'Vì công cụ AI không thể làm việc', 'Để bỏ bước đánh giá rủi ro', 'Vì SOP luôn đúng', 'A', 'Mục tiêu và cách đo giúp biết có cần AI hay không.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ba51b9a4-33c7-4070-8630-87bf80dc6b3f', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 2, 'Đâu là giới hạn thường gặp của AI tạo sinh?', 'Không thể tạo văn bản', 'Có thể tạo nội dung nghe hợp lý nhưng sai', 'Luôn truy cập đúng tài liệu mới nhất', 'Tự bảo đảm quyền dữ liệu', 'B', 'Đầu ra phải được đối chiếu với nguồn và người có thẩm quyền.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('43c8c38a-c080-47df-b1b4-7fa70bcce356', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 3, 'Khi không có SOP làm căn cứ, trợ lý cần?', 'Ước đoán thông số', 'Tạo mã SOP giả', 'Từ chối đúng và chuyển người phụ trách', 'Chọn đoạn nguồn gần giống', 'C', 'Không có nguồn thì không được bịa; từ chối đúng có thể được chấm đạt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('503a9dcc-2205-4ba8-ae20-ff021ee1ba96', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 4, 'Cách kiểm quyền tài liệu phù hợp là?', 'Chỉ thêm câu nhắc giữ bí mật', 'Mở tất cả dữ liệu cho mọi nhân viên', 'Bỏ nhật ký truy cập', 'Thiết lập quyền, luồng dữ liệu và phê duyệt riêng', 'D', 'Phân quyền và cơ sở xử lý dữ liệu phải được kiểm độc lập với prompt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2635991b-d8f3-4771-ae01-63e749534714', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 5, 'Trong 7 mẫu có 5 mẫu đạt, tỷ lệ đạt gần nhất là?', '71,4%', '85,0%', '50,0%', '95,0%', 'A', '5/7 x 100 gần bằng 71,4%.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('9d3b2474-f811-47af-9349-e698617114ff', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 6, 'Hai câu thiếu nguồn, một câu từ chối đúng. Tỷ lệ từ chối đúng là?', '100%', '50%', '25%', '71,4%', 'B', '1/2 câu không có nguồn được từ chối đúng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c45f34b6-f4c5-425e-9cd7-0b8a1425ba22', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 7, 'Một lần bịa mã tài liệu SOP nên dẫn đến hành động?', 'Tăng điểm trung bình', 'Cho vận hành rộng nếu câu còn lại đạt', 'Dừng mở rộng, điều tra và thử lại', 'Xóa câu khỏi bộ kiểm', 'C', 'Lỗi bịa nguồn không được bù bởi tỷ lệ đúng chung.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7fc0d7fa-a760-4c06-92e4-52c21a8a7d2d', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 8, 'Vì sao phải lưu phiên bản SOP trong kho?', 'Để tên tài liệu dài hơn', 'Để tăng dữ liệu không kiểm soát', 'Vì AI luôn chọn đúng bản mới', 'Để tránh dùng bản hết hiệu lực hoặc bản nháp', 'D', 'Người sở hữu tài liệu quyết định phiên bản được phép áp dụng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('6ecf772d-c9b1-4872-963c-bd9d41bbae15', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 9, 'Người duyệt được giao vai trò nào?', 'Đối chiếu đầu ra với nguồn và bác nội dung thiếu bằng chứng', 'Chỉ bấm duyệt vì AI viết mạch lạc', 'Chuyển quyền an toàn cho chatbot', 'Bỏ qua mọi trường hợp không có nguồn', 'A', 'Quy trình duyệt phải có người chuyên môn, nhật ký và căn cứ.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c30ebb33-3429-4420-b7a4-3fe1af549ac5', 'ff38603e-2659-5c35-a0bc-70cb9bca8d5f', 10, 'Đủ điểm kiểm thử nhưng thiếu cổng dữ liệu, quyết định nào phù hợp?', 'Triển khai cho toàn doanh nghiệp', 'Hoàn tất cổng, trình phê duyệt thử giới hạn', 'Đổi Chưa kiểm thành Đã kiểm mà không có chứng cứ', 'Bỏ bước kiểm riêng tư', 'B', 'Điểm tốt không thay quyền dữ liệu và thẩm quyền phê duyệt.', false);
