INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('4cce78c2-324d-4827-97f3-7e1a2802e687', '45adeb6d-9960-5956-b29c-defd86eba6dc', 5, 'Trong nghiên cứu đồng sở hữu, khi chưa rõ quyền công bố và khai thác, nhóm nên?', 'Xác minh chủ quyền và phạm vi trước chia sẻ', 'Công bố mã nguồn đầy đủ', 'Dựa vào lời nói của người thuyết trình', 'Bỏ bước kiểm vì đã có khách hàng quan tâm', 'A', 'Một phiên demo không làm phát sinh quyền sử dụng kết quả nghiên cứu.', false);
