INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ff8a6bb3-2ee3-485f-b01b-2bbbd2550857', '05ff18a7-62d7-5367-bcac-cb27c6a826cd', 10, 'Câu hỏi ôn tập 10: Nhận định nào sau đây là chuẩn xác nhất đối với ''Xây dựng hồ sơ công nghệ trên cơ sở dữ liệu nguồn cung''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('82f594eb-6dca-4bea-bec0-573bf2568946', '45adeb6d-9960-5956-b29c-defd86eba6dc', 1, 'Đâu là điểm bắt đầu phù hợp cho thương mại hóa kết quả nghiên cứu?', 'Xác định vấn đề, người dùng, cách đo giá trị', 'Chỉ liệt kê bằng sáng chế', 'Chọn giá bán bất kỳ', 'Làm video quảng bá trước khi tìm khách', 'A', 'Đề xuất giá trị phải phản ánh công việc mà khách hàng muốn giải quyết.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('2875292f-c055-4679-abb4-e8e66e7ad9f7', '45adeb6d-9960-5956-b29c-defd86eba6dc', 7, 'Trong phễu giả định: 6 đầu mối, 4 nhu cầu xác nhận, 3 demo đạt, 2 ứng viên. Số hợp đồng đã được chứng minh là?', '6', '4', '0', '2', 'C', 'Danh sách chỉ ghi ứng viên thẩm định, không có bằng chứng hợp đồng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('02f03391-aef9-49dd-8b53-13d5faae3e02', '45adeb6d-9960-5956-b29c-defd86eba6dc', 8, 'Cổng quyền khai thác còn “Chưa kiểm”, dù K1 và K6 là ứng viên. Hành động phù hợp?', 'Mời thử hiện trường ngay', 'Bán bản nguồn luôn', 'Xóa hết đầu mối', 'Hoàn tất xác minh quyền trước khi mời thử', 'D', 'Cổng bắt buộc độc lập với đánh giá quan tâm và kỹ thuật.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('c76248ac-d55d-4f0f-92b4-ce0489894aca', '45adeb6d-9960-5956-b29c-defd86eba6dc', 9, 'Giữa hai khách hàng, K4 demo chưa đạt còn K3 chưa xác nhận nhu cầu. Bước theo đúng thứ tự?', 'K4 sửa phép thử; K3 quay lại khảo sát', 'Cùng gửi hợp đồng', 'K4 bỏ lỗi; K3 nâng điểm', 'Cùng ghi thành công thương mại', 'A', 'Hành động phải đúng chỗ nghẽn của từng cơ hội.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('1add5fef-1b3a-4117-ac90-1e125f17ad7d', '45adeb6d-9960-5956-b29c-defd86eba6dc', 10, 'Biên bản sau demo nên có nội dung nào?', 'Chỉ lời khen của khách', 'Mẫu, kết quả, lỗi, phạm vi, người duyệt, việc tiếp và hạn', 'Chỉ bảng giá', 'Chỉ số người tham dự', 'B', 'Biên bản là hồ sơ bằng chứng và hành động, không phải tài liệu PR.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('3c7eaa36-846c-4ce0-90fa-2b4d297e106b', '641a0564-4c0a-553d-b485-2857b82f7131', 1, 'Vì sao phải tách danh mục thành phần công nghệ trong term sheet?', 'Để biết chính xác phần giao và quyền liên quan', 'Để kéo dài hợp đồng', 'Vì chỉ cảm biến là đối tượng có giá', 'Để không cần nghiệm thu', 'A', 'Phần mềm, mã nguồn, cấu hình và tài liệu có quyền và cách bàn giao khác nhau.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8510ed70-96d5-43a4-9108-ca7cbca168fb', '641a0564-4c0a-553d-b485-2857b82f7131', 2, 'Điểm khác chủ yếu giữa giấy phép sử dụng và chuyển nhượng quyền là gì?', 'Không có khác biệt', 'Cấp phép không mặc nhiên làm chuyển chủ sở hữu quyền', 'Cấp phép luôn cho sử dụng mọi nơi', 'Chuyển nhượng chỉ là thuê bảo trì', 'B', 'Phạm vi sử dụng và chuyển chủ quyền phải phân biệt theo đối tượng và thỏa thuận.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('b7b8ef5f-0674-4099-80fb-52277f6c4f9e', '641a0564-4c0a-553d-b485-2857b82f7131', 3, 'Ai cần xác minh trước khi có cam kết chuyển giao?', 'Chỉ người viết slide', 'Chỉ kỹ thuật viên lắp cảm biến', 'Chủ thể có quyền và người được ủy quyền ký', 'Chỉ khách từng xem demo', 'C', 'Nguồn hình thành tài sản và ủy quyền có thể ảnh hưởng quyền định đoạt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('200013c8-0b13-4f12-b2f4-22089334b6ef', '641a0564-4c0a-553d-b485-2857b82f7131', 4, 'Mô tả nghiệm thu tốt nhất là gì?', 'Đẹp mắt và chạy tốt', 'Khách thấy hài lòng', 'Không xảy ra lỗi nào', 'Bộ mẫu, ngưỡng, log lỗi, phiên bản và người ký biên bản', 'D', 'Tiêu chí nghiệm thu cần có khả năng kiểm chứng và được chốt trước thử.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('208f5a00-2a0b-47c8-b288-9e6621c80791', '641a0564-4c0a-553d-b485-2857b82f7131', 5, 'Nếu phí tính theo doanh thu, nội dung nào cần được làm rõ?', 'Doanh thu nào được tính, kỳ đối soát và cách kiểm tra', 'Chỉ số lượt xem video', 'Giá trị của logo', 'Mức giá mua của khách khác không có chứng cứ', 'A', 'Cơ sở tính phí nếu không được định nghĩa dễ gây tranh chấp.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('900ac19c-3ad2-45bf-ba33-6ba029b5c9b2', '641a0564-4c0a-553d-b485-2857b82f7131', 6, 'Dòng tiền năm 1: lợi ích 115, chi phí ứng dụng 25, phí chuyển giao 12 (triệu). Dòng thuần là?', '115', '78', '90', '102', 'B', '115 - 25 - 12 = 78 triệu đồng.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('836cf2d6-109f-4001-aaa1-bb6c2c7c10c7', '641a0564-4c0a-553d-b485-2857b82f7131', 7, 'Vì sao tiền năm 5 cần quy về hiện tại khi định giá theo dòng tiền?', 'Vì tiền năm 5 chắc chắn thấp hơn năm 1', 'Vì thuế luôn bằng không', 'Để phản ánh giá trị thời gian của tiền theo giả định chiết khấu', 'Để thay thế thẩm định pháp lý', 'C', 'NPV chiết khấu dòng tiền theo thời điểm và tỷ lệ đã đặt.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('8c56384b-2f5f-4264-931a-bf911641f538', '641a0564-4c0a-553d-b485-2857b82f7131', 8, 'Bảng cho NPV dương nhưng quyền phần mềm chưa rõ. Kết luận nào đúng?', 'Có thể ký ngay', 'Đã định giá pháp lý xong', 'Xem như tài sản đã được xác lập', 'Chưa đủ cổng pháp lý; phải kiểm quyền và thẩm quyền', 'D', 'NPV là một kết quả mô hình, không chứng minh đối tượng có thể chuyển giao.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('ca500ed5-c120-450f-9126-34de136b77db', '641a0564-4c0a-553d-b485-2857b82f7131', 9, 'Phí ban đầu 150 triệu, trần phí tính theo NPV bằng 0 là khoảng 287 triệu. Hiểu đúng là?', 'Trần chỉ đúng khi mọi dòng tiền và giả định khác giữ nguyên', 'Phải trả 287 triệu', 'Giá thị trường được nhà nước chứng nhận là 287 triệu', 'Doanh thu chắc chắn tăng', 'A', 'Trần là đầu ra theo kịch bản của người nhận, không phải giá trị khách quan.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('7b019815-bf20-47a5-8d4b-ae8c66b1bdcd', '641a0564-4c0a-553d-b485-2857b82f7131', 10, 'Đầu ra phù hợp sau khi hoàn thành học phần là?', 'Hợp đồng được ký chính thức', 'Term sheet, bảng dòng tiền và danh sách chứng cứ/cổng còn thiếu', 'Giấy xác nhận quyền sở hữu trí tuệ', 'Báo giá ràng buộc tất cả đối tác', 'B', 'Bài học chỉ tạo bộ hồ sơ phục vụ thẩm định, không thay luật sư và người có thẩm quyền.', false);
INSERT INTO lms.learning_quiz_questions (id, material_id, display_order, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, has_length_warning) VALUES ('14a944b8-3a24-478d-a978-28da0cde9273', '4136304a-a901-53c0-a081-b528490e14dd', 1, 'Câu hỏi ôn tập 1: Nhận định nào sau đây là chuẩn xác nhất đối với ''Nguồn vốn và chính sách hỗ trợ đổi mới công nghệ''?', 'Cần căn cứ trên hiện trạng dữ liệu và mục tiêu kinh doanh cụ thể', 'Chỉ cần quan tâm đến chi phí mua sắm ban đầu', 'Mọi công nghệ mới đều tự động đem lại thành công', 'Không cần sự tham gia của lãnh đạo và các bên liên quan', 'A', 'Căn cứ trên dữ liệu thực tế và mục tiêu kinh doanh là nguyên tắc xuyên suốt của chương trình E-Learning.', false);
